INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (26, '必修的课程', '$N，看到你进展顺利，我非常高兴。你正在不断地努力成为自然界的守护者，这是莫大的荣耀。$B$B现在是你深入学习更高级的变身技能的时候了，塞纳留斯赋予我们特殊的能力，让我们可以变身成为在水中行动自如的动物。所以，你必须到月光林地的永夜港去，跟塞纳里奥议会的德迪利特·星焰谈一谈。他将进一步指引你。', '与月光林地永夜港的德迪利特·星焰谈一谈。', '你好，年轻的德鲁伊。现在是让你了解我们的水栖形态的时候了。这种形态能让你在水中活动自如，你将发现它是一种非常实用的形态，是神对我们的恩赐……但你必须要通过自己的努力去获得它。$B$B你将面对两个考验。首先要测试你在水中压力下的作业能力，并掌握它。$B$B做好准备吧，试炼就要开始了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (27, '必修的课程', '$N，看到你进展顺利，我非常高兴。你正在不断地努力成为自然界的守护者，这是莫大的荣耀。$B$B现在是你深入学习更高级的变身技能的时候了，塞纳留斯赋予我们特殊的能力，让我们可以变身成为在水中行动自如的动物。所以，你必须到月光林地的永夜港去，跟塞纳里奥议会的德迪利特·星焰谈一谈。他将进一步指引你。', '与月光林地永夜港的德迪利特·星焰谈一谈。', '你好，年轻的德鲁伊。现在是让你了解我们的水栖形态的时候了。这种形态能让你在水中活动自如，你将发现它是一种非常实用的形态，是神对我们的恩赐……但你必须要通过自己的努力去获得它。$B$B你将面对两个考验。首先要测试你在水中压力下的作业能力，并掌握它。$B$B做好准备吧，试炼就要开始了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (28, '湖中试炼', '第一个试炼是要搜寻月神湖底的神殿灵珠。它会很快地腐烂，因此你要在找到它后立即把它拿到雷姆洛斯神殿去。在神殿里使用它，然后跟塔加里谈谈，她是月光林地里最值得信赖的守卫之一。$B$B你的时间非常紧迫，而且还要与其他寻找灵珠的德鲁伊竞争，灵敏和智慧是你取胜的关键。$B$B祝你好运，$N。', '在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。', '嗯，又一个成功完成湖中试炼的德鲁伊!做得好，我年轻的朋友。$B$B我是塔加里，月光林地及这座神殿的守护者，这是我的责任，也是我所拥有的特权。守护者雷姆洛斯指引着塞纳里奥议会努力保持着自然的平衡，并且他的神殿正在为此做出巨大的贡献。在这里使用灵珠，即表示你认同这个地方在议会中的重要性。', '要完成湖中试炼，你就必须在神殿内使用灵珠。如果你不这样做的话，你的试炼就不算完成，而且随时都可能会失败。', '完成湖中试炼。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (29, '湖中试炼', '第一个试炼是要搜寻月神湖底的神殿灵珠。它会很快地腐烂，因此你要在找到它后立即把它拿到雷姆洛斯神殿去。在神殿里使用它，然后跟塔加里谈谈，她是月光林地里最值得信赖的守卫之一。$B$B你的时间非常紧迫，而且还要与其他寻找灵珠的德鲁伊竞争，灵敏和智慧是你取胜的关键。$B$B祝你好运，$N。', '在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。', '嗯，又一个成功完成湖中试炼的德鲁伊!做得好，我年轻的朋友。$B$B我是塔加里，月光林地及这座神殿的守护者，这是我的责任，也是我所拥有的特权。守护者雷姆洛斯指引着塞纳里奥议会努力保持着自然的平衡，并且他的神殿正在为此做出巨大的贡献。在这里使用灵珠，即表示你认同这个地方在议会中的重要性。', '要完成湖中试炼，你就必须在神殿内使用灵珠。如果你不这样做的话，你的试炼就不算完成，而且随时都可能会失败。', '完成湖中试炼。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (35, '卫兵托马斯', '如果你担心关于鱼人的传言可能属实的话，就去一趟艾尔文森林东部的桥边和卫兵托马斯谈谈吧。他最近一个星期都驻扎在那里，应该很了解那个地区的情况。$B$B搞清楚事态之后，把他的报告带给我。', '治安官杜汉要你和卫兵托马斯谈一谈。', '没错，鱼人已经在这里落脚了，就在艾尔文森林东部的河流附近。我们不知道他们为什么会出现在这里，不过他们很有攻击性，而且看起来并不是很笨。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (37, '失踪的卫兵', '几天前，我派了卫兵罗尔夫和马拉凯沿着河岸去侦查这一代的情况，但他们到现在还没回来。我得先搞清楚这两个人发生什么事情才能完成报告。$B$B沿着河岸往北走，找到他们……或是他们的尸体。', '卫兵托马斯要你沿着河岸向北走，寻找两个失踪的卫兵罗尔夫和马拉凯。', '虽然这具尸体已经残缺不全，不过你发现尸体旁边的一块勋章上面刻着几个字:「步卒马拉凯.史东」。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (39, '托马斯的报告', '把罗尔夫和马拉凯的死讯告知治安官杜汉，向他报告说，靠我们现在的部队根本无法遏制住这些在艾尔文森林东部繁衍的鱼人。$B$B我知道我们的兵力很短缺，但是杜汉应该可以为我们提供人手。', '到闪金镇去向治安官杜汉报告。', '嗯，这个消息确实是很麻烦。我们的防守已经很薄弱了，罗尔夫和马拉凯死在鱼人的手上让我们的处境更加不妙。$B$B如果我们不想些办法的话，不用一个礼拜，这群长着腿的鱼就会杀到闪金镇来了!', '你好，$N。你拿到汤玛斯对东艾尔文森林的报告了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (40, '鱼人的威胁', '$N，艾尔文森林又遇到新的威胁了！鱼人正陆续从艾尔文森林东部的河流里游过来，把鱼都给吓跑了，而且它们还攻击平民！$B$B我已经向治安官杜汉发出过警告，不过他显然更担心那些豺狼人和强盗，而且他不相信鱼人能对我们构成威胁。$B$B请你和杜汉谈谈吧，最好能说服他向东部派遣更多部队！', '雷米要你去和闪金镇的治安官杜汉谈一谈。', '对，我和雷米谈过。他是一个很值得尊敬的商人，不过关于东部鱼人的报告目前还不甚明了。$B$B我们会注意这件事情，但除非我接到有关鱼人威胁的军事报告，否则我们是不能轻率地派更多人去东部的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (48, '琥珀酒', '高高的葡萄树生长在南方$b蜿蜒的清泉流过树根旁$b纯净宛如女神的眼泪$b你快点去给我弄来圣泉水！', '把圣泉之水带给葛瑞姆·雷酒。', '嗝……!呴呴!', '嗝……!呴呴!你还想再听一遍?$B$B高高的葡萄树生长在南方', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (65, '迪菲亚兄弟会', '那群自称为迪菲亚兄弟会的流寇贼子将我们这些善良的平民赶离西部荒野，他们一定要为自己的罪行负责！我要求你去打探一下，我们必须知道到底谁是他们的头儿，还有他们都藏在哪儿。在湖畔镇的旅馆里有个叫威利的小贼以前欠了我一个人情，你可以找他帮忙。$b$b到艾尔文森林东边的赤脊山去吧，湖畔镇就那座山的脚下，到那里去碰碰运气。', '格里安·斯托曼要求你去和湖畔镇的威利谈一谈。', '这么说来，是斯托曼派你来的?没错，我是欠他个人情。', '我们需要知道到底谁是他们的头儿，还有他们都藏在哪儿。在湖畔镇的旅馆里有个叫威利的小贼，他以前欠了我一个人情，你可以找他帮忙。$B$B到艾尔文森林东边的赤脊山去吧，湖畔镇就那座山的脚下，到那里去碰碰运气。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (66, '斯塔文的传说', '昨夜，一阵突如其来的不安掠过我的全身，令我感到我的孙女奥利萨正处在巨大的危机中。我用纸牌进行了占卜，“死神”在桌上凝视着我。$b$b在长时间的沉思之后，我找到了这个可怕而神秘的事情的一点线索，有一个名字进入了我的脑中，那就是“斯塔文”。$b$b到城镇大厅里去找书记员达尔塔吧，看看你能否得到更多关于这个斯塔文的信息……我担心包括你我在内的所有人都有危险。', '去夜色镇大厅找到书记员达尔塔。', '哦，是艾娃夫人让你来的……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (67, '斯塔文的传说', '斯塔文？让我查查镇里的档案。$b$b斯塔文…斯塔文…让我找找……啊，找到了！这里有斯塔文·密斯特曼托的档案。最后一次记录的地址是在月溪镇的学校里。哎呀，都是过时的东西了！$b$b朋友，你能帮我个忙吗？如果你碰巧路过月溪镇的话，也许能找到一些有关这个家伙的新消息，别忘了告诉我一声，好让我更新档案。', '到月溪镇的学校去寻找关于斯塔文的新信息，回来告诉书记员达尔塔。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (69, '斯塔文的传说', '哎呀！我上次肯定漏掉这个了。斯塔文的档案中的第一个地址下面还有另一个地址，这个地址被擦掉了一点。看起来好象他还去过闪金镇的狮王之傲旅店。你愿意的话就去那里查查看吧，$N。', '到狮王之傲旅店去问问那里的人，看看他们是否听说过斯塔文这个人。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (72, '斯塔文的传说', '我父亲从前是这幢宅子的管家，在那场大屠杀之后，他费了好大的工夫才把地上的血迹拖干净，不过这跟我们要谈的事情没什么关系。$b$b弗林特雷家的基金早已经用光，现在家里最后的财产都已经准备要拍卖掉了，那些像秃鹫一样贪婪的征税官！你要是真想找些什么资料，不妨在这堆垃圾里找找看，天知道你能找到什么。', '在打包的东西里寻找线索。', '你轻轻地将箱盖移开……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (85, '丢失的项链', '我的项链丢了，一定是那个讨厌鬼比利·马科伦偷走的！他总是像只老鼠一样在东边的马科伦农场里窜来窜去。$B$B请把我的项链拿回来给我，让我这可怜的寡妇得到一些安慰吧。', '和比利·马科伦谈一谈。', '你不见了什么?喔，我可没拿什么项鍊，因为我不是小偷!$B$B我可能知道是谁干的……<奸笑>……不过我太饿了，想不起来。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (95, '斯温的复仇', '我原来在东南部的一座农场里工作……直到有一天，从逆风小径来的黑暗强盗洗劫了我的农场，趁我不在的时候杀了我的全家！$B$B我回来时发现有个模糊的人影在我家的谷仓附近埋了一件什么东西，可惜我没能抓住他。我也不敢在这里继续逗留，因为我害怕会有黑暗强盗追踪我。直到现在，我都都不知道那人到底藏了什么。$B$B如果你能去找出真相，我一定会感激你的。那人埋东西的地方就在我的谷仓附近的一个老树桩后面。', '到斯温的农场去找出埋在老树桩后面的是什么东西。', '这儿有一堆土，看起来是匆匆忙忙堆上去的，好像有什么人急于在这里藏什么东西，却没有足够的时间去埋好它。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (100, '水之召唤', '你吟诵完了咒语，瞬时间火盆便放出了万丈光芒。水滴和火焰接触时的噼啪声越来越弱，你可以感觉到笼罩在周围的堕落气息已经被消灭了。', '和在银松森林的北流海岸的水之魂谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (110, '昆虫研究', '我要去看看谢申克的勘探装置……然后把他的东西整理一下。我预感到我们将会遇到更大的麻烦。$B$B我想让你去见见炼金师匹斯特苏格，了解一下他的研究是否有进展。如果他有什么新的发现，你就尽快向我回报。', '到加基森的炼金师匹斯特苏格那里去了解关于昆虫的研究有没有新的进展。', '是的，我已经得出结论了。它们让我感到……不安，不安这个词已经是最轻微的说法了。$B$B我们最初的推断看来是正确的，那些虫子是由一股外力所控制。如果真是这样，那我们所面对的这股未知的力量不仅非常强大，而且还非常邪恶。这些虫子表现出了超乎寻常的野性和攻击欲望，我以前从来没有见过这样的情况。', '你好，很高兴再见到你，$N。我能为你做什么?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (130, '寻访草药师', '你回到达希那边的时候，能替我捎几朵花给她吗？你可以在湖畔镇西边的草药店里买到花。$B$B不过，你去买花的时候……千万别告诉药草师玛蒂这花是谁买的，也别说是要送给谁的……', '找到草药师玛蒂·詹罗斯，和她谈一谈。', '你想要一束花?你在镇上似乎还没待多久……难道你这么快就已经在这里找到了一个小情人吗?$B$B我知道我不该问那么多，但真的很高兴看到有人堕入爱河……特别是在这样的危难时刻，爱情真是难能可贵啊……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (136, '杉德尔船长的宝藏', '如果你读到这封信的话，那就意味着我，杉德尔船长，已经长眠在深深的水底了。所以，只要你按我的提示去做，我的宝藏就是你的了。$b$b首先你要找到一只小提箱，它应该就在西部荒野西海岸的某处船只残骸旁，如今八成已经快被沙子埋起来了。海岸边有许多处船只的残骸，但只有一只沉船旁有个锈掉的锚。箱子就在锚的旁边！在箱子里面，你可以找到下一条线索。', '找到杉德尔船长的手提箱，在箱子中寻找下一条线索。', '这只置物箱慢慢地开启。里面似乎只有沙子和水。慢着!一只小螃蟹冲了出来，宝藏的线索就在它的螯上!', '如果你读到这封信的话，那就意味着我，桑德斯船长，已经长眠在深深的水底了。所以，只要按照我的线索去做，我的宝藏就是你的了。$B$B首先你必须要找到我的置物箱，它应该就在西部荒野西边海岸的某处船只残骸旁，如今应该八成都埋在沙里了。海岸边有许多处船只的残骸，但只有一只沉船旁有个锈掉的锚。找到锚你就找到箱子了!在箱子里面，你可以找到下一条线索。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (138, '杉德尔船长的宝藏', '你开始读小条上的字：干得好，哥们！现在你可以开始向东走，到悬崖边的路旁好好找找，看有没有一处破烟囱，你可以在那旁边的木桶中找到下一条线索。', '找到废弃烟囱旁的老木桶，在桶里寻找下一条线索。', '做得好，宝藏猎人!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (139, '杉德尔船长的宝藏', '仔细搜索了木桶了之后，你发现了一小片羊皮纸。上面写着：现在，从桶这里转向北，像乌鸦飞翔一般绝不回头，一直走到你看见了海边悬崖上的风车为止。找到那风车旁的一个空水罐。仔细检查那个水罐，你就可以找到你要找的东西了。', '在风车旁的一个空水罐里寻找下一条线索。', '你正一步步地迈向大奖，我的大探险家!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (140, '杉德尔船长的宝藏', '显然，在这只旧罐子中藏着另一条有关杉德尔的宝藏的线索。纸上有几处墨水已经化开变得模糊不清，而且泛着一股威士忌的味道，不过你还是能从中辨认出这样的字迹：看来你找到我的威士忌罐子了，你离我的财宝已经很近啦！只要向西走到海边，然后一直向西游，你就可以游到放着小宝箱的岛上啦！', '找到杉德尔船长的箱子并打开它，取得你的奖励。', '尽管这个箱子上的铰链已经锈了，但它仍然还有作用。你暴力的打开箱子，拿到了里面的东西。$B$B恭禧!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (148, '来自夜色镇的货物', '哦，一个可怜的老人家还能做点什么呢？我需要从夜色镇拿点东西过来，不过路途太遥远，我又太老了……实在是走不动啊。$B$B你能去夜色镇给我拿点幽灵的发丝回来吗？你可以向伊瓦夫人要这东西，她的家就在夜色镇的广场旁。', '去和伊瓦夫人谈一谈。', '啊，你要的是鬼魂的发丝，是吗?我已经没有存货了，不过如果你能提供鬼魂的头发的话，我可以做一些给你……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (158, '僵尸', '我需要一瓶叫做僵尸酒的饮料。夜色镇血鸦旅店的店主斯密茨应该有些存货。$B$B最近晚上寒风刺骨，我得来点僵尸酒，好让我的血液重新沸腾起来。', '去和旅店店主斯密茨谈一谈。', '你想要些殭尸汁?嗯…这东西味道很呛—很少有人点它。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (165, '隐士', '有个老人经常到镇里来买东西，不过我已经有些日子没见过他了。如果我没记错的话，他就住在一个可以俯视乌鸦岭墓地的小屋里。你能不能去看一看出什么事了？', '去乌鸦岭墓地附近的小屋查看老人的情况。', '伊莲.克尔文?呵呵，是的……当然，克尔文家的。不不不，我没什么事，只是现在要去镇上很困难。路上太危险了，而我已经不再年轻。你能帮帮我这个老头子吗?', '伊莲.克尔文?呵呵，是的……当然，克尔文家的。不不不，我没什么事，只是现在要去镇上很困难。路上太危险了，而我已经不再年轻。你能帮帮我这个老头子吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (172, '儿童周', '你愿意帮助我们的孤儿院？太感谢你了，我的朋友。感谢你愿意在儿童周的这段时间内为我们提供帮助。$B$B拿着这只哨子，你只能在儿童周的这7天内使用它。当你使用它的时候，就可以和那些由你负责照看的孩子进行对话，再次使用就可以解散那个孩子。$B$B不管怎么样，$N——使用这个口哨，见一见你的小朋友！我相信孩子们一定很想见到你。', '使用兽人孤儿哨与你即将在儿童周期间照顾的孩子进行对话。', '啧啧!我的名字叫葛兰斯，我想你是来照看我的吧?你是一个冒险者，就像我爸爸妈妈一样。我很高兴能遇到你。$B$B我希望我们之间能相处融洽。我有些事情想要做，而孤儿院院长说你在这个星期里会像大$G哥哥:姐姐;\n一样照顾我。我真是太高兴了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (175, '仰望星空', '根据考格的设计图，现在我还需要一个东西来反射光线。我记得有个叫玛丽的女人因为总是戴着一副眼镜而在这一带人人皆知，你可以去找找她，向她借一个反光镜。我记得她曾经住在暮色森林南部……', '找到玛丽，说服她借给你一个反光镜，用于维克托的计划。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (200, '书呆子赫罗德', '既然连库尔森都知道了这个秘密，那么他们一定也在我们这边安插了一个卧底。我们必须得搞明白这些机密内容是怎么泄露出去的！$B$B索尔森在那边的线人是书呆子赫罗德，他是库尔森的后勤官，了解库尔森的营地里的一切事务。如果你能搞到他的笔记或者档案什么的话，或许我们能分析出索尔森到底是怎么被发现的。$B$B当初，我们还跟库尔森一起共事的时候，书呆子的办公室是在营地里唯一一座两层房屋的二楼，他的档案应该还在那里。', '找到书呆子赫罗德的档案。', '这些是书呆子赫洛德的笔记和记录。$B$B其中有营地的补给品列表、库尔森上校的原料采购清单和一些其他的信件。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (215, '丛林中的秘密', '谢谢你救了我的命，$N。我知道这听起来有点奇怪，但……请听我解释。$B$B多伦上尉让我和库尔森的手下一起重新回到军队里，让我扮演卧底的角色，为我们反抗军搞一些有用的情报。我原本以为这里很适合我渗透入库尔森的营地，但我错了。再次感谢你救了我一命。$B$B这是个机密任务，所以你千万不能把它告诉任何人。但如果你去和多伦上尉谈谈的话，他会给你一个解释的。', '与反抗军营地里的多伦上尉谈一谈。', '没错，托尔森告诉你的事情都是真的。你得保守秘密。我们这些反抗军的战士以前都是誓死效忠库尔森上校的，但就是因为库尔森的堕落，我们当时的满腔热情也转化为了极端的愤怒。如果有人知道了士兵托尔森其实是在暗地里给库尔森捣鬼的话，不用一晚上，他的人头就落地了。$B$B据我所知，只有尤瓦中士、托尔森和我知道这件事情，但现在看来也有其他人知道了……我们这里有内鬼。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (225, '饱经风霜的墓碑', '这座饱经风霜的墓碑上仅仅写着几个字：$b$b摩根·拉迪莫尔$b$b<经过仔细的观察，你发现墓穴的泥土最近被人动过，很多泥土好像都翻开了……>', '去和夜色镇的希拉·沃宁迪谈一谈。', '摩根.拉迪莫尔?$B$B啊，当然，他的故事可就说来话长了，而且还很悲惨。我认识他，他上了战场以后就再也没有回来过。他是个令人尊敬的好人，可惜结局很凄惨。$B$B我这儿有点东西可以让你对他有所了解，这样就不用我自己去艰难地回忆了……', '这座饱经风霜的墓碑上仅仅写着几个字:$B$B摩根.拉迪莫尔', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (227, '摩根·拉迪莫尔', '<他从架子上翻出一本皮质封面的书。>$b$b如果你想知道更多，就去问阿尔泰娅，她最近正在为摩根·拉迪莫尔的事情头疼……', '去和夜色镇的指挥官阿尔泰娅·埃伯洛克谈一谈。', '摩根.拉迪莫尔?从来没听过……$B$B哦，你是说摩拉迪姆!你没听说他的事迹吗?$B$B我来简短地跟你说说吧。有个在暮色森林四处游荡的不死生物把自己叫作摩拉迪姆。据我们所知，似乎就是你所说的那个摩根.拉迪莫尔的不死生物。他一直在给我们制造麻烦，袭击出巡的守夜人，而且还疯狂地杀人。$B$B<她上下打量着你。>$B$B你看起来挺能干，也许你可以把他解决掉?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (229, '幸存的女儿', '我应该早点告诉你的……$b$b该怎么说呢……$b$b摩根可能以为他的家人都死了，不过实际上他的女儿莎拉·拉迪莫尔还活着，她现在也是个守夜人。她一直在因为她父亲死了以后所发生的……那些事情而苦恼。我想，你可以把关于她父亲的最新消息带给她。', '去和夜色镇的守夜人莎拉·拉迪莫尔谈一谈。', '什么?我父亲……$B$B<她的眼神开始变得忧郁。>$B$B我多希望…能为他做点什么…要是当初在他做那些事情之前，我能和他谈谈的话……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (235, '灰谷狩猎', '年轻的冒险者们，注意了！灰谷的野兽正在等着你们！$B$B部落在贫瘠之地以北的区域建立了强大的基地。我们的两个前哨站——碎木哨岗和佐拉姆海岸哨岗——正在努力地为部落的荣耀而战！想要证明自己能力的勇士就到那儿去吧。碎木岗哨位于贫瘠之地的正北方，塞娜尼·雷心正在那里招募愿意参与灰谷狩猎中的冒险者！', '与灰谷碎木哨岗的塞娜尼·雷心谈一谈。', '欢迎来到这块新的疆土，$N。梣谷是一片充满机遇的土地，像你这样年轻的$C肯定可以在这里找到无数证明自己实力的机会。在这里的前哨站到处转转，然后到佐拉姆海岸去，部落在那儿设有另一个岗哨。$B$B我看得出你是到这儿来学习狩猎的。用心学习吧，我将很乐意与你分享我所掌握的知识。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (239, '西泉要塞', '我们位于西部边界的要塞报告说，那里的豺狼人和迪菲亚盗贼最近越来越猖獗了。他们要求我从暴风城派更多士兵过去……但是我们已经没有多余的人可派了！$B$B如果你愿意帮忙的话，就去和西泉要塞的瑞尼尔副队长谈一谈，看看他需要你做些什么。$B$B沿着这条路往西走，过了桥之后向右转就是要塞。', '到西泉要塞去和瑞尼尔副队长谈一谈。', '治安官杜汉派你来的吗?你不是军人，不过既然杜汉让你来，那就说明你肯定很出色!$B$B我们目前的形势，嗯，至少可以说是压力重重，希望你能帮助我们。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (243, '进入沙漠', '你现在得去一趟塔纳利斯沙漠，在那里对当地的蜥蜴、蝎子和土狼进行一些组织测试，并搜集一些组织样品放进实验工具包里。当然，你有可能得花不少工夫才能找到合适的样品，这一点是可以预料的。每种生物的样本都要十份。$B$B另外，加基森的地精拥有这类工具包所需的能量源，去和那里的首席工程师沙克斯·比格维兹谈谈，或许能得到一些必要的帮助。$B$B此行只许成功不许失败，否则就不要回来见我。', '和加基森的首席工程师沙克斯·比格维兹谈一谈，请他为实验工具包提供能量源。', '啊，强大的4711-FTZ能量源!我们一般用它来驱动水井，但是自从那些该死的游牧民冒出来后，我们的能源就一直很紧张。$B$B当然，我可以想办法为你的实验提供能源，我可不管你要做什么实验，但这当然不会是免费的，$r。在加基森没有什么东西是免费的。', '嗯，我能帮你做些什么吗?你显然有事要找我帮忙，但也许我并不会帮你。你是否考虑到了出现这种情况的可能性?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (244, '豺狼人的入侵', '你好，$c。我是负责这段道路巡逻任务的卫兵。虽然这条道路现在是安全的，但我曾经在这附近的东北方看见过豺狼人的宿营地。$B$B湖畔镇必须得提防着这群豺狼人才行。请你把这条消息报告给湖畔镇的菲尔顿副队长,我想他一定会非常乐意给你的侦察行动付上一笔酬劳的。$B$B菲尔顿一般在湖畔镇桥南的地区执行警戒任务。', '找到菲尔顿副队长。他就在赤脊山湖畔镇南边的桥上。', '赤脊山豺狼人在艾尔文森林附近扎营?他们肯定是正在准备入侵我们的家园。这样下去很快就不止是湖畔镇面临战事了!$B$B尽管你带来了坏消息，但你还是该得到酬劳。看来最近情况很不妙，我们的准备还不够充分。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (247, '完成狩猎', '', '', '$N，你已经杀死了梣谷狩猎所需杀死的三头野兽，你已经给我带回了它们死亡的证据。对你的力量和坚毅，我们毫不怀疑。猎人的血液在你的血管里流动，你理应得到赞颂!$B$B这是对你为部落做出的伟大贡献的奖励，愿你的祖先见证你的荣耀!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (250, '水坝危机', '老天保佑，现在终于有人关心水坝的安全了。先是有人摧毁了萨多尔大桥，然后又有人抢劫丹莫德！我敢说这座大坝肯定会是黑铁组织下一次袭击的目标。这里的驻军——包括我的长官在内——大部分都开到了联盟前线。$b$b这就是我需要你的原因，$N。我看见有几个黑铁工兵在水坝东边的斜坡下转悠。去那里查看一下，带回点线索给我。', '查看水坝东边斜坡附近的区域，调查一下黑铁矮人准备做什么，然后把线索带给主工程师辛德维尔七世．', '这个看起来就很可疑的木桶里有一种味道很奇怪的粉末。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (254, '掘墓', '', '', '你挖掉墓穴上那些有点松动的泥土……发现下面有一具棺材。$B$B你可以感受到尖锐的爪子正在棺材里乱抓，腐烂的牙齿正在棺材里摩擦……$B$B你有勇气打开棺材并拿回藏尸者的心脏吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (270, '被诅咒的舰队', '几年前，库尔提拉斯的第三舰队在湿地的海岸线附近全军覆没，对，就是丹莫罗北方的那块湿地。其中一条船上满载着光铸铁。$B$B这种金属对我们来说相当珍贵，它们可以用来制造出附有神圣力量的武器。如果你要去与摩本特·费尔作战的话，应该会需要这样一把武器。$B$B去米奈希尔港找我的矮人同事戈罗林·钢眉谈谈吧，如果你可以找到那些丢失了的金属，他应该会知道该到哪里去找。', '到湿地的米奈希尔港去，找戈罗林·钢眉谈一谈。', '光铸铁是一种宝贵的金属，但你的任务听起来倒是挺恐怖的。看来你是长途跋涉来到这里的，$G兄弟:小姐;\n。就凭这份诚意，你一定会找到你想找的东西!$B$B如果你确实得到了这种金属的话，我知道有个人能把它铸造成可以对抗暮色森林里的那个死灵法师的武器。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (273, '挖掘场的补给品', '现在还不算太晚，你还可以去找胡达尔。他不大可能走得太远，尽管米兰和赛恩都很壮实，但是他们带着几只大桶是没法走太快的。$b$b他们走的是补给车队常走的路线，从镇子出发，沿着洛克湖的边缘往南走。$b$b只要他们还没走到挖掘场，你就应该可以在路上找到他们。', '和胡达尔谈一谈。', '就算是黑铁矮人也别想阻止我们!$B$B不过赛恩……我从没想过他居然也会是他们的支持者。我们和赛恩共事了将近一年……也许是我疏忽了。$B$B好吧，以后再说这个问题吧。', '', '找到胡达尔、米兰和赛恩', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (281, '夺回雕像', '不久之前，有一艘名叫“盲眼公主”的商船遭到了一群鱼人的袭击。尽管这艘船完完整整地逃了出来，但船甲板上放着的货物都被那些该死的鱼人给拖下水抢走了，其中甚至包括一座十分宝贵的泰瑞纳斯·米奈希尔的雕像。我们希望有人能把这座雕塑给抢回来。$B$B到海岸边的鱼人村落里去，仔细找找看有没有木箱、木桶，或者其他丢失货物的踪迹。在那里找到米奈希尔雕像，然后回来向我复命。', '搜索海边鱼人村落中的木箱和木桶。', '这只木箱上满是爪印，还有被水长时间浸泡过的痕迹。你努力撬开了它，发现木箱中满是水，还有一些腐烂的稻草，似乎这里面曾经装过某些很贵重的物品。你继续在稻草堆中寻找……$B$B……很快，你就发现其中有一堆红色的瓶子。', '你好啊，$N。你是来报告你的搜索进度的吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (283, '水坝危机', '木桶发出了轻微的嘶嘶声。', '拆弹剂看来已经产生了效果。你可以回去向主工程师辛德维尔七世汇报这个好消息了。', '非常感谢你，$N!!你挽救了巨石水坝!没有你的帮忙，黑铁恐怖分子应该已经毁了这座标志性的建筑。你是我们王国和联盟的骄傲，勇敢的$C!$B$B水坝安全了……至少现在是这样的……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (284, '继续搜寻', '你继续在鱼人的村庄中仔细搜索着，但没有找到任何关于米奈希尔雕像的蛛丝马迹。$B$B也许北边和东北边的另两处鱼人村落那会有些什么线索。', '搜索米奈希尔雕塑。', '这个木桶似乎还没有人碰过。你用力撬开了它……$B$B你一下子就被扑鼻而来的浓烈乳酪味给冲了个天旋地转。虽然有点发潮，但这些乳酪的味道似乎还不错!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (285, '搜寻雕像', '你仔细地搜索了这几处鱼人村落，但却没什么有价值的发现。$B$B……但你有一种直觉，就是你在下次搜索中一定能找出一些很有价值的线索。$B$B北边的最后几处村落里一定会有米奈希尔雕像！', '继续在鱼人村落中搜寻米奈希尔雕像的踪迹。', '这只桶半埋在泥土和杂草之中……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (302, '铁环的火药', '如果铁环还需要火药粉的话，以麦格尼的名义，就再给他送一批过去！我已经派了一个信差把我的许可交给塞尔萨玛的吉恩·角盔，让他负责准备火药和其它物资。$B$B还有一件事情：我要你保证亲自把这批火药送达目的地。上一批没有送到，中间也许出了什么岔子，所以这次你得仔细提防着点。', '和洛克莫丹的塞尔萨玛的吉恩·角盔谈一谈。', '什么?勘察员塔伯斯.雷矛叫你亲自护送这批货到铁环挖掘场去?$B$B我……我看这样挺好。唯一的问题是，我已经让胡达尔跟着搬运工米兰和赛恩一起去了。他们刚刚才出发，你正好错过了。', '啊，$N!谢谢你带来的火药许可。勘察员基恩萨.铁环一定会很满意。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (305, '寻找挖掘队', '啊，天呀，你一定就是长须派来的帮手！你真是不知道我有多担心。$b$b我的老婆麦琳上个月的时候每礼拜都会给我写一封信的。她是维尔加挖掘队的成员，她最后一次写信过来是两周前的事了。一定是出了什么事！$b$b长须说，要是我们一直都没有收到挖掘队那边送来的信，那么他就会派出一名探子去看看情况。我猜那个探子应该就是你吧，$N。快去东边的挖掘场里找到麦琳！', '塔雷尔·石纹要求你到挖掘场里去找到麦琳·石纹。', '啊，终于有人来了，真是谢天谢地!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (309, '护送货物', '准备出发了吗，$n？$b$b首先，我们得把炸药粉送到铁环挖掘场。要我一个人运这么多炸药太困难了，这些东西又很危险——而且谁知道那帮黑铁矮人打算对我做什么？$b$b有你跟我一起走，我感觉就好多了。', '确保把米兰和货物送到挖掘场，然后通知勘察员基恩萨·铁环。', '啊，感谢圣光，炸药终于运来了。不过你带来的消息也很让人担忧。黑铁的支持者想要抢了些炸药去实现他们邪恶的计画。$B$B这个问题还是留给别人来考虑吧，我得赶快工作去了。', '我的炸药粉呢，$N?我已经不能再等了!', '护送米兰去挖掘场', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (318, '艾沃沙酒', '雷杰德·麦酒一直以来都亲口试验他自己酿制的酒。有的好喝，有的难喝，还有的连酒量最好的矮人都能轻松放倒。$B$B他住在烈酒村，那地方就在卡拉诺斯的西边。我需要一些他酿造的那种叫作艾沃沙的酒，在寒冷的旅程中，喝这种酒能帮我暖暖身子。$B$B还有……这种酒实在是太烈了，在紧要关头还可以当燃料使，只要把它注入我那坦克车的油箱里，整辆坦克都会爆发出无穷的力量！这个小诀窍让我不止一次地化险为夷。', '从烈酒村的雷杰德·麦酒那里弄到一桶艾沃沙酒。', '贝隆费兹想要一些我酿造的艾沃沙酒?嗯……没问题。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (321, '光铸铁', '这附近的海滩上的船只残骸大多是属于库尔提拉斯第三舰队的，在上一次大战中，那支舰队曾与红龙们在此激战，不幸全军覆没了。$B$B那支舰队里的船大多是洛丹伦的战舰，但有一艘船却不是，那是一艘名叫“飞翔鱼鹰”的精灵驱逐舰。它运着满满一船的光铸铁加入了第三舰队的船队中，本以为这样就足够安全了，结果却讽刺性地落得个被红龙击沉的厄运……$B$B故事就讲到这儿吧，飞翔鱼鹰的残骸就在米奈希尔港的南边。如果你能在那里找到光铸铁的话，就把它给我带回来吧。', '搜索飞翔鱼鹰号的残骸。', '这箱子已经被水泡了很久，有一边还破了个大洞。箱子内外布满了爪痕……似乎鱼人们已经光顾过了这箱子，而且还把里面的宝藏都偷光了。$B$B不过，箱子里面还剩下了一块光铸铁锭。但是如果你想要打造一把武器的话，应该还需要更多这样的金属。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (330, '巡逻时间表', '你给我的便笺上的签名只有一个字母“M”……我也不知道这代表谁。$B$B但是……这便笺同时也告诉我们，这个人应该是上周与索尔森一同巡逻的同伴。所以，只要知道上周谁和索尔森一起巡逻过，那他就应该是内鬼没错了！$B$B去找塞斯曼下士问一问，他是负责制订巡逻时间表的人，可以告诉你那个时候索尔森和谁在一起。', '与塞斯曼下士谈一谈。', '噢，当然，我可以帮你查一下。我看看……上周是……$B$B……嗯，上周是士兵默尔和托尔森一起巡逻的。他们俩上周一直在一起。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (331, '向多伦报告', '多伦上尉不是说要你向他回报关于巡逻时间安排的情况吗？', '与多伦上尉谈一谈。', '没想到竟然是默尔背叛了我们，这太令我痛心了。他一直是个勇敢的士兵，我也一直以为他是忠于我们的。但令人欣慰的是现在终于把他找出来了……有这样一个内鬼潜伏在我们的队伍里，难怪我们一直不敌库尔森上校。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (343, '关于坚韧的演讲', '我正要作一次关于“坚韧的灵魂”的演讲，我想引用一本关于金属学的著作《金属的延展性》里的一些段落。暴风城堡里的皇家图书馆里应该有这本书的副本。你能把它拿来给我吗？如果可以的话，圣光定会保佑你的！$B$B皇家图书馆很大，但首席管理员米尔顿·西弗对每一个书架上有些什么书都了如指掌。告诉他我需要什么，他就会把书找给你的。', '到暴风城堡的皇家图书馆去与米尔顿·西弗交谈，他将会为你找到克里斯托弗修士所需要的关于冶金学的书。', '冶金学?啊，当然，我们这儿有很多关于冶金学的书，我也很愿意帮助克里斯多夫修士完成他的演讲稿!那么……可敬的修士先生要的书名叫什么来着?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (344, '帕克斯顿修士', '《金属的延展性》？是的，我知道这本书。那是本非常好的书，是十几年前一位矮人矿工马戈尔夫·布拉贡写的。他的一生似乎都奉献给了卡兹莫丹的群山，整日在那里挖矿。他是个很聪明的家伙！$B$B但这书在哪来着？哦，对了，《金属的延展性》！这本书被我送到北郡修道院去了。那里的管理员帕克斯顿修士想为他那里的图书馆抄写一份留作副本。$B$B但这是几个月前的事了，我不知道他为什么会花这么长的时间……', '与北郡修道院的帕克斯顿修士谈一谈。', '西弗先生在担心他的书?啊，这真让人为难。这本书是在我这儿，可我还在抄写呢，没法把它还回去。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (345, '墨水短缺', '我也想把《金属的延展性》这本书尽快抄完，但是……$B$B你看看，我只用自己的墨水抄写书籍。这墨水是用我自己的配方制作的，它不容易化开，也不容易弄脏纸，唯一的缺点就是它干得太快了！我的最后一瓶墨水在我抄完之前就用光了，而且我也没法去做新的墨水！$B$B要想再配点墨水的话，我就得先弄到一些赤脊山的瑞斯班铁矿石，一直以来，这种矿石都是由湖畔镇的工头奥斯洛为我提供的。', '与湖畔镇的工头奥斯洛交谈，并向他要一些瑞斯班矿石。', '什么??你难道没看到吗?我们现在都在忙着巩固湖畔镇的城防，修补上次兽人进攻所造成的损坏。如果你需要瑞斯班矿石的话，你最好还是自己去找吧!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (350, '老朋友', '马尔松曾和迪菲亚兄弟会的一个成员进行联系，而且莱斯科瓦公爵似乎也脱不了干系……$B$B在范克里夫和特雷德被杀之后，莱斯科瓦依然逍遥法外，我们手上还是没有他罪行的证据。除了证据问题之外，莱斯科瓦本身就是个神通广大的贵族，这些优势让他得以凌驾于法律之上。$B$B你需要帮助。虽然我并不很情愿走这一步棋，但是的确有一个可以帮助我们的人。你应该到暴风城的贸易区去找提亚斯。', '与暴风城的埃林·提亚斯谈一谈。', '你在开玩笑?肖尔又要我帮忙了?这个该死的……$B$B你是说迪菲亚兄弟会?好吧，你总是会给我带点爆炸性的大新闻过来，不是吗?估计下一次你就要告诉我死亡之翼还活着而且正在攻击这座城市了。$B$B好吧，把这件事情详详细细地告诉我，不要遗漏任何细节，我要了解一切才能知道该怎么办。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (355, '与塞弗伦交谈', '你把阿加曼德家族所有人的遗骸都带来给我了，这完全可以满足我的复仇欲望。但阿加曼德磨坊对我，哦，不仅仅是对我，对我们全体被遗忘者来说仍是个威胁。$B$B我已经把你与阿加曼德家族战斗的事迹告诉了执政官塞弗伦大人，他也希望能和你谈谈。', '与布瑞尔的执政官塞弗伦谈一谈。', '库勒曼对你的评价很高，$N，他说你成功地突袭了阿加曼德磨坊。$B$B被遗忘者如今又需要你的帮助了……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (359, '亡灵卫兵的职责', '我要这里东边的亡灵卫兵驿站立刻给我提交一份最新的报告。$B$B我必须知道天灾军团是否已经迂回绕过了防波堤并进入了提瑞斯法林地。我们要时刻保持警惕，封锁住这里与瘟疫之地的边境，绝对不能让天灾军团占据这里的任何一寸土地！$B$B沿着路向南走，在第一个岔路口转向东，就可以到达驿站了。到那里去找亡灵卫兵林奈，她手里掌握着我最需要的情报。', '与亡灵卫兵林奈谈一谈。', '执政官塞弗伦需要一份报告?情况是这样的:驻扎在防波堤上的军队将天谴军团的大部分士兵挡在了边境外，不过仍有一些漏网之鱼。$B$B我们的确发现了一些零星的天谴军团士兵在驿站以东一带活动，主要集中在巴尼尔农场一带。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (360, '向塞弗伦回报', '现在带着这些情报回到执政官塞弗伦那里去吧。他急需这几份报告，你动作最好快点。$B$B如果你回程的路上看见了任何天灾军团的成员，就顺便干掉他们，我们可不能让这些垃圾在我们的地盘上胡作非为。', '向布瑞尔的执政官塞弗伦报告。', '竟然有天谴军团的士兵通过了防波堤，这听起来真令人担忧。巫妖王与他的喽囉们正在不停地骚扰着我们的领土。$B$B但我们绝不能放弃!不能再让天谴军团得逞了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (363, '突然醒来', '你醒得可真是时候。我们本来还准备把你和其他的死人一起火葬了，没想到你居然醒来了。$b$b我是摩尔多，丧钟镇墓穴的看护人。现在你已不再是巫妖王的奴隶了。$b$b暗影牧师萨维斯就在山脚下的教堂里，去和他谈谈吧，他会告诉你更多你必须了解的事情。$B$B你可以从那段向上的阶梯离开这座墓穴。沿着路一直走到教堂，就能找到萨维斯。', '和暗影牧师萨维斯谈一谈。', '又一个行尸走肉，嗯?走在阴冷的地窖里，只有摩尔多陪伴在你身边，一定让你心惊胆战……$B$B我看到你脸上的困惑了。让我把我们……我们的处境……告诉你。$B$B我们新的领袖希瓦娜斯把我们从巫妖王的统治下解救了出来。黑暗女王领导我们与万恶的天谴军团作战，同时还要应付那些一直跟踪我们的人类。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (389, '巴基尔·斯瑞德', '范克里夫和我过去都曾是石匠行会的成员，我们的主要工作是在战后重新建设暴风城。$b$b当我们完成了自己的职责时，却发现我们被彻底地欺骗了。贵族们拒绝付给我们酬劳，一些石匠行会的元老被提拔成了官员，但范克里夫出于对所有石匠会员的忠诚拒绝了他们。他组织了一场暴动，并离开了城市，从此发誓要进行复仇。$b$b他的副官巴基尔·斯瑞德或许对范克里夫的计划有一些了解，他目前正被关押在监狱里。', '与监狱的典狱官塞尔沃特谈一谈。', '以圣光之名，你来这儿有什么事?你没看见这儿正乱得一团糟么?$B$B巴基尔.斯瑞德!你为什么想要和这个疯子说话?我怎么知道你们是不是一伙的，如果你是想要来这里帮他挑起暴动的怎么办?要不是因为所有该死的牢房都满了的话，我一定会把你丢进其中一间里去待上一阵!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (394, '禽兽的首级', '到暴风城去找肖尔，告诉他莱斯科瓦的问题已经被你解决了。我敢说他一定会为暴风城出了你这样的一位英雄而感到自豪的。$B$B他甚至有可能将你引荐给暴风城里的达官显贵。你要知道，$n，这座城市里还真没有什么肖尔搞不定的事情。贵族们可以自认为他们完全控制着暴风城，但总有一些事情是他们无能为力的。', '去见暴风城旧城区的马迪亚斯·肖尔。', '他已经死了?你的行动果然很快，$N。圣光保佑，可永远别让我成为你的猎物!$B$B<他大笑并拍着你的肩膀。>$B$B我没别的意思，$N。我怎么可能会有那么一天，我可是所有刺客的首领呢!事实上，你为暴风城的人民做了一件大好事，我要为此谢谢你。', '好久不见了，$N。你的任务完成了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (395, '兄弟会的灭亡', '啊，我差点忘了。阿历克斯顿在你离开的时候来过，他有话想跟你说。显然他是想向国王陛下报告关于迪菲亚兄弟会的事情。$b$b给你个忠告，$n。如果有人问到这个，我会把除了你杀掉莱斯科瓦以外的所有细节都告诉他。相信我，我…对这种事…已经习以为常了……$B$B另外，别跟任何人说起提亚斯的事情。', '与暴风城的巴隆斯·阿历克斯顿谈一谈。', '很高兴见到你，$N。我听说葛瑞格.莱斯科瓦大人已经被杀了……$B$B看来，你的任务很成功。你从范克里夫的复仇行动中拯救了我和其他人的性命，我对此非常感激。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (397, '干得好', '我听说维沙克公爵很喜欢他收到的饮料。$b$b你帮了我们的大忙，$N。暴风城的术士们从此可以不再受他人干涉地自由行事了。我准备了一件特殊的小礼物给你，以表示我们的感谢。去找我的仆人兹吉，收下你的报酬吧。', '去找黑爪加尔德斯的仆人兹吉谈一谈，并向他索要你的酬劳。', '主人说要把礼物给$N。兹吉想留下漂亮的礼物，但兹吉不能背叛主人的命令。', '嗯?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (401, '等待希拉完工', '我很快就能把信件翻译完了。请稍等一会儿再过来吧。', '稍等片刻，然后再和希拉·沃宁迪交谈。', '完成了。它的意思是……$B$B<空气突然变得凝重，仿佛有一层黑暗厚重的幕布笼罩着大地……>', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (403, '戒备森严', '', '', '这桶麦芽酒由加文.雷酒看管着。只要他在地窖里，谁都别想碰这些麦芽酒桶。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (415, '雷杰德的新酒', '烈酒村的雷杰德·麦酒正在找你。$B$B他要和你谈谈他最新正在酿造的一种酒……他告诉我你帮了他很多忙。你也许应该去一次烈酒村，看看他要说什么。$B$B也许，你可以在那里免费享受到一顿大餐……', '和雷杰德·麦酒谈一谈。', '$N!还记得你带给我的微光草吗?我用它实验了几种酿酒配方，有一种的效果非常好!$B$B品一口看看，然后告诉我，你觉得口味怎么样?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (419, '失踪的驾驶员', '我的朋友，同时也是同一蒸汽坦克车组的同事——莫里·铁钻，在山上失踪了。我们当时正在寻找一种可以用来制作高爆炸药的稀有矿石。在我们搜寻的过程中，莫里驾驶着他的坦克攀上一处陡峭的山坡后抛锚了！$B$B他确信矿石就在这片山地里，所以就让我守着我们的机车，而他一个人步行继续去搜索。$B$B莫里已经有好些天没回来了，夜里我时常能听见山中的野兽发出的咆哮。莫里是个硬汉，不过我还是有点为他担心。$B$B求求你，$N，帮我找到他。', '找到驾驶员莫里·铁钻。', '这里有一具伤痕累累的矮人尸体，已经完全被冻住了，而且被食腐动物撕咬得不成样子。在它的手里是一本由莫里.铁钻草草写下的日记。这本日记保存得很好，因为它被包在一件坦克驾驶员军用外衣里。$B$B这里一定是那位攻城机具的驾驶员遇难的地方。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (428, '失踪的亡灵哨兵', '几周前，亡灵哨兵兰妮·尤瑞克和奎恩·尤瑞克被派遣到银松森林北部去执行一次侦察任务。可我们一直没有再得到他们的消息。$B$B也许他们已经成了天灾军团的牺牲品。当然，我仍然希望有人能去确认一下，你去找到这两名亡灵哨兵。$B$B他们最初的任务是去侦察银松森林北边的农场，你可以从那里开始搜索。', '找到亡灵哨兵兰妮·尤瑞克和奎恩·尤瑞克。', '你找到我们了!虽然迟了点……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (431, '诱灵蜡烛', '', '', '你拿了一根蜡烛并把它放进了你的背包中。', '木箱中整齐地摆放着一排诱灵蜡烛，你得从中取出一支来召唤莉莉丝.奈法拉。$B$B你要拿起一根蜡烛吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (435, '护送埃兰德', '外面的狼群看来是不想离开了，而且我每次走出屋子的时候，它们都恶狠狠地盯着我。这些野狼显然是饿极了，它们把我当成了大餐！$B$B我得通知我的队友，亡灵哨兵兰妮·尤瑞克。也就是说，我要到她那里去，得先找人帮我搞定这群狼。$B$B请护送我吧！不过，这边的狼也实在是多了点，如果你还有别的朋友的话…再好不过……', '护送亡灵哨兵埃兰德避过群狼，直到他找到兰妮·尤瑞克。', '多谢你的帮助，$N。我正担心埃兰德在银松森林里遭遇不幸了呢。幸亏有你帮忙，我才放下心来。', '请说得尽量简短点。这太危险了，我们可没法站在这里悠闲地聊天。', '埃兰德必须到达兰妮·尤瑞克身边', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (436, '铁环挖掘场', '勘察员基恩萨·铁环正在负责挖掘洛克湖东边的一座古老的废墟。虽然我们已经给他送去了不少物资，但是他那里最近进展非常缓慢。$B$B基恩萨·铁环是一个顽强、诚实而精干的矮人，没理由会如此懈怠，所以我担心他那儿出了什么问题。$B$B到铁环挖掘场去问问麦格玛尔·落斧，他负责挖掘场的琐事，一定知道那里到底是怎么了。$B$B你要可以从湖的南端绕过去，然后一直向东走，就可以到挖掘场了。', '和麦格玛尔·落斧谈一谈。', '吉恩想知道为什么进展缓慢，是吗?铁环已经把最近的情况写进了一份详细报告里，不过我可以简单地告诉你:$B$B是穴居人在作祟!!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (438, '破旧渡口', '$N，我们最近发现了天灾军团的一个新据点：破旧渡口。这处渡口就在瑟伯切尔的东方，有许多腐皮豺狼人和其他亡灵层层守卫着那里。$B$B天灾军团占据了那里，这其中一定有些什么阴谋。到破旧渡口去调查一下，看看为什么天灾军团会在那里。', '到破旧渡口去，找到天灾军团占据那里的理由。', '这艘小船中装满了尸体。你抬头向东边看去，发现在洛丹米尔湖中央的芬里斯岛上也有一个码头。$B$B这些尸体应该是要被运到芬里斯岛上去的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (448, '给哈德瑞克的报告', '在你展开对芬里斯岛的攻击之前，先向高级执行官哈德瑞克复命吧。他或许还有些额外的装备或者情报要给你。', '向瑟伯切尔的高级执行官哈德瑞克复命。', '如果比索说的是真的，那么图勒.鸦爪恐怕真是一个不容我们忽视的家伙了，我们得尽快把他消灭掉。$B$B为了帮助你完成好这个任务，你可以从我们的军械库里拿些东西。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (452, '焚木村中的伏击', '你来得正好，$N！$b$b焚木村议会随时都有可能回来，而阿鲁高此时正好无暇顾及这里。他利用议会作为傀儡控制着焚木村中无知的村民们，我相信如果没有议会的引导，阿鲁高的奴隶们一定会反戈一击，背叛他们的主人。$b$b我无法独自应付他们所有人。我需要你的帮助，只要齐心协力，我们一定能为希尔瓦娜斯主人消灭焚木村议会。', '帮助亡灵哨兵费雷亚消灭焚木村议会。', '你就像一名黑暗女王的真正仆从一般勇敢战斗，$N。议会已经完蛋了，也许我们能完全控制这里，并将阿鲁高彻底驱除出影牙城堡。向你致敬!', '', '帮助费雷亚消灭焚木村议会。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (454, '恶战之后', '在这事之前，我们一直在来来回回拖着这几个装着火药的桶往挖掘场运。现在我们得分工一下，米兰负责搬这些桶，我负责搬其它的。$b$b不过让米兰一个人运送剩下的货物我多少有点不放心，你能不能在他下次送货的时候护送他一程呢？', '和米兰谈一谈。', '你好，$C。$B$B你要护送我去挖掘场吗?很高兴听到这个消息……天知道在赛恩和他的亲信之外，黑铁还策划了哪些阴谋?$B$B不管怎样，让我收拾一下，你准备好了就跟我说一声。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (458, '森林守护者', '谢天谢地你在这儿，$c。森林中的小精灵们告诉了我一些奇怪的消息。$b$b神秘的森林守护者塔琳德拉又回到了幽影谷。这位树妖的身影已经许多年都没有在卡利姆多大陆上的森林中出现过了。她既然回到了这里，就意味着这里一定出了什么事情。$b$b找到了塔琳德拉，并且问问她我们的森林到底怎么了。有个哨兵向我报告过，塔林德拉曾在奥达希尔的西边出现过。', '找到树妖塔琳德拉。', '我知道你在找我，年轻的$r。麦利萨尔派你来证明了他的睿智。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (463, '绿色守卫者', '你听说过绿色守卫者？你应该不是在找他吧，是不是？如果是的话，我真得说你是个疯子，不过我为什么要阻止一个疯子去找他送死呢？$B$B好吧，如果你真是在找那只凶兽的话，我听说它就在沼泽里，在通向丹莫罗的那个岔路口的东边。他就潜伏在那个危险的地方，在鳄鱼群之间……听说那里还有些更可怕的东西！$B$B把你的钱留在这里吧，要是你去找他，钱对你来说也就没用……你该不会想在那家伙咬你的时候用你的金币给他镶金牙吧？', '找到绿色守卫者。', '树木与小草都在赞扬你，渺小的$R。尽管我有着许多的名字，但我只会回应其中的一小部分，你可以叫我雷希耶尔。$B$B你必须仔细聆听……为了这片满目创痍的大地，我必须得指派你去医治它的创伤。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (467, '迪恩·石轮的梦想', '驾驶员迪恩·石轮和其他驾驶员一样非常喜欢他的攻城坦克，他一直都想要找到加强坦克火力的方法！$B$B他听说有一种罕见的矿石，现在正在到处拉人为他寻找这种矿石呢。如果你想找点事干的话，就去丹莫罗的钢架补给站找他，看看他都需要些什么。', '和驾驶员迪恩·石轮谈一谈。', '你好啊，$N。你是来帮我忙的?很高兴看到像你这样一个年轻的$r能为了冒险而热血沸腾啊!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (468, '向巡山人罗克加报告', '巡山人罗克加正在招募一些能穿越丹奥加兹到湿地去执行任务的志愿者。$B$B如果你想去北边感受一下鞋子里灌满水的感觉，那就到丹奥加兹去找罗克加谈谈吧。沿着道路向北，走过哨塔就到丹奥加兹了。', '与巡山人罗克加谈一谈。', '你好，$C!你来这里是打算接下侦察任务的，对不对?非常好!$B$B我希望你的装备补给什么的都没问题，因为这次的「侦察」任务似乎并不如你想像得那么简单……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (472, '丹莫德的陷落', '丹莫德已经被黑铁矮人攻陷了！$b$b我伤得很重，$c。我们的大多数战友都已经牺牲了！我们在萨多尔桥遭遇了伏击，正在重整部队的时候，那群该死的黑铁矮人再度突袭了我们。$b$b我们的领袖布莱德·长须被迫吹响了撤退的号角。我们刚一离开镇子，我就被人从背后砍了一斧子，然后就眼前一黑昏死了过去。$b$b当我醒来的时候已经身在米奈希尔了，但是，我现在很担心我手下的士兵们。我依然保有一丝希望，也许布莱德·长须还活着！看看你能不能在丹莫德附近找到他吧，$c！', '在丹莫德镇附近寻找布莱德·长须的踪迹。', '勇敢的$C，你从米奈希尔带来了消息?啊，他们叫你$N。$B$B你给绝望的我们带来了希望，那就是年轻的哈尔罗还活着。当时他正在撤退，却遭受了重伤，这的确非常令人揪心。我们只好急匆匆地将他搬上了军中最后一匹战马的背上，送他离开了战场。$B$B但现在我们仍然面临着一个非常糟糕的局面。丹莫德已经陷落，而我们的大军也已经不复存在了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (473, '向斯托菲队长报告', '$N，龙喉氏族的兽人们一天天地壮大了起来，这样下去它们迟早会攻破奥加兹的。斯托菲队长正在诚招志士来对抗那些兽人，他就在城堡里面的指挥室中。', '与斯托菲队长谈一谈。', '$N，瓦斯塔格已经跟我简单地说过你当初是如何成功地在龙喉兽人的眼皮底下穿越丹奥加兹的了。对我们来说，你真是个非常有价值的$R。$B$B我有个任务要托付给你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (475, '烦恼之风', '一阵令人烦恼的微风吹过了森林。$b$b盖洛拉斯·塔文斯伦一直负责为那些在班奈希尔兽穴中休眠的猛禽德鲁伊们放哨。作为沉睡者们的保护者，他的职责是确保德鲁伊们的安全，从而使他们可以履行与伊瑟拉定下的契约。$b$b但是我很久都没有收到盖洛拉斯的消息，现在我已经越来越紧张了。到东边的星风村去一趟，帮我把盖洛拉斯的报告带回来，这样会让我心里轻松一些。', '在星风村找到盖洛拉斯·塔文斯伦。', '感谢森林之灵，终于有人来了!我知道阿斯瑞达斯会感觉到这里有了麻烦，而且会及时伸出援助之手……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (476, '瘤背熊怪的堕落', '瘤背部族的熊怪已经堕落了！$b$b曾经爱好和平的熊怪现在转而与森林的保护者为敌。我刚刚动身准备去班奈希尔兽穴的时候就遭到了它们的伏击，而熊怪们现在还准备掠夺星风村！它们的首领——大槌乌萨尔——正在运用魔苔的邪恶力量使它们变得更加疯狂。$b$b我伤得太重了，无法返回去把这个十万火急的消息告诉阿斯瑞达斯。这个任务就交给你了，年轻的$c。我们只能希望疯狂的瘤背熊怪还没有对班奈希尔下手！', '返回多兰纳尔去见阿斯瑞达斯·熊皮。', '以众星之名!这确实令人非常不安!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (477, '越境', '你也许知道，安伯米尔镇里还有一群人类在负隅顽抗，事实上，这主要是因为达拉然的法师们在支援着他们。$b$b我不知道他们到底有什么计划，不过我想，既然他们对这样一个偏僻的小镇表现出如此浓厚的兴趣，那么这个地方一定有什么还不为我们所知的重要意义。$b$b法师们隔三差五地用马车把一些木箱从希尔斯布莱德运到安伯米尔去，他们补给线的终点就在焚木村北面的一处营地里。帮我把木箱里的东西拿来一些，让我好好研究一下。', '从达拉然法师的木箱中拿出里面的东西。', '<小心地打开了木箱盖之后，你发现了一些摆放整齐的东西，它们都被仔细地包裹着。最上面是一捆地图，因为年代久远，纸张已经有些泛黄了，这些地图绘制的是银松森林一带，以及西罗德隆的其他一些地区。$B$B地图的下面则是一个神秘的魔法坠饰。>', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (482, '达拉然的意图', '啊！我想起来了！$B$B安伯米尔一直是为肯瑞托所关注的地方，因为那里隐藏着一个能量节点。那群法师们一定计划启动节点，并使用里面蕴涵着的能量来为他们更深一层的目的服务。$b$b我们不能允许这样的事情发生……$b$b启动节点需要花费大量的魔法能量，只要我们把这些坠饰抢走，达拉然的法师们就无法继续他们的行动了。$b$b把这件事告诉奥利斯特，他会制定出行动计划的。', '与瑟伯切尔的暗影牧师奥利斯特谈一谈。', '这真不是个好消息，$N。如果达拉尔的推测没错的话─他一向不会出错─我们就必须快点行动了。$B$B我必须先和他谈谈，再制订一个袭击计画。但是与此同时，我们得让达拉然法师们的计画进程慢下来。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (494, '进攻的时机', '嘘！安静点，仔细听我说，$c。$b$b我被派到这个地方来监视希尔斯布莱德镇里的人类的动向，你必须把我的口信带给塔伦米尔的高级执行官达萨利亚，跟她说一句：$b$b“西边传来乌鸦的第三声叫声。”$b$b沿着大路往东走，注意看路标。快点！赶快去塔伦米尔，这件事情很紧急！', '到塔伦米尔去，把亡灵哨兵莱什的口信带给高级执行官达萨利亚。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (495, '意志之冠', '希尔瓦娜斯殿下曾派出玛格索尔和他的食人魔手下们前往奥特兰克去夺取意志之冠。然而，不幸的是，他们并没把它还回来，那个白痴竟然把它戴在了自己的头上……我猜这群食人魔恐怕对这种亮闪闪的东西没什么抵抗力吧。$b$b无论如何，他这种自作主张的行为已经酿成了大错。想必是意志之冠操控了他，令他背叛了希尔瓦娜斯殿下。$b$b黑暗女王陛下希望我们处理掉愚蠢的玛格索尔，以此来警示其它不识时务的蠢货。到希尔斯布莱德丘陵的塔伦米尔镇去，向我的部下梅里萨拉报到。', '到希尔斯布莱德丘陵去，向塔伦米尔的梅里萨拉报到。', '你来得正是时候，我想我们没有时间聊天了，$B$B玛格索尔是个很大的隐患，我们必须赶快把他除掉，当然，办事也要以稳重为先。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (506, '布莱克摩尔的余孽', '一两天前，辛迪加的首领来找过我。他叫奥里登·匹瑞诺德，他声称自己是这片土地的领主。他向我吐露了他的计划，说要把反对他的那些兽人都变成奴隶，就象他的父亲和导师埃德拉斯·布莱克摩尔所计划的那样。$b$b更重要的是他还带着他的小情人，一个名叫艾丽萨的娇弱女孩。酋长想得到她脖子上带着的项链。$b$b现在你可以回去报信了，等手头上的事情忙完之后，我会自己回去的。', '把高迪尔收集的消息带给塔伦米尔的克鲁斯克。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (538, '南海镇', '$N，如果你不介意多跑点路的话，我有件任务给你，好为我们的暴风城图书馆增加一些书籍。$B$B古代王国奥特兰克在大战之后就已经衰落了，但那里有着大量的藏书。奥特兰克的都城被毁实在是个悲剧，但如果他们的知识也失传了的话，那就将是个更大的悲剧！我们必须竭尽全力地挽救我们能挽救的东西。$B$B南海镇是最接近奥特兰克废墟的地方，到那里去找博学者迪布斯吧，他会告诉你在哪里可以找到书。', '与南海镇的博学者迪布斯交谈。', '啊，对，我记得密尔顿。没错，那家伙是个大书虫。愿圣光保佑他。$B$B他说得对。奥特兰克废墟中的确还有许多书卷有被毁的危险!$B$B现在有许多巨魔占据了奥特兰克，而且，他们可丝毫不关心学习和研究什么的。', '你好!你一看就不是本地人，是个修行中的学徒吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (561, '法尔林的证据', '请告诉法尔林·奥里涅尔中尉，我觉得他应该把注意力重新集中在滋生于东部海滩的纳迦身上。告诉他，一旦有什么进展，就亲自来向我汇报。', '和南海镇的法尔林·奥里涅尔中尉谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (583, '欢迎来到丛林', '欢迎来到荆棘谷！$b$b也许你没有注意到，那边的那位矮人就是联盟的大英雄、顶级猎手赫米特·奈辛瓦里的儿子。和他父亲一样，他并不欢迎陌生人来这个营地，不过你看上去已经见过大世面了，$c。$B$B去和他谈一谈吧，或许他能教你些狩猎的技巧。', '与赫米特·奈辛瓦里二世谈一谈。', '很高兴认识你，$N。已经很久没有$C来过这里了。$B$B我来这里只有一个目的:就是猎杀更大更狡猾的野兽。既然你是个英雄，我也很乐意让你参加这里的狩猎，但首先你必须得证明自己的能力。$B$B我会教你如何猎杀迅猛龙。艾耶克会教你如何猎杀老虎。而艾尔加丁爵士则是一位优秀的猎豹者。$B$B证明了你的能力之后，我将会允许你参加这次大狩猎。', '嗯?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (588, '耶尼库的命运', '<奈兹里奥克开口说话了>$B$B现在，我会告诉你关于你所寻找的那个耶尼库的事情……$B$B年轻的耶尼库和他的氏族失散了。$B$B他被巫医赞吉尔给带走了。现在赞吉尔控制了他的身心，只有一种极端强大的法术才能使他恢复自由之身。$B$B而你肯定没有这种法术，$c。$B$B或许你暗矛部落的朋友们有办法拯救耶尼库，不过我对此也相当怀疑。', '与肯维雷谈一谈。', '『流亡者』赞吉尔??$B$B要是耶尼库真是被那个邪恶而强大的巫医给控制着，恐怕要拯救他就真的只有那么一点点希望了。见鬼，这希望简直等于是没有。$B$B但是，毕竟还是有那么一丁点希望的……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (590, '潜行者的交易', '什么？$B$B什么？！$B$B你要钱？我可不欠你什么钱。$B$B信？什么信？哦，你是不是想打架？好吧，朋友……放马过来啊！', '打败丧钟镇的卡尔文·蒙泰古。', '让人难以置信!你真有两下子!$B$B我以为你肯定会是我的手下败将呢，$N。你确实打败我了。$B$B这是我答应给你的钱……没我说的那么多，不过总比没有好吧，对不对?', '不错啊，朋友……干得真不错。', '击败卡尔文·蒙泰古', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (594, '瓶中信', '这张便笺上有极漂亮的字迹：$B$B致任何能帮助我的人$B$B拜托，我迫切地需要帮助。一只巨大的蓝鬃猩猩将我囚禁在了南海的一座岛屿上。$B$B这里夜晚的星象我以前从未见过，岛上全是茂密的丛林，但在天气晴朗的时候，我能看见西北方的蛮荒的海岸，还有几条大船在向西南航行。$B$B求求你，请帮帮我吧。', '找到瓶中信的作者。', '你是来救我的吗?', '我不慎被囚禁，这实在是愧对我的祖先与部族。除非有谁能帮我拿下这些镣铐，否则我没有任何逃离这里的希望。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (595, '血帆海盗', '你看起来特别像要找份活干似的，伙计。虽然我不清楚为什么一个喜欢在平地上过日子的$r$c会愿意帮助我们这些黑水强盗，但我不会阻拦你的。$b$b我们的船就停泊在藏宝海湾，而我们的死对头——那些该死的肮脏的血帆海盗——正在整个荆棘谷南部胡作非为。$b$b现在我们这里的人不是抱着酒瓶子就是抱着姑娘！我需要一个探子来帮我做事。$b$b去侦察一下野人海岸上有些什么，没错，就是藏宝海湾北边的那片沙滩。', '大副克拉兹要求你去侦察一下藏宝海湾北边的海滩。', '你在小艇中发现了一张写着潦草文字的地图与一些钱币。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (597, '血帆海盗', '这是一张藏宝海湾的地图，上面用红笔标叉的地方就是你现在站的位置。$b$b图上潦草的写着几行字：$b$b“你们的任务就是悄悄地在此地扎营，等待南方指挥部发出信号后再开始攻击。如果任何人试图阻碍你们，格杀勿论。”', '将你的发现报告给藏宝海湾的大副克拉兹。', '当然，我正等你呢，$C。让我看看你的发现……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (599, '血帆海盗', '太令我吃惊了！那么血帆海盗正计划着进攻藏宝海湾吗？这群发了神经病的恶棍当真是不要命了么，藏宝海湾永远都是我们黑水海盗的地盘！$b$b这事比我想得还要严重。马上将你所知道的一切报告给舰队指挥官卡拉·海角！这群该死的海狗可能已经开始在镇子外面集结了……', '把血帆海盗的计划报告给舰队指挥官卡拉·海角。', '血帆海盗计画攻击藏宝海湾?看来他们已经离开了望海崖。虽然现在情况不容乐观，但你带来的这条宝贵资讯实在是帮了我们舰队的大忙。我代表黑水强盗感谢你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (603, '安斯雷姆的钥匙', '嗯，拥有那块石头的法师一定通过在某处集中力量来加强他的魔法效力……比如在某个祭坛上。按理说你应该可以用更强大的力量去瓦解它。$b$b就目前的情况而言，我知道有件物品可以派上用场：巨魔一族失落的另一件神器，一把远古匕首。但是，还有一个……只有一个……小问题。$b$b你知道，我过去在荆棘谷进行研究的时候得到了那把匕首，但我把匕首给了我那任性的女儿，她叫凯特琳。她现在已经去了藏宝海湾，也许是真的想当个海盗吧。', '与藏宝海湾的凯特琳谈一谈。', '我的匕首?你是干什么的，喜剧演员吗?$B$B什么?当初我可是藏宝海湾第一刀客，如今却沦落成海贼们的笑料，难道你还要我把那可悲的过程重复一遍么!$B$B我在一次斗刀的时候输给了一个血帆海贼--真是群好朋友啊!--而他拿走了我的匕首作为战利品。$B$B做为一个刀客我实在无法容忍这种羞辱和讽刺……', '你最好不是来挑战我的，你没听说过吗?我已经决定不再参加任何决斗了。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (615, '船长的弯刀', '我的第一条船被那些海巨人们搞沉了之后，我只好买了第二艘，而且给它起名为“斯莫特的复仇”。我为它配备了新的装备和船员，并出发去寻找那些该死的巨人。我找到了他们，但……他们又一次击败了我们。他们把“斯莫特的复仇”号给打成了碎片，船员也几乎被他们杀光了，但那帮混蛋却把我丢在了一条救生艇上，让我一个人漂了回来。$B$B这次，那些海巨人中的另外一个偷了我的弯刀。$B$B到奈古拉什那里去把我的佩刀给抢回来！$B$B去和斯普罗格谈谈吧。他本来是“斯莫特的复仇”号上的厨子，沉船的时候他也幸存了下来，我想他能帮你们找到那些', '与斯普罗格谈一谈。', '你好你好，$N。船长大人跟我说你要去找奈古拉什的晦气，呵呵，是真的吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (616, '幽灵岛', '大财主里维加兹让我留意最近在藏宝海湾和荆棘谷附近流传的古怪传闻。虽然我平时是绝不会关心什么鬼故事的，但这两天在酒馆里听一些水手们说在海岸附近有一座闹鬼的小岛。据他们说，那上面全是水元素和一只整日说着疯话的地精的鬼魂。$b$b如果你正好要去见里维加兹阁下的话，能替我将这件事转告给他吗？', '与藏宝海湾的大财主里维加兹谈一谈。', '有趣。我记得我前一阵子读的一本书上提到过……$B$B啊，当然，那本书写的是食人妖的传说。如果克拉兹克的报告是真的，或许我马上就能将海潮之石纳入我诸多的古董收藏品之中了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (624, '科泰罗的谜题', '有一座装饰华丽，人来人往的桥$b逆风径东，赤脊山南面之地$b在那之下，它正等待着你$b这可以叫提示，也可以叫线索$b在那里，无尽的明天正等待着你$b在悲伤沼泽之中静静地等待着你', '解开这道迷题！', '你找到了一张发霉的卷轴。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (625, '科泰罗的谜题', '卡利姆多上的某个遥远之地$b危险湮灭了命运与希冀$b贫瘠之地以东的环境糟糕至极$b绝望与威胁伴着沼泽中的尘泥$b但那里埋藏着线索供你寻觅$b在西南的一处洞穴中可解此谜题', '解开这道迷题！', '你找到了一张发霉的卷轴。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (626, '科泰罗的谜题', '到洛丹伦去！那片混乱中的土地$b在那里，勇敢的战士们与亡灵为敌$b在剧烈的动荡中寻找属于你的路途$b最终你会解开这谜题$b沿着鹰巢山峦，位于瀑布之底$b波光之下的宝藏正等待着你', '解开这道迷题！', '你找到了一张发霉的卷轴。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (631, '萨多尔大桥', '当时，山里突然传出了一阵巨大的爆炸声，而且在山谷中回荡了很久。那简直太可怕啦！$b$b士兵们为了守卫萨多尔大桥死伤惨重。长须说我们总有一天要向黑铁矮人们复仇的。$b$b我们目前的情况非常窘迫，而且暂时也得不到任何援军。长须派了老伊本瑟去侦查东边的那座桥，看看我们是否有机会攻陷那里。$b$b可这已经是好几天以前的事了。丹莫德目前全城被围，我们根本无法抽出人力去联络他。$b$b或许你能帮忙去找他……', '拉格·加玛森要求你找到老伊本瑟。', '你搜索了一下那具身材瘦小的矮人尸体。他的盔帽上刻着他的名字:伊本瑟.锈铁。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (634, '请求援助', '我想拜托你再帮我一个小忙，$c。我们正等待着来自铁炉堡的援军。但是，罗戈说阿拉希高地上的避难谷地那里还有一处联盟的营地。$b$b到那里去找尼艾丝队长吧。问问这位善良的队长，看联盟是否能派一些暂时没有任务在身的士兵来帮我们夺回丹莫德和萨多尔峡谷。', '去阿拉希高地避难谷地找到尼艾丝队长。', '请先允许我为长须和他手下英勇无畏的士兵们表示敬意并对他们同伴的死表示哀悼。在听到萨多尔大桥惨剧与丹莫德陷落的消息时，我的内心感到十分沉痛。$B$B但是，激流堡也被攻陷了!因此我们才会被迫退到避难谷地这里来。我们必须夺回由我们的祖先亲手建造出的伟大城市。$B$B因此，无论是从荣誉还是责任的角度来看，在国王陛下的旌旗重新飘扬于激流堡之前，我们都不能离开这片高地。我会给长须写一封信说明他只能靠自己了……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (635, '山中的水晶', '你拿着这块碎片，明显地感觉到它在跳动着……$B$B你感到它在祈求，好像有什么人想要与你交流，急切地需要你的帮助。$B$B你的脑中出现一幕奇特的影像——在阿拉希的北部山脉上，有一块明亮的水晶从地面上突出来。$B$B你感觉到自己仿佛被带到了那个地方……', '找到你在幻觉中看到的那块水晶。', '啊，你找到我了!$B$B求求你，善良的$g先生:女士;\n，我请求你帮助我。我被囚禁了，而囚禁我的人永远也不会释放我!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (636, '大地公主的传说', '这本书叙述了元素公主密斯莱尔和她被囚禁在阿拉希高地下面的故事。$B$B它还叙述了高地里的一处秘密的水晶岩层。这些被称为“密斯莱尔水晶碎片”的东西是囚禁大地公主的监狱的窗户。$B$B如果某个勇敢的人能找到密斯莱尔水晶碎片，那么$g他:她;\n就有可能和她交谈……', '找到密斯莱尔水晶碎块。', '啊，你找到我了!$B$B求求你，善良的$g先生:女士;\n，我请求你帮助我。我被囚禁了，而囚禁我的人永远也不会释放我!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (638, '巨魔之敌', '随着索拉斯·托尔贝恩的死与激流堡的毁灭，沃金大人指示我们要不惜一切代价将那把传说中的宝剑托卡拉尔从人类的手里抢过来，供我们在与祖尔格拉布的巨魔的战斗中使用。$b$b我们已经派出了一个名叫森谷的资深猎人前往阿拉希高地东北部的落锤镇去寻找它。', '前往阿拉希高地的落锤镇，与森谷谈一谈。', '你好啊，$C。沃金大人交给我们的任务确实不容易，你对我们的任何帮助都是必要的，我先谢谢你了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (648, '拯救OOX-17/TN！', '那个侏儒的声音再次从那个机器人中传了出来：$B$B“我需要你帮忙把OOX-17/TN移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到，靠近时光洞穴那里去！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”$B$B“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”', '安全护送OOX-17/TN到达目的地，然后向藏宝海湾的奥格索普·奥布诺提斯报告。', '哦，你是OOX-17/TN的伟大救世主!我简直无法用言语来表达对你的感谢!如果让我自己重新构造一个母体机器人的话，无疑要浪费大量的时间，你真是帮了我的大忙，不仅节约了我的时间，同时也节约了我的钱!$B$B请从这些东西中选择一样你中意的吧。再次感谢你无私的帮助，我的机器人和我都欠你的人情!', '没错，我就是奥格索普.奥布诺提斯，世上最强的发明家，随时为您效劳!现在，我能帮您什么忙吗?', '将OOX-17/TN安全护送到目的地。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (649, '寻找蜜酒', '我这有些事情要你来做，如果你和我一样是蜜酒的爱好者，那我敢说你一定会接受这项任务！$B$B蜜酒当然是一种酒，你这个蠢货！$B$B在一座被部落废弃的村庄那里有很多的辛特兰蜜酒，这些蜜酒是以前那里还有人做生意的时候留下的，那绝对是极品的蜜酒！玛尔顿的手下知道这个村庄的具体位置，我要你去那里一趟，给我带一些蜜酒回来！和玛尔顿谈谈吧，他会给你进一步指示的。', '和奥格瑞玛的玛尔顿·杜佛斯谈一谈。', '哦，没错，我父亲最喜欢蜜酒了!他想要把蜜酒卖给奥格玛的酒馆，如果那些蜜酒是原装货的话，肯定可以卖个大价钱。我知道谁能帮我们，他就在辛特兰，但是他是一个……高等精灵。$B$B不管怎么样，他是个很好心的高等精灵，他不是人类联盟的成员。好吧，他不是一个完美的高等精灵，因为……他是个酒鬼，一个真正嗜酒如命的家伙。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (650, '寻找蜜酒', '你得去跟那个名叫基沃拉丁·猎日者的精灵谈谈。他只需闻一下就可以辨别任何一种葡萄酒！他可以帮我们弄到蜜酒。嗯……我们需要至少六瓶包装好的蜜酒，其中两瓶是给爸爸的，至于他实际上需要多少瓶倒无关紧要……当你打包好了蜜酒，并且搞到了给爸爸的两瓶蜜酒之后，就回到我这里来！$B$B基沃拉丁的营地在辛特兰的高等精灵大屋附近，不过那些高等精灵不太友善……相信我。', '和基沃拉丁·猎日者谈一谈，他的营地就在辛特兰区域。', '啊，那么说来你认识玛尔顿?他是我的老酒友了。你也看到了，我已经找到了超越那些人为定制的条约和联盟关系的东西─那就是酒。如果我们刚刚都畅饮了这种美味的饮料，那我们现在都会精神焕发。$B$B唉，看来你找我并不是为了学习酒类的价值，那我们现在就开始说说你的问题吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (653, '密斯莱尔的盟友', '<密斯莱尔开始说话>$B$B自由！我自由了！我终于自由了，我要恢复力量，不过现在我还得躲避那些追捕我的敌人。因为如果他们现在找到我的话，肯定会轻松将我降服并重新监禁我。$B$B总有一天我会回到那些巨人的面前，让他们为禁锢我的行为而后悔！$B$B你是一个高尚的盟友，$N。我会再次需要你的帮助。等我准备好之后，我需要你来将我召唤到地表上。$B$B去和铁炉堡的葛利·硬骨谈谈吧，他知道如何召唤我。', '和铁炉堡的葛利·硬骨谈一谈。', '$C，大地公主和我说过你要来找我。欢迎你来到我的住所，你和我一样，都有着更高的目标。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (655, '落锤镇', '一切是那么的清晰，似乎就发生在昨夜……那么多年了，从来都看不到任何希望，却有重重的木枷和钢索将我们的族人束缚在这个可怕的地方。终于，终于！奥格瑞姆酋长回来解救我们了！他像座铁塔一样站在那里，穿着那套如午夜一般漆黑的战甲，将他的战锤高高举起。$b$b那……太恐怖了……那懦夫的一击居然击倒了我们最伟大的英雄。那个懦夫骑着战马，手持长矛向他刺去……我跪倒在地。哪里才有希望？哪里才有希望……', '和落锤村的托尔甘交谈。', '啊，你是说戈莫尔啊。没错，看来他依然无法从对末日锤战死的悲伤中恢复过来。$B$B当索尔和奥格林为解放这里作战的时候，戈莫尔正是这里的俘虏。但当大地开始震动，我们向外逃离这里的时候，他却落单了。他漫无目的、毫无方向地一个人独自游荡了很多年，直到我们来到落锤村并在这里建立了属于自己的家园。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (657, '新的瘟疫？', '<奎艾开始仔细地阅读这份文件>$B$B这很有趣。看起来药剂师乔瑞尔正在格沙克农场里进行着一些危险的试验，很难说这和希尔斯布莱德有什么牵连，不过我看最好还是别让他得逞。$B$B你走了以后，我们看见有一些兽人跑了进来，不过我没有足够的实力去帮基恩洛的忙——她要到农场里去偷取乔瑞尔的那些还没有送往塔伦米尔的研究资料，你能协助她吗？', '和阿拉希高地中格沙克农场附近的基恩洛谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (659, '新的瘟疫？', '欢迎你，$N。我带着一群探险者到这里来调查最近发生的一些怪事。$B$B我在希尔斯布莱德有个堂兄，他最近杀掉了家养的那只名叫斯坦雷的狗，因为这只狗突然长得很巨大，而且还野蛮地攻击所有靠近它的人。$B$B我想这一定和亡灵有些关系，我们正在寻找能证明这个猜想的更多证据。$B$B我的两个同伴奎艾和基恩洛到阿拉希高地上的格沙克农场去了，最近这些天一直没有她们的消息。你能帮我找到她们吗？我越来越担心了……', '到阿拉希高地上的格沙克农场附近找到奎艾和基恩洛。', '旅人，请你尽量保持安静。$B$B监视兽人们的活动可不是件容易的事，农场里隐藏着的秘密远比我们所看见的要多。', '希尔斯布莱德到处都是一片混乱，这让我十分担心。$B$B在我前往侦察的同伴回来以前，我是不会离开这儿的。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (660, '新的瘟疫？', '好了，$N。我已经准备好了。$B$B可以出发了吗？', '保护基恩洛，直到她回到奎艾身边。', '你帮了我们的大忙，$N，谢谢你。$B$B但愿基恩洛刚才的凶狠善战没有吓到你。她对朋友很和善，但是对于敌人，她决不会有半点怜悯之心。', '现在不是聊天的时候。为了希尔斯布莱德的所有人民，请你一定要保护好基恩洛。', '保护基恩洛', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (661, '新的瘟疫？', '就算让基恩洛在旅店里睡上一晚，她也不会比现在看起来更健康。显然，你很好地保护了她。$B$B她从农场拿回来的这些东西至少能让费恩了解到在阿拉希高地附近究竟发生了些什么事情。为了确保你们的行动不会导致任何报复行动，我们会在这里继续留守一段时间。你愿意返回南海镇去和费恩谈谈吗？', '到希尔斯布莱德丘陵的南海镇去找到费恩·奥德利克。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (663, '法迪尔海湾', '鲁鲁看见了一个小$r！鲁鲁总是待在哨所上！$b$b欢迎来到法迪尔海湾。奥布里船长说过，我们在这里待不了多久。我们只要搜集宝藏然后返回藏宝海湾就行了。$b$b但是鲁鲁认为我们要在这儿待很长很长的时间，我们失去了两艘船。可怜的银松之魂号和处女号！她们长眠在海底！$b$b鲁鲁说，如果你想在这逗留的话，就去和奥布里船长谈谈吧。', '和阿拉希高地中法迪尔海湾的奥布里船长交谈。', '嘿，伙计。$B$B这真是乱得一塌糊涂。如果海角大人发现我这里的状况的话，他一准会没收我所有的船只。$B$B教授的装置显示丢失的宝藏就在海湾附近。我把先驱号开到码头，然后向银松之灵号和处女号发出请跟随的信号。$B$B突然之间大海隆隆作响，海浪将那两艘可怜的船卷向了暗礁。$B$B那里不止是片暗礁，而且还潜藏着别的东西……$B$B帮我把我的船员救出来吧，我发誓你会得到一笔丰厚的奖励。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (667, '水下伏兵', '太糟了，看来那些刺脊纳迦正在囤积重兵准备发动攻击。纳迦在作战时是出了名的冷酷无情，只要你还有一口气，他们就决不会停止攻击。$b$b我并不是说我自己的性命比弟兄们更宝贵，但你必须得保护我，因为如果没有我对大海的了解，弟兄们是不可能回到藏宝海湾去的。$b$b纳迦会从大海里向我们发起进攻，我要你留在这儿与我一起对抗他们，齐心协力把他们打退。$b$b你准备好了吗，$n？', '在纳迦的攻击中保护沙克斯·奥布里。', '我们打退了纳迦的进攻!$B$B如果不是你出手帮助，我们是不可能成功的，$N。$B$B等涨潮的时候，我们就马上离开。原本我想让你加入我们的，但是你的英雄之旅才刚刚开始，我可不想妨碍你。$B$B即便你现在只是个微不足道的$r，将来你也必定大有作为!', '准备作战!', '保护沙克斯·奥布里', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (675, '振奋精神', '<戈穆尔把护身符扔到了地上>$b$b托尔甘让你来的，是吗？呸！我不理解他为什么要怜悯我。在我不能和我的酋长一起战死的时候，我就不再接受任何怜悯了。我注定要被这残酷的命运煎熬……', '和阿拉希高地落锤镇的托尔甘谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (686, '国王的礼物', '象巴鲁夫人这样好心的矮人可能无法理解要忍受这场可笑的战争其实是为了我们族人更高的利益。无论是她的丈夫还是其他在战斗中献出生命的矮人，每次听到他们的名字都让我感到非常心痛。$b$b虽然我不能让她的丈夫死而复生，不过我可以向他致以崇高的敬意。$b$b我会委派大石匠玛布勒斯坦为苏利·巴鲁建造一座纪念碑。$b$b把口信带给他，$c。你来负责传达我的这条命令。', '国王麦格尼·铜须让你去和大石匠玛布勒斯坦谈一谈。', '是国王陛下亲自指示你来找我的?$B$B哦，天啊!这件事肯定非常重要!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (687, '迷失者塞尔杜林', '迷失者塞尔杜林曾经是我们暮光之锤的一员。但是有一天他突然精神失常，摒弃了我们的信条，背叛了我们的信仰。在背离我们之前，他还偷走了密斯莱尔卷轴！我们没能抓到他，但有传言说他就躲藏在荒芜之地中，整日胡言乱语，已经完全疯掉了。$B$B如果你要将公主带回来的话，就必须找到卷轴，而要找到卷轴，你就必须找到塞尔杜林。', '找到迷失者塞尔杜林。', '你好。你好啊，你好你好你好你好你好，你好啊!$B$B我很抱歉─等等，我才不抱歉呢!别这么粗鲁!$B$B天哪……真是一堆没意义的疯话。$B$B但是……有时候……发疯却是我唯一的安慰……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (688, '密斯莱尔的盟友', '<密斯莱尔开始说话>$B$B自由！我自由了！我终于自由了，我要恢复力量，不过现在我还得躲避那些追捕我的敌人。因为如果他们现在找到我的话，肯定会轻松将我降服并重新监禁我。$B$B总有一天我会回到那些巨人的面前，让他们为禁锢我的行为而后悔！$B$B你是一个高尚的盟友，$N。我会再次需要你的帮助。等我准备好之后，我需要你来将我召唤到地表上。$B$B去和落锤村的萨鲁克谈谈吧，他知道如何召唤我。', '和阿拉希高地落锤镇的的萨鲁克谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (690, '马林的要求', '你好，$N。我看出你是个渴望冒险的$c，现在我有项任务需要你的帮助。$B$B我原来的主人，大法师特雷莱恩，不久从位于阿拉希高地的激流堡里逃了出来。他让我到那里去帮他取回一些临走时落下的物品。$B$B激流堡现在已经陷入了重围之中，他在努力保卫阿拉索之塔，但是现在看来情况越来越危险了。我的人已经到了阿拉希高地，但他们需要更多的支援。你有兴趣去帮忙吗？', '找到位于阿拉希高地上的避难谷地中的斯奎尔图。', '是马林派你来的?就算是穆拉丁死而复生，然后用一百条龙把你护送到这里来，跟我又有什么关系?我很忙!如果你需要什么，就跟克里汀说吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (695, '学徒的魔法', '拿着宝石吧，$n。只要将宝石放置在塔基的任何一个支撑脚上，就能激活阿拉索之塔的防御。当你准备进入塔中寻找特雷莱恩的其余物品时，就使用这颗宝石。$B$B祝你好运，我将在营地里等你回来。哦，对了，在你离开之前别忘了去和斯奎尔图谈谈，他会告诉你一些你必须了解的细节。', '和阿拉希高地中避难谷地的斯奎尔图谈一谈。', '很好，很好。$B$B如果没别的事，我们就开始吧?', '那么，$N，你都准备好了吗?这块宝石已经附魔了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (700, '国王的礼物', '啊，洛丹伦的石头真不赖，可惜那儿已经变成一片废墟了。$b$b纪念碑完成了！我想国王陛下一定会满意的。$b$b如果你愿意的话，请替我去告诉国王陛下，纪念碑已经完成了。', '向铁炉堡的国王麦格尼·铜须汇报。', '和一个伟大矮人的生命相比，这块花岗岩只是一个微不足道的纪念品，不过没有一个矮人可以长生不老。$B$B希望这座纪念碑可以永远提醒未来的那些在艾泽拉斯享受和平和安宁的人们:为了他们的幸福生活，无数像苏利.巴鲁这样英勇的战士付出了自己宝贵的生命。', '你回来啦，$C。$B$B我委托你负责建造石碑的事情办得如何了?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (707, '铁环挖掘场需要你！', '$N。洛克莫丹的勘察员基恩萨·铁环从他的挖掘场给我送来报告，说是需要为我们的另一项挖掘计划外出搜集一些情报。$B$B我就知道这么多了，如果你愿意活动一下筋骨，就去和基恩萨·铁环谈谈吧。', '和洛克莫丹铁环挖掘场的勘察员基恩萨·铁环谈一谈。', '雷矛让你来的，是吗?很好。$B$B我有个重要任务要交给你……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (708, '黑盒子', '这个黑色金属箱的表面已经被严重破坏，似乎在酸液中浸泡过——它一定在那只巨型秃鹫的肚子里呆了很长的时间。$B$B翻转过箱子之后，你发现箱底印着一个标记，标记下是一行字：$B$B“19号坦克 - 铁炉堡攻城坦克旅”', '把这个黑盒子带到铁炉堡的军事大厅去。', '这是我们的一辆攻城机具的黑盒子!我们所有的坦克都带有这样一只盒子，是驾驶员用来存放他们收到的命令、地图和其他关键作战资讯的。$B$B难以置信!这只盒子来自于我们最古老的攻城机具，是很多年前在一次巡逻任务中丢失的。它的表面变形得很厉害，好像这几个月来一直就浸在酸液中一样。$B$B你刚才说是在哪里找到它的?', '什么?你说你找到了什么?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (720, '一线希望', '<在地图上有一行用粉笔潦草写下的文字>$B$B“雷杜尔，$B他们把我带到了奥达曼，请速来援助。$B——铁趾”', '找到勘察员雷杜尔，告诉他铁趾格雷兹还活着。', '铁趾还活着?真是难以置信，$N!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (721, '一线希望', '$N，你能找到他吗？你能在奥达曼找到铁趾吗？$B$B如果那些卑鄙的暗炉矮人将他抓为人质是为了获得他掌握的有关泰坦的信息的话，铁炉堡就有大麻烦了。$B$B很久以来，黑铁矮人一直在寻找可以制造出威力更大的作战傀儡的魔法。铁趾也在寻找这样的魔法，但他的目的仅仅是为了阻止他们。$B$B估计在套出重要情报之前，他们是不会杀了铁趾的。你要抓紧时间，尽快救出铁趾！', '在奥达曼找到铁趾格雷兹。', '嗯?啊，对不起……<咳嗽>我感觉很虚弱。你能靠近点吗，$C?$B$B雷杜尔派你来的?他比我想像中的要快多啦……<咳嗽>', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (726, '亡者的警告', '<顾问贝尔格拉姆读到信的结尾，他的眼睛瞪大了好一会儿。>$B$B哎哟，这真是太可怕了。$B$B$N，你回去告诉史学家卡尼克，赶快以国王的名义对这一事件采取行动。他必须制止暗炉矮人在荒芜之地的所作所为！', '和史学家卡尼克谈一谈。', '$N，你在处理这件事情的时候行动非常迅速，我一直以来都希望国王陛下也能够这么对待这种问题。$B$B好吧，我知道该如何打败暗炉矮人了。$B$B只要我们攻击他们在荒芜之地的军事要塞─苦痛堡垒，就能对他们进行有效的压制。', '$N，你回来啦?和顾问贝尔格拉姆谈过吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (729, '健忘的勘察员', '首席考古学家杜瑟·灰须派我在伟大的勘察员雷姆塔维尔的指导下进行工作，这对我来说是无上的荣誉。在铁炉堡学院时，每个人都知道雷姆塔维尔有许多伟大的发现。$b$b不过这位伟大的勘察员实在是……嗯……有些健忘……他常常对周围的一切都浑然不觉。$b$b我们刚刚发现了一座大型的古代城镇，但是突然间，可怕的傀儡从地下蜂拥而出，占据了那里。不过雷姆塔维尔似乎还没有发现这一点，我跑回奥伯丁就是为了找人去救他。$b$b请到南边去一趟，看看伟大勘察员是否还一切安好！', '到南边去一趟，看看勘察员雷姆塔维尔现在处境如何。', '霍莉，是你吗?我得凿开这块石头。给我一把石刷，我想我看到了一些有趣的东西。$B$B嘿，你不是霍莉!我想你应该没有看见我的石刷吧?$B$B现在别去想它了!我向协会保证过，我一定会把我发现的神秘化石寄回去。霍莉去哪里了?$B$B有这么多的工作要做!现在那块神秘的化石去哪里了……还有我的石刷……还有霍莉……$B$B你是谁……这没关系，我只关心的是，你现在是来帮忙的吧?$B$B当你准备好开始搜索工作的时候，就和我说一声。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (730, '黑海岸的麻烦事', '很高兴见到一个对我们伟大的考古事业有如此浓厚的兴趣的$c。$b$b我们的工作经常被联盟中的其他朋友当成是矮人的休闲活动而不被理解，但是很多人都没有意识到，最近在卡兹莫丹一带的发现证实，一股强大的势力正威胁着从洛丹伦到卡利姆多的整个世界。$b$b我很担心那些到黑海岸去考古的兄弟们，他们有好几个星期都音信全无了。$b$b到奥伯丁去找找看有没有关于他们的线索吧。', '到奥伯丁去寻找矮人挖掘队的线索。', '很高兴看到首席考古学家杜瑟.灰须派你来找我们……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (734, '不祥的感觉', '太好啦，太好啦。$B$B<鲁特维尔看了你一会儿，又去摆弄他的镣铐了>$B$B去找卢希恩吧，$N。跟他说我需要一个5号齿轮。你能把它拿来给我吗？', '和荒芜之地的卢希恩·枪穗谈一谈。', '5号齿轮，是吗?嗯，我感觉不太妙啊。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (738, '寻找阿戈莫德', '勘察员阿戈莫德曾是荒芜之地的挖掘场负责人，就是西南边的那座挖掘场。我说“曾是”，是因为……嗯，最近几周我都没有得到他的任何消息。请你帮我找到阿戈莫德并拿到他的报告。$B$B我最后一次得到的消息是：阿戈莫德在荒芜之地最南边的挖掘场——那是苦痛堡垒附近的一个不起眼的小地方。你先去那里找找看吧。', '找到阿戈莫德。', '这具骷髅一定是可怜的埃格蒙德留下的。他的尸体四分五裂，只剩下了一副空架子。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (742, '灰谷狩猎', '年轻的冒险者们，注意了！灰谷的野兽正在等着你们！$B$B部落在贫瘠之地以北的区域建立了强大的基地。我们的两个前哨站——碎木哨岗和佐拉姆海岸哨岗——正在努力地为部落的荣耀而战！想要证明自己能力的勇士就到那儿去吧。碎木岗哨位于贫瘠之地的正北方，塞娜尼·雷心正在那里招募愿意参与灰谷狩猎中的冒险者！', '与灰谷碎木哨岗的塞娜尼·雷心谈一谈。', '欢迎来到这块新的疆土，$N。梣谷是一片充满机遇的土地，像你这样年轻的$C肯定可以在这里找到无数证明自己实力的机会。在这里的前哨站到处转转，然后到佐拉姆海岸去，部落在那儿设有另一个岗哨。$B$B我看得出你是到这儿来学习狩猎的。用心学习吧，我将很乐意与你分享我所掌握的知识。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (749, '被破坏的货车', '几天前，我们在石牛湖北岸发现了有一个被重兵保护着的风险投资公司的马车。我们在先前的战斗里已经失去了两个同伴，所以我们就把怒气倾泻在这辆马车身上，速战速决地把它给摧毁了。$b$b我们没去管他们的储物箱，满以为一把火就可以把这些东西和马车一起烧成灰。不过有人在那辆熊熊燃烧的货车附近看见了风险投资公司的抢救人员，那些箱子可能没被烧掉。$b$b也许你可以去那辆货车旁，看看箱子里面到底是什么。', '摩林·云行者要你去查看被破坏的货车附近的储备箱里有什么东西。', '木箱的每一面都盖上了风险投资公司采矿部的印章。木箱上还印有清楚的说明，这些货物都要送到他们的中心厂房去加工。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (752, '一件琐事', '我们部族的所有成员都过着完美和谐的生活，我们一起劳作，一起生活。$b$b部族中的每个成员都对其他人负有义务，并且我们总是将这些义务放在首位。现在我需要你帮我做一件麻烦的事情。$b$b我的母亲今天早上去纳拉其东南方的水井中取水，她已经去了很久了。你能不能替我去看看？部族里的事务让我实在抽不开身。', '鹰风酋长要求你去纳拉其营地东南方的水井处寻找他的母亲。', '你跑了那么远的路过来就是来帮我忙的?唉，难道你是个保镖吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (755, '大地之母仪祭', '你愿意为纳拉其的牛头人做这样琐碎的小事，同时又渴望学习新的知识，这足以说明你有着高贵的品质，$n。我相信总有一天你会成为一位在雷霆崖赫赫有名的$c。$b$b不过在那之前，你必须首先完成大地之母仪祭，这个伟大的传统共由三个不同的试炼组成。$b$b第一个试炼是力量之仪祭。去找灰舌先知，告诉他是鹰风酋长派你去的。$b$b翻过纳拉其营地正南方的山后，你就可以找到他的居所了。', '找到居住在纳拉其营地正南方山中的灰舌先知。', '是鹰风酋长派你来的?大地之母祭仪可不是件小事……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (758, '净化雷角之井', '图腾已经准备好了，$N。这一次还是由你来完成净化仪式。$B$B到村庄北面的雷角之井去，用雷角之井净化图腾完成净化仪式，然后再回来找我。$B$B愿大地之灵指引你。', '在雷角之井使用雷角之井净化图腾，然后回来见穆尔。', '雷角氏族的祖先托梦与我，向我赞扬了你所做的事。$B$B为了表达他们的感激，他们想交给你这个……', '雷角之井的水仍未得到净化，$N。你必须马上完成净化仪式!', '净化雷角之井', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (760, '净化蛮鬃之井', '你净化冰蹄之井和雷角之井的事迹已经被广为传诵了，年轻的$N。我也已经做好了蛮鬃之井净化图腾，接下来这就是你的最后一个任务了。$B$B蛮鬃之井在雷霆崖的北面，到那里完成净化仪式吧，拯救这片被地精污染的土地，让这片土地上的生灵再次畅饮甘甜纯净的井水！', '在蛮鬃之井使用蛮鬃之井净化图腾，然后回来见穆尔·雷角。', '你成功了!你净化了水井，也净化了我们的土地。血蹄村非常感激你，$N。$B$B愿你的功绩在风中传诵百年，愿莫高雷的水永远纯净。', '最后一口井还是又臭又脏，$N。你不能松懈!', '净化蛮鬃之井', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (767, '幻象仪祭', '作为大地之母仪祭之一的幻象仪祭可以指引你最终赢得雷霆崖长老们的尊重。$b$b我们早已认识到，土地就是我们最神圣的生命之本。如果你准备好要进行幻象仪祭的话，就得去和村里的精神领袖扎尔曼·双月谈一谈。', '和血蹄村的扎尔曼·双月谈一谈。', '我感觉到你会来找我，$C。我能够辨认出那些想要通过大地之母仪祭的人。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (770, '恶魔之伤', '鬼嚎那粗糙的毛皮上还留着一个可怕的伤口，是在它与燃烧军团的战斗中留下的。$B$B也许你应该把鬼嚎的死讯告诉血蹄村里的什么人……', '去打听打听谁听说过鬼嚎。', '我简直不敢相信我的眼睛!你打败了鬼嚎?我得用尊敬的眼光来看你了，年轻的$C。你真是个技艺高超的猎手!$B$B让我给你点东西吧。我已经不会再去打猎了，不过如果你能用我的武器去打猎，我会感到很荣幸的。$B$B但愿它能对你的狩猎有用，愿它为你带来名誉。$B$B希望鬼嚎的灵魂已经了得到安息。', '你好，$N。你在平原上的狩猎进行得如何?你听到鬼嚎的吼叫声了吗……?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (772, '幻象仪祭', '现在，我把神圣的先知之水交给你。$b$b准备好了之后，就去部族之火旁把水喝下，然后稍等片刻，一个幻象就会出现在你的眼前。$b$b你必须立刻决定是否要追随这个幻象……', '在血蹄村的部族之火前将先知之水喝下，当幻象出现之后跟随它。', '不要害怕，$N。你已经通过了幻象祭仪。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (773, '智慧仪祭', '要让雷霆崖的资深长者接受你，你就必须再完成大地之母仪祭的下一个阶段：智慧仪祭。$b$b你已经通过了幻象仪祭，赤色石的先祖之魂会祝福你的，只有那些喝过先知之水的人才能得到这种祝福。$b$b向雷霆崖的东面去，到赤色石寻找先祖之魂吧。', '到雷霆崖东边的赤色石去和先祖之魂谈一谈。', '你在通过大地之母祭仪的过程中已经显示了你的勤奋和努力，$N。$B$B我们是先祖之魂，我们代表了那些为保卫雷霆崖而付出生命的勇敢的牛头人。现在，我把保卫这里的神圣职责交给你。$B$B你已经通过了智慧祭仪，年轻的$C。你可以骄傲地走进雷霆崖了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (775, '雷霆崖之旅', '任何能够完成大地之母仪祭的$r都可以赢得整个雷霆崖的尊重。$b$b你的最后一个任务是去见见我们的伟大首领凯恩·血蹄，他就住在雷霆崖最高的那座台地上。', '和雷霆崖的凯恩·血蹄谈一谈。', '你好，年轻的$C。你终于来见我了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (783, '身边的危机', '我希望你已经整装待发了，年轻的$c。北郡需要你的帮助！$B$B当然，我不是在说让你去耕田种地之类的。$B$B暴风城的卫兵们努力地维持着这里的和平，但我们人手短缺，更多的危险还在不断迫近。我们正在招募愿意出力保卫家乡和联盟的人。$B$B如果你也是应招而来的话，请和我的上级——治安官玛克布莱德谈谈。他就在我身后的这座修道院里。', '与治安官玛克布莱德谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (787, '新的部落', '向你致意，$c。我是伊崔格，奉萨尔酋长的命令在此负责招募新兵。$b$b部落已经不再是从前的那个部落了。我曾经离开过部落，在那段时间里，我受到燃烧军团的蛊惑而迷失了自我。在被放逐后，我被一群人类抓去当了俘虏，但最终被我们伟大的酋长救了出来。在酋长那拯救部落的远大志向的指引下，在萨满祭司的教诲之下，我回来了。$b$b高内克会给你进一步的指示。', '向大兽穴里的高内克报到。', '你也是伊崔格招募的新兵吗?$B$B目前的态势确实不能令人满意，但部落已经尽了最大的努力。没关系，等到我们认为你可以出谷的时候，你就已经是一名能让部落感到自豪的优秀战士了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (804, '萨科斯', '看见你为我这么一个素不相识的可怜家伙做了这么多事情，我突然又坚强了起来。我绝不能就这么轻易地死在这种地方！我得坚持下去！$b$b可现在我还是不能自己回到大兽穴去。$n，请你再帮个忙，回大兽穴向高内克报告一下我现在的情况。', '将哈纳祖目前的状况告诉大兽穴内的高内克。', '从你对那只野兽的描述来看，你说的一定是萨科斯!怪不得哈纳祖被它打倒了。我们马上就会派人去帮助它，你就不用再管哈纳祖这摊子事了。$B$B无论如何，我不得不说的是，对于你能够单枪匹马杀死萨科斯这样的猛兽，我的确感到非常震惊。这绝对是一件值得自豪的事，$N。你再一次无私地选择为一个陌生人的荣誉而战，你应得的荣耀又多了一分。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (805, '去森金村报到', '你在这山谷中的针对火刃氏族的试炼……如今就算是完成了。但我希望你能去向其他人报告一下你的发现。$B$B到森金村去找加德林大师吧。先从山谷的东侧出去，在岔路口转向右一直走到底就能抵达森金村了。$B$B我们必须把火刃氏族的势力出现在试炼谷的事告诉加德林大师。$B$B去吧，$N，动作要快。恐怕我们在火刃集会所中找到的东西只是更可怕的威胁的预兆而已……', '与森金村的加德林大师谈一谈。', '什么?你的报告来的真不是时候。燃刃氏族在森金村倒是看不到，但他们的邪恶似乎已经蔓延到这里了─在回音岛上。$B$B兽人是暗矛食人妖的盟友，真正的盟友。我们很想帮助兽人，但是……我们现在也需要帮助。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (809, '雅克塞罗斯', '自从我们在上一次大战中击败燃烧军团之后，我一直在寻找潜藏在兽人中的恶魔势力的源头。你带来的项圈证实了我的担忧。$B$B这个项圈属于火刃氏族，这帮恶魔的信徒正在凭借着一件被称作恶魔之种的器物重整旗鼓。你可以在鬼雾峰山顶的贫瘠之地找到恶魔之种，一定要把它毁掉！$B$B到贫瘠之地西部边境的前沿哨所去找我的助手雅克塞罗斯吧，他会给你进一步的指示。', '到贫瘠之地去和雅克塞罗斯谈一谈。', '尼尔鲁要毁了恶魔之种?奇怪……$B$B好吧，既然他想要让恶魔之种消失，那我就告诉你该怎么做。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (823, '向奥戈尼尔报告', '我们森金村这边还有许多棘手的问题要解决，非常感谢你的帮助。但是你带来的消息说明火刃氏族也许对所有人来说都是个大麻烦。$B$B剃刀岭那里有一处兽人营地，奥戈尼尔·魂痕就在那里负责监视火刃氏族那一类的邪恶势力。去跟他谈一谈，跟他说说我们目前的情况，还有你从试炼谷得到的消息，他肯定会大吃一惊的。$B$B剃刀岭就在这里的北边。', '和剃刀岭的奥戈尼尔·魂痕谈一谈。', '什么?你有情报要告诉我?好吧，说说看!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (828, '玛高兹', '有个名叫玛高兹的萨满祭司对于火刃氏族的堕落颇有了解。他说在奥格瑞玛外面的山里有个叫骷髅石的山洞，有一大批火刃祭司藏匿在那里。$B$B在你前往骷髅石之前，去和玛高兹谈谈吧。他十分睿智，会给你一些有价值的建议。$B$B玛高兹就住在东北方的海岸和枯水谷中间。$B$B你要听从玛高兹的建议，但是不管他怎么说，$N，我都要求你干掉那些火刃祭司！', '和玛高兹谈一谈。', '欢迎，$N。我听说你要来这里，对你在杜洛塔的丰功伟绩更是耳熟能详。$B$B你是一个越来越强大而知名的$C。$B$B继续在正义之路上前进，你将前途无量。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (836, '拯救OOX-09/HL！', '那个侏儒的声音再次从那个机器人中传了出来：$B$B“我需要你帮忙把OOX-09/HL移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到，啊，那个地方有些隐蔽的大岩石！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”$B$B“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”', '安全护送OOX-09/HL到达目的地，然后向藏宝海湾的奥格索普·奥布诺提斯报告。', '哦，你是OOX-09/HL的伟大救世主!我简直无法用言语来表达对你的感谢!如果让我自己重新构造一个母体机器人的话，无疑要浪费大量的时间，你真是帮了我的大忙，不仅节约了我的时间，同时也节约了我的钱!$B$B请从这些东西中选择一样你中意的吧。再次感谢你无私的帮助，我的机器人和我都欠你的人情!', '没错，我就是奥格索普.奥布诺提斯，世上最强的发明家，随时为您效劳!现在，我能帮您什么忙吗?', '将OOX-09/HL安全护送到目的地。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (838, '通灵学院', '通灵学院坐落在凯尔达隆岛上，这所学校是亡灵天灾的一座堡垒。我们的敌人就聚居在那里，安全地进行研究并不断增强他们的力量。有一扇坚固的大门封住了唯一的入口，如果没有一把合适的钥匙，我们无论如何都无法通过它。$B$B药剂师迪瑟斯一直以来都负责与通灵学院有关的事务，他应该知道如何才能获得那把钥匙。你应该向我证明你确实有存在的价值，现在我把这个任务交给你，去跟迪瑟斯谈谈关于这件事的详细情况吧。', '和西瘟疫之地亡灵壁垒的药剂师迪瑟斯谈一谈。', '没错，$C，高阶执行官向我提起过你，看来你是个值得信赖的$C，而且有能力解决这件有关通灵学院大门钥匙的问题。我最近把大部分的精力都花在研究通灵学院上，我相信我已经找到了让你获得钥匙的方法。$B$B这个任务并不简单，不过这类任务一向如此。看来你已经明白其艰难的程度。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (847, '迅猛龙的狡诈', '这……这力量……是托尔甘要显示给我的萨满祭司的力量吗？我不得不承认，这很有趣。告诉托尔甘他让我十分信服……至少是现在。我会对他要说的一切都洗耳恭听。', '和阿拉希高地落锤镇的托尔甘谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (854, '十字路口之旅', '我已经预见到你会来找我，年轻的$c，虽然你可能已经并不是那么年轻了。$B$B我想，现在是时候让你深入这片土地了，我能感觉到你命中注定是要做一番大事业的人。$B$B你应该到十字路口去，因为我们和兽人的命运已经紧紧地联系在了一起，他们那儿需要帮助。沿着这条路往东走，然后向北就可以走到十字路口。到那里去找索克吧。', '去十字路口和索克谈一谈。', '很高兴看到越来越多的$r盟友来帮助我们。十字路口需要更多帮助。在这里到处转转，和大家聊聊天，你就会发现这儿有很多事等着你去做。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (860, '瑟格拉·黑棘', '如果你想继续沿着猎人之道前行，就得到贫瘠之地去了。那儿的野兽强壮而凶猛，在那里打猎会让你学到很多东西，而你的意志力也会随之增强。$B$B去和瑟格拉·黑棘谈谈吧，她会是你在贫瘠之地的第一位向导。她就在十字路口，只要从血蹄村一直往东进入贫瘠之地，见到岔路口之后再往北走就可以到那里了。$B$B在贫瘠之地旅行的时候可得小心点，那是一个充满危险和挑战的地方。', '和贫瘠之地十字路口的瑟格拉·黑棘谈一谈。', '你想在贫瘠之地打猎?$B$B从你的双眼中我可以看到朝气和热情。当你在这片干燥的平原上捕猎的时候，你也不会在烈日的强光之下闭上双眼。$B$B别担心，我们会使你变得更加强壮，更加坚强。而且我们还会让你知道，狩猎不仅仅只是找到并杀掉你的猎物。$B$B做好准备吧。真正的旅程现在才刚刚开始。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (874, '玛伦·星眼', '你已经猎杀了贫瘠之地的猛兽，在这个过程中你的精神力量也已经变得相当强大了。作为一个猎人，你应当时刻都作好准备，一个真正的猎手理应能在任何环境下追踪猎物。无论是山川还是沼泽都无法阻止$g他:她;\n。$B$B甚至连海洋都不能。$B$B去找到我的妹妹玛伦，她正在海岸边猎杀一种大型水兽，你可以从她那里学习更高深的狩猎之道。$B$B不过你找她的时候要当心，因为贫瘠之地的海岸一带是现在是被人类控制着的。', '和玛伦·星眼谈一谈。', '是我哥哥派你来的吗?那你一定已经在他面前证明了自己。如果你赢得了乔恩的尊重，那么你也就赢得了我的尊重。$B$B你准备好接受学习更进一步的猎人之道了吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (886, '贫瘠之地的绿洲', '雷霆崖的德鲁伊们感到有一股奇怪的力量正在渗入莫高雷东边的贫瘠之地。$B$B图加·符文图腾已经被派去查找这股力量的来源了，但是我们担心他可能需要更多的帮助。$B$B到贫瘠之地去和图加谈谈吧，他应该就在十字路口。从血蹄村一直往东走就可以进入贫瘠之地，在路口向北转，然后继续往北走，很快就到十字路口了。$B$B记得一直在路上走，$N，贫瘠之地是一块非常危险的土地。', '和贫瘠之地十字路口的图加·符文图腾谈一谈。', '雷霆崖的兄弟们派你来真是太明智了，年轻的$C。以我一人之力是无法揭开贫瘠之地的这些秘密的。$B$B有了你的帮助，我们就有希望找到问题的答案了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (894, '什么什么平衡器', '风险投资公司最近在北边设立了小型的研究设备，就在淤泥沼泽的西南部。我对他们在做的东西并不了解，只知道他们正在试验一种名叫“主动式负载平衡器”的装备。$b$b那个主动式负载平衡器到底是什么东西呢？不管它是什么，我都想研究研究它，所以我需要找个人来帮我把它弄到手。$b$b我手里有控制系统操作手册的副本，你应该知道该怎么把那什么平衡器卸下来。', '在风险投资公司研究基地里找到控制台。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (920, '特纳隆的召唤', '你叫$n，没错吧？我听说特纳隆大人正在找你。你可以在奥达希尔树冠的最顶层找到他。$b$b虽然我们的生命近乎无限，可你最好别让他等得太久。', '与奥达希尔顶部的特纳隆·雷拳交谈。', '啊，$N。我正希望你能快点来我这里报到呢，这里有个重要的任务要托付给你。', '怎么啦?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (926, '有瑕疵的能量石', '', '', '这些石头被赋予了魔法的力量，但是却被人有意破坏了。它们很不稳定，一旦从桌子上拿起，能量就会很快耗尽。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (936, '协助大德鲁伊', '打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B雷霆崖的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是哈缪尔·符文图腾亲自负责这项研究。$B$B要是你感兴趣的话，请直接去雷霆崖的长者高地找他谈谈。', '与雷霆崖的大德鲁伊哈缪尔·符文图腾谈一谈。', '你好，$C。很高兴你愿意帮助我们进行研究。你要做的事情很多，如果是我告诉你这工作并不危险，也许会伤害到你的感情。希望你不会因此受惊……但是，从你的表情看来，你已经经历过不少危险了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (945, '护送瑟瑞露尼', '救命呀！$B$B我正在主宰之剑附近散步的时候，这些肮脏的家伙包围了我。多亏我善于隐藏才没有被他们找到！我很厉害吧！$B$B你能帮我离开这里吗？还有还有，你能不能给我姐姐瑟瑞希尔捎个口信，告诉她我平安无事？要不然她会担心死的。她住在艾森娜神殿里，那地方就在南方的灰谷森林里。', '帮助瑟瑞露尼逃跑，然后告诉在灰谷艾森娜神殿的瑟瑞希尔，她的妹妹目前很安全。', '我的妹妹在哪里?瑟瑞露尼天不怕地不怕，但终究还是遇到麻烦了!去主宰之剑的路途很遥远，而且那里并不是一个好地方……$B$B谢谢你，$N。感谢你告诉我她一切安好。', '我妹妹喜欢到处闲逛，不过这次她离开的时间也太长了……', '护送瑟瑞露尼离开主宰之剑。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (948, '安努', '古树之林里的一棵知识古树安努得知了你到壁泉河瀑布去的这次旅行，他希望和你谈谈。古树之林就在南方的山麓附近。$B$B这些古树耐心而充满睿智，$N，不过，如果是安努找你是为了向你询问瀑布一带的情况，我想事情一定非常紧急。', '和古树之林的安努谈一谈。', '$N，你来了。$B$B很好。$B$B我们有些事情……要谈谈。你我之间。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (949, '暮光之锤的营地', '暮光之锤来到主宰之剑的目的还不得而知，不过肯定是为了某些不可告人的邪恶目的。$B$B到主宰之剑去搜寻他们的营地……设法查出他们准备干什么。$B$B在制定计划之前，我们必须首先知道他们的意图。', '到位于主宰之剑的暮光之锤营地去寻找线索。', '这本书是用某种古代的文字手写的，而插图则是由一个技术高超的画师手绘的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (954, '巴莎兰', '有一伙恶魔的爪牙在东部的巴莎兰废墟里到处横行。盘踞在那里的劣魔和萨特疯狂地汲取着魔法的能量，致使它们的魔力不断地迅速膨胀。$b$b但是，我也注意到那里有一处它们始终无法侵犯的神殿，就在那片废墟西侧的小峭壁上，那座神殿里弥漫着奇特的蓝光……一定有什么原因使得恶魔不愿靠近那里。$b$b我希望你去调查一下。', '到巴莎兰废墟去找到奇怪蓝光的源头。', '啊……有像你这样的$r来陪伴我，真是让我感到无上的光荣。当然，我并不是想要冒犯我的主人，也就是那些高贵的劣魔和萨特，但你的出现可以说是一种改善。$B$B请不要被我粗陋的语言吓跑，我已经有许多年……甚至是几十年没有和任何文明人接触过了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (960, '正在冥想的安努', '', '', '发现暮光之锤的信徒在那里活动真是件糟糕的事情。我必须仔细想想他们要干什么……$B$B如果你有更多的消息，就用占卜之碗和我交谈。如果你还需要更多的占卜之瓶来制造占卜之碗的话……我这里还有一瓶。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (961, '正在冥想的安努', '', '', '发现暮光之锤的信徒在那里活动真是件糟糕的事情。我必须仔细想想他们要干什么……$B$B如果你有更多的消息，就用占卜之碗和我交谈。如果你还需要更多的占卜之瓶来制造占卜之碗的话……我这里还有一瓶。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (965, '奥萨拉克斯之塔', '欢迎你，年轻的$r。我是艾莉萨·星风，保卫奥伯丁不受邪恶势力的侵害是我的职责。$b$b正因为如此，我派巴苏尔·影击去调查东北方的奥萨拉克斯之塔，那里最近发生了一些怪事。$b$b他早就应该回来了，我担心他在森林里碰到了危险，如果你能帮我找到他，并看看他是否一切安好的话，我会非常感激你的。', '在黑海岸的奥萨拉克斯之塔附近找到巴苏尔·影击。', '艾丽莎派你来的?太好了。我有些不太好的消息要报告她，正愁没人送信呢。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (972, '水之灵契', '', '', '带着水之灵契，到银松森林去找到那个被污染的水池。我对你的能力充满信心。', '很遗憾你得回来再拿一个灵契，不过这是你应得的。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (975, '玛艾里的容器', '在给你符咒之前，我最好解释一下如何使用它。$B$B如果你戴上符咒，你就可以从那些被你干掉的生物身上得到特殊的物品，如果你没有戴上符咒的话，那你就得不到那些物品，懂了吗？$B$B这些物品的名字叫做魂精。如果你找到它们，就把它们交给玛艾里，她会帮你解决剩下来的事情。$B$B在我给你修理符咒的时候，请在这里等一会儿。', '与巫医玛艾里再次谈话，然后拿到好运符。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (979, '兰莎尔拉', '嗯，嗯，这些羽毛上附着的魔法似乎与我以前见到过的很类似……虽然我并不能确定我们会发现什么，但我想你必须继续追查下去，$n。$B$B我的一位同事最近到冬泉谷去观察当地枭兽的生态了，你为什么不去找她谈一谈，看看她有些什么发现呢？', '在冬泉谷找到兰莎尔拉。', '你好!艾瑞拉斯让你来找我的吗?我正准备到那边的山洞里去看看呢，多个同伴也不错!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (980, '新的泉水', '我听说在北边的冬泉谷里还有其它的温泉。奇怪的是，那地方并没有任何火山的存在。这听起来很有趣，对吗？$B$B好吧，如果你想要查个水落石出，那就到冬泉谷去跟我的朋友谈一谈吧。他的名字叫做多诺瓦·雪山，现在就在那温泉附近。$B$B温度计的事情真是太感谢你了，祝你好运，再见！', '到冬泉谷去和多诺瓦·雪山谈一谈。', '你好啊，$N。没错，克拉兰克所说的都是真的……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (981, '奥萨拉克斯之塔', '你应该为你所作出的贡献而得到奖励。回到德尔格伦那里，告诉他埃瑟里克斯·纳拉辛已经死在你的手下，暗滩教派也已经被打得一败涂地，溃不成军。', '和迈斯特拉岗哨的净化者德尔格伦谈一谈。', '$N，我就知道你肯定能完成任务。$B$B我对你寄予厚望，确信你能拯救我们的家园。接受我的祝福吧，$N，当然，别忘了拿着这件礼物。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (990, '灰谷之旅', '$N，我的主人莱恩·狼行者正在灰谷的阿斯特兰纳城中等你。有了你的帮助，我们至少能稍微控制一下那里混乱的局势。$B$B从这儿向南走，沿着路一直前进——只要跟着那些指示牌，你应该不会迷路的。', '在灰谷中找到莱恩·狼行者。', '啊，从黑海岸来的一个$C。塞拉伊干得真不错，这么快就把你派到这儿来了。我希望你一路上没有经受太多的危险。也许在你的帮助下，我们可以把事情做得更好。', '找我有事吗，$C?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (991, '莱恩的净化', '$N，我有一个老朋友也正为灰谷的哨兵部队提供援助，不过他还没有回来。$B$B他正在寻找一件东西，一件他认为可以延缓熊怪对我们的同胞发起进攻的物品，由一个早已死掉的邪恶巫师制造的魔棒。$B$B在他离开这儿以前，他曾说过要去寻找一块宝石，这块宝石能帮他找到那根魔棒。$B$B他提到这块宝石很可能就藏在法拉希姆湖的神殿中，那座神殿就坐落在西边的山脚下。在宝石被人取走之前，它一直都放在那里。$B$B请去找到我的朋友，$N。', '在灰谷找到泰洛尼斯。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (993, '丢失的主人', '$N，斗篷做好了。你现在可以去寻找沃科尔，我希望时间还来得及。$B$B斗篷上的魔法被激活之后持续不了多久间，也许就只有五分钟左右的时间。你可以自行决定什么时候使用它，不过我建议你在找到锐爪以后再用。$B$B如果锐爪告诉我的消息是真的，那么你应该可以在南边的某个洞穴中找到他的主人。锐爪会在路边等你，看见它以后向它挥手打个招呼（使用/wave指令），然后它就会将它的主人所在的位置告诉你。', '找到沃科尔。', '太好了!特伦希斯找到了可以帮助我的人。$B$B<咳嗽>哦……真难受，我真是太不小心了。$B$B我还没来得及逃跑就被熊怪给打伤了。给我一些时间，我应该有力气多说几句。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (994, '杀出重围', '很好，$N，就是这样，让我们一起冲出去。我们要杀出一条到锐爪身边的路，到了那里之后我们可以分开行动。$B$B不过我想特伦希斯一定会听你来讲述这次惊心动魄的逃亡，所以在我们活着离开这里以后，别忘了尽快去一趟奥伯丁。', '保护沃科尔离开，然后去和奥伯丁的特伦希斯谈一谈。', '$N!很高兴看见你能安全返回。你对沃科尔提供的帮助使我相信，我们最终可以战胜在黑海岸或是其他任何地方所遇到的一切挑战。', '嗯，$N?', '帮助沃科尔逃到路上', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1000, '新的边疆', '注意了，英雄们！$B$B塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想象的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。$B$B所有对此感兴趣的部落成员都应该去向塞纳里奥议会报到。去和雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈谈吧！', '与雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈一谈关于议会号召部落成员探索卡利姆多大陆的事情。', '你好，$C。$B$B我很高兴看到像你这样的勇士对大自然保持着兴趣。我已经听说过你的事迹了，欢迎你。看见你站在这里，我相信塞纳里奥议会已经得到了我们所需的帮助。$B$B我们与月光林地的塞纳里奥议会之间的联系已经超越了种族和政治的界限。请记住，你是在为议会效力，你会干得很出色的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1004, '新的边疆', '注意了，英雄们！$B$B塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想象的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。$B$B所有对此感兴趣的部落成员都应该去向塞纳里奥议会报到。去和雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈谈吧！', '与雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈一谈关于议会号召部落成员探索卡利姆多大陆的事情。', '你好，$C。$B$B我很高兴看到像你这样的勇士对大自然保持着兴趣。我已经听说过你的事迹了，欢迎你。看见你站在这里，我相信塞纳里奥议会已经得到了我们所需的帮助。$B$B我们与月光林地的塞纳里奥议会之间的联系已经超越了种族和政治的界限。请记住，你是在为议会效力，你会干得很出色的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1015, '新的边疆', '注意了，英雄们！$B$B塞纳里奥议会正在招募精干的联盟成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想象的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。$B$B所有对此感兴趣的联盟成员都应该去向塞纳里奥议会报到。去和达纳苏斯的大德鲁伊范达尔·鹿盔谈谈吧！', '与达纳苏斯塞纳里奥区的大德鲁范达尔·鹿盔谈一谈关于议会号召联盟成员探索卡利姆多大陆的事情。', '是什么让你觉得我会被你这样的$r所干扰，$C?好吧，让我停下每天都要处理的无数重要事情，来帮你搞定你那点鸡毛蒜皮的小事情，我们相信达纳苏斯的利益-啊，不，整个泰达希尔的利益-与你手头上的事情相比都是不值一提的，对吗?$B$B月光林地的那群蠢货找了一堆人来为我提供帮助，这简直是在浪费我的时间，那么现在我是不是要继续忍受下去呢?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1018, '新的边疆', '注意了，英雄们！$B$B塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想象的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。$B$B所有对此感兴趣的部落成员都应该去向塞纳里奥议会报到。去和雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈谈吧！', '与雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈一谈关于议会号召部落成员探索卡利姆多大陆的事情。', '你好，$C。$B$B我很高兴看到像你这样的勇士对大自然保持着兴趣。我已经听说过你的事迹了，欢迎你。看见你站在这里，我相信塞纳里奥议会已经得到了我们所需的帮助。$B$B我们与月光林地的塞纳里奥议会之间的联系已经超越了种族和政治的界限。请记住，你是在为议会效力，你会干得很出色的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1019, '新的边疆', '注意了，英雄们！$B$B塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想象的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。$B$B所有对此感兴趣的联盟成员都应该去向塞纳里奥议会报到。去和达纳苏斯的大德鲁伊范达尔·鹿盔谈谈吧！', '与达纳苏斯塞纳里奥区的大德鲁范达尔·鹿盔谈一谈关于议会号召联盟成员探索卡利姆多大陆的事情。', '是什么让你觉得我会被你这样的$r所干扰，$C?好吧，让我停下每天都要处理的无数重要事情来帮你搞定你那点鸡毛蒜皮的小事情，我们相信达纳苏斯的利益-啊，不，整个泰达希尔的利益-与你手头上的事情相比都是不值一提的，对吗?$B$B月光林地的那群蠢货找了一堆人来为我提供帮助，这简直是在浪费我的时间，那么现在我是不是要继续忍受下去呢?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1021, '身陷危险的树妖！', '听着，我不知道你是谁，但我需要你的帮助。我的姐妹们去从萨特那里取回塞纳留斯的树枝，她们说会很快回来，可是已经过去两天了！$B$B$n，你得赶快去找到我的姐妹们，她们到去东北边的萨维亚去寻找一个暗夜精灵的废墟了。我的脑海里是一片空白，不知道该干什么了……去找到安妮莉亚吧，她是这次搜寻行动的首领。', '到灰谷的萨维亚去找到安妮莉亚。', '安妮莉亚身上伤痕累累，看来快要死了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1029, '莱恩的净化', '我建议你去找莱恩，告诉她魔棒的魔力已经复原了。我想她会告诉你下一步该做什么的。$B$B祝你好运，$N。', '回到阿斯特兰纳的莱恩·狼行者那里。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1030, '莱恩的净化', '唉，我不能完全肯定地说他下一步想要做什么。$B$B如果他关于魔棒的说法是真的，那么这根魔棒就可以将你变成另一种形态——我也不知道会变成哪一种形态。$B$B也许他本想利用魔棒的力量更加靠近那些堕落的熊怪，可是假如他不当心的话，就连没有堕落的熊怪也会杀了他。 在变形之后，达图尔得找到一个没有受到魔苔影响的熊怪谈谈。', '找到一个尚未堕落的熊怪，利用达图尔的变形魔棒的能力与其交谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1036, '嘿，水手！', '$N……对，我听说过你。我听说你不是藏宝海湾的朋友——就像我们血帆海盗一样。舰队指挥官菲尔拉伦正在征召像你这样精力充沛的$c去执行一个特殊的任务。$B$B如果你感兴趣的话，就去红雾号的甲板下找他吧。红雾号就停泊在这里东面的海岸边，靠近斩浪号和达姆希的好运号。', '登上停泊在荆棘谷海岸边的红雾号，与船里的舰队指挥官菲尔拉伦谈一谈。', '嘿，说你呢!我听说你想要找点事情干，嗯，如果你不是藏宝海湾的朋友，那么也许我们血帆海盗这里有你感兴趣的事情。$B$B呃……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1037, '维琳德·星歌', '维琳德·星歌是我在灰谷森林的前任指挥官。起初，她似乎将费伍德森林的一切都调理得井井有条，然而她对于森林的影响却变得越来越小。终于有一天，她突然消失了。$b$b我被派来接替她的工作。不过恐怕我对于这位女祭司了解得并不使很多。也许哨兵部队的指挥官塞恩提尔·刃纹会知道更多有关她失踪的细节。$b$b当然，她也知道这件事情的重要性。', '在达纳苏斯的战士区与塞恩提尔·刃纹谈一谈。', '维琳德.星歌?这位女祭司在不久前神秘失踪的事情已经是尽人皆知了。有关她离开的详细情况……你得拿出些更好的理由，我才能告诉你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1039, '贫瘠之地的港口', '棘齿城是贫瘠之地唯一的港口。最有可能发生的情况是，维琳德在棘齿城登上了一条驶往艾泽拉斯的黑水湾的商船。我们和管理港口的那些地精交往有限，不过码头的管理者应该有来来往往的乘客的信息。$b$b顺着这条路往东南方走，过了灰谷就进入贫瘠之地了。你要当心，$n，部落一方的战士一直在那片土地上巡逻。不过，在港口地区你应该是安全的。', '和贫瘠之地棘齿城的码头管理员迪兹维格谈一谈。', '呃，$R?我得说，在我们这儿像你这样的家伙可不多。你要找谁呀?给我一点时间，我想我一定可以找到记录的。$B$B途经这里的旅行者实在是太多了，所以请稍微再等一会儿。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1040, '藏宝海湾的航道', '啊，终于找到了。她是很久以前经过这里的，你看……$b$b维琳德，乘黑色鱼鹰号去往藏宝海湾。其它的没什么要说的了，我想那艘船应该是安全抵达目的地了。$b$b我没有什么可以帮你的啦，不过她问过一些关于在那片陆上旅行的事情，我向她提到了拉兹戈特，一个藏宝海湾的商队成员。没准维琳德会去找他当导游什么的。$b$b现在出发吧，我没时间再陪你了。', '坐船去藏宝海湾，和旅行者拉兹戈特谈一谈。', '嗯?你看起来不像是那种有货物需要托运的人，那么你是来商队找活干的吗?抱歉，现在我这里没有合适的工作给你-要不然就是你找错了哥布林。$B$B你到底找我干什么呢?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1041, '商队通路', '若我说的不对请不要见怪，我应该记得没错，毕竟不是每天都会发生这样的事儿的。$b$b我记得你要找的那个维林德。那是不久前发生的事，要知道，不是每天都会有一位漂亮的夜精灵女祭司会愿意搭着我这辆破烂的大蓬车旅行的，不过，我的车用来代步的确很不错，不是么？$b$b我们在向北去的路上分手了，她往夜色镇去了。那里的书记员应该有所有的出入记录，或许从那里你能知道些对你有用的东西。$b$b在丛林里你最好多加小心，即使是在安全的时节，那儿仍然是个危险的地方。', '与夜色镇的书记员达尔塔谈一谈。', '由于这几年我们这儿发生的怪事越来越多，所以我就保留了所有出入过这里的陌生人的记录。虽然这不是个令人愉快的活儿，但谁又能知道这些东西什么时候就会派上大用场呢?不过……很抱歉，我这里似乎没有你要找的那个维琳德的任何资料。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1042, '卡尔文家族', '不，夜色镇没有关于这个维琳德·星歌的任何记录……不过如果你不介意的话，我想说，我很难想象一个暗夜精灵的女祭司会在旅店里过夜，你懂我的意思吗？$b$b不过我听说过你提到的这些狼人。就在前几天，卡洛尔还提着几个狼人的头到镇上来。卡洛尔是为卡尔文家族效力的，这个家族专门对付恶魔、亡灵和各种杂七杂八的怪物。你去和乔纳森谈谈吧，他是卡尔文家族的首领。', '去和夜色镇的乔纳森·卡尔文谈谈。', '现在是黑暗的时期。每根摇摆的树枝都传播着糟糕的消息，每块岩石之下都隐藏着邪恶的力量。$B$B这种时候有个陌生人到我家里来，向我询问狼人的事情……请不要责怪我的疑神疑鬼，我只要知道你的动机。$B$B而且我相信你会告诉我的，对吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1044, '问题的答案', '不要担心，我们会解决狼人的问题，也一定可以遏制这些由你朋友引到森林里来的邪恶势力。对于你的朋友，我也没有什么敌意。各种诡异的事情越来越多了，$n，黑暗的势力不会停止它的脚步。$b$b我就不耽搁你了，可能还有其他人想要知道你在暮色森林的矿山里发现了什么。', '回到达纳苏斯去见塞恩提尔·刃纹。', '这就是维琳德.星歌的命运吗?高阶女祭司听到这个消息一定会很失望的，维琳德失踪之前和她是很好的朋友。不过可以肯定的是，月神镰刀是我们的女神恩赐给维琳德的，而它现在已经不见了，这令我感到很不安。$B$B不过一事归一事，你为我们做出了贡献，我得好好感谢你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1047, '新的边疆', '注意了，英雄们！$B$B塞纳里奥议会正在招募精干的部落成员来帮助他们探索卡利姆多大陆！在塔纳利斯沙漠的西边隐藏着常人难以想象的危险，议会希望有人能光荣地接过这个任务，去探索那个地方。$B$B所有对此感兴趣的联盟成员都应该去向塞纳里奥议会报到。去和达纳苏斯的大德鲁伊范达尔·鹿盔谈谈吧！', '与达纳苏斯塞纳里奥区的大德鲁范达尔·鹿盔谈一谈关于议会号召联盟成员探索卡利姆多大陆的事情。', '是什么让你觉得我会被你这样的$r所干扰，$C?好吧，让我停下每天都要处理的无数重要事情来帮你搞定你那点鸡毛蒜皮的小事情，我们相信达纳苏斯的利益-啊，不，整个泰达希尔的利益-与你手头上的事情相比都是不值一提的，对吗?$B$B月光林地的那群蠢货找了一堆人来为我提供帮助，这简直是在浪费我的时间，那么现在我是不是要继续忍受下去呢?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1055, '莱恩的净化', '完整的魔棒就在你的手中，莎尔蒂恩正在静候佳音。', '回到月亮井旁的莎尔蒂恩那里。', '你成功了，$N!干得不错!', '你好，$N，我们又见面了。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1056, '石爪峰之旅', '森林之魂告诉我，你是个勇敢无畏而且乐于旅行的$c。$b$b在南方离密斯特拉湖不远的地方，有一条名叫石爪峰小径的隧道，沿着这条隧道走，你会到达石爪山脉中的一个名叫风剪峭壁的地方。到了那儿以后，穿越西南方的峭壁湖，然后向北爬上陡峭的斜坡，就可以到达石爪峰了。$b$b看守者奥巴格姆在那里等着你。听从他的吩咐，$n。$b$b这次旅程会很危险。', '拜访石爪峰的看守者奥巴格姆。', '啊，你终于来了。法德瑞斯一定是听从了森林之魂的指引……', '嗯?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1059, '夺回焦炭谷', '虽然血怒氏族目前已经被我们压制住了，但如果我们不采取进一步的行动的话，她们很快就会再度组织起来。$b$b在离贫瘠之地很远的南方，有一个叫作千针石林的地方。如果你能从千针石林一直向西走，一直走到菲拉斯森林的边缘，就会在那里找到一位名叫法芬德尔的德鲁伊。$b$b这位伟大而睿智的德鲁伊能够召唤大量的森林之灵来帮助我们将焦炭谷变成一片茂密的森林。$b$b马上去找到他吧，$n！', '在千针石林与菲拉斯的边境上找到法芬德尔。', '守护者奥巴格姆在这种紧急的情况下派你来找我，这确实是个明智的选择。$B$B我们要尽快为焦炭谷做点什么,不然就要来不及了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1061, '石爪之灵', '地精们在石爪山地区烧杀劫掠，山灵们已经被彻底地激怒了。土地正在哭泣，而那些可以听到这种哭泣的人……正在聆听着这声音……$B$B希雷斯·碎石是部落里的一位前途无量的萨满祭司，她已经被派去了石爪山。她报告说那里到处都是地精的伐木站，并向我们请求支援。$B$B到石爪山去和她会合吧，你只需要沿着贫瘠之地的十字路口西边的道路一直前进即可，她的营地就在巨木谷里。', '找到石爪山脉和贫瘠之地交界处的的希雷斯·碎石并和她谈一谈。', '啊，来了一个$C，非常好。我们正好非常需要你的帮助来对付这群盗掠者!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1063, '长者', '为了彻底平息石爪山的山灵，我们必须与牛头人长老们商讨商讨。$B$B我记不清他们那么多首领的名字，但我知道其中肯定有一个名叫玛加萨的。我听说她已经很老了，但漫长的岁月赐予了她无穷的知识。如果说有哪位牛头人能够提供精神力量的帮助的话，那一定就是她了。$B$B玛加萨就居住在牛头人部族的首都城市雷霆崖中的长者高地上，也就是城市西北部的那座高地。去与玛加萨谈谈，告诉她石爪山这边发生的事情。', '与雷霆崖的玛加萨谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1064, '被遗忘者的援助', '牛头人和这片土地是血脉相连的，听到石爪山陷入困境之后，我感到非常痛苦。恐怕如果我们要治愈这片土地，就必须先着手祛除这片土地上的疾病。$B$B说起来也巧，被遗忘者正好和我们结了盟，他们应该对疾病有不少了解。我相信他们能帮助我们，而且他们也能借此加强我们之间的相互信任。$B$B去和药剂师扎玛谈谈吧，她是被遗忘者派来的使者。你可以在灵魂高地下的预见之池找到她。', '和预见之池的药剂师扎玛谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1070, '守卫石爪山', '你好，$N。$B$B你看起来真像是个喜欢旅行的$r啊。你有没有去过石爪山？现在那个地方被风险投资公司和其他一些暗夜精灵的敌人给占据了。$B$B最近，哨兵莱恩·狼行者派我的朋友凯拉·影矛到那里去进行调查，但至今我还没收到她的任何消息。更让我担心的是，联盟还派了一名侏儒法师跟着她……这真是麻烦。$B$B你能找到她，然后把她的近况汇报给我吗？', '找到位于石爪山脉狂风峭壁旁的山谷中的凯拉·影矛。', '啊，是塔拉要你从梣谷过来这里的─我很想念她，也想念我的家乡和朋友们。她执行的那些任务一定进行得不错吧，我为她而自豪。$B$B很高兴见到你，$N。', '你好，$C。$B$B是联盟派人来增援我了吗?或者你是来视察工作的?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1072, '老同事', '我正在构想的新装置是这世上最先进的，但我需要有一种特殊的药水来驱动它。我想我们应该得弄一些质量上乘的材料来制作这些东西，也许这会是你这个最后一个任务，所以我当然会希望做得尽善尽美。$B$B除此以外，我们还需要一些强力爆炸材料：硝酸甘油炸药。$B$B能制出NG-5炸药的只有一个人，那就是我的老朋友洛玛克·链带，你可以在侏儒区的升降机边上找到他。$B$B你让他帮我们造些NG-5吧，我要去继续制造我的新装置了。', '与铁炉堡的洛玛克·链带谈一谈。', '啊啊啊……加克希姆让你来的，是吗?我怎么知道你不是在骗我?!说啊!你说啊!你倒是说啊!', '对矮人哲学家来说，时间并不是什么难题，问题是你在这里干什么。有什么事啊?快说快说!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1075, '玛伦的卷轴', '好吧，现在我们来研究一下我计划里的远程引爆这部分吧……哦，我有解释过吗，没有？$B$B好吧好吧，简而言之就是这样的：只需要一个小魔法，我就可以在远离这玩意的情况下引发爆炸。这么一来，我得给它加一个装置，这样就可以让你只消轻轻按下一个按钮，NG-5便会爆炸。$B$B但我需要另一个老友的帮助，就是暴风城里的科林·玛伦，让他给我提供引爆用的法术。他就在暴风城的法师区里，他是一个人类，相信你很容易就可以找到他。', '找到暴风城的科林·玛伦。', '你要的那道法术要能让你在很远的地方引爆爆裂物……嗯，我明白了。', '你好，$C。我能为你做些什么吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1081, '泰兰德的接待', '$N，我想泰兰德·语风一定会感谢你接下这个任务。$B$B相信我，如果你能很好地完成这个任务，我们在石爪山脉的力量就将大大增强。$B$B如果你认为你也可以帮助我们对抗地精的暴行，就去达纳苏斯城的月神殿找到泰兰德吧。', '到达纳苏斯去找到泰兰德·语风。', '你好，$N。我肯定我以前听过你的名字。尽管你还非常年轻，但我很高兴能看见你踏上了属于你自己的征程。$B$B如果你愿意接受这件礼物的话，我将感到非常荣幸。', '你好，$C。我能帮你什么忙吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1082, '向塞恩希尔报告', '感谢你的巨大帮助，$N。$B$B如果你向她们证实了我和加克希姆还活着的消息，灰谷的哨兵部队一定会重重酬谢你的。告诉她们，我们正在努力地阻止着风险投资公司在此的恶行，努力地为治愈这片大地而忙碌。$B$B去找阿斯特兰纳的塔拉·塞恩希尔吧，她会很高兴听到你的好消息的。', '向灰谷的哨兵塞恩希尔复命。', '感谢你，$N。感谢你为哨兵部队效力。$B$B我很高兴得知凯拉─呃，还有加克希姆─的工作进行得非常顺利。$B$B我们非常感谢你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1085, '守卫石爪山', '就一个暗夜精灵和一个侏儒的搭档来说，石爪山目前的状况实在是不容乐观。$B$B风险投资公司几乎快把这里全都毁了，而我正努力地阻止着他们。$B$B请别对加克希姆抱有偏见，他知道我们得精诚合作。$B$B如果你愿意帮助我们的话，就先去和加克希姆谈谈吧。$B$B很抱歉我现在没法让你给塔拉带去一些好消息，但我想很快就会有了。', '与石爪山脉的加克希姆谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1090, '格雷苏的要求', '你知道的，我曾经是这里的二把手，但在格雷苏接管了这里之后，一切就全变了。我的老板菲兹克斯被他炒了鱿鱼，而我被丢到这片矿里来当苦力。菲兹克斯让我就呆在这里，暗中收集信息，如果我们能知道格雷苏在打什么算盘，菲兹克斯的新老板就会付给我们不错的酬劳。$b$b无论如何，现在我知道的是，格雷苏下令要大量地开采这种青绿色的矿石。要不这样，我给你搞出一份样本来，你帮我带给菲兹克斯，但是我在采集矿石的时候，你得帮我留意外面的巡逻兵。', '在匹兹尼克完成开采之后拿到神秘矿石。', '谢谢啦，$N。时间越长越危险，还好我们及时完成了任务。$B$B重要的是我们拿到了矿石，你赶快去将它送到菲兹克斯那里。', '小心，巡逻兵和工人经常会在这一带走动，要是我们被抓住可就惨了。', '在匹兹尼克采矿时保证他的安全。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1095, '新的指示', '风险投资公司雇用侏儒的事情在安德麦引起了太多的风波。贸易巨头们不赞成拉兹杜克与这个叫格雷苏的家伙合作。$b$b雷德沃克斯主管让我来处理这个问题，我相信是某几位贸易巨头让他这么做的。当然，主管并没有告诉我这些，只是我自己的猜测而已。$b$b不管怎么样，我们必须赶走格雷苏，让菲兹克斯去“照顾”他一下应该是个不错的主意。', '把新的指令带给石爪山的菲兹克斯。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1097, '艾尔默的任务', '暴风城里有位名叫格瑞曼德·艾尔默的矮人铸剑师，他需要有人帮忙送一份东西。据我所知，他是把一个包裹送到他在北方的故乡去。$B$B你看上去很强壮，所以如果你有兴趣做这份跑腿工作的话，就去找格瑞曼德吧。我们这儿的确很需要你，但我们也得加强与矮人盟友们的联系。$B$B你可以在暴风城矮人区的武器店里找到格瑞曼德·艾尔默。', '与暴风城的格瑞曼德·艾尔默谈一谈。', '你是来帮我送东西的?好极了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1098, '影牙城堡里的亡灵哨兵', '为了一次针对影牙城堡的突袭行动，我们派了两名亡灵哨兵潜入到城堡内部去收集情报。他们一直没有回来，可如果我们还想让这次攻击行动不至于无功而返的话，就必须收到他们的报告！$B$B这就是你的任务了，$N。潜入南边的影牙城堡并找到亡灵哨兵阿达曼特和文森特。找到他们之后要尽力帮助他们。$B$B这个任务很危险，但也很重要，$N。只许成功，不许失败。', '找到亡灵哨兵阿达曼特和亡灵哨兵文森特。', '文森破碎的尸体躺在地上。$B$B尽管亡灵哨兵阿达曼会把他的报告呈送给哈德瑞克……但文森收集到的资料细节恐怕就永远无法得知了。$B$B但是……他的手里抓着一个小玩意……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1115, '车手的传闻', '既然我们已经为侏儒服务过了，那么也该帮帮地精一把！$B$B我听说地精的赛车手，就是名叫纳兹·斯迪波尔的那个，他并不是一直都用这个名字。我想知道他为什么改名字，这其中是否隐藏着一个秘密，还有……我不知道他是否很看重这个秘密。$B$B如果说有人知道真相的话，那肯定是在荆棘谷南端的藏宝海湾里的克拉兹克。去找克拉兹克谈谈，问问他关于那个地精驾驶员的事情。$B$B如果你从他那儿得到有用的信息的话，我们也许能从中挣一大笔钱。', '和荆棘谷藏宝海湾的克拉兹克谈一谈。', '你想了解有关纳兹.斯迪波尔的事?那个闪光平原的赛车手，是吗?$B$B嗯，我也许能找到一些关于他的东西……但这并不容易，也不会很快。$B$B当然，也不会很便宜。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1123, '拉比恩·萨图纳', '这个任务的内容是这样的，守护者雷姆洛斯在月光林地的总管——拉比恩·萨图纳——正在征集愿意去探索塔纳利斯沙漠以及安戈洛尔环形山地区的冒险者，他就住在月光林地的永夜港里。$B$B我想让你明白你出现在那里的重要性，达纳苏斯的暗夜精灵和月光林地的塞纳里奥议会之间的关系越来越紧张。你要抛开种族区别，去和议会的成员谈谈吧。祝你好运。', '与月光林地永夜港的拉比恩·萨图纳谈一谈。月光林地在费伍德森林和冬泉谷之间，可以从木喉要塞中的一条通道抵达那里。', '我是拉比恩.萨图纳，我代表守护者雷姆洛斯以及这块圣地的所有居民欢迎你。$B$B我感谢你有兴趣并且急切地想要帮助塞纳里奥议会。牛头人非常尊重塞纳留斯神，通过这座友谊的桥梁，部落的成员在这里也会受到我们的欢迎。艾泽拉斯世界的安全是我们共同的目标。$B$B你在这里就是我们的朋友，$N。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1130, '梅洛的关注', '$N，梅洛·石蹄已经听说了你的作为，并为你的将来做了打算。$B$B如果你愿意的话，去雷霆崖和他谈谈，他就在猎人高地上。', '和雷霆崖的梅洛·石蹄交谈。', '你终于来了，$N。你有没有做好去远方旅行的准备?$B$B如果是的话，年轻的$C，请听我说……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1132, '菲欧拉·长耳', '哦，又来到了海上！感受着清风温柔的吻，让海浪拍打着我的身体，这让我不禁想起我那可敬的母亲。$B$B好心的$c，希望我能有像你一样的好运，因为我一眼就看出你会做出一番轰轰烈烈的事业！$B$B我应该把卡利姆多的故事讲给每个人听，卡利姆多是一片充满机遇的土地！如果你愿意去海的那边试试运气，就乘着船去那迷人的奥伯丁港吧，到那里去和我的精灵同伴菲欧拉·长耳谈一谈。$B$B她将指引你开始卡利姆多的冒险之旅！', '与黑海岸奥伯丁码头的的菲欧拉·长耳谈一谈。', '你好!是米奈希尔港的弗林特先生派你来的吗?弗林特先生从来就不会看错人的。如果是他派你来的，那么我坚信你就是那个命中注定要在卡林多做出一番事业的$r。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1133, '通往阿斯特兰纳的旅途', '$n，快到阿斯特兰纳去。我确信像你这样热心的联盟成员会在这里有一番作为的。和辛德瑞尔·速火谈一谈，尽可能地帮助他吧。$B$B对了，你不必提起我，因为辛德瑞尔根本不认识我……', '到阿斯特兰纳去和辛德瑞尔·速火谈谈。', '$N，你是来为联盟提供帮助的吗?我们欢迎这样的帮助，尽管梣谷森林美景依旧，但它早已不是以前那片安宁祥和的森林了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1137, '回复菲兹尔', '精铁有惊人的抗热性！我肯定它对菲兹尔要制造的活塞有所帮助，但他需要真正的精铁矿石，而不仅仅是一些小碎片。$B$B完美的矿石只能从荒芜之地北部边境的奥达曼挖掘场深处采到，只有那里才是精铁矿真正的产地。$B$B请代我向菲兹尔·铜栓致意，并把我对你说的话告诉他。$B$B路上小心，$N。我相信我们会再次见面的。一旦菲兹尔知道有精铁这样一种东西，他一定会让你帮他去奥达曼采集那些矿石的！', '和千针石林中闪光平原的菲兹尔·铜栓谈一谈。', '$N，你回来啦!你找到马特克了吗?你和他谈过了吗?他说了些什么?他能帮忙吗??$B$B告诉我告诉我告诉我!!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1144, '进口商威利克斯', '总算有人来帮忙了！$b$b你肯定不知道我被关在这鬼地方有多久，我已经不记得外边的世界是什么样子了。$b$b你看，我好歹还是个大商人来着。照他们的说法我这叫“见钱眼开”，前一阵子看到这里有利可图我就来了！麦伯克·米希瑞克斯愿意为在这个猪圈一样的地方生长的红叶薯付个好价钱，我还以为这是个有利可图的营生哪，结果……如你看到的一样，我犯了个小错误！$b$b总之，如果你这大善人愿意帮我逃出这儿的话，我是不会吝啬的。', '护送进口商威利克斯到达剃刀沼泽的出口。', '再谢你一次，朋友!我说过我是绝对不会吝啬的。', '带我出去!', '帮助进口商威利克斯逃离剃刀沼泽。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1152, '知识试炼', '你与我在一起的时光就要结束了。虽然我具有丰富的知识，但是知识的试炼不是由我来安排的。有许多新的知识等着你去学习，有许多新的地方等着你去探索。$B$B如果你已经准备好了，那就去找布劳格·幽魂——他是个拥有无穷智慧的萨满祭司。他将进一步对你进行试炼，你要按照他的话去做，$N。$B$B一切准备就绪后，就去找连接石爪山和灰谷的通道，布劳格就住在那儿。要当心，$N, 暗夜精灵也许会阻止你的试炼。', '找到连接石爪山和灰谷的石爪小径里的布劳格·幽魂。', '天气越来越冷，哥布林越来越倡狂地肆虐在我们的土地上，夜精灵对新生的种族表现出了他们一贯的高傲自大。被遗忘者和兽人并不是造成世界创伤累累的唯一原因，许多智慧的种族都对此负有责任。多恩知道这一点，他派你来找我，因为你也拥有足以认识到这一点的智慧。$B$B我是布劳格。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1159, '知识试炼', '干得好，$N。你已经通过了知识的试炼的第一部分，但是此外还有一个问题要你回答，这个问题将由别人来提出。$B$B去找洛丹伦城的帕科瓦·芬塔拉斯。在被瘟疫控制之前，他曾是一个伟大的人类历史学家。现在他依然继续寻求着启迪，虽然那是一种不同性质的启迪。$B$B他在向你提问之前会另有一个要求。到目前为止你都能对各种情况应付自如——因此我也相信你能越过这个障碍。', '找到幽暗城的帕科瓦·芬塔拉斯。', '布劳恩派你来的?不可能。$B$B<帕科瓦仔细打量了你一番。>$B$B深入朵丹尼尔，怀着信仰纵身跳下高崖，击败了强大的元素生物?哈!你可能是个小丑，或是个在旅店里信口开河的冒险者。现在你跑来跟我说你有能力通过我的试炼?好吧……$C。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1167, '奥萨拉克斯之塔', '在你正面对抗埃瑟里克斯之前，最好先向巴苏尔请教请教。毫无疑问，他一直都在警惕地观察着那座塔，应该会有一些新消息。', '去和奥萨拉克斯之塔附近的巴苏尔·影击谈一谈。', '啊，真高兴我们又见面了，$N。这里刚刚发生了一件非常奇怪的事情，你来的真是时候!$B$B这真是太奇怪了，$N。一切似乎都很正常─就像现在这周围一样平淡无奇─突然，从塔顶的一间小屋里发出了令人眩目的强光，紧接着传出了一阵尖叫。那尖叫声刺破了夜空，时断时续的强光照亮了大地。究竟发生了什么呢?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1170, '奥妮克希亚的血脉', '石槌村被奥妮克希亚的种族所侵犯，不过死亡之翼的女儿怎么会来侵犯我们的领地？$b$b这真是个大麻烦。奥妮克希亚来这里肯定不仅仅是为了围攻食人魔，而是还有别的什么目的。$b$b快去通知莫格穆洛克！我们必须采取行动了。', '和蕨墙村的莫格穆洛克大王谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1171, '奥妮克希亚的血脉', '别烦我。去告诉德拉兹辛比，我们就留在这儿。这儿没有黑龙。', '去和蕨墙村的德拉兹辛比谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1178, '地精赞助商', '不管在哪里，我们的赛车队都是地精的骄傲。你会对那些以各种方式为车队贡献自己力量的人感到吃惊的。$b$b你认识加兹鲁维吗？他为我们从全世界寻找赛车零件，有一次他甚至为我们找来了一台完整的赛车！$b$b几星期前，他说他要送给我们一套新的燃油调节器，但至今还没有到货。他一向说话算数……你能去棘齿城帮我问问吗？我原本并不是特别心急，但是侏儒正在赶上我们的步伐！', '和贫瘠之地棘齿城的加兹鲁维谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1180, '地精赞助商', '回到关于你为何来这里的话题上。我的确向普兹克保证过会帮他运一台新的调节器，但我现在还没有收到这台机器。藏宝海湾的里维加兹说他已经把东西装船运了过来，也许是在运输过程当中出了什么差错。$b$b如果是那样的话，我们就无能为力了。现在我只知道它已经从藏宝海湾运了出来。$b$b去找码头管理员罗兹基尔吧，他应该能帮你查一查出货记录。', '和荆棘谷藏宝海湾的码头管理员罗兹基尔谈一谈。', '运往棘齿城的货物?让我查查出货记录……$B$B没有，记录上最近一次运往棘齿城的货物是崔斯里克的靴子。除了一些建筑材料和工具之外就没别的了，肯定没有你要找的东西。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1181, '地精赞助商', '恐怕我也只能帮你这些了，$n。如果你还想了解更多事情的话，就直接去找大财主里维加兹本人吧。还有谁能比里维加兹对他自己的生意更了解呢？$b$b你到港口那边的小酒馆顶楼的房间里就能找到他了。', '与藏宝海湾的大财主里维加兹谈一谈。', '噢，当然，我当然知道你在说什么。不过，恐怕我帮不上你的忙了。我的确是派了些人去搞一张燃料调节器的设计图来，可他们却都两手空空就回来了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1184, '虫群的消息', '返回奥格瑞玛的贝尔戈洛姆那里，告诉他摩克塔正在一丝不苟地执行他的命令。把我的研究进展也告诉他，我希望他能知道这些信息，贝尔戈洛姆一定会为此感到高兴的。', '回到奥格瑞玛的贝尔戈洛姆·石槌那儿。', '感谢你的帮助，$C。大酋长也会对你大加赞赏的。$B$B哦，当然，我会向他提及你的名字。他经常找我谈话，而且非常尊重我的意见。$B$B现在如果你不介意的话，我还有很多事要做。如果你又见到了科兰，并且他有了关于这些生物的最新消息，那么就赶快回来告诉我─我会认真考虑这些昆虫给我们带来的威胁，并且认真地对待它们。', '$C，你还没去千针石林吗?我希望马上就能听到来自摩克塔的消息。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1185, '壳中的东西…', '', '', '嘿，又是你!哦，我是说你，$N!没错─就是你!$B$B嗯，说正事吧!$B$B你在希利苏斯找到的东西其实是一本书，它是一本以某种非常古老的语言─也就是达纳苏斯语─书写的日记。我要好好阅读一下，不过这得花一些时间。你所发现东西的对议会来说意义重大。$B$B大家会非常兴奋的!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1186, '第十八个驾驶员', '我要开始着手将这个新的燃油调节器装到赛车上去了，如果你想要帮助车队的话，就去和拉泽瑞克谈谈吧。他是我们的驾驶员——更确切地说，是第18个驾驶员——他想为这些赛车做一个小小的修改。$b$b他经常有些奇思妙想，所以请不要太吃惊了。', '和千针石林闪光平原的拉泽瑞克谈一谈。', '你就是给普兹克帮忙的那个$r，是吗?我曾经就像你一样，在这里到处奔走，解决天知道哪里来的机械师交给我的各种问题。$B$B现在么，看看我!我已经是整个哥布林车队里最非凡的驾驶员了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1190, '跟上节奏', '铜栓兄弟俩发现了一种新的材料，这是唯一说得通的解释。它们的车速比以前快了，但它们的设计，以及我们搜集的其它一些数据都和以前的一致。$b$b我们知道的是，瑞兹尔·铜栓一直以来都致力于这项新发明的计划之中。$b$b扎米克可以为你提供掩护，这样你就能从他们那儿偷到这些计划了。', '让扎米克掩护你，然后为千针石林闪光平原的普兹克偷到瑞兹尔的计划。', '这是一卷草草写成的有关某种原材料精炼方法的笔记和设计图。', '我们必须搞清楚铜栓兄弟发现的这个东西到底是什么玩意儿，然后将其弄过来为我们自己所用。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1191, '扎米克的困扰', '', '', '我们走!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1194, '瑞兹尔的图表', '瑞兹尔的图表上介绍了精铁矿石的精炼过程。从他的草稿中可以得知，精铁矿石来自于荒芜之地之中的奥达曼挖掘场。$b$b很多其它笔记的内容都与这种矿石的抗热性能有关。$b$b整个笔记的重头似乎是关于未精炼的精铁矿石的。', '把精铁矿石样本交给千针石林闪光平原上的普兹克。', '精铁?真有趣……如果它真如你所说有那么强的抗热性能的话，那就能解释地精赛车最近的出色表现了。$B$B你带给我的这个样品是绝对是无价的。我将用它来做些测试，但我需要更多的矿石来将其投入实际的应用。', '你发现了什么，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1198, '寻找塞尔瑞德', '这些天有很多关于暮光之锤与黑海岸北部黑暗深渊里的纳迦结盟的传闻。$b$b我在这里的任务是收集尽可能多的情报，这样我们就知道何时何地会需要帮助了。$b$b我派去侦察黑暗深渊的斥候塞尔瑞德已经离开好几个星期了，但直到现在他也没有提交任何报告。$b$b糟糕的是我的其他斥候也正在处理一些紧急事务，实在抽不出人手了。$b$b帮我找到塞尔瑞德，并且帮助他完成任务吧，$n。', '到黑暗深渊去找到银月守卫塞尔瑞德。', '哨兵山德拉斯派你来的?太好了。有一个险恶的阴谋正在这片堕落之地上悄悄地酝酿着……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1246, '失踪的使节', '对了，就是他，现在我想起来了…达舍尔…达舍尔…什么来着……他的名字是什么来着？拳！达舍尔·石拳。圈里人都叫他拳——或许是因为他喜欢制造事端的缘故吧。$B$B你通常可以在旧城区里见到他——在旧城区中心练拳。去和他谈一谈，如果有必要的话，你不妨威胁威胁他，用点暴力手段什么的，有时候只有那样才能让他说点真话出来。别犹豫！要是真像这份东西上所写的那样，他应该已经深陷其中，不会那么轻易就告诉你什么有用的信息。', '与暴风城旧城区里的达舍尔·石拳谈一谈。', '什么?!$B$B你算老几，居然敢来过问我的私事?我的事情和你无关，闪开!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1247, '失踪的使节', '原来如此……唔……我对腐草农场那边的会议略知一二，我记得是几周前组织的，但我没有去参加那个会议。我只参加了A计划的那部分，但A计划失败了……那些该死的冒险者。$B$B我们的线人说，那个执行B计划的小子来自米奈希尔，他的外号叫干柴。对于他们的后备计划我就知道这么多了。', '与暴风城的埃林·提亚斯谈一谈。', '很高兴看见你还活着，$N。那么，达舍尔那边进行得还算顺利吧?$B$B我已经仔细读过他们的计画了，尽管没有在里面看到我们使节的名字，不过这计画书里曾写到，如果他们的第一次绑架计画失败的话，就会马上实行B计画。$B$B达舍尔提到的『瘦子』似乎在这里面查不到别的资讯，但如果真如你所说，他来自米奈希尔的话，我们就有线索了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1248, '失踪的使节', '我有一个隐居在米奈希尔港的线人。他已经退休了，不过如果你告诉他你是为我工作的话，他应该会很愿意帮助你的。他名叫米克哈尔，在几年前离开暴风城的时候，他提到过自己要去旅店工作。$B$B和他谈谈，想办法找到这个干柴，再打听一下有没有关于使节被绑架的消息。我们现在得弄清楚他被带到了什么地方去，或者至少弄清楚他是谁。这份摘要里没有提到绑架行动完成以后的事。', '与湿地的米克哈尔谈一谈。', '国王陛下?!我是说……国王陛下?真正的国王陛下?你不会是在开玩笑吧?你可没说你在找的是绑架国王的绑匪啊，我甚至没听说他失踪了啊－－这多少也能解释他儿子继位的理由。$B$B我马上和伊林联络，他一定会想知道你的进展的。$B$B我可从没想过贾恩会为了一点肮脏的钱就把暴风城给出卖了。须知盗亦有道啊!$B$B现在最重要的是要找到亨德尔。我想我应该能帮上忙。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1250, '失踪的使节', '好吧，迪菲亚兄弟会出价虽高，可还不值得把我的命也给赔上。他们抓走的是国王。对，没错，正是暴风城的国王，他可不是什么简单的外交使节。他当时正在去塞拉摩与吉安娜·普罗德摩尔会面的路上——这显然是件大事，当然也是个大秘密。但这可不是迪菲亚兄弟会的主意，实际上他们也是为别人效力的。我想只有他们自己知道谁是他们的雇主。$B$B我的份内事就是趁国王的船还在港里的时候，和他们在船上的内应碰头，那家伙叫亨德尔。我就知道这么多了，我发誓！', '与湿地的米克哈尔谈一谈。', '国王陛下?!我是说……国王陛下?真正的国王陛下?你不会是在开玩笑吧?你可没说你在找的是绑架国王的绑匪啊，我甚至没听说他失踪了啊－－这多少也能解释他儿子继位的理由。$B$B我马上和伊林联络，他一定会想知道你的进展的。$B$B我可从没想过贾恩会为了一点肮脏的钱就把暴风城给出卖了。须知盗亦有道啊!$B$B现在最重要的是要找到亨德尔。我想我应该能帮上忙。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1259, '帕瓦尔·雷瑟上尉', '我不认识这个帕瓦尔·雷瑟上尉，你最好还是去问问泰索兰副官。他负责管理塞拉摩所有守卫的档案，包括守卫的个人资料和他们的装备。$b$b他可以查查这些档案，然后告诉你这个雷瑟到底是谁。', '从塞拉摩的泰索兰副官那儿找出更多关于雷瑟的消息。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1260, '摩根·斯特恩', '我在为餐馆编写新的菜谱，这套新菜谱里都是本地特产的菜色，以“海湾”为主题。我想，蓝色隐士旅店的客人一定会很喜欢这个的！$B$B我让我侄子摩根到塞拉摩去收集当地的食谱了，那地方就在尘泥沼泽的边界地带。现在我得知道他目前都找到了些什么。$B$B去塞拉摩的路很长，起码对我来说是太长了些。不过像你这么个年轻的$c对这种长途旅行一定会欣然往之的，对吧？', '和塞拉摩的摩根·斯特恩谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1264, '失踪的使节', '每个月初，库尔提拉斯的水兵们都会领取薪水，然后离开塞拉摩到别的地方去游玩。大部分人会到这里来找女人，喝酒，寻欢作乐一番。他们当中有一些人整天都会泡在酒馆里，我敢肯定亨德尔也是其中之一。$B$B只要那家伙现在还留在塞拉摩的话，那么当地的指挥官萨穆尔就能帮你找到他。虽然他只对普罗德摩尔家族效忠，但如果你说出埃林的名字，他也会帮助你的……应该会的。', '找到尘泥沼泽的指挥官萨穆尔。', '很高兴见到你，$N。我是指挥官萨莫尔，普劳德摩尔女士麾下的塞拉摩驻军的最高负责人。$B$B尽管我很忙，不过如果你有什么问题的话，请尽管说出来。虽然我不能在这上面花费太多时间，但只要你需要帮助，我是绝对不会坐视不理的。$B$B如果你计画出城旅行的话，我建议你务必小心。除了巨魔、兽人和鱼人外，沼泽地的南部到处都是黑龙。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1266, '失踪的使节', '亨德尔下士就在这里的西边，他现在正在执行保护那些轮休的塞拉摩密探们的任务。密探们正在那边监视着部落的前哨基地——蕨墙村，当然也时刻留心着其它任何有可能威胁到我们的东西。$B$B你应该很容易就能找到他，沿着道路搜索每一个帐篷就行。$B$B我现在还有另一件事要处理，但很快就可以追上你。', '找到尘泥沼泽中的亨德尔下士。', '你好。这里可不是个散步的好地方。如果你珍惜自己的生命的话，就不应该在这一带闲逛。$B$B如果你有什么问题的话，我想我会尽可能地帮助你。请时刻警惕那些肮脏的巨魔，据说部落在这片沼泽地里有一处基地。我们的密探已经开始尽力搜寻那个基地了，可是他们取得的进展实在是过于缓慢，我们还没有什么成果。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1267, '失踪的使节', '', '与尘泥沼泽的吉安娜·普罗德摩尔谈一谈。', '首先我要对你所做的一切表示感谢，$N。我的人民与暴风城的人民都应该对你表示感谢。可惜，鉴于目前的情况，我不能将你的事迹公诸于众。$B$B你也得理解，我同样无法公开对你表示答谢，但我向你保证，你所做的事情一定会得到嘉奖。$B$B总有一天，当你再次来到塞拉摩的时候，我一定会让你获得你所有理应得到的荣誉。$B$B再一次感谢你，$N。', '你好，$N。特沃什已经向我解释过了你的来意。在你寻找那名与外交使节的失踪有着直接联系的人的时候，我一直在关注着事态的发展，最后我们决定先找到你，以确保此事处理得妥善迅速。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1268, '可疑的蹄印', '有几排蹄印从树荫旅店那仍然冒着烟的废墟中延伸出来。大部分蹄印都埋在沼泽地的松软泥土里没法辨认，不过至少还有一些是可以看清的。', '把树荫旅店的可疑蹄印报告给蕨墙村的克罗格。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1270, '伊格纳兹的逃亡', '太好了，总算碰到一个不是要来吃了我的人了！$B$B我正愁没人来帮我对付这儿的怪物哪，$g兄弟:小姐;\n，你看来就挺合适。$B$B棘齿城一个叫麦伯克·米希瑞克斯的地精需要弄些睡菜叶……或是别的什么东西来做药剂，说实话我不在乎他做什么，反正他给的报酬不错，而我又正巧熟悉这个沼泽，所以我就来了。$B$B倒霉的是还没找到睡菜，我就被包围了！你能帮我从这儿逃出去吗？哦，对了，顺便在我找睡菜的时候替我断后。', '护送伊格纳兹，然后和棘齿城的麦伯克·米希瑞克斯谈一谈。', '伊格纳兹把我要的草药带回来了，他说是你帮助他脱身的。干得好!伊格纳兹的朋友就是我的朋友!$B$B在他再次进入南方的沼泽地之前，他让我见到你的时候就把这个交给你。', '嘿!你有没有在沼泽地里看到一个名叫伊格纳兹的臭哄哄的家伙?我派他去尘泥沼泽采点草药给我，现在他也该回来了吧!', '帮伊格纳兹找睡菜叶', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1271, '盛筵', '', '', '我的侄子告诉我，你帮助他在尘泥沼泽进行研究工作，还帮助他的同事化险为夷。嗯，我们斯特恩家族向来团结一心，而且我们绝对不会漠视我们的朋友!$B$B去准备一下吧，$N，我们要为你举行一个宴会，以表达我们对你的敬意!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1274, '失踪的使节', '很抱歉，$g先生:夫人;\n。德拉维主教要我征召一些冒险者以帮助他解决一件棘手的事情。$B$B如果你能尽快而且悄悄地去一趟暴风要塞与他谈一谈的话，我想他将会非常感谢你的帮助。我得再申明一次，口风请紧一些，这件事情很重要。', '找到暴风要塞的德拉维主教。', '你好，$N。我是德拉维主教。$B$B如果你想说的是我正准备处理的那件事务的话，那么很明显年轻的汤玛斯已经成功地说服你来帮助我们暴风王国了。他总是对我的指示领会得很透彻。$B$B恐怕我没有时间把事情说得很详细了，所以请允许我简单扼要地跟你说明一下情况，并且，请把它牢记在心。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1282, '微笑的吉姆', '我对吉姆的事很遗憾……他以前不是那样的。他曾在沼泽地开了个旅店，那是个很不错的地方。$b$b我真不想谈这个。你想谈的话就去找维米斯队长吧。他在塞拉摩的城堡里，也就是吉安娜女士的法师塔东边的那座大兵营。', '与塞拉摩城堡顶层的盖兰·维米斯队长谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1284, '可疑的蹄印', '有几排蹄印从树荫旅店那仍然冒着烟的废墟中延伸出来。大部分蹄印都埋在沼泽地的松软泥土里没法辨认，不过至少还有一些是可以看清的。', '把树荫旅店的可疑蹄印报告给塞拉摩的盖兰·维米斯队长。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1285, '戴林的下属', '雷东……雷德帕斯……啊，找到了！帕瓦尔·雷瑟上尉。$b$b他和大部分跟随普罗德摩尔女士横渡大海的征募兵一起加入了塞拉摩守卫军。16岁时加入库尔提拉斯海军，战绩出色，屡获提升……$b$b已列入失踪名单。', '把雷瑟的资料报告给塞拉摩的盖兰·维米斯队长。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1286, '背叛者', '在沼泽地里立足确实是非常艰难的，但是通过不懈的努力，最后我们终于在这一带守住了几座防守哨塔。$b$b我收到的最新消息和侦察报告说一群背叛者占据了旅店西南方的一座废弃哨塔。$b$b这群背叛者的首领叫加科因，去看看能不能从他身上找到什么消息。$b$b小心点，$n。他可是个难对付的家伙。', '从巴鲁斯·加科因及尘泥沼泽的背叛者那里打探消息。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1287, '背叛者', '雷瑟？那个懦夫？$b$b我们把他赶出营地，因为他坚持要袭击蕨墙村的食人魔，还要抢他们的物资。我们人数不够，没法跟那帮不长脑子的畜生斗。$b$b他不止一次做出过分的事，所以我们就把他赶了出去。$b$b现在我帮了你的忙……那么，别管你是不是偶然来这儿的，不如帮帮我的忙，别给我惹麻烦了吧？', '和塞拉摩的盖兰·维米斯队长谈一谈关于雷瑟的事。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1301, '詹姆斯·海厄尔', '在蓝色隐士旅店干活之前，我曾在一个最棒的厨师兼旅店老板手下学艺，他的名字是詹姆斯·海厄尔。我今天能有这样的成就都得归功于他。$b$b不知道他现在在干什么，他和他的兄弟文森特到米奈希尔港的一家旅店去工作了，不过最近我一直没听到他的消息。$b$b你要是碰巧要往米奈希尔去的话，能不能帮我问候他一下？', '和米奈希尔港的文森特·海厄尔谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1302, '詹姆斯·海厄尔', '我的兄弟詹姆斯跟随吉安娜女士到塞拉摩去了。我最后一次听到他的消息是说他们在那儿打完了仗，詹姆斯还在那里的某个地方开了个旅店。不管他现在在哪儿，我想他的生意肯定很红火，他是个很棒的厨师。$b$b啊，说起来我已经有一阵子没听到他的消息了——旅店的生意太忙了——不过塞拉摩的书记员应该可以帮你找到他。他就在那里的城堡顶楼。', '与塞拉摩城堡中的书记员伦德瑞谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1318, '戈多克食人魔的事务', '现在你是大王，你可以从那个精灵王子手里拿回令戈多克骄傲的神器！你前一任的大王失败了，自从托塞德林那个可恶的精灵从我们古代戈多克大王手中偷走它之后，没有一个大王能想办法把它夺回来！$B$B这个神器叫做戈多克力量护手。传说说只有真正的戈多克大王才能把它拿回来。这个可恶的精灵还在附近——如果你找到它的话，那你就可以使用它！真的！', '找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。$B$B根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。', '喔……你是真正的大王!我这辈子都从来没有看见过它!看来上面的油都要干了……也许那个可恶的精灵把它偷走之后就再也没用过它。好吧，我要对他说哈哈哈哈哈!$B$B看这里─护手上的标志是一个很古老的魔法印记，据说比戈多克巨魔的历史还要久远。好吧，作为戈多克的队长，我们曾经学习过一种知识─如何将印记还原并将力量重新注入护手中!$B$B我会为你这么做的，大王!给你，拿着护手，永远统治我们吧!', '哈哈，你还没有找到它，是不是，老大?也许那只是一个故事……很难相信那个可恶的精灵居然可以从我们戈多克的大王身边偷走东西!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1320, '黑色盾牌', '啊，我差点没注意到这个……背面的皮带一定是被烧掉了，不过看上去这条皮带是给某个身材高大的家伙用的。我猜是个牛头人。$b$b我就只能告诉你这些了，告诉维米斯队长，很抱歉我帮不上别的什么忙了。', '与塞拉摩的盖兰·维米斯队长谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1323, '黑色盾牌', '呃，我想我大概倒了太多酸液在盾牌上，得擦掉点儿……$b$b嗯……有点难辨认，不过好象是一个叫“莫萨恩”的名字。从来没听过这个名字。克罗格认识不少人，他也许知道这个莫萨恩是谁。', '和蕨墙村的克罗格谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1339, '巡山人卡尔·雷矛的任务', '我听说巡山人卡尔·雷矛正在找一个为他跑腿的人。你看怎么样，要去试试看吗？$B$B如果愿意的话，你就去北边的哨塔找他吧。', '和巡山人卡尔·雷矛谈一谈。', '没错，我有件事情要办，不过我得在这里站岗，根本走不开。事实上，要你去的地方离洛克莫丹还挺远的。B', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1362, '凄凉之地的科卡尔部族', '科卡尔半人马居住在凄凉之地，但他们的势力已经渗透到了贫瘠之地。这是事实，我们已经派了斥候去时刻监视着他们。$B$B只要凄凉之地的半人马依然足够强大，对我们而言，他们就是个威胁，我们应该主动出击清除这个威胁。$B$B去和凄凉之地幽灵岗哨的费古尔·双刃谈谈，他也是被派去收集有关半人马的情报的，他会知道该如何对付凄凉之地的科卡尔部族的。', '和凄凉之地幽灵岗哨的费古尔·双刃谈一谈。', '是雷戈萨派你来的?那么你一定是来对付半人马的。很好。$B$B我希望你已经休息够了。我不知道我们与半人马的战争何时会结束，但我知道那一定会很漫长。$B$B坐下来慢慢听我说吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1363, '马森的请求', '作为魔法和科学学院图书馆的管理员，我的职责是保证所有的魔法书和卷轴随时在库。如果这些充满魔法能量的文字落在邪恶的人手里，天知道会发生多可怕的事情！$b$b啊，我突然想起来……我的助手迪利斯上礼拜犯下了一个可怕的错误。他在图书馆里确实是个好帮手，但他一走出暴风城就几乎寸步难行。你能帮我把老迪利斯给找回来吗？', '与暴风城里的助手迪利斯谈一谈。', '这不是我的错，真的，不是我的错。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1372, '真言药水', '瓦里玛萨斯派遣我们这支远征军来对艾泽拉斯南部进行侦查。$b$b我偶然发现一个人类间谍在乞丐鬼屋附近探头探脑。我正准备暗中跟踪他，这个家伙就被一些…我们的兽人朋友抓去，押进了位于悲伤沼泽里的斯通纳德要塞。$b$b兽人们还不知道我们在这里安营扎寨，不过…我想去帮助他们，帮助我们的兽人盟友。$b$b去找法奥斯丁，让他给我们在斯通纳德的朋友制造一瓶真言药水……', '到乞丐鬼屋去和药剂师法奥斯丁谈一谈。', '莱度斯刚刚还跟我提起过那个爱追根问底的人类探子。$B$B他确实是很麻烦，我们决不能让这么个爱管闲事的家伙在乞丐鬼屋周围到处探察。$B$B斯通纳德的兽人肯定很想知道我们这位探子朋友的脑袋瓜里藏着什么秘密。既然兽人是我们的同盟，咳咳，那么我们就得帮他们从这个人类间谍嘴里榨出些消息来。$B$B帮帮我吧，$N，让我们做出一瓶真言药水送到斯通纳德去。$B$B为了部落!$B$B……是这么说的吧?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1393, '加林的逃亡', '请救救我！这些东西想要吃掉我！$B$B帮我离开这儿，我就给你一笔巨大的财富！那笔财富就在斯通纳德北部沼泽的营地中，但是被锁在了一个保险箱里，只有我知道方法来打开箱子。$B$B如果你帮我逃走，我就告诉你怎么拿到那笔财富！', '护送加林逃出困境，然后打开他放在悲伤沼泽营地里的保险箱。', '保险箱的钥匙孔里填满了黑色树脂，看来是不可能打开的。$B$B但是加林告诉过你在箱子的底部有个隐藏的锁……$B$B你迅速地找到了锁的位置，并轻轻地按了一下，保险箱应声打开了……', '保险箱的钥匙孔里填满了黑色树脂，看来是不可能打开的。', '护送加林离开农田避难所。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1394, '通过试炼', '你做得很好，$N。你已经通过了所有的试炼，现在回到千针石林的多恩那里去吧。他会感觉到你的变化，他会看出你的思想、身体和精神都已经足够强大了，而你的努力理应受到嘉奖。$B$B将你在这些测试中所表现的优秀素质继续保持下去吧，$N。如果你能做到这些的话，多恩将在以后的日子里再次对你进行试炼。', '和千针石林的多恩·平原行者谈一谈。', '啊，$N。上次你到我家来已经是很久以前的事情了，自从你踏出冒险旅程的第一步之后，已经过了好长一段日子了。$B$B现在你回来了，比以前更加强大……也更加博学了，这让我非常高兴。你应该为你通过这么多艰苦的试炼而得到奖赏。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1418, '尼卡·血痕', '可怕的荒芜之地就在联盟所控制的洛克莫丹地区南方，因此斯通纳德与荒芜之地中的卡加斯前哨站之间的交流经常中断。$B$B去证明你自己的实力吧，$N。旅行到荒芜之地去，与尼卡·血痕谈一谈，她是卡加斯前哨站的侦察队长。把她的报告给我拿回来。', '和尼卡·血痕谈一谈。', '赫格拉姆想要一份报告，是吗?我不到三天前才派了个信差到斯通纳德去，难道他没能完成任务吗?如果斯通纳德没有收到我的报告的话，那他应该是失败了。$B$B希望我下次派去送信的人能有更强的本事，或者更好的运气。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1422, '海中的威胁', '在我给你打造武器的时侯，为什么你不去和卡塔尔谈谈呢？他曾说过需要有人帮忙在海滩上巡逻，我非常乐意看到像你这样睿智而警觉的$r去协助他，而不是我们这片营地中的某些只会骗酒喝的家伙。', '与悲伤沼泽的卡塔尔谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1427, '海中的威胁', '在你休息之前，记得再去和托克卡尔谈谈吧，我估计在你离开的时候他就应该把那些武器完成了。为了感谢你的帮助，他会送一把给你。一切都准备就绪以后，你就可以在对抗鱼人的过程中好好试一下那把武器了……', '与悲伤沼泽的托克卡尔谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1431, '联盟关系', '请等一下，$c，让我告诉你一些对我们的族人来说非常重要却几乎不为人知的东西。$B$B我们兽人是个令人骄傲的种族，而与人类之间的战争是如此漫长，就连萨尔都有些不耐烦了。你知道的，我们的酋长睿智而谨慎，并总是以他的族人为重。总之，他是一个出色的外交家，在他与人类共同生活的那段日子里，他也学会了许多人类的行事之道。$B$B如果我刚才说的故事引起了你的兴趣，那么就去找城市西门附近的科尔丹吧。', '与奥格瑞玛的科尔丹谈一谈。', '你好，尊贵的$C。我是科尔丹，魔法和某些「神秘艺术」的学徒。$B$B那帮懦弱的商人让你到这里来和我接触，想要与我进行更加微妙的接触，但这并不意味着你就不能再帮助我们了。$B$B请不要紧张，我会告诉你为什么大酋长那么需要我的帮助……还有你的。$B$B首先这是一个形象问题，$N。部落是怎样看自己的，我们的盟友是怎样看我们的，以及最重要的，我们的敌人是怎样看我们的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1432, '联盟关系', '随着联盟在卡利姆多的推进越来越深入，部落与燃烧军团有染的错误结论一定会流传开来。酋长可不会允许这样的事情发生。受酋长所托，我正在负责这个问题的解决。$B$B我已经往凄凉之地派了密探，就在科多兽坟场北部的幽灵岗哨附近。你的任务是跨过石爪山脉，一直走到山脉的南侧，到那里去找塔卡塔·钢刃。', '与凄凉之地的塔卡塔·钢刃谈一谈。', '你好，$C。你带来了奥格玛的消息，这真好。$B$B这里恶魔的腐臭气息足以盖过半人马的粪味，那群马人宣称这片土地是他们的，但是仅仅以他们那一点可怜的影响力，这个地区并不完全在他们的控制范围之内，如果我们不对此有所行动的话，他们定会遭到灭顶之灾。$B$B虽然间接地帮助半人马对我来说不算是个乐事，但这对部落有好处，所以我会对大酋长尽责，即使这种责任意味着我正在给部落里的术士们帮忙。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1433, '联盟关系', '和火刃氏族相关的说法是多如牛毛，但你要知道，这帮家伙实在是邪恶到家了，他们的精神已经腐朽，他们利用破坏与毁灭来维持并证明自己的存在。$B$B科尔丹派玛乌林·碎骨来与我同行，因为玛乌林对火刃氏族及他们的术士之道都有着充分的了解。$B$B他负责策划针对火刃氏族的行动，而我则负责对付在凄凉之地活动的恶魔。$B$B去和他谈一谈吧，他会告诉你如何按他的计划行事。', '去找凄凉之地的玛乌林·碎骨谈一谈。', '啊，好极了!感谢来自$r的帮助。$B$B我的名字是莫林。我是奉科尔丹以及年轻的大酋长索尔之命来到这里的。能够帮助年轻的领袖抵抗威胁着部落的邪恶势力，那是我一生的夙愿。$B$B来，靠近点，$C。我将会向你说明一下我的计画，关于如何将燃刃氏族这颗毒瘤除掉的计画。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1436, '联盟关系', '形势很顺利，$N。如果我们能继续保持目前的推进势态的话，或许酋长会允许我们在换季之前回到久别的家园。$B$B回到科尔丹那里去，告诉他我们都干了些什么。我敢打赌他一定会为你在这儿的功绩而奖励你。他的事业对他来说很重要，并且如果酋长也会对他的成就表示敬意的话，他一定会非常自豪。', '与奥格瑞玛的科尔丹谈一谈。', '你好，尊贵的$C。我是科尔丹，魔法和某些「神秘艺术」的学徒。$B$B那帮懦弱的商人让你到这里来和我接触，想要与我进行更加微妙的接触，但这并不意味着你就不能再帮助我们了。$B$B请不要紧张，我会告诉你为什么大酋长那么需要我的帮助……还有你的。$B$B首先这是一个形象问题，$N。部落是怎样看自己的，我们的盟友是怎样看我们的，以及最重要的，我们的敌人是怎样看我们的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1437, '瓦拉里尔的搜寻', '你好，$n，我是瓦拉里尔。我到这里是来寻找达纳苏斯商业世家——玛雷姆家族的两个失踪的孩子。这个家族的族长已做好了最坏的打算，不过我还是要尽一切可能找到他的孩子。我已经开始了搜寻泰拉尼斯和黛琳达的工作，但愿一切顺利。$B$B我最近得知的线索是，几周前他们已经越过了石爪山。$B$B如果你发现了他们的踪迹，就请立刻通知我。', '去凄凉之地寻找泰拉尼斯·玛雷姆和黛琳达·玛雷姆的马车。', '仔细地查看过马车的残骸之后，你发现它明显曾受到魔法和武器的双重攻击。似乎那场战斗的实力对比相当悬殊，因此很快就结束了，地上既没有血迹，也没有发现任何尸体。$B$B看来袭击者动作敏捷，而且颇有效率。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1438, '瓦拉里尔的搜寻', '找到泰拉尼斯和黛琳达，然后带着你的发现回来见我。从这座城堡开始进行搜寻吧，我会立刻和达纳苏斯的上级联系，让他们知道这里的情况。$B$B对了，$N，还有一件事情一定会让你影响深刻。我的上级最关心的并不是泰拉尼斯以及他在这里的活动。对他们来说，更重要的是黛琳达能否安全地回来。泰拉尼斯……在他回来之前必须要接受评估。', '去凄凉之地找到黛琳达·玛雷姆。', '感谢伊露恩，总算有人来了。$C，我需要你的帮助。燃刃氏族抓住了我和我的哥哥泰拉尼斯，然后把我们带到了这里。我想他们是要把我献祭给他们的恶魔主子!$B$B我早知道来凄凉之地是个错误，泰拉尼斯对所有神秘的事情都很好奇─甚至是那些有悖于大多数人的意愿的事情。即便明知道这片土地上恶魔横行，他也不惜冒险。$B$B我很担心他。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1440, '回复瓦拉里尔', '怎么样，你准备好了吗？我感谢你的帮助，如果时间不是太紧的话，请在此时此刻就接受我对你的感谢：感谢你对我和我的家族所做的一切。如果你准备好了，我们就赶快动身离开吧。', '护送黛琳达·玛雷姆离开雷斧堡垒，然后回到凄凉之地的瓦拉里尔·屠魔者那里。', '谢谢你，$N。黛琳达安全地返回了尼耶尔前哨站，情况比我想像的还要好一些。她能自己回到这里是件不错的事情，你一切都还好吧?$B$B可惜泰拉尼斯没有和黛琳达一起回来，这让我很痛心，不过我想黛琳达还是得承受泰拉尼斯的决定。她回到达纳苏斯以后还会有许多事情要做。', '', '营救黛琳达·玛雷姆', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1444, '向费泽鲁尔复命', '预言者迦玛兰宣读了对我的放逐令，将我从阿塔哈卡神庙中赶了出来。我过去曾认为这位祭司是一位优秀的领导者。$b$b但他对自己的预言能力的过度依赖与盲目的服从一定会导致我们阿塔莱部族的毁灭，这是迟早的事情。$b$b当我说出了我所担忧的事情时，我被判为异端，从庙里被赶了出来。$b$b你拿来的这些东西都是无害的。但如果迦玛兰找到了能够启动召唤仪式的魔法神像，这个世界一定会落入巨大的灾难之中……', '向斯通纳德的费泽鲁尔回报。', '距离上次我们交谈已经有很长一段时间了，$C。我希望你的旅程很顺利。$B$B你从辛特兰那个被流放的阿塔莱食人妖那里知道了些什么?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1449, '去辛特兰的旅程', '正如我之前所说的，我曾经尝试过从空中寻找那座神殿。事实上，那次我并不是独自行动的。$b$b我先是去了位于辛特兰的鹰巢山上那座著名的狮鹫饲养场，在那里我请他们的一位最优秀的飞行员帮助我。在探险中，那位飞行员从他的座骑身上掉了下去，一直掉进了沼泽之中……$b$b我老了以后，这个可怜人的名字一直出现在我的脑海里，挥之不去。饲养场的管理员也应该还记得这件事。$b$b到那里去找弗斯塔德·蛮锤吧。$b$b我们得搞清楚那位飞行员后来到底怎么样了。', '找到辛特兰的弗斯塔德·蛮锤。', '有什么事吗，$g小伙子:小姑娘;\n?没看我正忙着吗?谁有时间待在这里跟一个$r闲聊呀?$B$B这堵墙外面可全是食人妖!有话快说!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1450, '狮鹫管理员', '那么说你这个$g毛头小子:小姑娘;\n来这里就是给探险者协会里的某个老头子跑腿的吗？$b$b那你听好了，$c。我根本不知道他说的那个曾经在艾泽拉斯到处飞的老家伙是谁。你跑来问我这些，难道我脸上写着“狮鹫管理员沙拉克·鹰斧”这几个字吗？嗯？$b$b要是你想飞那么一次两次的，干嘛不去找个正儿八经的狮鹫饲养员呢？你要是还在这里继续闲晃的话，那我就真的要给你找点什么活去做做了。$b$b快走快走。', '与辛特兰的鹰巢山狮鹫饲养场里的狮鹫管理员沙拉克·鹰斧谈一谈。', '啊，对。我还记得曾派出过一名狮鹫兽骑士去帮助布罗哈恩.铁桶。$B$B我对探险者协会一向是有着特别的感情的。我的父亲也曾经帮助他们的挖掘队伍找到了奥达曼古城。$B$B当时我派出了手下最优秀的狮鹫兽骑士去陪同布罗哈恩完成他的任务，嗯，我想想……他叫拉普索迪.铁铲。$B$B多么优秀的一个狮鹫兽骑手呀!可惜……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1451, '拉普索迪·铁铲', '拉普索迪那家伙特别爱喝酒，不要误会我的意思——我们饲养场里所有的矮人没事的时候都爱喝上那么一小口麦酒。$b$b但拉普索迪不一样，那家伙一碰见烈酒就跟狮鹫见了天空一个模样。而且我不得不承认的是，没人能比拉普索迪这家伙飞得更好了。$b$b但是自从他勉强和你那位朋友飞回来以后，他就彻底变成了另一个人，因此我们只好让他走了。$b$b我听说拉普索迪东边的某个地方弄了个酒窖。', '去辛特兰找到拉普索迪·铁铲。', '嗝儿!$B$B我一直看着你，但拜托请不要上下乱动。这让我头晕眼花。呵呵呵!$B$B嗝儿!$B$B啊!你难道没有感觉到吗?大地在晃动，我的朋友，我需要一杯喝的!$B$B嗝儿!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1453, '寻物公司的业务', '我有些活儿要你去凄凉之地跑一趟，$N。那里满地都是半人马和其它讨厌的东西，是个非常凶险的地方。不过如果你想找一份为期一星期的充实工作的话，就去那儿找克雷迪格·安戈尔，告诉他是我叫你去的。$B$B他就在尼耶尔前哨站，那是凄凉之地北部山区里的一个小营地。当你从石爪山进入凄凉之地的时候就向东转，尼耶尔前哨站有些难找，所以路上要多留心看看，免得错过了。', '和凄凉之地尼耶尔前哨站的克雷迪格·安戈尔谈一谈。', '很高兴看到寻物公司的业务这么繁忙，而且有这么多像你一样的冒险者乐意帮忙。$B$B我是克雷迪格。你来帮助寻物公司是个明智的举动，这年头任何人都有需要:总是有人会弄丢自己的传家之宝、值钱的魔法物品或者自己珍爱的东西，这种事情多不胜数。只要有寻物公司，只要价钱合适，没理由会找不回他们丢的东西!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1454, '卡尼托的海难', '我的第一笔订单来自于法师卡尼托，他是暴风城里的一个贵族。他的船似乎在西北边的海岸附近受到了海巨人的袭击，他和仆人们想把最值钱的一个箱子带上岸，然而，海巨人成群结队地发起攻击，所以他不得不放弃了这个想法，把自己和仆人传送到了安全的地方。$B$B他希望我们能帮忙找到那只箱子，并且把它送到暴风城。', '在凄凉之地找到卡尼托的箱子。', '你注意到这只箱子似乎没有进水。$B$B你注意的第二件事是这个箱子的顶部被撬开了，而且保护箱子的魔法机关早就已经被触发了—从箱子边缘的灼烧痕迹就可以看出这一点来。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1455, '卡尼托的海难', '你仔细考虑着到底是什么东西撬开了箱子，同时观察着箱子四周和顶部的又长又深的痕迹。显然，这并不像是某个人或是某个海巨人干的，而且这些撬痕似乎也不是匕首或者是利剑留下的。$B$B打开箱子检查了一番之后，你发现它是空的。$B$B找不到一点头绪，于是你关上箱子准备离开。克雷迪格一定会很失望。', '回到凄凉之地尼耶尔前哨站的克雷迪格·安戈尔那里。', '欢迎回来，$N。你找到什么东西了吗?$B$B什么!?空的箱子?恐怕我们无法为一只空箱子付钱。$B$B请给我再讲讲你看到的箱子上的那些痕迹……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1462, '大地灵契', '', '向鸦羽先知要另一瓶大地灵契。', '拿着它，记住，这是神圣之物。', '你没有了灵契，也没有得到大地图腾，真是不幸。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1463, '大地灵契', '', '向坎纳甘·地鸣要另一瓶大地灵契。', '我以信仰之名再交给你一个灵契。虽然你已经证明了自己的能力，但我想你以后似乎应该更加小心一些才是。', '所以，你需要再拿一个灵契才能完成任务，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1465, '瓦拉里尔的搜寻', '当你继续搜寻马车的残骸时，你发现有一串足印一直向南方延伸过去。在远方有一座巨大的城堡上空烟雾缭绕，那烟雾来自于城堡哨塔上的烽火，而不是房屋的燃烧。你的直觉告诉你：如果玛雷姆兄妹还活着，那他们一定就在那里。', '向凄凉之地尼耶尔前哨站的瓦拉里尔·屠魔者回复。', '这真让人恼火!一场彻彻底底的失败!$B$B我早就警告过他们两个，到这里来会非常危险。现在他们都失踪了……甚至可能会更糟。$B$B你说你看到了通向附近城堡的足迹?那也许是我们最后的赌注。$B$B根据当地人所说，那个城堡里有许多燃刃族的恶棍—燃刃族是一群异常残忍的兽人。他们也许不能代表部落的大部份信仰，但是他们非常邪恶，一旦你被他们发现，就会立刻招来杀身之祸。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1468, '儿童周', '你愿意帮助我们的孤儿院？太感谢你了，我的朋友。感谢你愿意在儿童周的这段时间内为我们提供帮助。$B$B拿着这只哨子，你只能在儿童周的这7天内使用它。当你使用它的时候，就可以和那些由你负责照看的孩子进行对话，再次使用就可以解散那个孩子。$B$B不管怎么样，$N——使用这个口哨，见一见你的小朋友！我相信孩子们一定很想见到你。', '使用人类孤儿哨与你即将在儿童周期间照顾的孩子进行对话。', '嗯……你好，我的名字叫兰迪斯，我想是你来照顾我的吧?你是一个冒险者，就和我爸爸妈妈过去一样。我很高兴能遇到你。$B$B我希望我们之间能相处融洽。我有些事情想要做，而孤儿院院长说你在这个星期中会像大$G哥哥:姐姐;\n 一样照顾我。我很喜欢这样，$G先生:女士;\n。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1472, '噬魂者', '魅魔是灵魂的吞噬者，心灵的毁灭者，它们以诱惑人类为生，它们的心中只有纯粹的邪恶。$b$b在没有诱饵的情况下，我们是无法将它引入到我们的世界中来的。$b$b因此，我们要以它自身的力量来对抗它。只要有一个真正善良、纯洁而博爱的人的精华，魅魔就将因为无法抵抗这种吸引力而被引入我们的世界。之后，你就要控制它，使它对你俯首贴耳。$b$b与我的助手高德瑞克·法杉谈谈吧，他就在神殿里。他会帮你找到你需要的诱饵。', '与诅咒神殿中的高德瑞克·法杉谈一谈。', '你是凯伦丁大人派来的?$N，那么……$B$B别因为我瞎了就小看我。如今我已经有了某种我也弄不清楚的清晰灵觉，这让我即使丧失了视觉也能看清周围的东西。尽管我当初将它视为一种诅咒，但如今我觉得这是一种恩惠。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1477, '重要的补给', '法师们正在诅咒之地的守望堡里进行研究，这项重要的研究关系到我们对黑暗之门的了解。他们需要持续的补给，然而我们到守望堡的补给线非常脆弱。$B$B你必须提供帮助以保证补给物资安全抵达守望堡。到夜色镇去找守卫队长索里加尔，按他的指示去做。这次任务要求你进入敌方区域，准备出发吧，$N。', '和暮色森林中夜色镇的守卫队长索里加尔谈一谈。', '安多玛斯派你来的?很好。我有一项重要任务的吩咐给你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1478, '哈加尔的召唤', '啊，$n！我刚刚收到了凯伦丁·哈加尔托人带来的口信，他希望你能去接受进一步的训练。$b$b你应当为此感到自豪，$n。哈加尔先生可不是每天都会私下里指导年轻术士的。$b$b他在幽暗城的法师区里，应该就在诅咒神殿旁边。', '与幽暗城的凯伦丁·哈加尔谈一谈。', '很好，看来埃格隆找到你了，$N。我们就不要浪费时间说笑和寒暄了，直接来谈谈关于你的学习吧。你需要掌握的东西还有很多。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1483, '菲兹克斯', '风险投资公司偷走了许多最有天分的地精的创意，不过我们时不时地会偷一些回来。$b$b不久以前，风险投资公司在石爪山的分支机构居然雇佣了格雷苏——一个侏儒！他们的另一个工程师菲兹克斯只有靠边站了。他恳求我帮他在工匠协会找份工作，我交给他一些任务，不过他或许会需要帮助。$b$b也许你能帮他一把？菲兹克斯现在就住在狂风峭壁的西部。', '和石爪山脉中狂风峭壁的菲兹克斯谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1484, '堕落者', '这家伙远比我预料的要危险得多。塔卡塔肯定会怀疑我是否能够成功地刺杀他，而且如果不把这件事情告诉他的话，实在是对他的侮辱。$B$B去告诉塔卡塔，如果他允许的话，你将去刺杀那个恶魔，不过你也不要太坚持，如果他有别的办法就最好了。', '与凄凉之地的塔卡塔·钢刃谈一谈。', '我看到了莫林以及他所侦测到的恶魔领主，即使只是他的亡魂，那力量也远比我的术士伙伴要强大得多。我怀疑莫林是否能打败这个怪物?如果我能亲自前往的话，或许会容易一些，但我的职责是保卫这里，如果我抛弃在这里的义务而为了个人的荣誉去挑战邪恶的话，我的氏族定然会因此蒙羞。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1490, '纳拉·蛮鬃', '我进入了梦境，梦见一群住在哀嚎洞穴的德鲁伊。他们曾经是那么的高贵，但如今却已经迷失了方向，变成了一股邪恶力量的奴仆，协助他们的主子席卷贫瘠之地。$B$B我已经年老力衰，无法长时间地停留在梦境之中，也无从得知更多有关那些堕落的德鲁伊的事情。不过，纳拉很年轻，她的精力非常旺盛。当我离开的时候，她还在梦境里搜索。去找她吧，她就在那边的帐篷里。', '和纳拉·蛮鬃谈一谈。', '是的，这是真的。我认得哀嚎洞穴中的那些德鲁伊……我见过他们那扭曲而且长满缀鳞的面孔。我了解他们的罪行，我也了解他们的计画。$B$B你必须阻止他们，$N。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1499, '邪灵劣魔', '祖雷萨正在找你这样的新手，让他们到当初你猎杀邪灵劣魔的那个地方旁边的洞穴里去，削减那里的生物数量。$b$b我想你可以在帮助她的过程中学到很多东西。记得跟她说，你是去帮忙解决小鬼问题的，她肯定会准备一份奖励给你。', '与祖雷萨谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1502, '索恩格瑞姆·火眼', '一柄铸造精良的武器对于战士来说是很重要的。兽人这里最好的武器铸造师是索恩格瑞姆·火眼，他隐居在十字路口东边的山上。$B$B如果你想要寻求一把称手的武器，那就去找索恩格瑞姆吧。从这里往西走，到了十字路口以后再往东进入山区，他的营地就在山顶上。', '与贫瘠之地的索恩格瑞姆·火眼谈一谈。', '长时间盯着锻炉让我的双眼变得干涩，但是我仍然能看清一些东西。我可以看出你需要我的帮助。$B$B如果你能找到这里来，那么我应该可以猜出你想要什么。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1505, '老兵犹塞克', '部落非常尊重战士，因为他们具有毋庸置疑的力量。但是真正伟大的战士同时也是一个优秀的学生。$B$B去找犹塞克吧，他经历了很多场战斗，并且向很多年轻的战士传授过精湛的战斗技艺。你可以在前沿哨所的南边找到他，那个地方位于贫瘠之地和杜隆塔尔的交界处。', '和贫瘠之地前沿哨所的犹塞克谈一谈。', '你好，年轻人。你是来这里寻求指引的吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1506, '甘鲁尔的召唤', '嘿，你！你叫$n，没错吧？$b$b你现在不忙吧？甘鲁尔要马上见你。他在暗影裂口和几个高阶术士待在一起。$b$b根据我以前和他打交道的经验，他找你要么是有什么美差吩咐给你，要么就是你大难临头了。', '去奥格瑞玛和甘鲁尔·血眼谈一谈。', '很好，我还担心奥菲克找不到你呢。$B$B现在是时候让你的术士训练更进一步了。你手边的其他事都得暂时放一放。$B$B我相信你对此没什么意见吧?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1507, '噬魂者', '是时候让你学些其它的召唤魔法了。你得学习如何召唤魅魔，那是一种具有非常强大的精神力量的恶魔。她会诱惑意志薄弱者，让他们心甘情愿地成为她的奴隶！我觉得你已经有足够的能力去面对这样的挑战了。$b$b魅魔只能在以一件象征着伟大的爱与奉献的物品作为媒质的情况下才能被召唤出来，你必须自己去寻找一件这样的东西。$b$b建议？去和卡祖尔谈谈吧……这世上没什么东西是那个老术士不知道的。', '和暗影裂口的卡祖尔谈一谈。', '嗯……$N。以你的修为而言，你还是个新手，但我能感觉到你将会成为一个伟大的术士。$B$B你生来就受到了祝福，$N。不过你可不要白白浪费了神对你的恩赐。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1508, '盲眼卡祖尔', '嗯……根本不用问你是为什么来找我的。$b$b既然是甘鲁尔让你来，那你一定是想要召唤魅魔了，而你现在需要一件东西作为媒质，对吧？$b$b嗯……如果你确信我这个瞎子能够帮助你的话，那就听着吧，$n。在奥格瑞玛城内的通天塔以西的一处断崖上住着一个名叫赞卡沙的女性。$b$b去找她吧。', '和奥格瑞玛的赞卡沙谈一谈。', '你有没有听说过多格兰这个名字?按理说他应该几天前就回来了，但我却没有任何有关他的消息。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1509, '多格兰的消息', '我的丈夫多格兰最近被派去十字路口值勤了。这对他来说是一种奖赏，令他感到十分自豪。$b$b不过我对此却不是那么开心，不过我当然不能让他知道这些，更不能让他担心。大家都说贫瘠之地是一片比奥格瑞玛要危险得多的土地，在我看来那是世上最糟糕的地方。$b$b他一星期之前就该回来了，但我现在却仍然没有得到他的丝毫消息……$b$b$c，你能不能去一趟十字路口，帮我打听一下他们那边有什么消息？他与一个名叫加兹罗格的战士是搭档，那个加兹罗格应该还在那里值勤。', '找到十字路口的加兹罗格并和他谈一谈。', '赞卡沙?那不是多格兰的妻子么?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1510, '多格兰的消息', '他是在陶拉祖营地被抓住的。我们当时正在和那里的野猪人交战，他带了一小队步兵去进攻野猪人的一处营地，但他在那场战斗里受了重伤。其他战士杀出重围，然后想要回去救他，但多格兰的情况很糟糕，他的伤口已经溃烂了，所以他们觉得要是不能先把他治好再带出来的话，他可能就会因为伤筋动骨而死掉。$b$b所以他们和这里联络了一下，希望能从石爪山的玛拉卡金那里的巨魔手里讨些伤药来。我们已经派人去找巨魔们了，但他们至今还没有回复我们。', '找到玛拉卡金的肯兹格拉并和他谈一谈。', '又一个兽人受伤了吗?我希望你所说的就是上一个信差所说的那个。那个信差被哥布林们伏击，已经重伤不治了。$B$B他只来得及告诉我，那个受伤的兽人需要一些伤药，然后就死了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1517, '大地的召唤', '灵契是一种可以在我们的灵魂与元素之间建立起连接的特殊药水。这种融入了魔法的药水将使完全放开了心灵的你看到别人所不能看到的元素。你的灵魂将会永久地与灵契所对应的元素连接起来，只有我们中的少数被选中的人才知道灵契的制法。$B$B你必须知道一点……只有在神圣的地方喝下灵契才有效，其它任何地方都是不行的。$B$B到这里西南面的灵魂石地去吧——它就隐藏在一些茂密的藤蔓植物之间。到那里去把你的灵契喝掉，然后……嗯，到时候你就知道该怎么做了。', '找到灵魂石地，在那里喝下大地灵契。', '啊……$N……我很高兴你来到了这里。$B$B让你的身体与精神接受土地的洗礼吧，你将会发现山丘就是你的力量，平原就是你的宽容，而世界本身就是你的精髓所在。$B$B在这个祭仪中你唯一所要做的事情，就是谦卑地站在土元素面前。当你以后遇到其他元素的时候，会发现它们也许并没有土元素这么平静。或许它们是混乱而暴戾的，但这是元素自身的天性。它们相互之间总是存在着对立，而你必须对这一点非常了解才行。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1520, '大地的召唤', '灵契是一种可以在我们的精神和自然的元素之间建立连接的药水。这种药水融入了魔法，它可以使打开了心灵之门的你看到别人所不能看到的元素。你的精神将会永久地与灵契相应的元素连接起来，只有我们中的少数被选中的人才知道灵契的制作方法。$B$B灵契只能在神圣的地方生效，其它的任何地方都不行。$B$B到东边的萨满祭坛去，在那里喝下灵契吧。', '找到科多石并喝下大地灵契。', '啊……$N……我很高兴你来到了这里。$B$B让你的身体与精神接受土地的洗礼吧，你将会发现山丘就是你的力量，平原就是你的宽容，而世界本身就是你的精髓所在。$B$B在这个祭仪中你唯一所要做的事情，就是谦卑地站在土元素面前。当你以后遇到其他元素的时候，会发现它们也许并没有土元素这么平静。或许它们是混乱而暴戾的，但这是元素自身的天性。它们相互之间总是存在着对立，而你必须对这一点非常了解才行。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1522, '火焰的召唤', '嘿，火焰可是很强大的，孩子。我看你在地系魔法方面还挺有一套，是时候让你和卡纳尔谈谈了。$B$B卡纳尔就住在贫瘠之地，从十字路口一直向北走。他擅长元素魔法，可以教教你怎么使用火焰……当然你得先做好准备。$B$B你可以很容易地找到他，不过别走太远——太远就进入精灵的领地了。', '去贫瘠之地找到卡纳尔·菲斯。', '嗯，是希尔恩让你来找我的吧?$B$B他是值得信赖的朋友，也就是说，你已经准备好要建立下一个灵契了─火焰灵契。$B$B我已经看到了熊熊燃烧的火焰和欲望。你已经拥有了一些力量，现在你已经准备好掌握更多了。耐心点，$N。记住大地所教会你的那些。力量和毁灭随手可得，不过你必须首先知道什么时候应该收手。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1523, '火焰的召唤', '你已经很久没有接受试炼了，$N。到目前为止，你已经证明了自己有足够的耐心，现在是时候让你学习更多东西，是时候让你了解毁灭…和混乱了。只要你明白自己即将为此付出的代价，火焰的元素就会与你建立连接。$B$B到贫瘠之地去找卡纳尔·菲斯，他就住在十字路口北部的一间小房子里。路上小心点，走太远的话，你就会进入精灵的领地。', '去贫瘠之地找到卡纳尔·菲斯。', '嗯，是希尔恩让你来找我的吧?$B$B他是值得信赖的朋友，也就是说，你已经准备好要建立下一个灵契了─火焰灵契。$B$B我已经看到了熊熊燃烧的火焰和欲望。你已经拥有了一些力量，现在你已经准备好掌握更多了。耐心点，$N。记住大地所教会你的那些。力量和毁灭随手可得，不过你必须首先知道什么时候应该收手。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1528, '水之召唤', '你的下一个目标是水，年轻的$n。我可以看出你已经能很熟练地运用火焰的力量，看来你也准备好去和伊斯伦谈谈了。$B$B伊斯伦住在贫瘠之地的河岸边，你只要沿着怒水河往南走，就肯定能找到她。她对各种元素的使用方法都很熟悉，可以教你关于水元素的知识……$B$B不要向南走得太远，她就在棘齿城旁边。', '找到贫瘠之地的水之先知伊斯伦。', '地平线吹来的风轻拂着你，脚下的大地是如此坚实，火焰温暖了你的灵魂，而现在我想让你体味水的纯洁。$B$B你已经达到了一定的境界，你的精神将赐予你走得更远的力量。不过，你先得迈出至关重要的第一步。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1529, '水之召唤', '从你上次接受测验到现在已经有很长的时间了，$N。迄今为止，你展示了足够的耐心，不过现在你应该学到更多的东西，应该去了解水的纯洁。$B$B去贫瘠之地找到水之先知伊斯伦，沿着怒水河的东岸向棘齿城的南方走，你可以在一间小渔屋里找到她。祝你好运，$N。', '找到贫瘠之地的水之先知伊斯伦。', '地平线吹来的风轻拂着你，脚下的大地是如此坚实，火焰温暖了你的灵魂，而现在我想让你体味水的纯洁。$B$B你已经达到了一定的境界，你的精神将赐予你走得更远的力量。不过，你先得迈出至关重要的第一步。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1530, '水之召唤', '关于水，有一点是你必须要了解的：水意味着重生。$B$B水流动着，消蚀和清洗一切事物。水的治疗和恢复能力是无与伦比的，但这只有在水是完全纯洁的情况下。$B$B如果水受到了污染，那么它将毁灭一切它接触到的东西。理解了这一点，你就应该能明白保证水源的纯洁性是多么的重要。$B$B如果你想要得到水之灵契，就到南贫瘠之地去找布瑞恩吧，她的家园最近时常受到野猪人的骚扰。', '到南贫瘠之地的黑棘山去找到布瑞恩。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1531, '空气的召唤', '你正在不断地进步，朋友。你已经证明了自己拥有可以控制空气图腾的能力，但是首先，你要去千针石林找普拉特·白云。如果你给予她足够尊重的话，她会很乐意告诉你如何得到空气图腾。$B$B从这里一直往南穿越贫瘠之地，在你进入千针石林之后再往东走。你会在一座山洞里找到她和她的男朋友的——哈哈，不要告诉她我说了她那么多的坏话——否则她可不会放过我，真的。', '到千针石林去找普拉特·白云。', '由于时间的关系，我必须将能够集中你的法术并且召唤风之灵的物品给你。拿走这个图腾，当你准备好的时候，跟着我一起多练习。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1532, '空气的召唤', '卡利姆多之风正急切地想要见你，而你应该已经成为了我们最强大的$g兄弟:姐妹;\n之一。我很荣幸能够看到你的光辉未来。$B$B风元素是一种非常难以控制的元素，但是我相信以你的能力可以克服挡在你面前的一切困难。$B$B到贫瘠之地的最南端，然后从那里走到千针石林。你可以在千针石林的东部找到普拉特·白云，她可以教你更多的东西。', '到千针石林去找普拉特·白云。', '由于时间的关系，我必须将能够集中你的法术并且召唤风之灵的物品给你。拿走这个图腾，当你准备好的时候，跟着我一起多练习。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1559, '闪光弹的制法', '', '', '这么说来你是个工程师囉?感谢你帮我取得了那些珍珠，这是闪光弹的制作方法。$B$B祝你好运，可别弄伤了自己的眼睛!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1560, '图加的任务', '我走丢了！$b$b我的妻子托尔塔让我出来找晚餐，我一定是迷了路！$b$b你能行行好带我回到托尔塔身边吗？她正在热砂港南部等我。', '把图加带回到他的妻子托尔塔身边。', '他找不到回自己家的路?真衰。$B$B好吧，我想你应该得到报酬……', '图加在哪里?', '把图加带回托尔塔身边', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1638, '战士的训练', '你已经展示了作为一个战士应有的天赋，$N。但是你现在还很年轻，还有很多东西需要学习。$B$B去和哈里·伯加德谈谈吧——他通常都在暴风城旧城区的猪和哨声旅店里。哈里是个老兵，也是个优秀的老师。他能教你许多一生受用的知识。', '和暴风城的哈里·伯加德谈一谈。', '啊哈!来跟我喝一杯，$g小伙子:小姑娘;\n。你看起来很硬朗，不过让我看看几杯猪和哨声旅店里最烈的酒下肚以后你的表现如何!!$B$B嗯……你是来向我学艺的?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1639, '醉鬼巴特莱比', '当然，我可以教你。不过，我先要看看你到底有多大的本事。$B$B看见酒吧最里面的那个醉汉了吗？就是那个巴特莱比，我要你去把他的酒杯拿来。$B$B哈哈，如果你了解巴特莱比，你就会明白他是不会轻易把酒杯给你的。', '和巴特莱比谈一谈。', '你好呀，天真的小$g男孩:女孩;\n!你在猪和哨声旅店里面做什么呢?小心点，不然你们会有苦头吃的……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1640, '击败巴特莱比', '你要什么？？你疯了吧？$B$B你想要我的酒杯？来试试看啊！', '打败巴特莱比，然后再和他谈一谈。', '看不出你这么厉害!', '你想要我的酒杯?先打倒我再说吧!', '击败巴特莱比', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1641, '圣洁之书', '', '', '很高兴见到你，$N。我的职责是指引圣骑士们，让他们在致力于保卫艾泽拉斯、抵抗天谴军团和其他威胁的同时领悟更多的美德。是时候让你踏出走向真正美德的第一步了。如果你同意的话，我会给你一本圣洁之书。通过学习这本书可以让你了解圣光，以及圣光对你的期望。理解它，并证明你的能力，最终你会获得更强大的力量。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1642, '圣洁之书', '无论在什么时候，圣骑士都必须严格地遵循圣光之道，因为它是我们力量的源泉。对于我们圣骑士来说，为了追求神圣而进行的几近苛刻的修行并不意味着我们是为了神格而努力——我们的目标是要在各方面都努力完善。$B$B虽然和邪恶斗争是眼前的当务之急，但是你必须牢记，只有无私地帮助他人才是圣骑士区别于普通人的根本要素。同情、耐心、勇敢——这些品德对圣骑士而言，和战斗中所表现出来的力量一样重要。$B$B记住这点，永远不要忘记。', '与暴风城的达索瑞恩·拉尔谈一谈。', '你好，我们又见面了，$N。你对圣洁之书的研究进展如何?$B$B那么你应该准备好接受考验了。我们的城市和国家到处都有等着我们去完成的任务，给予他人同情和理解;\n援助需要帮助的人;\n击杀凶恶的生物。$B$B只要证明你可以秉持耐心去帮助别人─特别是那些不幸的人，你就能证明自己是圣光的侍从，正直心灵的表率。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1643, '圣洁之书', '你的任务就是在暴风城里找到一个需要帮助的人，一个心灵纯洁动机单纯的人。这也许是某个想要帮助别人的人，也许是某个需要指引的人。不管怎样，这个人必须心地纯朴，而且需要你的帮助。$B$B完成这件事之后再回到我这里来，那时我们再来谈关于你的修行之道，以及成为圣骑士的意义。', '在暴风城的贸易区找到斯蒂芬妮·特纳。', '哦，你好，圣骑士。你的冒险旅程还顺利吗?哦，我很高兴听到你一切都好。$B$B哦，我吗?谢谢你—我也很好，一切都顺利。$B$B城里的商人越来越多，使得愿意捐赠皮革和布匹的人变得越来越少，想要帮孤儿院里的孩子做衣服就越来难越了，不过我们会想办法的。我所说的「我们」是指我和我的丈夫，他现在正在铁炉堡寻求当地居民的援助。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1645, '圣洁之书', '', '', '很高兴见到你，$N。我的职责是指引圣骑士们，让他们在致力于保卫艾泽拉斯、抵抗天谴军团和其他威胁的同时领悟更多的美德。是时候让你踏出走向真正美德的第一步了。如果你同意的话，我会给你一本圣洁之书。通过学习这本书可以让你了解圣光，以及圣光对你的期望。理解它，并证明你的能力，最终你会获得更强大的力量。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1646, '圣洁之书', '无论在什么时候，圣骑士都必须严格地遵循圣光之道，因为它是我们力量的源泉。对于我们圣骑士来说，为了追求神圣而进行的几近苛刻的修行并不意味着我们是为了神格而努力——我们的目标是要在各方面都努力完善。$B$B虽然和邪恶斗争是眼前的当务之急，但是你必须牢记，只有无私地帮助他人才是圣骑士区别于普通人的根本要素。同情、耐心、勇敢——这些品德对圣骑士而言，和战斗中所表现出来的力量一样重要。$B$B记住这点，永远不要忘记。', '与铁炉堡的蒂萨·热炉谈一谈。', '你回来得真快啊，在离开的这段时间中，你做了怎样的祷告?$B$B你有没有完成什么高尚的事业?也许你已经了解了慈善的真正价值，或者更多你对艾泽拉斯居民的责任。告诉我，你都帮了谁，怎么帮的……你的所做所为令人印象深刻，$N，你的行为毫无疑问证明你在坚定不移地追随圣光的指引。$B$B这样的牺牲一定会得到及时的奖赏。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1647, '圣洁之书', '$N，你的任务是在铁炉堡里找到一个需要帮助的人，一个心灵纯洁动机单纯的人。这也许是某个想要帮助别人的人，也许是某个需要指引的人。不管怎样，这个人必须心地纯朴，而且需要你的帮助。$B$B完成这件事之后再回到我这里来，那时我们再来谈关于你的修行之道，以及成为圣骑士的意义。', '在铁炉堡的外环区域找到约翰·特纳。', '暴风城的孤……哦，抱歉，我不是在对您大声喊，$G先生:小姐;\n，$B$B我叫约翰.特纳。您好吗?$B$B很好，很好，很高兴听说您一切顺利。我已经在这里工作很长时间了，我非常想念我的妻子，不过那是为了养家糊口不得不付出的代价。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1649, '勇气之书', '勇气，以及伴随着它而共同存在的一切美德，就如同那些珍贵的矿石一般：当你拥有它们的时候，要记得珍惜，因为它们非常宝贵。你也需要花费很大的精力去开采，去提炼。当你恰当地将这些矿石混合起来，一种新的坚不可摧的金属就会产生，即使是最强大的力量也无法将其破坏。$B$B这种来自你的信仰和勇气的力量必须经过考验。你必须学会绝不放弃信仰，并了解到在圣光之力的庇护下，你可以跨越过凡人根本无法跨越的障碍。', '与暴风城的达索瑞恩·拉尔谈一谈。', '啊，你希望我来考验你的勇气，非常好。$B$B这座城市的内部和外部有着无数的机遇与挑战正在等着一位乐于接受挑战并有能力接受挑战的$G男人:女人;\n。$B$B这项试炼可不容易，$N。它正如我们在修行之路上遇到的许多其他的试炼一样，有可能会夺走我们的生命。教会总是想提高自己的地位，但它也知道，必须通过圣骑士的牺牲才能彰显出教会的价值。$B$B你准备好了吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1650, '勇气之书', '很好！你对此表现出来的毫不犹豫可以清晰地佐证：你已经准备好了，并渴望着进行试炼。那么，去吧。$B$B在西部荒野的长滩最南端的尽头，有一处临海而建的小屋。屋里住着一对名叫斯迪威尔的夫妇。丈夫乔丹·斯迪威尔是一位技艺精湛的铁匠，他暂时去铁炉堡会见他的矮人朋友们了。于是他那无依无靠的妻子达芙妮目前一个人在家里待着。$B$B根据线报，迪菲亚兄弟会几乎已经完全控制了那片地区，势单力薄的达芙妮或许需要一位勇士的保护。去吧。', '在西部荒野找到达芙妮·斯迪威尔。', '你好，$N。既然你带着盔甲和武器来到这儿，我想你如果不是来抢我的土地，就是在我丈夫离开以后由教会派来保护我的。$B$B那么，请先允许我自我介绍一下:我是达芙妮.斯迪威尔。很高兴见到你。$B$B你来得还不算太晚……从日出到现在，我只干掉了6个坏蛋。他们本来一直在这四周晃来晃去的，但后来他们可能是看见你来了，就很快跑掉了，不过，这或许意味着他们随时都会再来。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1651, '勇气之书', '我敢打赌，他们马上就要再杀过来了，你最好有所准备。$B$B我在屋里放了一把枪，我会用它来帮你的，不过可别太指望我了，最终你还是得靠自己。$B$B我不知道他们来了多少人，但我敢肯定会比先前来的要多。$B$B祈祷圣光保佑你和我吧，因为……你听到脚步声了吗？他们来了！$B$B准备战斗！', '在迪菲亚兄弟会进攻时保护达芙妮·斯迪威尔的安全。$B$B如果你想成功的话，你和达芙妮都不能死在他们的剑下。', '干得好，$N!感谢你的帮助，你真是个不可思议的人。我从没想过一名圣骑士能同时抵挡住这么多得敌人。$B$B你在强大的敌人面前确实显示出了无与伦比的勇气。', '我们要守住这里!', '保护达芙妮·斯迪威尔。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1652, '勇气之书', '拜托你，请回到达索瑞恩那里，转告诉他我现在已经安全了，我一定要好好感谢你和教会。$B$B他会派人给正在铁炉堡的乔丹带份口信，让他不要担心我。啊，我是多么想念他呀……我都等不及想见他了。', '与暴风城的达索瑞恩·拉尔谈一谈。', '啊，你希望我来考验你的勇气，非常好。$B$B这座城市的内部和外部有着无数的机遇与挑战正在等着一位乐于接受挑战并有能力接受挑战的$G男人:女人;\n。$B$B这项试炼可不容易，$N。它正如我们在修行之路上遇到的许多其他的试炼一样，有可能会夺走我们的生命。教会总是想提高自己的地位，但它也知道，必须通过圣骑士的牺牲才能彰显出教会的价值。$B$B你准备好了吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1653, '正义试炼', '事实上，我想乔丹本人会非常感谢你的。我正准备找人给他送个信，让他知道他的妻子目前很安全，我想你就是个合适的人选。$B$B乔丹原本可以成为一名为圣光而战的圣骑士，不过后来为了继承他父亲的手艺走上了另一条路——他对我们的生活方式非常熟悉，也是我们最忠实的朋友。$B$B他应该还在铁炉堡，白天的时候，乔丹喜欢在室外工作，比如在山里呼吸新鲜的空气。', '去和铁炉堡的乔丹·斯迪威尔谈一谈。', '你好，圣骑士，愿圣光与你同在。$B$B嗯?达索瑞恩让你来的吗?我妻子……她怎么样了?我就知道在我离开以后她会遇到麻烦的。请你告诉我，她……哦，感谢圣光。她一切都好，我真是太高兴了。迪菲亚盗贼一直以来都是我们的威胁，对于这一点，国王的顾问们现在已经不能再否认了。$B$B你就是那个被派去保护我妻子的圣骑士吗?那我得再次感谢你了，$N。你真是勇气可嘉。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1658, '稻草人的节日', '我需要勇敢的人去提瑞斯法林地然后找到亡灵的稻草人节日举办地点。我不想撒谎——去那里会有危险。那里的守卫非常凶悍。但是，我们需要知道今年这个展会的规模有多大，另外就是被遗忘者打算在万圣节给我们造成多大的麻烦。$B$B如果你愿意接受这个任务的话，去提瑞斯法林地进行侦查吧。当你得到有价值的情报之后就回到我这里来，我会给予你优厚的补偿。', '在提瑞斯法林地找到被遗忘者的稻草人节日举办地点。任务完成之后回到南海镇的哈特曼中士那里。', '你做的很好，$N。只要那些可恶的被遗忘者还继续骚扰罗德隆的遗迹，稻草人节就会一直是个麻烦。这对一个曾经伟大的王国来说是个困扰，让我告诉你…。$B$B这里有一些钱让你做需要的修补工作，还有一些你会喜欢的季节小点心。万鬼节尾声快乐 – 让南海镇这里尽可能的保持安全吧。', '你去过提里斯法林地查看过了吗?他们通常会在幽暗城附近庆祝那个节日……', '找到被遗忘者的稻草人节日举办地点。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1661, '高贵之书', '很高兴再见到你，$N。我很荣幸能够称呼你为$g兄弟:姐妹;\n——你的奉献和无私对我们而言是一种恩赐。$B$B现在我要对你进行嘉奖了，但是你要知道，虽然这次我把它免费送给你，但是将来，如果时间允许的话，这将成为所有圣骑士都要接受的挑战。$B$B等一会再来与我交谈，我就将给你一份很棒的礼物。', '与暴风城的达索瑞恩·拉尔谈一谈。', '恭喜你，愿圣光保护你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1666, '治安官哈迦德', '你学会了一些招数，但你应该有一件像样的武器。我敢打赌，只要你和治安官哈迦德先生谈谈的话，他一定会帮助你的。$B$哈迦德先生就住在艾尔文森林东谷伐木场的一个庄园里。他已经退休了，不过他在工作期间曾收集了不少装备。$B$B告诉他是我派你去的，如果你够走运的话，他会提供给你一件武器的。', '和治安官哈迦德谈一谈。', '谁呀?是伯加德吗?你应该再走近一点。我老眼昏花了，看你走路的样子，我还以为你是个豺狼人呢!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1680, '托姆斯·深炉', '既然你已经学了几招，该是为你配备一件像样的武器的时候了。去和托姆斯·深炉谈谈吧，他能铸造一件肯定让你喜欢的武器。$B$B托姆斯就在铁炉堡的大锻炉。', '和托姆斯·深炉谈一谈。', '穆伦派你来的?没错，我可以帮你造一件利器……但是在那之前，你得帮我一个小忙。$B$B别担心。这个任务会很危险，你甚至有可能为此丧命，这难道不是一个合格的战士所追求的那种任务吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1682, '灰铁武器', '', '', '这里是一些刚从滚烫的铁鉆上取下来的武器，是用你带给我的阴影矿石制成的!$B$B$N，你随便挑一件吧!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1684, '艾兰娜瑞', '你好啊，勇敢的战士。你的技能越来越纯熟，但战士这个职业的要求比你想象中的要高很多。要想再进一步，你就必须要找到一个优秀的老师。$B$B艾兰娜瑞就住在达纳苏斯的战士区里，她会成为你的良师。', '和艾兰娜瑞谈一谈。', '你好，$N。你的名字在达纳苏斯已经家喻户晓，因为你让人们看到了未来。不过，要不了多久，我们就能知道你是否真的具备成为一个合格的战士所必需的意志了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1685, '加科因的召唤', '难道不是每次都这样吗？！我找了你一整天都不见你的踪影，等我已经不指望能找到你的时候你却来了。$b$b你已经浪费我太多时间了，所以现在咱们就少废话了。加科因大师要召见你进行更多训练，我觉得你最好还是尽快找到他。$b$b他在已宰的羔羊旅店的地窖里。顺便说一句，他的藏身地点你可得保密，不要让别人知道了。', '去暴风城的法师区向黑暗缚灵者加科因报到。', '我很高兴有人找到你了，$N。我正在担心呢。我们为你付出了这么多时间，失去你会很可惜的。$B$B不过这些问题我们可以晚点再谈，现在继续对你进行训练才是最重要的事。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1693, '月神武器', '', '', '$N，我用你带来的月神矿石打造了这些武器，请选一样最适合你的。$B$B我必须谢谢你。能打造月神武器对我来说是一件荣幸而愉快的事情。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1698, '犹鲁斯·麦酒', '犹鲁斯·麦酒向联盟所有强大的战士发出了挑战。他在赤脊山的湖畔镇旅店等候着你们，并承诺会给所有通过试炼的战士提供丰厚的报酬。', '与犹鲁斯·麦酒谈一谈。', '哈!你听说了我的挑战，对吗?$B$B请坐下来听我说。来一杯酒，慢慢享受……因为这也许是你这辈子最后一次喝酒了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1699, '往返瑞斯班洞穴', '我把我的挑战项目称作“往返瑞斯班洞穴”。要想通过这次挑战，你要做的就是进入瑞斯班洞穴，然后回到这里——非常简单的任务！当然，路上也许会有一些小波折……$B$B你必须在一个小时之内返回这里，有成堆的赤脊山豺狼人挡在路上，所以你得花些时间打发它们。$B$B在出发之前，请喝下以我的家族名字命名的美酒：热麦酒！$B$B那么，你觉得如何？瑞斯班洞穴就在湖畔镇北面的山脚下，你准备好了吗？', '进入瑞斯班洞穴，然后在规定的时间内回到犹鲁斯·麦酒那里。$B$B在整个过程中你都不能死掉或者释放灵魂，否则任务就宣告失败。', '你成功了!干得不错!为$N欢呼喝彩!', '时间在不断流逝，$N。如果我是你，我已经出发了……', '进入瑞斯班洞穴', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1706, '格瑞曼德的铠甲', '', '', '我简直不敢相信!弗伦居然成功了，这副铠甲应该能承受超强的压力。$B$B$N，拿着它吧。谢谢你，如果你没有收集到这些材料，那我就必须自己进行测试，而那样也许我永远都无法相信弗伦的发现。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1709, '科罗莫特的成果', '', '', '给你，这是你要的铠甲，$N。弗伦那一套果然很棒!简直是完美!不可思议，真的不可思议!$B$B我看它即使是被攻城机具辗过去也不会有什么问题!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1711, '玛希尔的铠甲', '', '', '我已经完成了铠甲，而且我对它感到非常满意。现在我已经可以将弗伦的新技术运用得非常娴熟了，我想这副铠甲一定具有超强的韧性。$B$B谢谢你，$N。愿它能帮助你在以后的战斗中无往而不胜。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1715, '已宰的羔羊', '哎，以前术士们都在卡兹莫丹由诺莫瑞根的大师训练，现在我们不得不搬到铁炉堡这个老鼠洞里，而且麦格尼又在一直监视我们，所以我们只能把新手都送到暴风城去训练了。$b$b幸运的是，加科因还算是个有能力的人，你还是能在那里学到你需要的东西的，不过现在这种样子还是让我很冒火！$b$b加科因就在暴风城的“已宰的羔羊”旅店的地下室里。', '去暴风城的法师区向黑暗缚灵者加科因报到。', '黑钳让你来的?铁炉堡的术士应该想办法自己解决问题，暴风城空间就这么大，导师也就这么多。活动越频繁，我们就越有可能引起别人的注意。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1716, '噬魂者', '魅魔是灵魂的吞噬者，心灵的毁灭者，思想的控制者。她脑中永远只有邪恶的念头。$b$b这就是你现在要学会召唤并控制的生物，但在没有诱饵的情况下，你是无法将她引入到我们的世界中来的。$b$b以一件象征爱的事物作为诱饵，魅魔才会回应你的召唤。在这之后，你只有战胜她才能将她变为你的工具。$b$b但是找到象征着爱的东西可不容易，你最好和先知塔卡尔谈谈。他就住在卡利姆多大陆的贫瘠之地，靠近陶拉祖营地的地方。', '与贫瘠之地的先知塔卡尔交谈。', '你是历尽艰险才来到这儿的吧，$N?为了找我，你真可以说是不远万里了。不过，我知道加科因为什么派你来，他这么做很明智，因为我能帮助你寻找你所要的东西。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1717, '加科因的召唤', '$n！没想到在这儿遇见你，不过我接到指示说要注意你的行踪。$b$b你应该接受更多训练了，下一次去暴风城的时候记得去见一下加科因，他正在等你。', '去暴风城的法师区向黑暗缚灵者加科因报到。', '我很高兴有人找到你了，$N。我正在担心呢。我们为你付出了这么多时间，失去你会很可惜的。$B$B不过这些问题我们可以晚点再谈，现在继续对你进行训练才是最重要的事。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1718, '岛民', '作为一名战士，你的名声越传越响，$N。现在是时候让你和其它战士比试一下，看看你真正的实力了。$B$B在贫瘠之地的海岸附近有一座名叫勇士岛的小岛，就在棘齿城的南部，强大的战士们时常在那里聚会。$B$B他们在那里相聚，然后互相切磋。$B$B去和勇士岛的首席战士克兰诺克·马克雷德谈谈吧。如果他认为你够格的话，就会指引你在勇士的道路上更进一步的。', '和克兰诺克·马克雷德谈一谈。', '你好，勇敢的战士。很高兴看到你来到勇士岛，希望你能喜欢这里……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1719, '格斗考验', '如果你想从我这儿学到什么，你必须首先通过格斗考验。对于我们勇士岛上的自认为勇猛而又跃跃欲试的战士们来说，这是他们必须通过的挑战，如果你能通过这个考验，那么你就证明了自己的价值。$B$B要开始接受考验的话，就走到那边人群中的斗阵中央。图维基·弗拉海德会知道你已经准备好了，然后他就会派出挑战者来对你进行考验。$B$B在战胜了所有挑战者之后，他会叫出比格维尔。杀了比格维尔，在限定的时间内回到我这里来复命。', '杀掉比格维尔，然后向勇士岛的克兰诺克·马克雷德回复。', '干得好，$N。你通过了格斗考验!$B$B你是个有价值的战士，我很荣幸能向你传授一些技艺……', '你完成挑战了吗?', '走上战阵开始格斗考验', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1758, '阴谋之书', '仅仅靠一个简单的召唤法阵是无法为你召唤出地狱猎犬来的。$b$b我和我的三个助手会帮助你制造召唤法阵，但是你必须先弄到一本阴谋之书的副本，我们很久之前就把那本书给弄丢了。阴谋之书是当初一批术士为了召唤地狱猎犬而写的书。$b$b克罗姆·粗臂也许能给你提供一些帮助，他原本是一个四处巡游的术士，但是现在却整天躲在铁炉堡的图书馆里苦心研究古代文献。', '与铁炉堡的克罗姆·粗臂谈一谈。', '阴谋之书?嗯……蛮耳熟的。不过我在这儿没看到过─相信我，我对我读过的每一本书都记忆犹新。$B$B啊，对了，我曾经在图书馆里的书籍目录中看见过有关它的介绍。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1778, '圣洁之书', '我计划不久后就回到家乡。幸运的是，斯蒂芬妮在暴风城把孤儿院照顾得不错，我简直等不及要见她了。再见，$c。', '与铁炉堡的蒂萨·热炉谈一谈。', '你回来得真快啊，在离开的这段时间中，你做了怎样的祷告?$B$B你有没有完成什么高尚的事业?也许你已经了解了慈善的真正价值，或者更多你对艾泽拉斯居民的责任。告诉我，你都帮了谁，怎么帮的……你的所做所为令人印象深刻，$N，你的行为毫无疑问证明你在坚定不移地追随圣光的指引。$B$B这样的牺牲一定会得到及时的奖赏。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1779, '圣洁之书', '我希望你带上这个，$N。它的名字叫生命符记。$B$B你已经显示了自己的仁慈与耐心，现在我需要你证明在战斗和魔法两个方面的能力。$B$B最近，我的丈夫穆里顿在和黑铁矮人的战斗中负伤归来，他几乎丢了性命——一个牧师治好了他所受的伤。$B$B带上生命符记，和我丈夫谈谈。如果你能帮助他的话，我们可以再聊聊。愿圣光保佑你。', '带上生命符记，和铁炉堡的穆里顿·热炉谈一谈。', '*咳嗽*$B$B你好，$C。别担心我的伤，好心的牧师会照顾好我的。我还不需要使用你带来的生命符记的魔法。$B$B那么，是我的妻子让你到这里来找我的?很好。我会和你谈谈─给你讲讲在我和我最好的朋友纳姆身上发生的事情。纳姆是一个像你一样的圣骑士。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1780, '圣洁之书', '我今天就把这些拿给孩子们。你要多加小心，好心的$n。城里已经很难看到像你这样乐于助人的$G绅士:女士;\n了，不过你已经证明了圣骑士决不会拒绝帮助那些陷入困境的人。$B$B请多保重。', '与暴风城的达索瑞恩·拉尔谈一谈。', '你好，我们又见面了，$N。你对圣洁之书的研究进展如何?$B$B那么你应该准备好接受考验了。我们的城市和国家到处都有等着我们去完成的任务，给予他人同情和理解;\n援助需要帮助的人;\n击杀凶恶的生物。$B$B只要证明你可以秉持耐心去帮助别人─特别是那些不幸的人，你就能证明自己是圣光的侍从，正直心灵的表率。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1781, '圣洁之书', '拿着这个，$N。这是生命符记。$B$B你已经证明了自己的仁慈和耐心，现在让我们看看你是否有能力掌握光明之道的一项最伟大的能力。$B$B我的朋友贾森最近刚从艾尔文森林的英烈碑回来，他在那里遭遇了迪菲亚盗贼，差点就没命了。现在他正在圣坛边上接受牧师的治疗。$B$B把这个符记带给他，和他谈谈。如果你帮得了他，我们很快就能再见面了。愿你永享圣光的荣耀。', '把生命符记带给暴风城的贾森·坦诺姆。', '*咳嗽*很高兴见到你，$C。别担心我的伤，这儿的牧师很好，老杰生拣了一条命。我不需要你拿来的生命符记的力量……至少现在还不需要。$B$B那么，是达索瑞恩.拉尔要你来找我的，对吗?很好。我会告诉你我和我的朋友亨兹遇到了什么。只要有那么一丁点的运气，再加上你的能力，也许你还能再帮我们做点什么。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1782, '弗伦的铠甲', '', '', '这是你要的铠甲，$N。如果它不能承受最猛烈的攻击的话，我就不叫弗伦.长须!$B$B我要谢谢你，在用你带回的材料进行锻造的同时，我也学会了很多的东西。我想也许哪一天我会在锻造技艺上再来一次惊人的突破!$B$B我要把我学到的东西告诉联盟的其他铁匠。$B$B我会告诉他们是你帮了我的大忙，没准他们也会报答你的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1783, '圣洁之书', '我们一直在侦察一些潜伏在盔枕湖以南的黑铁矮人。我们知道他们出现在那里决不是什么好事，因此我和纳姆决定靠近些去看看——看看他们的头目到底下了些什么命令。$B$B我和纳姆发起了突袭，杀掉了一些黑铁矮人，但他们比我们想象的还要顽强，一大堆黑铁矮人朝我们扑了过来。纳姆让我来求援，我就跑回来了。$B$B纳姆需要帮助，我们一定要尽快，否则我不会安心的。$B$B你能帮助我吗，$N？', '使用生命符记复活丹莫罗的纳姆·法奥克。', '我该怎么才能感谢你，$G兄弟:姐妹;\n。$B$B你带有生命符记，我猜想是提萨和穆里顿派你来帮我的。$B$B事实确实如此，我被黑铁矮人抓住了，但是总算还是尽量拖延了时间，让穆里顿有足够的时间逃跑，当你来了之后，我感到全身充满了圣光的力量。现在我已经可以看出你能够熟练使用生命符记了，这非常好。但是关于这个还是等我们到了安全的地方再继续讨论吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1785, '圣洁之书', '我的妻子正在那里骄傲地微笑，你最好快过去和她谈谈，我想她有些话要和你说。$B$B圣光会保佑你的，伟大的$c。相信有一天，我会邀请你一起来对抗亡灵天灾和那些该死的黑铁矮人。', '与铁炉堡的蒂萨·热炉谈一谈。', '你回来得真快啊，在离开的这段时间中，你做了怎样的祷告?$B$B你有没有完成什么高尚的事业?也许你已经了解了慈善的真正价值，或者更多你对艾泽拉斯居民的责任。告诉我，你都帮了谁，怎么帮的……你的所做所为令人印象深刻，$N，你的行为毫无疑问证明你在坚定不移地追随圣光的指引。$B$B这样的牺牲一定会得到及时的奖赏。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1786, '圣洁之书', '亨兹和我去了英烈碑，那地方就在艾尔文森林东北的石碑湖中央的一座小岛上。我们听说迪菲亚盗贼在边境一带搞间谍活动，就受命去找到证据交给国王的顾问。$B$B我们看见两个人在鬼鬼祟祟地阅读什么文件，就向他们发起了突袭。这时突然出现了很多法师将我们团团包围。$B$B亨兹为我拖住了他们，让我先逃脱了……这个傻瓜，他为什么要那么做……$B$B我的兄弟亨兹，他的尸体现在还躺在那里。你能帮助我们吗，$N？', '把生命符记带到艾尔文森林的英烈碑去，复活亨兹·法奥克。', '谢谢你，$G兄弟:姐妹;\n。看到你刚才使用了生命符记，我想是不是达索瑞恩和杰生派你来的?$B$B我和杰生试图探听迪菲亚盗贼的计画时，和迪菲亚法师打了起来。我成功地支撑了一会儿，让杰生得以逃脱。但最后我还是被他们的魔法所打败。$B$B不过你又拯救了我!生命符记并不是什么人都能用的，$N。你持有它，说明了你拥有足以使用生命符记的信念。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1788, '圣洁之书', '在达索瑞恩看过这份文件之后，我会把它交给国王的顾问，不过你现在应该去和达索瑞恩谈谈。他一定会表扬你的！$B$B再次感谢你，$N。我希望我们还能见面。有你这样的朋友绝对是我的骄傲与荣幸。', '与暴风城的达索瑞恩·拉尔谈一谈。', '你好，我们又见面了，$N。你对圣洁之书的研究进展如何?$B$B那么你应该准备好接受考验了。我们的城市和国家到处都有等着我们去完成的任务，给予他人同情和理解;\n援助需要帮助的人;\n击杀凶恶的生物。$B$B只要证明你可以秉持耐心去帮助别人─特别是那些不幸的人，你就能证明自己是圣光的侍从，正直心灵的表率。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1789, '生命符记', '', '', '快点，$N，你的成功与否关系着不止一条人命。$B$B如果因为某些原因让你无法帮助杰生和亨兹，就赶快回来找我，我会再给你一个生命符记。$B$B别以为我的帮助仅仅是简单的恩惠，你必须证明自己具备和其他圣骑士一样的价值,在今后的日子里，你还会不断遇到挫折。', '快点，$N，你的成功与否关系着不止一条人命。$B$B如果因为某些原因让你无法帮助杰生和亨兹，就赶快回来找我，我会再给你一个生命符记。$B$B别以为我的帮助仅仅是简单的恩惠，你必须证明自己具备和其他圣骑士一样的价值,在今后的日子里，你还会不断遇到挫折。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1790, '生命符记', '', '', '快点，$N，你的成功与否关系着不止一条人命。$B$B如果因为某些原因让你无法帮助杰生和亨兹，就赶快回来找我，我会再给你一个生命符记。$B$B别以为我的帮助仅仅是简单的恩惠，你必须证明自己具备和其他圣骑士一样的价值,在今后的日子里，你还会不断遇到挫折。', '快点，$N，你的成功与否关系着不止一条人命。$B$B如果因为某些原因让你无法帮助杰生和亨兹，就赶快回来找我，我会再给你一个生命符记。$B$B别以为我的帮助仅仅是简单的恩惠，你必须证明自己具备和其他圣骑士一样的价值,在今后的日子里，你还会不断遇到挫折。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1791, '捕风者', '现在既然你已经学会了狂暴姿态，就应该去弄一把称手的武器。$B$B去和捕风者巴斯拉谈谈吧，他是住在奥特兰克山脉和西瘟疫之地之间一个巨魔隐士。他是制造武器的行家，也是一个强大的萨满祭司。$B$B去找到巴斯拉，沿着塔伦米尔东侧的河流一直向北——巴斯拉的营地就在这条河东岸的废墟旁。', '和捕风者巴斯拉谈一谈。', '你是从很远的地方来的吧，年轻的战士。我在你的眼里看到了火焰，你正在寻求一件威力巨大的武器，对吗?$B$B我能帮你完成你的梦想，你也能帮我完成我的梦想。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1792, '旋风武器', '', '', '现在有了旋风之心，我就可以把蕴含在其中的力量注入到武器里。$B$B选择一件你中意的武器吧，$N，它将获得塞克隆尼亚的力量。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1793, '勇气之书', '', '', '圣光与你同在，$N。不过在你将来面对更加危险的境况时，了解自身所具备的力量就显得非常重要了。当魔鬼、恶龙和其他邪恶在我们的土地上肆虐时，你的勇气将接受真正的考验。你有足够强大吗?$B$B不管在什么情况下，勇气对于圣骑士来说，都是和对圣光的信仰一样重要的精神，它是你铜墙铁壁的护盾，你无坚不摧的武器。在圣光大教堂中修行的时候，你还将学习圣骑士的另外两条标准，时刻铭记要保护弱者，保持信念。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1794, '勇气之书', '', '', '圣光与你同在，$N。不过在你将来面对更加危险的境况时，了解自身所具备的力量就显得非常重要了。当魔鬼、恶龙和其他邪恶在我们的土地上肆虐时，你的勇气将接受真正的考验。你有足够强大吗?$B$B不管在什么情况下，勇气对于圣骑士来说，都是和对圣光的信仰一样重要的精神，它是你铜墙铁壁的护盾，你无坚不摧的武器。在圣光大教堂中修行的时候，你还将学习圣骑士的另外两条标准，时刻铭记要保护弱者，保持信念。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1798, '寻找斯坦哈德', '是该教你召唤地狱猎犬的时候了，$n。但我现在手里没有教你这个法术所必需的材料，所以你得去找另外一个人来教你，也就是斯坦哈德·法尔杉，他是我们我们的另一个成员。$b$b他就住在地精港口城市棘齿城附近。在你到达之前，我会通知他你要过去的。', '与贫瘠之地的斯坦哈德·法尔杉谈一谈。', '$N?哦，就是你啊。你可是最近的风云人物，但我恐怕你是盛名之下难符其实啊。$B$B别介意，别介意，你来这儿是学习的嘛，别管我的自言自语的说笑了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1801, '阴谋之书', '要召唤地狱猎犬并迎接它的挑战，一个简单的召唤法阵是不够的。$b$b我和三个侍僧可以帮你制造法阵，但是你需要一本《阴谋之书》。很久以前我们就把这本书给弄丢了，它是由最早的那批不借助任何外力帮助就召唤出地狱猎犬的术士写下的。$b$b也许约拉·安尼森能帮你的忙。这段时间里，他作为一名制图师受雇于幽暗城，在古籍方面他知道的比我多。', '和幽暗城的约拉·安尼森谈一谈。', '地图绘制!图是对现实的模拟，不过这些东西对我来说没什么价值。$B$B书，书就是叙述和描写!真知就在其中。我宁愿用所有的地图去书店里换一本有通灵术起源的书，或者是一本关于黑暗女王百战百胜的传记故事。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1806, '正义试炼', '我们现在就到熔炉边上去开始工作吧！我已经为你的到来准备很久了，现在不用再等了。$B$B在我们完成这把武器之后，你就可以更好地为圣光而战，这一点我绝对可以保证。$B$B说实话，$N，看到你所取得的这些成绩，我真有点羡慕。不过我知道我也可以用我自己的方式给你提供一些帮助，这样就已经让我很高兴了。', '等待乔丹·斯迪威尔为你铸造武器。', '拿着这个，$N。这把武器可以配得上像你这样勇敢的圣骑士。我用我的一位伟大的朋友，一位矮人圣骑士的名字来给它命名。他的名字是维里甘……伯施.维里甘。请为了我和我妻子收下它，我们欠了你很多。我相信这个世界会因为你而更加安全。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1818, '迪林格尔', '亡灵卫兵迪林格尔告诉我有一份工作可以交给像你这样的$c。如果你想要为黑暗女王效力的话，那就马上去迪林格尔那边报到吧。$B$B亡灵卫兵迪林格尔在布瑞尔最西边执勤，就在墓地的旁边。', '和布瑞尔的亡灵卫兵迪林格尔谈一谈。', '你来这里找事干?很好，我有一个很重要的任务要交给你，可以看看你到底有几把刷子……还可以检验你为我们被遗忘者效力的决心。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1820, '库勒曼', '你已经向黑暗女王证明了自己的价值，现在你应该有资格继续完成她下达的其它任务了。$B$B库勒曼·法席恩正在征召可以帮助他对付敌人的勇士。$B$B你可以在布瑞尔东部的恐惧之末旅店找到他。', '和库勒曼·法席恩谈一谈。', '没错，确实如此。我需要你这样训练有素的$C，这个任务并不仅仅为了我自己，而是为了所有的被遗忘者。帮我完成这个任务吧，我保证你会得到丰厚的奖励。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1822, '祖传武器', '', '', '我将从你找来的武器中留下三样作为我所遭受的痛苦和折磨的纪念。但是，$N，请你在这些武器中选择你最喜欢的一件作为奖赏吧。$B$B希望你选择的那件武器能够在战场上为你赢得荣誉，而不是像以前那样被它那该死的主人所玷污。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1823, '和鲁迦交谈', '作为一名战士，你已经具备了相当的素质，而且名望也日渐显赫。也许你已经准备好要接受鲁迦·狂暴图腾的试炼了？如果是这样的话，就去贫瘠之地的陶拉祖营地找鲁迦吧。$B$B他一直以来都在那里等待英勇的战士响应他的召唤。', '和鲁迦·狂暴图腾谈一谈。', '$N，你是来这里接受我的试炼的?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1825, '和索恩格瑞姆交谈', '著名的兽人铁匠索恩格瑞姆·火眼已经听说了你为部落作出的杰出贡献。他愿意为你制作一套护甲，马上去找他谈谈吧。$B$B索恩格瑞姆的营地就在贫瘠之地十字路口的东边。', '与贫瘠之地的索恩格瑞姆·火眼谈一谈。', '你终于来了。很好，我有很多事情要跟你谈。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1839, '尤拉莱克和野蛮护手', '巨魔铁匠尤拉莱克会为你铸造一副野蛮护手，他住在杜隆塔尔的森金村里，那儿是暗矛氏族的家园，他正在等着你。', '与杜隆塔尔的尤拉莱克谈一谈。', '你好，$N。老索恩格瑞姆说过你会来我这里，但是即使他不告诉我，我也不会对你的到来感到惊讶。$B$B年轻的战士，我可以从你的灵魂中看出，曾有许多敌人倒在你的脚下。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1840, '奥姆·石蹄和野蛮头盔', '奥姆·石蹄因为他杰出的铸造技术而被大家尊敬，他会为你铸造野蛮头盔。$B$B你可以在雷霆崖找到他，他就在城市中心最大的那根图腾旁的池塘附近。', '和雷霆崖的奥姆·石蹄谈一谈。', '你好，勇敢的战士。我是欧姆，索恩格瑞姆和我说你想要一顶头盔?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1841, '维罗拉·奈特雷和野蛮腿甲', '在死亡之前，维罗拉·奈特雷曾是洛丹伦最好的铸甲师。看来死亡让她的技艺退步了许多。去和维罗拉谈谈——她会帮你铸造野蛮腿甲。$B$B维罗拉住在洛丹伦的幽暗城里，你可以在贸易区找到她。', '与幽暗城的维罗拉·奈特雷谈一谈。', '你来这里是为了野蛮腿甲?太好了!$B$B嗯……是我帮你铸造野蛮腿甲还是你帮我铸造野蛮腿甲?$B$B开玩笑啦，不好笑吗?我不知道……在我停止呼吸和嗅觉的时候，我已失去了幽默感。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1843, '野蛮护手', '', '', '谢谢你，$N。这些护手是我的心血之作。拿着吧，如果你能一直带着它的话，对我和我的祖先来说都是一种荣耀。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1845, '野蛮头盔', '', '', '我把这顶头盔交给你了。$B$B是崇高的事业和大地之母的意愿将你带到我这里来的，$N……我相信还有着更加伟大而崇高的事业在等待着你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1847, '野蛮腿甲', '', '', '这是你的腿甲，$N。看看它是否合适，如果你需要对它进行一些改动的话，我很乐意为你效劳!$B$B这些天我并没有专心于打造装备，因为我总是为感到自己是天谴军团的手下而感到悲哀!$B$B我想应该是这样吧……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1848, '野蛮锁甲', '', '', '我相信你为这个任务付出了很大的代价，$N。你的努力现在应该得到回报。$B$B希望它能够帮助你，愿你有一天能够回到这里来，向我讲述你穿着这件护甲所经历的冒险故事。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1859, '瑟祖克', '小声点，$n。没错，我知道你叫什么。有人让我注意一个兽人，你完全符合他的描述。$b$b我们听说你在战斗中颇有一套，有时也会使用一些非常的手段。$b$b我没说错吧？$b$b不管怎样，你得去见见奥格瑞玛的瑟祖克，他有事要吩咐你。', '到奥格瑞玛的暗影裂口和瑟祖克谈谈。', '很好，我很高兴卡普拉克能找到你。$B$B我有点事情要跟你谈谈，这和你的前途息息相关。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1860, '和詹妮亚交谈', '我们法师有一项任务要交给你去完成，一项对于暴风城和艾尔文森林的安全至关重要的任务。$B$B詹妮亚·坎农会告诉你任务的细节。她正在暴风城的法师区里的巫师圣地里学习，你最好尽快找到她。', '和暴风城的詹妮亚·坎农谈一谈。', '你是来帮助我的，$N?很好。有你这样年轻的法师愿意加入到我们的事业中，真是件让人鼓舞的事情……$B$B你问是什么样的事业?问得正是时候，年轻的$r。你会知道的……到时候你就会知道。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1879, '和彬克交谈', '$N！我在铁炉堡的侏儒同事彬克送话过来说，她有一项必须交由某个法师来完成的任务！你不正好是个法师吗，$N？$B$B如果你愿意的话，去和彬克谈谈吧。她就在铁炉堡秘法区的秘法大厅里。', '和铁炉堡的彬克谈一谈。', '哦，我知道你很能干!但是，只是很能干还不足以成为一个好法师。如果你不是一个好法师，那你就是一个糟糕的法师。糟糕的法师会引发一大堆问题，没错，一大堆!$B$B哦，我说到哪里去了……让我们回到正题上吧!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1881, '安娜斯塔西娅', '$N，安娜斯塔西娅·哈特威尔有个任务需要你这样有才干的$c来完成。她就在幽暗城的魔法区，去和她谈谈，准备为被遗忘者的法师们完成你的第一个任务吧。', '和安娜斯塔西娅·哈特威尔谈一谈。', '你好，$N。你很明智地回应了我的召唤，如果你能按照我说的去做，那你就更加明智了……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1883, '安苏瓦', '森金村的部落法师安苏瓦发现杜隆塔尔的魔法流出现了波动，为此他向我寻求帮助。去和安苏瓦谈谈，尽你所能去帮助他。$B$B快去吧，到时一定会有更多的秘密展示在你的面前。', '和安苏瓦谈一谈。', '你好啊，$N，感谢你。我寻求帮助的呼声终于得到了回应，希望你能胜任这项任务……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1885, '米奈特·卡加德', '$n？虽然现在的情况并不像我所预计的一样，但卡加德确实对你非常感兴趣。听起来是不是有点难以置信？$b$b无论如何，你得尽快去找他谈谈。我想你并不想知道上一个对他的召唤置之不理的人的下场吧。', '与幽暗城盗贼区的米奈特·卡加德谈一谈。', '嗯。显然你在接到我的召唤之后第一时间就来到了我的面前，不是吗?当然。我对于一个像你这样潜力十足的亡灵哨兵抱有很高的期望。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1919, '向詹妮亚报告', '你的能力正在不断地增强，年轻的$N。你准备好要接受真正的挑战了吗？你愿意加入到我们正在进行的这场秘密战争之中吗？$B$B如果你愿意的话，就去和詹妮亚·坎农谈谈吧，她在暴风城法师区的巫师圣殿里。她有一项任务要交给你，这将帮你打开通向那个秘密世界的第一扇窗。', '和暴风城的詹妮亚·坎农谈一谈。', '$N，我有一项任务要交给你去做，就在法师区里。仔细听好了，我们现在时间紧迫。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1939, '高阶巫师安多玛斯', '高阶巫师安多玛斯希望和你谈谈，$N。他就在暴风城法师区的高塔顶端。$B$B能去和他会面可是非常难得的机会，因为安多玛斯是少数几个没有被困在达拉然的超强的大法师之一，他找你也一定是有非常重大的事情。', '和高阶巫师安多玛斯谈一谈。', '你好，$N。我很高兴见到你，希望你有时间听听一个老人的话……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1941, '法纹长袍', '', '', '这是你的长袍，也是我自己最满意的一件作品!请自豪地穿上它，当人们问起的时候……告诉他们这是拉尔森服装店为你制作的!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1942, '星结之衣', '', '', '你的长袍做好了!你收集的蛛丝真是太好了……我在做长袍的时候稍微偷工减料了一些，剩下一些蛛丝给自己留着，你不介意吧?$B$B我只是开玩笑啦。这件长袍很适合你，无论是外出探险还是出席晚宴都非常棒。希望你能喜欢!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1943, '巨魔法师迪诺', '$N，巨魔法师迪诺需要你的帮助，她就住在奥格瑞玛的暗木小屋里。', '和迪诺谈一谈。', '太好了，你终于来了。我的任务可不是那么简单，但对于整个法师界来说是非常关键的。如果你能帮忙的话，我相信你一定不会后悔的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1946, '虚灵长袍', '', '', '这是给你的虚灵长袍，$N。这件法袍穿在身上非常舒适，而且很耐磨，袍子里还蕴含着欢笑姐妹的头发的魔力。$B$B希望它对你有用，如果你喜欢这件法袍，别忘了告诉迪诺。我非常欣赏她……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1947, '沼泽之旅', '现在，是让你得到自己的法师魔杖的时候了。首先，你得去和住在尘泥沼泽的人类隐者塔贝萨谈一谈。你可以在沼泽深处找到她的小室，那地方就在塞拉摩的西边，石槌废墟的北边。$B$B去和她谈谈，她的知识非常渊博。', '和塔贝萨谈一谈。', '请安静!我正在思考重要的问题，不要打扰我!$B$B请等一会儿……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1949, '隐藏的秘密', '为了制作你的魔杖，我得查询一本书里的一些关键段落。这本书叫做《能量仪祭》，是大法师提尔斯写的。$B$B我没有这本书，世界上所有的大图书馆也没有收藏。你必须去和提尔斯谈谈，从他那里要一本来。$B$B祝你好运。提尔斯曾经是个伟大的法师和学者，不过他现在把时间都花在饮酒、赌博，还有去闪光平原观看侏儒与地精的车赛上了。', '和闪光平原的大法师提尔斯谈一谈。', '什么?大声点!我的耳朵不像以前那样灵光了。$B$B好吧，我希望你给我带来一杯新鲜的麦芽酒，或是准备给下一轮的车赛丢几注!否则，你最好离开这里……因为我的变形魔杖可不长眼睛!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1952, '法师的魔杖', '我现在要去铸造魔杖了。', '等塔贝萨的仪式完成后，和她谈一谈。', '这些就是我铸造的魔杖。选一件吧!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1953, '返回沼泽', '$N，是时候让你去和塔贝萨谈谈了……这位尘泥沼泽里的隐士将指导你如何铸造强大的法师物品。$B$B塔贝萨就隐居在尘泥沼泽的深处，塞拉摩的西边。', '和塔贝萨谈一谈。', '啊，这么说来，你是为宝珠或是魔杖而来的?非常好，我会帮助你铸造它的。$B$B但是我得先警告你─铸造过程是很危险的，有可能会送掉你的命。$B$B或者是我的命，反正肯定有什么人为此丧命……$B$B但是我们都希望送命的是别人，对吧?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1958, '苍穹之力', '', '', '$N，你应该为自己感到骄傲。许多法师都被你刚刚击败的生物所杀害了。$B$B天国宝珠已经完成，如果你需要的话，我也可以把它镶在一根法杖上。你来决定吧，虽然我偏向于只拿着宝珠，不过你说了算!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1959, '向安娜斯塔西娅报告', '幽暗城的法师们注意到城里出现了一股魔法波动，他们随即发出消息，请求部落的法师来协助他们进行调查。$B$B安娜斯塔西娅·哈特威尔会告诉你更多的详细内容，她就在幽暗城的魔法区，去和她谈谈吧。', '和安娜斯塔西娅·哈特威尔谈一谈。', '确实如此。在我们的城市里出现了一股魔法波动，我们还不清楚它的起源，也无从得知它到底是好是坏。我们必须搜集更多的消息……$B$B$N，你来执行这个任务。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (1962, '魔焰长袍', '', '', '拿着这件长袍，$N。好好地利用它吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2039, '寻找宾格斯', '我们和宾格斯失去了联系！他被派去侦察诺莫瑞根，不过已经有足足一个星期没回来报告了。这家伙应该是失踪了。$B$B最后有人看到他时，他正在洛克湖上空飞行。你可以去那一带调查一下，$N。', '去洛克莫丹寻找宾格斯。', '诺恩不相信我的侦察能力?为什么……$B$B不管了，我需要你帮忙!不!是这个行动需要你帮忙。', '你绝对不能看这个文本。绝对不能。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2041, '沉默的舒尼', '也许……也许你能帮我们攻打诺莫瑞根。$B$B你可以到暴风城去找秘密攻击部队的指挥官，沉默的舒尼。舒尼需要有人帮他找一些东西。$B$B你可以在暴风城的矮人区中找到她。$B$B祝你好运，$N。', '去暴风城的矮人区去，和那里的沉默的舒尼谈一谈。', '指挥官让你来的?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2158, '休息和放松', '每个冒险家在疲惫的时候都需要休息——而休息和放松的最佳去处就是狮王之傲旅店！$B$B我的好朋友法雷是那里的旅店老板。告诉他是我介绍你去的，也许他还会给你些特别优惠呢。$B$B如果你要去狮王之傲旅店的，沿着大路往南走就没错了！', '和狮王之傲旅店的旅店老板法雷谈一谈。', '又累又冷的旅行者啊，狮王之傲就是您温暖的家─这是我们的格言!请坐在火边，让您疲惫的身体好好放松一下。$B$B您要不要尝一尝我们这儿最好的酒菜?', '你和旅店老板法雷谈过了吗，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2200, '回到奥达曼', '我的一个邪恶的竞争对手居然污蔑我，说是我制作的项链诅咒了那个圣骑士！显然没有人愿意买被诅咒的东西。$B$B不如我们来做笔交易吧：如果你能帮我找回宝石，我就能重新把它镶到项链上，然后只要你帮我宣传这条项链并没有受到诅咒，帮我恢复名誉的话，我就将把这条项链送给你！$B$B我建议你从奥达曼开始搜集线索，或许那个圣骑士的尸体就在下面，毕竟他是最后一个拥有它的人！当你找到宝石之后就使用这个东西，它可以让你随时和我进行联系。', '去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。', '通过阅读日记，你了解到圣骑士经过很大的努力最终找到了所有三块宝石的下落:$B$B暗炉矮人正在为奥达曼的控制权而与石腭怪展开激烈的战斗，所以他们把红宝石藏在了重兵设防的区域。$B$B石腭怪把黄宝石藏在了靠近联盟矮人区域的一个瓦罐中。$B$B最后的一块蓝宝石就在石腭怪的首领手中。', '经过一番搜寻之后，你在圣骑士的遗体上找到了一本日记。被鲜血浸透过的日记只有一部分的内容可以辨识，但你还是可以看出里面大概写了些什么。看来那些宝石就遗落在圣骑士的遗体附近。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2218, '救赎之路', '又一个迷失的灵魂，是来寻找指引的么？我想你一定希望能找到目标——属于你自己的目标。像你这样的$r我已经见过不下一千个了，又是一个找活干的英雄！$B$B今天你运气不错，朋友，霍格拉尔可以帮你。$B$B按照我说的去做吧：沿着这条路到铁炉堡，找到被遗弃的洞穴里的盗贼公会，和霍夫丹·黑须谈谈，他会指引你一条救赎之路的。', '和铁炉堡的霍夫丹·黑须谈一谈。', '那么，你认为自己是个恶棍啦?你认为自己是我们需要的那种人?─你看，给你一个隐秘议会的官员当当如何?$B$B只有一无是处的饭桶才会高估$g他:她;\n自己。$B$B你就是我们需要的$r!欢迎上我们的贼船，$N!', '我们只跟狡诈且不可靠的人服务，$C。你有什么事吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2238, '国王的财宝', '你知道，国王抢走了采集矿石宝物的机会，那些财富……矮人活十辈子也挣不到。$B$B我们在铁炉堡那里有些关系，$N，很有价值的关系，你懂吧？$B$B国王应该把他的财宝拿出来和我们分享，不过我们不想让那老家伙知道他正在和我们分享——你懂我的意思吧。$B$B你到诺莫瑞根附近去和奥宁·雨锤谈一谈，然后回来跟我报告。那个狡猾的矮人混迹在一群麻疯侏儒当中，你要小心点。', '在诺莫瑞根附近找到奥宁·雨锤。', '嘘!声音轻点，你这个笨蛋!他们会听见的。', '有话快说。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2259, '艾瑞安·影语', '别担心，$N，我不是要把你送去见塞尤娜。艾瑞安正在塞纳里奥区等你，快点吧！', '与达那苏斯的艾瑞安·影语取得联系。', '是时候让你出去闯荡闯荡了，$N，一个神秘的未知世界在等着你。', '你好，$N。我一直在期待着你的到来。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2260, '艾瑞安的命令', '你已经是个很有名气的$c了，$N。事实上，暴风城的情报机构点名要你去为他们效力。$B$B这次旅行会很辛劳，而且一路上危机四伏，不过我想谁也不会轻易放弃在暴风城军情七处训练的机会。$B$B一个崭新的世界在等着你，$N。到暴风城的旧城区去,和军情七处总部里的“剃刀”雷吉克谈一谈吧，祝你好运。', '到暴风城的议会去找到“剃刀”雷吉克。', '你响应了军情七处的召唤，从遥远的国度赶来加入到我们的队伍中，不过你要学的东西还很多。', '你好，$C。我是『剃刃』雷吉克，暴风城军情七处的主管。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2281, '赤脊山的联络员', '现在就把你派出去等于让你去自杀，雷吉克可不想再让哪个初出茅庐的潜行者平白挂掉。不过你也别着急，$N。雷吉克要先培养你的能力。$B$B现在你就动身去赤脊山，和一个名叫卢修斯的军情七处联络员谈一谈吧。他就在湖畔镇的码头附近，和其他一些游手好闲的家伙整天搅在一起。', '到赤脊山的湖畔镇去和卢修斯谈一谈。', '啊，你的手指有点粗，是吧?别担心，$N，我把很多比你更没用的小偷都变成了成功的盗贼。', '你要干嘛，$C?我可没时间跟你搅和。$B$B什么?「剃刃」派你来的?真是抱歉，卢修斯当然会帮你!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2284, '搜寻项链，再来一次', '玛尔顿这个笨蛋，我确信宝石还在奥达曼的某个地方，你必须回去找到它们。$B$B就像我之前所说的那样，如果我们掌握的情报是正确的话，那么这条项链上原本应该有红宝石、黄宝石和蓝宝石各一块。找到它们，并且把它们放回到项链上。$B$B至于那些宝石的具体位置就没有人知道了。如果你运气不错的话，也许你能找到那个笨蛋圣骑士的尸体。如果他还没有被剥光的话，没准你还能在他身上找到那些宝石。', '在奥达曼里找寻宝石的线索。', '在搜查尸体的过程中，你找到了他的日记。这本书已经变得破破烂烂了，干涸的血迹使得整本日记变得难以辨识。能够看清的部分的文字也让你难以理解，显然这是用人类的语言撰写的一本日记。$B$B你得找个人来帮你翻译其中的内容才能决定下一步该干什么。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2298, '国王的搜查', '然后我们就到了那里，准备执行第三阶段的计划。突然，一伙麦格尼手下的家伙闯了进来，他们自称是来搜查的，二话不说就要抓人。$B$B但是没人敢在我霍夫丹·黑须面前动粗！于是双方唇枪舌剑地开始吵，结果你的名字就被不知道哪个白痴吼了出来！$B$B我的意见？赶紧骑上狮鹫离开铁炉堡，到暴风城去。到旧城区里去找我的一个老朋友，他的名字叫“剃刀”雷吉克。', '到暴风城里去找到“剃刀”雷吉克。', '让一个霍夫丹的盗贼加入我们的行列，嗯，不错!', '$N，麦格尼国王是无法在暴风城里呼风唤雨的。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2299, '去找霍夫丹！', '你去哪儿啦，$N？霍夫丹到处找你。我们都以为国王把你抓起来了。$B$B快去铁炉堡找霍夫丹！', '到铁炉堡去和霍夫丹·黑须谈一谈。', '小点声，$N，守卫会听到的。', '以我自己的胡子的名义，你居然还活着!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2300, '军情七处', '雷吉克在找你呢，新手。$B$B如果我是你的话，就不会让马迪亚斯的副手干等着。', '到暴风城去找到“剃刀”雷吉克。', '你是准备好开始工作了呢，还是想在我们开始前先打个盹儿?', '你去哪儿了，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2318, '翻译日记', '显然你看不懂日记上的字，得找个人来帮忙翻译才行。这个世界上有不少可以胜任这项工作的人，最近的一个应该在荒芜之地的卡加斯哨所里。也许你应该去那里找找。', '在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。', '强大的$C，我知道你在这里干什么，我也知道你需要靠我的帮助来翻译东西，你在为奥达曼的那根项鍊的事情忙碌。$B$B很惊讶吗?哈哈，我的工作就是收集这些情报。那么，让我们来讨论一下你准备用那本日记干些什么吧。相信我─只有我可以帮你翻译它。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2341, '项链任务的终结', '在德兰和玛尔顿为了他们的战利品而争执不休的同时，你的任务也算完成一半了。现在你得去荒芜之地完结这个任务，卡加斯营地里的加卡尔应该已经为你准备好了特别的奖励。', '去卡加斯看看加卡尔是否成功了。', '你给我的能量源真是太棒了。我可以给你和我都制作一条项鍊，而且我至少还可以制作三条项鍊。把它们卖给杜佛斯家的那几个笨蛋的话，一定能大赚一笔。$B$B拿着这个，我的朋友。我对你的工作表示衷心的感谢……另外我这里还有些特别的东西来表示谢意。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2360, '马迪亚斯和迪菲亚盗贼', '$N，不久之前，军情7处接到西部荒野出现大量迪菲亚兄弟会成员的报告。$B$B现在他们已经占据了位于哨兵岭东南部的一座荒废的哨塔，并将其作为从赤脊山走私补给物资的中转站。$B$B到西部荒野去和密探吉尔妮会面，你应该可以在哨塔的附近找到她。$B$B另外……$n，一旦你的行动被发现，军情7处将会否认与你有任何联系。', '去西部荒野和密探吉尔妮谈一谈。', '马迪亚斯终于派人来帮我了?好吧，我这里的确是有些坏消息。', '快点表明你的身份，$C。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2361, '修复项链', '', '', '我很高兴能给你这条项鍊，强大的$C。你对我的帮助是无价的，我为此对你表示万分的感谢。请把它戴上吧，这是属于你的荣耀，请在别人问及的时候告诉他们，是我制作了这条项鍊!$B$B另外，如果你证明这条项鍊根本没有受到诅咒，那就更棒了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2378, '寻找碎手氏族', '$N，你一向以来都对我们衷心耿耿，现在是让你出去闯一闯的时候了。虽然你已经展现出了在潜行者之路上过人一等的天赋，但是你还是需要更多的练习才能达到更高的境界。$B$B我们和碎手氏族是盟友。去找他们吧，一直以来我们的关系都很好——去奥格瑞玛找申苏尔。', '前往奥格瑞玛，和暗影裂口那的申苏尔谈一谈。', '这么说来，我们那强大的盟友派到我这里来的就是你?太令人失望了……', '啊，一股腐臭的气味。米奈特派你来的?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2379, '赞杜沙', '单凭你的决心是无法帮助我们克服困境的。$B$B去和赞杜沙谈谈，然后你就可以作为碎手氏族的一员接受训练了。$B$B只有掌握了潜行和搜索的技术，你才能继续沿着你的命运之路前进。', '与暗影裂口的赞杜沙谈一谈。', '也许是赞杜沙错了，赞杜沙道歉。', '赞杜沙帮不了你，$r。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2380, '向奥格瑞玛进发！', '你还不是个秘密行动和欺诈的高手，不过迟早会是的。曾经训练过你的导师们都对你的潜力印象深刻，于是伟大的申苏尔点名要召见你。$B$B沿着路向北走，一直到奥格瑞玛去，在暗影裂口和申苏尔谈一谈。', '在奥格瑞玛城中的暗影裂口和申苏尔谈谈。', '索尔想要改变部落的传统，我们破碎之手氏族必须对此保持警觉，这一点很重要。从人数上来说，我们很难和索尔的势力相抗衡，所以我们必须精于隐秘行动和欺诈。', '很好，你收到了我的资讯。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2382, '棘齿城的维尼克斯', '赞杜沙确实看到了！是的，我看到了那一天的到来！萨尔死了……匕首刺在他的背上，毒液渗透到他的血管之中……赞杜沙说得太多了。$B$B$N！赞杜沙有个任务要交给你！你必须马上到十字路口东边的棘齿城去，跟卑鄙的维尼克斯谈谈。', '到贫瘠之地的棘齿城去，与卑鄙的维尼克斯谈一谈。', '又来一个?那个疯狂的食人妖派来的前五个倒楣鬼都已经塞了鲨鱼的牙缝。我希望你的结局不会那么惨。', '你好!维尼克斯喜欢像早餐吃了许多魔法蘑菇的食人妖那样说话。那么维尼克斯，呃，我能帮你做些什么吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2398, '失踪的矮人', '奥达曼挖掘场从前并不是现在这样一团糟的。我们铁炉堡的矮人曾经控制了这个区域，但是……当穴居怪来了之后，一切都变了。它们的数量太多了，连我们矮人也挡不住它们！$B$B事实上，因为它们非常突然地发起了攻击，所以我担心我们有些人被困在了挖掘场里面。$B$B我的朋友巴尔洛戈带了一个矮人小队进入了挖掘场深处，就在穴居怪发起攻击之前。如果他和他的同伴们还活着的话，我希望你能找到他们。', '在奥达曼找到巴尔洛戈。', '你终于现身了!我差点输给了奥拉夫!$B$B他跟我打赌说，在他看到一个活的$r之前，他的胡子可以长到足以盖过他的膝盖那么长。现在你来了，而奥拉夫的胡子离他的膝盖还有几寸的距离哪。$B$B谢谢你，$N。我会把我赢来的钱分给你一些的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2399, '发芽的树叶', '', '', '德纳兰植入土中的树叶开始迅速生根并成长，它们振颤着，仿佛急于被采摘一样……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2458, '卧底密探', '风险投资公司……也许你听说过他们？$B$B一年以来，我们一直都想在他们的高层中安插一名密探，经过艰苦的努力和仔细的谋划，我们终于成功了。$B$B最近密探给我们带来情报说风险投资公司有个大规模的计划，所以我派你到淤泥沼泽的北部去，在风险投资公司的塔楼附近联系我们的卧底密探费苏勒。$B$B找到塔楼之后，用这个信号枪和费苏勒联系，然后用碎手军礼向他致敬。', '到淤泥沼泽北边的风险投资公司塔楼去，联系碎手氏族的卧底费苏勒。$B$B看到塔楼之后，用信号枪发射信号，向工头费苏勒示意你已经到达。发出两个闪光信号，然后使用碎手军礼和工头费苏勒接头。$B$B注意，这些步骤必须依次进行，因为费苏勒会攻击并干掉任何他无法识别的人。', '在这儿看到破碎之手氏族同僚的感觉真不错，不过你发的信号似乎多了点!$B$B下次如果你还要找我的话，只要拿这只哨子吹两声就可以了。', '你好!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2460, '碎手军礼', '作为碎手氏族的潜行者，你必须学会碎手军礼。这是识别氏族成员的唯一方法。$B$B看好了，然后重复做一遍。', '对着申苏尔练习碎手军礼。', '很好，$N。你现在可以进入下一步了。', '练习!', '碎手军礼', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2480, '希诺特的帮助', '我从来没有见过哪种毒药能产生这么惊人的效果！你是说赞吉尔？从没听过这个家伙，不过既然他能制造出这种毒药来，那他还是值得我刮目相看的。$B$B那么你是要我帮你解毒，然后教你如何使用这种毒药？$B$B给我点时间研究一下毒药，$N。', '等待瑟尔格·希诺特完成解药。', '解药准备好了!喝下这个解药就能解除你的痛苦，不过对于你身上那股味道，我就无能为力了。', '不要催我!', '解药完成', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2498, '向德纳兰回报', '我刚接到消息，奥拉密斯湖畔的德纳兰可能已经发现了让林精长出那些毒瘤的原因。你去和他谈谈吧，告诉他是我派你去的。$B$B动作快点，$N，他需要我们的帮助。', '雷利亚·绿树要你和奥拉密斯湖的德纳兰谈一谈。', '哦，是雷利亚派你来的，我很高兴你这么快就来了。$B$B我这里有些令人不安的发现!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2519, '月神殿', '森林里有一个曾经强大无比的生物现在急需帮助，$c。$B$B现在你有一项艰难的任务必须完成。$B$B请你去找女祭司艾茉拉，她会向你解释具体的问题。她就在这里东南方的月神殿里。', '艾奎恩妮让你和月神殿的女祭司艾茉拉谈一谈。', '是艾奎恩妮修女让你来的?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2607, '赞吉尔之触', '看样子你带来的消息比我想象的还要多。这的确是一个奇怪的转折点，$N。$B$B解药？嗯……到地窖里去跟道克·米希匹克斯谈谈吧——他也许能提供点帮助。', '到兵营的地窖里去和道克·米希匹克斯谈一谈。', '很好!把乳酪放在桌上就赶紧走吧。奥斯伯会在你出去时付钱给你的。', '你不该看这个……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2621, '悔恨的战士', '遗憾，我现在只有遗憾。一个错误的决定造成了这么可怕的结果。我真应该留在那儿等候命令。也许它可以告诉我们，在那个该死的地方有什么可怕的事情在等着我们！也许它是要将我们调到别的地方去？归根结底还是我的错，都是我的错。$B$B所以我现在就站在这儿，等候命令。我必须了解情况，必须拿到那些命令。$B$B传令官鲁尔格驻扎在斯通纳德，去找他，查明那封命令现在到底在哪里。', '与悲伤沼泽中斯通纳德的分队指挥官鲁尔格谈一谈。', '索尔近卫军……我还清清楚楚地记得那可怕的一幕。$B$B<指挥官卢尔格摇了摇头。>$B$B这个军团经历了可怕的遭遇。部落也因此失去了最好的一批士兵。', '我能帮你吗，老百姓?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2622, '丢失的命令', '命令？你怎么能向我要酋长的那封命令？$B$B你是什么意思，$N？我当然派人把命令送了出去！我派去送信的士兵被鱼人伏击，损失惨重，只有本戈尔活下来——如果那还算活着的话。他现在几乎不能说话，更不要说走路了，他只能靠管子喂食，奄奄一息。如果你想知道那封命令出了什么事，就去和他谈谈，他肯定就在附近什么地方……还有，这里到处都是危险的生物，你一定要小心一点。', '与悲伤沼泽中斯通纳德的本戈尔谈一谈。', '沼……沼泽……空谈者……', '<本戈尔痛苦地呻吟着>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2662, '诺格弗格药剂', '现在，把这些粉末和露水混合在一起。$B$B等会儿再回来找我……那时我应该已经完成效力惊人的诺格弗格药剂了！', '马林·诺格弗格让你在他制成药剂之后再去找他。', '喝下这个!效果绝对一流!!$B$B我就知道我有这方面的天份……哦，我要再次对你表示感谢，感谢你给我的帮助，不过请往边上站一点好吗?你妨碍我做生意了!我要靠效力惊人的诺格弗格药剂挣几百万，几百万!等我有钱了……$B$B什么?斯普琳科说我欠她一个人情?哦，这个斯普琳科，真会开玩笑!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2701, '古代英雄', '请把这些古老的遗物拿走吧，我们不再需要这些东西了。$B$B希望在你和燃烧军团的战斗中，它们能对你有所帮助。', '打开箱子，取走你的酬劳。', '突如其来的火花和光芒让你暂时失明。', '你打开了箱子。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2702, '古代英雄', '你用你高尚的行动和英勇的表现为我赢得了荣誉，$N。$B$B你也为他们赢得了荣誉……', '和桑德·裂蹄谈一谈。', '你的确为我们大家赢得了荣誉。我真是不知道该如何谢你。', '你好，$r。很高兴再次见到你。石头外面的风景真是好多了。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2721, '基利斯', '你已完成了一次冒险，现在又有新的冒险在等着你，$N。$B$B我有个手下至今下落不明，他应该在诅咒之地的某个地方，我说的就是基利斯中尉。$B$B我告诉过你，我和他当时被奥利斯塔囚禁起来严刑拷打，可怜的基利斯……他的意志力变得越来越薄弱。在我的牢房里都能听到他受刑的声音，他的惨叫在山洞里回荡。那是我最后一次听见基利斯的声音。', '找到基利斯的下落。', '特雷博?特雷博让你来的?', '老朋友……你一定带来他的消息了吧，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2743, '黑暗笼罩', '我们都别拐弯抹角了，$c，我的时间有限。$B$B你必须摧毁保护恶魔之王拉瑟莱克的三大魔头的势力。这个任务可不像解救一个被诅咒的灵魂那样简单。$B$B<基利斯咧开嘴大笑着>。$B$B你要知道，拉瑟莱克的三个手下各自戴着一件由拉瑟莱克特制的护符的三分之一。有了这个护符，你才能召唤那个恶魔。$B$B回去见特雷博，告诉他需要什么东西才能召唤拉瑟莱克，他会给你进一步的指示。', '回去见部落英雄的灵魂，将你的发现告诉他。', '$N，这个恶魔领主表现出的狡诈与他的残暴一样令我震惊。', '你从诅咒之地给我带回了什么消息?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2745, '潜入城堡', '嗯，真是个有趣的故事，而且我们还要认真对待它。好吧，我可以帮你，但如果你想成功的话，就必须采用某种……正义而非法的手段。$B$B我们要赶快解决莱斯科瓦和马尔松，你认为你能胜任吗？$B$B你必须下定决心，到城堡里去找我的一个老朋友，一个名叫泰里恩的侏儒。几星期来他一直在监视着莱斯科瓦，他可以帮你解决这件事。', '与暴风城堡的泰里恩谈一谈。', '你是谁?!别那样偷偷摸摸地走到我后面来!小声点!你到底在干啥?没看见我很忙吗，你这个蠢货?$B$B你说什么?我在干啥?我在等下一个黑暗之门被打开，你以为我在干啥?在卫兵发现我们两个一起藏在灌木丛中之前赶紧走开……我要维护我的声誉。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2755, '沃姆什的喜悦', '奥罗克没哭，$N，眼睛进了灰。$B$B<奥罗克偷偷地抹去一滴眼泪>$B$B还有一个沃姆什家族的秘密，奥罗克可以告诉你。多谢$N，奥罗克现在死而无憾了。$B$B学习沃姆什家族的喜悦之舞，然后你就掌握了锻造钢铁手套的技术！', '观察并学习沃姆什的喜悦之舞。', '<奥罗克喘着气说。>', '抡起铁锤吧!', '学会奥罗克的喜悦之舞', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2764, '加尔文的得意门生', '如果你准备要结束在加尔文这里的训练课程，就应该到加基森去。$B$B在那儿有我最得意的学生：特伦顿·轻锤。他可以教你很多有关精制秘银装备的知识，当然你也可以留在这里继续学习！$B$B哦，对了，加基森在塔纳利斯沙漠里！', '和塔纳利斯的加基森的特伦顿·轻锤谈一谈。', '『长者』加尔文让你来的?$B$B<特伦顿向你鞠了一躬。>$B$B很荣幸见到大师的另一个学生!', '不要打扰我，我正在为全山谷的锻造勇士赛加紧训练呢。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2765, '锻造专家!', '你刚来的时候，我就知道你会成为我最出色的学生之一！你毫不犹豫地把这个有魔力的饰品交给了马克迦文，因此你才有了来见我的资格。你的全心奉献和坚定信念应该得到回报。$B$B你已经在锻造技艺方面取得了长足的进步，$N。拿上你的回报吧！', '到加尔文那里拿取报酬！', '你将得到一个比你放弃的饰品更棒的东西，好好利用它吧，$N。', '领取你的报酬!', '你是大赢家！', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2769, '铜栓兄弟', '你有没有遇见铜栓兄弟？他们在卡利姆多的闪光平原上与地精赛车，而且他们通常都会获得胜利，这并不奇怪——地精的赛车轮胎总是爆掉，他们几乎从来都没有完成过比赛！$B$B但即使是这样，铜栓兄弟也还是在寻找新的方法使他们的车速更快，维兹尔跟我说过，他的下一个实验需要一种很稀有的原料。$B$B或许他需要别人的帮助来获取这种原料，你去和他谈谈就知道了。', '和闪光平原的维兹尔·铜栓谈一谈。', '啊，你想帮我?太好了!$B$B我的实验需要一样东西，我正好需要一个你这样的$C来帮我得到它!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2783, '争论', '我们在和错误的敌人进行战斗，$N。$B$B这片土地上真正强大的力量正在不断增强，而我们却还在和兽人为了这片焦土进行无谓的争斗。$B$B我们难道要继续这种争斗，直到有一天让燃烧军团把我们都踏扁吗？这实在是一种愚蠢的行为。$B$B$N，抛开你的偏见，和部落英雄的灵魂谈谈吧，他知道诅咒之地真正的秘密。', '与诅咒之地和悲伤沼泽交界处的部落英雄的灵魂谈一谈。', '联盟想要帮助我们?$B$B我以为这一天永远也不会再次到来了，我以为联盟永远也不会再次与部落并肩作战了。$B$B终于……我们要联合起来!', '一个$R?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2842, '主工程师斯库提', '斯库提和我刚刚从克努比那里得到关于新型侏儒钻探设备的消息，就马上开始动手研制捷运器6000型了，它是去诺莫瑞根最快捷可靠的方法！$B$B现在它已经完成了，$N。如果你想试试的话，就到藏宝海湾去和空运处的斯库提谈谈吧。你可以从棘齿城乘船去藏宝海湾。$B$B当然，你也可以试试从满地都是矮人的丹莫罗山脉走到诺莫瑞根去！', '和藏宝海湾的斯库提谈一谈。', '她很漂亮，不是吗?哥布林运输技术的巅峰─只爆炸过十几次而已。$B$B别担心，$N，我把一切都安排妥当了，她绝对不会爆炸的─即使真的爆炸了，也只是一瞬间的事情，而且我保证你根本不会有痛的感觉。', '我在她身上倾注了毕生的心血，但在运输结束之前，我们的德莱尼水晶没有了。这真是奇耻大辱。谁知道呢，或许做只小鸡生活会更好?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2844, '大保姆', '都是我不好，$N。我本应细心照顾我的小朋友，沙恩。但是不知道为什么，她离开了我。我并不十分清楚发生了什么事，真的，但我最后一次看到她的时候，我们正在穿越这里北面的废墟。$B$B一切都很正常，但我转过身一看……她就不见了。$B$B现在我不知道该怎么办了。你有办法吗，$N？我很担心。$B$B嘿，你帮我去找沙恩怎么样？你看上去应该比我跑得快一些。', '寻找走丢了的精灵小姑娘。', '哦，终于有人找到我了!嗯，我是有点迷路了……但是难道这里不是个非常美丽的地方吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2861, '塔贝萨的任务', '据说有个名叫塔贝萨的法师想要某个祖尔法拉克巨魔的命。如果你去找塔贝萨的话，她会让你知道详情的。$B$B别忘了带上几个伙伴，$n。如果塔贝萨真的让你去祖尔法拉克的话，你最好不要独自前往。$B$B塔贝萨的小屋就在尘泥沼泽里，准确地说，是在塞拉摩的西边，石槌废墟的北边。', '与尘泥沼泽的塔贝萨谈一谈。', '没错，我确实想要一个食人妖去死。我要他身上的骨头，所有的骨头!$B$B你想要帮助我吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2864, '特兰雷克', '我的兄弟特兰雷克现在显然处于困境中。几个星期之前他曾经向我承诺会给我一批圣甲虫的壳，但是至今为止我还没有收到。他是我的兄弟，所以我可不想派人去加基森砸他的场子。$B$B你能帮我去问问特兰雷克到底是怎么回事吗？在我真的发飙之前他最好快点把货给我送来。$B$B加基森就在卡利姆多大陆上的塔纳利斯沙漠北部。', '与加基森的特兰雷克谈一谈。', '你好!$B$B哦，是我兄弟克拉兹克派你来的?他最近怎么样了?我希望他在藏宝海湾过得还好……$B$B你是说圣甲虫壳?好吧……让我告诉你一个故事……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2866, '索兰萨尔废墟', '在我们的南边就是索兰萨尔废墟，那个地区的历史相当悠久。我们探索过那个遗迹，没有发现什么特别值得注意的东西，所以我们就离开了。$B$B最近，憎世纳迦占据了那片遗迹，而且他们的数量已经多到了让我们不得不警惕的程度。一开始我们认为那些纳迦是准备对我们发起攻击，虽然这种可能性现在依然存在，但我们觉得他们可能是有什么别的目的。$B$B现在就到那片废墟去查看一番吧，祝你好运，$n。', '探索索兰萨尔废墟，并调查纳迦在那个地区的情况。', '在仔细察看了这座了望台后，你发现它和周围的其他东西比起来显得非常有趣，而且有些异乎寻常。$B$B首先，相对于这里的其他建筑物来说，这座了望台显然是近期刚刚建造的。其次，了望台上有一些小的雕纹，这些雕纹按照某种方式排列着，但是你看不出它们要表达什么意思。最后，构造了望台的石头触摸上去居然让你感到一丝温暖。$B$B显然，这些特征让这座了望台变得格外特别了!', '当你进入废墟的中心地带后，你注意到这个了望台显得格外突出……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2867, '返回羽月要塞', '在索兰萨尔废墟的心脏地带发现了奇怪的瞭望台之后，你觉得应该马上回到羽月要塞去向珊蒂斯·羽月汇报这个发现。', '向羽月要塞的珊蒂斯·羽月汇报你的发现。', '欢迎回来，$N。你关于了望台的报告真的让我感到非常……不安。即使那座了望台并不表明纳迦准备对我们发起攻击，但是他们的存在对我们向菲拉斯的推进总是一种阻碍。不管怎么样，这些是你应得的补偿。$B$B看来羽月要塞急需增援了。如果你愿意的话，我希望由你去完成这个任务。我们有很多事情要做。', '欢迎回来，$N。你对索兰萨尔废墟的调查有什么结果了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2872, '斯杜雷的债务', '我的老朋友欠我一瓶特殊的朗姆酒。他在塔纳利斯沙漠的热砂港里经营着一家酒吧，他向我保证说，那里的朗姆酒绝对比藏宝海湾的任何酒都要香醇，还说如果我喝了他的酒不满意的话，那他就会双倍奉还他欠我的钱！$B$B好吧，我想他现在已经不像他上次说这话的时候那么自信了，他害怕给我尝他的朗姆酒了。但是我还是想继续这个赌注，那么你就替我去和他谈谈吧……', '与热砂港的斯杜雷谈一谈。', '啊，你和麦克基雷谈过了?$B$B事实并不是他想像的那样!我当然不是不想给他尝尝热砂港朗姆酒……$B$B但是我现在一瓶朗姆酒都没有了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2902, '调查木爪岭', '豺狼人不是菲拉斯最具威胁的势力，但它们最近的活动毫无疑问是有些具体战略的。如果我们能找到它们的计划，那么我们就能知道究竟是什么让它们变得如此精明。$B$B我要你回到木爪岭去，寻找任何有可能是它们的战斗计划的东西。他们一定有些这样的东西，因为它们的攻击行动太协调了，没有一个像样的战斗计划是不可能进行的。找到那东西，然后再回到我这里来。', '在莫沙彻营地以南的豺狼人营地中寻找豺狼人的战斗计划。', '检查地图之后，你发现这正是哈杜肯.迅蹄想要的作战地图。地图上所画的无数箭头或许代表了军队行进的方向，不过几乎所有箭头都指向了南部，而不是莫沙彻营地所在的北部。$B$B地图的另一个部分是一幅图，上面的东西看起来像是某种大型昆虫，下面画了一些记号。这些记号也许是表示与那些未知生物作战所遭受的损失。', '在豺狼人营地里的一堆堆垃圾中有一张画得很潦草的地图……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2923, '工匠大师欧沃斯巴克', '工匠大师欧沃斯巴克正在为他发明的尖端机器人的命运感到沮丧。我记得尖端机器人对侏儒来说是一种很友好的辅助工具，但欧沃斯巴克告诉我，它出了故障。$B$B我很难过，不过如果运气不错的话，也许他还可以修好尖端机器人！$B$B去跟铁炉堡侏儒区的工匠大师欧沃斯巴克谈谈吧，看到有你这样的$c想要帮助他，他会很高兴的。', '与铁炉堡的工匠大师欧沃斯巴克谈一谈。', '对，确实如此。尖端机器人失灵了!你能帮帮我吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2925, '帮助科劳莫特', '我的侏儒朋友科劳莫特·钢尺从铁炉堡给我捎了个信过来，说是要我找人去完成一项很危险但也很重要的任务：潜入诺莫瑞根。现在这座壮观的侏儒城市里到处都是疯狂的侏儒和他们的机械装置。$B$B我必须呆在这里，但无法帮助我的朋友让我感到很心痛。如果你能替我去的话，我会很感谢你的。$B$B你可以在铁炉堡的侏儒区里找到科劳莫特。', '与铁炉堡的科劳莫特·钢尺谈一谈。', '对!我是要找些冒险者帮我去诺姆瑞根完成任务，你这个$C简直是再合适不过了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2927, '灾难之后', '你不会认为我生来就是是秃子吧？事实并不是这样的，$g先生:女士;\n！诺莫瑞根的放射性泄露导致了我悲剧性的脱发。在那之前，我有着整个艾泽拉斯世界独一无二的侏儒式飞机头！$B$B<诺恩一边说一边挥舞着拳头>$B$B那些该死的穴居怪——他们都该死！！$B$B或许现在还不晚，$N。我们也许仍然可以挽回局势——我说的是这座城市！去跟卡拉诺斯的奥齐·电环谈谈吧，他和他伙伴拉兹正在想办法。', '与丹莫罗中卡拉诺斯的奥齐·电环谈一谈。', '我想他在掉落了那一头秀发之后一定是万念俱灰了，但是他却活了下来!$B$B他被辐射栓击中的时候，我正站在他旁边。那一绺绺美丽的棕色头发就那样掉在了地上!一大绺一大绺地往下掉!当诺恩完全失去理智后，那场面就更恐怖了!对，完全失去理智!诺恩摸着他的秃头，满脸的难以置信和悲痛莫名，双眼中充满了复仇的火焰，$N!然后他就将愤怒全部发泄在了那些穴居怪身上!$B$B<奥齐显得有些害怕。>', '嘿，拉兹，看看这个穴居怪带来了什么!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2931, '卡斯派普的任务', '铁炉堡的大机械师卡斯派普正在征集冒险者！他正在组织一个冒险小队，要到诺莫瑞根去执行一项极度机密和重要的数据收集任务。$B$B卡斯派普也许不是炼金术、魔法和工程学协会的一员，不过他也算是个很聪明的侏儒，如果是他认为这是件很重要的事情，那么根据我的计算，这件事有百分之八十四的可能性是确实很重要的！$B$B这个可能性可不小！', '与铁炉堡的大机械师卡斯派普谈一谈。', '我正在组织去诺姆瑞根进行资料收集的团队。如果你是为此事而来这里的，那么就请听好了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2935, '请教加德林大师', '巢穴守卫的毒液没有你先前带来的毒液那么有威力，它肯定来自不同类型的蜘蛛。$B$B我要那种毒液的新鲜样本。如果要找到它的出处，那么你必须与一个很了解枯木巨魔的巨魔谈一谈——我说的是森金村的加德林大师。到杜隆塔尔去找加德林吧。如果运气好的话，他会知道枯木巨魔是在哪里找到这种毒液的。', '与森金村的加德林大师谈一谈。', '啊，你想要枯木食人妖的新鲜蜘蛛毒液，对吗?好吧，坐下……接下来我将要告诉你的东西可能会让你不太舒服……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2939, '寻找知识', '虽然遍布菲拉斯的废墟和遗迹可能很危险，但是它们讲述了许多曾经发生的事情……$B$B几天前我在南边的碎石堆里搜索的时候，发现了一个看起来像是根普通法杖的东西。但是，我总觉得事情并不是那么简单，安吉拉斯和我在这里钻研书籍已经很久了，不过我们没发现什么和它相关的信息。$B$B我在达纳苏斯有一个同事，她能告诉我这是什么东西，$N。你为什么不去跟她谈谈呢？也许她能帮助我们。', '与鲁瑟兰村的达蕾恩·轻风谈一谈。', '哦，特洛亚斯.月风派你来的?$B$B<小声嘀咕着>……他总是认为自己发现了很重要的东西，这种疯狂的想法使我厌烦……$B$B你看，$N，让我来向你解释一下关于特洛亚斯的事情吧。他总是认为自己会在这些废墟中有重要的发现。不过问题是，真正有价值的东西早在很久以前就被那里的巨魔和鹰身人藏起来了。$B$B欢迎你到处看看，但我不知道这里的书是否对你有用。', '我现在很忙，$C。我希望你不是来闲聊的。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2940, '菲拉斯的历史', '看起来这本书很久没有人打开过了。它的封面破旧而且书页发黄，但检查后你会发现这正是特洛亚斯要找的那本书。$B$B你把它捡了起来，但你却突然意识到，也许应该在借阅之前得到物主的允许。', '如果你想借达蕾恩·轻风的书，要先得到她的允许。', '那你想借《菲拉斯的历史》这本书?$B$B让我想想……$B$B我允许你借这本书，$N，但你先得为我做件事。', '你找到了什么吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2952, '超级清洁器5200型！', '', '', '超级清洁器5200型突然停止了运行，「叮」的一声响，机器的盖子打开了，里面放着一只扎着蝴蝶结的小盒子。似乎这机器在清除物体表面的污垢以后会把物体包装起来。即使机器没有清理过什么，至少这东西被装在了一个漂亮的盒子里。$B$B好吧，让我们来看看它有没有清洁你放进去的东西……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2963, '奥丹姆的线索', '你好，很高兴再一次见到你，$n！你在奥达曼的发现使探险者协会兴奋不已。协会一直都在努力揭开你所发现的那张白金圆盘的秘密。你来的正是时候，我可以和你分享一下我们的最新进展！$B$B史学家卡尼克发现了一些很重要的线索，可能有助于找到塔纳利斯沙漠中的守卫之谷的起源。他想和你谈谈，越快越好！', '与铁炉堡探险者大厅中的史学家卡尼克谈一谈。', '我很高兴你仍有探险的热情，$N!你有天生的才能和勇气，让我们有希望揭开那些从未揭开过的秘密!奥达曼的诺甘农圆盘中储存着大量资讯，而那些只是所有圆盘中的一小部分而已。据说造物之神在艾泽拉斯各地留下了更多的圆盘，这就是我们要去奥丹姆的原因……', '啊，你是$N，太好了!是这样的，你在奥达曼发现的小东西解决了我们在守卫之谷所碰到的一些窘境。那里有一处封印之地，我们知道它的名字是什么:奥丹姆。你拿来的那些圆盘……我们认为它们可以用来启动奥丹姆的某些东西，没有它们，那些东西就永远不会露出真面目来!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2964, '进一步的任务', '好吧，$n…我们现在好象走进了一个死胡同。我们知道我们需要的是什么——奥丹姆圆盘——但我们不知道这些东西在哪里。我们得进行大量的研究才能制定出确实可行的计划。关于到哪里去寻找圆盘……我有一些想法，我坚信我们马上就会要求你尽快出发去找到它。$B$B这件事要通知资深探险家，$n，毫无疑问，他也会再次感谢你对探险者协会的帮助。', '与铁炉堡的资深探险家麦格拉斯谈一谈。', '我们的意见是一致的─我们要把圆盘可能存在的范围缩小，然后再采取行动。是你让我们有了今天的成就，$N……我希望你能再次出手，替我们解开奥丹姆之谜!$B$B请拿着这个作为酬劳，请务必尽快回来和我们联系……奥丹姆在等待着我们!', '很好，很好，你正是我要找的$r……$N，探险者协会永远的朋友和盟友!卡尼克已经把事情大体上跟你说过了，对吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2965, '奥丹姆的线索', '啊，$n，你来得正好。你在奥达曼挖掘场的发现让我们的贤者进行了激烈的讨论。我和纳拉·蛮鬃也交换了看法，因为当初我和她一起经历过一段冒险旅程，这段经历对于我们将要采取的下一步行动非常重要。$B$B我想让你和她去谈一谈，听听她当年在塔纳利斯的守卫之谷中遇到的事情。她在长者高地等你。', '与雷霆崖长者高地的纳拉·蛮鬃谈一谈。', '在塔纳利斯沙漠中有一个守卫之谷。你找回的圆盘……其中雕纹的翻译提到了一个叫奥丹姆的地方，许多人都认为这个地方只有在神话中才存在过。$B$B我知道这是不对的，奥丹姆的确存在，因为我去过那里。好吧……我只是到了它的外面。$B$B$N，我认为关键在于:圆盘和奥丹姆之间具有某种联系，我们希望你能去那里进行调查。', '$N，我很高兴你能过来与我进行交流。贤者图希克跟我说过你在奥达曼的冒险历程，我相信我这里有些新的资讯要告诉你。你应该可以找到对我们都有利─并且我们都感兴趣的秘密。$B$B我要继续说下去吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2968, '进一步的任务', '好吧，$n…我们现在好象走进了一个死胡同。我们知道我们需要的是什么——奥丹姆圆盘——但我们不知道这些东西在哪里。我们得进行大量的研究才能制定出确实可行的计划。关于到哪里去寻找圆盘……我有一些想法，我坚信我们马上就会要求你尽快出发去找到它。$B$B这件事必须要通知圣者图希克，$n，毫无疑问，他也会再次感谢你对我们的帮助。', '与雷霆崖的圣者图希克谈一谈。', '我们的意见是一致的─我们要把圆盘可能存在的范围缩小，然后再采取行动。是你让我们有了今天的成就，$N……我希望你能再次出手，替我们解开奥丹姆之谜!$B$B请拿着这个作为酬劳，请务必尽快回来和我们联系……奥丹姆在等待着我们，年轻的$r。', '随着风吹过，变化的迹象开始散播。你是不是想要知道我对奥丹姆的看法呢?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2969, '精灵龙的自由', '可恶的恐怖图腾部族正在捕捉精灵龙，$N。耶尔卡和我不知道他们打算对这些精灵龙做什么，但那总不会是什么好事。$B$B我们还没有强悍到可以杀进营地去解救那些精灵龙，但也许有了你的帮助……如果你能找到一些得力的帮手的话，就从笼中释放那些精灵龙吧，另外你要保证它们都活着逃出去。我也会帮你的。耶尔卡会留在这里继续戒备。', '从恐怖图腾营地的围栏里释放被俘获的小精龙。至少6个小精龙和辛达尔·月纹必须活着。$B$B如果6分钟之内你还没能达成这个目标，辛达尔就会决定撤退，任务也会随即失败。', '感谢伊露恩，$N!你真是我们和精龙的福星。仅凭耶尔卡和我是绝不可能救出它们的 - 我们将永远记得你在恐怖图腾中的帮助。$B$B现在去和耶尔卡谈谈吧……我要开始准备我们的报复行动。精龙是被释放了，但这并不意味它们会一直保持自由。耶尔卡和我要以进攻夺取主动!', '我们不能让恐怖图腾氏族毁灭这些美丽的精灵龙!', '至少拯救6只小精龙', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2981, '菲拉斯的危机', '菲拉斯是一个有成就的$c证明自己能力的理想场所。有个名叫戈杜尼的食人魔部落是那里最主要的军事力量，而且他们的势力仍在不断增长。在这些食人魔威胁到我们在菲拉斯的地位以前，我们必须要阻止他们。$B$B我认识一个名叫洛卡·奥赫的战士，她住在菲拉斯的莫沙彻营地里，去找她谈谈吧，她会让你知道更多情况的。', '贝尔戈洛姆·石槌想让你去和莫沙彻营地的洛卡·奥赫谈一谈。', '那么，是贝尔戈洛姆派你来的。你来的正是时候，$C。$B$B让我说明一下现在的形势，然后你再决定是否要迎接挑战……不过如果贝尔戈洛姆推荐你的话，那么我相信你的勇气是无可置疑的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2983, '火焰的召唤', '你上次考验至今已经有一段时间了，$N。从那以来，你一直耐心地学习，但在是时候让你学习更大的力量了……是时候让你学习真正的力量。如果你准备好付出，火的元素就是你的了。$B$B在贫瘠之地找到卡纳尔·菲斯。他居住在十字路口北部的小房子里，小心，如果你到了被诅咒的暗夜精灵的领地，那你走得太远了。', '去贫瘠之地找到卡纳尔·菲斯。', '嗯，是希尔恩让你来找我的吧?$B$B他是值得信赖的朋友，也就是说，你已经准备好要建立下一个灵契了─火焰灵契。$B$B我已经看到了熊熊燃烧的火焰和欲望。你已经拥有了一些力量，现在你已经准备好掌握更多了。耐心点，$N。记住大地所教会你的那些。力量和毁灭随手可得，不过你必须首先知道什么时候应该收手。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2984, '火焰的召唤', '你已经很久没有接受试炼了，$N。到目前为止，你已经证明了自己有足够的耐心，现在是时候让你学习更多东西，是时候让你了解毁灭…和混乱了。只要你明白自己即将为此付出的代价，火焰的元素就会与你建立连接。$B$B到贫瘠之地去找卡纳尔·菲斯，他就住在十字路口北部的一间小房子里。路上小心点，走太远的话，你就会进入精灵的领地。', '去贫瘠之地找到卡纳尔·菲斯。', '嗯，是希尔恩让你来找我的吧?$B$B他是值得信赖的朋友，也就是说，你已经准备好要建立下一个灵契了─火焰灵契。$B$B我已经看到了熊熊燃烧的火焰和欲望。你已经拥有了一些力量，现在你已经准备好掌握更多了。耐心点，$N。记住大地所教会你的那些。力量和毁灭随手可得，不过你必须首先知道什么时候应该收手。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2985, '水之召唤', '看上去你已经准备接受下一个考验了，$N。你在学习中充分显示了你的耐心，是时候让你多学点东西了。是时候让你了解水的纯净了。$B$B去贫瘠之地找水之先知伊斯伦。她居住在怒水河东岸，沿着怒水河向荆棘城的南边走就行了。你可以在她的捕鱼屋里找到她。祝你好运，$N。', '找到贫瘠之地的水之先知伊斯伦。', '地平线吹来的风轻拂着你，脚下的大地是如此坚实，火焰温暖了你的灵魂，而现在我想让你体味水的纯洁。$B$B你已经达到了一定的境界，你的精神将赐予你走得更远的力量。不过，你先得迈出至关重要的第一步。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2986, '水之召唤', '从你上次接受测验到现在已经有很长的时间了，$N。迄今为止，你展示了足够的耐心，不过现在你应该学到更多的东西，应该去了解水的纯洁。$B$B去贫瘠之地找到水之先知伊斯伦，沿着怒水河的东岸向棘齿城的南方走，你可以在一间小渔屋里找到她。祝你好运，$N。', '找到贫瘠之地的水之先知伊斯伦。', '地平线吹来的风轻拂着你，脚下的大地是如此坚实，火焰温暖了你的灵魂，而现在我想让你体味水的纯洁。$B$B你已经达到了一定的境界，你的精神将赐予你走得更远的力量。不过，你先得迈出至关重要的第一步。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2992, '占卜', '在我进行占卜仪式的过程中，不要打断我。我会找出你拿来的那根羽毛和它主人之间的关系，然后顺藤摸瓜找到沙普比克。$B$B理论上讲是这样……如果一切都按照计划进行的话。如果不是，那么……你最好闭上眼睛。', '等待萨迪斯完成占卜仪式。', '仪式很成功。我看到了沙普比克，也可以告诉你如何找到它了。', '', '等待萨迪斯的仪式结束', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2993, '返回辛特兰', '沙普比克被关在巨魔城市辛萨罗的悬崖上的一只笼子里，笼子的钥匙由邪枝巨魔的邪恶祭司海克斯掌管着。$B$B我已经做了我该做的那部分事情，希望你执行任务的时候一切顺利，$N。', '与辛特兰的狮鹫管理员沙拉克·鹰斧谈一谈。', '你已经同格希德谈过了?他说什么?$B$B……什么?邪枝食人妖抓了沙普比克?太过分了!我们必须组织力量把它给抢回来!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2996, '寻找斯坦哈德', '我过去曾教过你一些知识和技艺，现在该让别人继续教你了。我说的是棘齿城的斯坦哈德，他是个人类，但不要以为他很弱小。虽然他看上去非常矮小，但是却有着超强的力量。他可以教你最强大的召唤法术——我觉得你已经准备好了，现在就到他那里去吧。他住在棘齿城……他的塔就在那座港口城市旁边的山上。', '与棘齿城的斯坦哈德·法尔杉谈一谈。', '棘齿城的又一个忙碌的一天，不是吗?我多么喜欢看见港口城市的喧嚣啊，充满神秘，充满冒险……也充满着无知。$B$B我在你眼里看见的是仇恨吗，$N?很好，我们会好好利用这种仇恨的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2997, '圣洁之书', '你好，$N。我知道你在忙着帮助艾泽拉斯的人民，但如果你有时间，你应该去铁炉堡，同我们最受尊敬的族人蒂萨·热炉谈一谈。当年轻的圣骑士需要学习更多关于圣光以及其它必要的知识时，他们就会去见她。$B$B你可以在秘法区的秘法大厅楼上找到她。', '与铁炉堡的蒂萨·热炉谈一谈。', '你回来得真快啊，在离开的这段时间中，你做了怎样的祷告?$B$B你有没有完成什么高尚的事业?也许你已经了解了慈善的真正价值，或者更多你对艾泽拉斯居民的责任。告诉我，你都帮了谁，怎么帮的……你的所做所为令人印象深刻，$N，你的行为毫无疑问证明你在坚定不移地追随圣光的指引。$B$B这样的牺牲一定会得到及时的奖赏。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2998, '圣洁之书', '你好，我的$G兄弟:姐妹;\n。我们这里最有影响力的圣骑士——达索瑞恩·拉尔最近谈起过你。我听他说过你应该去找他接受试炼了……我也从他那里听说过你的出色表现。$B$B如果我是你，而且我有时间的话，我就会去暴风城和他聊聊的。我很肯定他会待在光明大教堂里——他一般都待在那里。', '与暴风城的达索瑞恩·拉尔谈一谈。', '你好，我们又见面了，$N。你对圣洁之书的研究进展如何?$B$B那么你应该准备好接受考验了。我们的城市和国家到处都有等着我们去完成的任务，给予他人同情和理解;\n援助需要帮助的人;\n击杀凶恶的生物。$B$B只要证明你可以秉持耐心去帮助别人─特别是那些不幸的人，你就能证明自己是圣光的侍从，正直心灵的表率。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (2999, '圣洁之书', '你好，$N。我知道你在忙着帮助丹莫罗的人民，但如果你有时间的话，你应该去铁炉堡，到那里去跟我们最受尊敬的族人蒂萨·热炉谈一谈。当年轻的圣骑士需要学习更多关于圣光以及其它一些必要的知识时，他们就会去找她。', '和铁炉堡的蒂萨·热炉谈一谈。', '你好，$N。希望圣光为你指引真理之路，让你免受邪恶的威胁。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3000, '圣洁之书', '你好，$N。我知道你在忙着帮助艾泽拉斯的人民，但如果你有时间，你应该去铁炉堡，同我们最受尊敬的族人蒂萨·热炉谈一谈。当年轻的圣骑士需要学习更多关于圣光以及其它必要的知识时，他们就会去见她。$B$B你可以在秘法区的秘法大厅楼上找到她。', '与铁炉堡的蒂萨·热炉谈一谈。', '欢迎你回来，$N。我想，你应该已经读过这本书了吧?$B$B那幺你应该准备好接受考验了。我们的城市和国家到处都有等着我们完成的任务，给予他人同情和理解;\n援助需要帮助的人;\n击杀凶恶的野兽。$B$B只要你有帮助别人─特别是那些不幸的人─的耐心和热情，你就能证明自己是光明的代言人，正直心灵的表率。$B', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3001, '寻找斯坦哈德', '我过去曾教过你一些知识和技艺，现在该让别人继续教你了。我说的是棘齿城的斯坦哈德，他是个人类，但不要以为他很弱小，也不要以为他是你的敌人……至少现在不是。他很强大，所以理应受到尊重。他可以教你最强大的召唤法术，我觉得你已经准备好了，现在就到他那里去吧。他住在棘齿城……他的塔就在那座港口城市旁边的山上。', '在棘齿城找到斯坦哈德·法尔杉。', '棘齿城的又一个忙碌的一天，不是吗?我多么喜欢看见港口城市的喧嚣啊，充满神秘，充满冒险……也充满着无知。$B$B我在你眼里看见的是仇恨吗，$N?很好，我们会好好利用这种仇恨的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3129, '灵魂武器', '将灵魂精华注入武器是个非常艰难的过程。既然我现在具备了所有必需的材料，还有这些你弄到的灵魂精华，那么我现在可以开始了。请等一会儿，我马上就回来。', '巫医尤克里希望你在他准备武器的时候稍等一会儿。', '就像我许诺过的一样，你有选择的权利，$N。这些生物的灵魂精华已经被永远地封存在这些武器中。$B$B你可以借它们的力量为自己所用了，好好利用它吧。', '看看吧，这就是你的努力所创造出来的东西。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3130, '憎世纳迦之战', '现在，我要让你到我的助手拉托尼库斯那里去，他一直都在密切注意纳迦的动向。我会对这里的综合形势作出评价，然后才能够采取行动将他们赶出这里，但是一旦我们发起攻击，我们的要塞就必然处于部落的直接威胁下——或者更糟，因此这并不是最佳的方案。$B$B不管怎么样，拉托尼库斯正在等着你。你的表现一直很不错，$n，希望你能继续保持。$B$B你可以出发了。', '到羽月要塞的拉托尼库斯·月矛那里去报到。', '太好了，$N─我十分欣赏那些对自己信心满满的同事。$B$B羽月将军吩咐我直接负责对纳迦作战的事宜。我的计画分为两步:第一，在数量上削弱他们，第二，我们要了解废墟里部署了多少纳迦部队。有你的帮助，我们就可以在不调动要塞的主要防卫力量的情况下对付纳迦了。', '羽月将军派你来帮我对付纳迦军队，对吗?好吧，如果你愿意接受挑战，我这里有对付纳迦的很有效的方法……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3221, '与伦弗利尔会面', '你在这里帮助我们的亡灵哨兵的时候，药剂师伦弗利尔派人来找过你。他没有告诉我详情，但他想和你谈谈你交给他的那些狼的心脏。', '与瑟伯切尔的药剂师伦弗利尔谈一谈。', '啊，太好了。最近有一件与你给我的那些狼心有关的事情，我们最好注意一下。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3261, '乔恩·星眼', '你将结束跟随我进行修炼的日子，$N。为了进一步的深造，你必须到南边的陶拉祖营地去找乔恩·星眼，他会对你进行更深入的指导。', '与陶拉祖营地的乔恩·星眼谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3371, '矮人的正义', '我的心已被悲痛腐蚀，变成了一个空虚的黑洞，$N。杜里奥斯的逝去让我一时之间无法恢复。我必须让他的心愿得以实现——那个冷血的凶手必须得到正义的惩罚。$B$B回到灼热峡谷去，达成他最后的心愿——解放他的同伴。黑铁矮人强迫他们的奴隶在一处被称为熔渣之池的矿洞中工作，去那里寻找杜里奥斯的同伴吧。', '回到灼热峡谷，找到杜里奥斯的考古队员。', '别管我，快去帮别人吧。', '对我来说这已经太晚了，$r。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3380, '沉没的神庙', '世界上到处都是不肯安息的灵魂，$N。有些灵魂因为孤独而被腐化，继而和一个上古的邪恶力量联结了起来……$B$B我听说有一个地下的神庙，那里游荡着极其强大的力量。$B$B如果你想要对这个被称作失落的神庙的地方有更多了解的话，就去找一个名叫玛尔冯·瑞文斯克的地精吧。他曾经研究过许多古代遗迹，我最后一次听到他的消息时，他正从从棘齿城出发去塔纳利斯沙漠研究巨魔的遗迹。', '到塔纳利斯找到玛尔冯·瑞文斯克。', '嗯，沉没的神庙，我可是亲眼见过它的。也许你想要知道更多有关它的消息?$B$B你看起来就是那种爱冒险的类型 -- 我想，你也许会对我所知道的东西感兴趣……', '啊，你好，旅人。什么风把你吹来了?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3402, '黑市交易', '我要你把考维克被干掉的消息亲自带给加基森的维兹格里克，他知道考维克死亡的消息一定会很高兴的，我敢说他肯定会为此给你丰厚的奖励。', '和加基森的维兹格里克谈一谈。', '考维克被干掉了?真是让人兴奋的一天啊，$N!这些年来，这个恶棍一直都在从事暗黑拍卖会交易，欺压全世界老实交易的辛苦商人。$B$B你理应为这个成就获得一份奖励!一份丰厚的奖励!', '想要看看我的商品吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3421, '回程', '', '', '我现在会把你送回萨纳斯的营地里。$B$B不要理会他的坏脾气—除了主人之外，他对所有人都很粗鲁，迟早他要为此吃苦头的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3445, '沉没的神庙', '我听说有一个地方被埋在地底深处，它是被一个我闻所未闻的强大力量沉入地下的。$B$B如果你想要对这个沉没的神庙有更多了解，就去找一个名叫玛尔冯·瑞文斯克的地精吧。就像特洛亚斯和我一样，他也探索过许多人迹罕至的地区。听说他离开了在棘齿城的家，前往塔纳利斯研究巨魔遗址去了。$B$B祝你好运，我好久都没有他的消息了。', '到塔纳利斯找到玛尔冯·瑞文斯克。', '嗯，沉没的神庙，我可是亲眼见过它的。也许你想要知道更多有关它的消息?$B$B你看起来就是那种爱冒险的类型 -- 我想，你也许会对我所知道的东西感兴趣……', '啊，你好，旅人。什么风把你吹来了?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3447, '雕像群的秘密', '我的记忆有些模糊了，但是我会尽量把我能回忆起来的细节都告诉你。虽然沉没的神庙中的雕像群充满危险，但我相信它们正是找到一笔巨大财富的钥匙。$B$B你可以在主祭坛上激活一系列光芒。我认为如果你能搞清楚出这些光代表着什么，或许你就能解开那座大厅中隐藏着的秘密。$B$B但是我要警告你，$N。神庙中潜伏着可怕的恶魔。它们会忠心地守护那些有价值的东西……', '到沉没的神庙去，揭开雕像群中隐藏的秘密。', '在半黑的神庙中，这尊雕像的眼睛仍然闪闪发光。透过清彻的眼睛你可以看到后面有某种发光的东西，你转动眼球，伸手进去抓住雕像中的东西。$B$B阿塔莱的宝藏是你的了。', '哈卡塑像耸立在你的头上…', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3448, '委以重任', '最近我一直在负责调查艾萨拉地区，那片美丽的土地曾经是精灵的故乡，他们曾在此研习魔法。现在这儿变得非常危险，但是这并不能阻止我们搜寻每一寸土地来寻找我们的历史。$B$B我的同伴泰摩尔对这样的事情特别感兴趣，因此他愿意帮助我调查艾萨拉。$B$B在城里的秘法大厅右边有一间小房子是他的。', '跟铁炉堡的泰摩尔谈一谈。', '啊，卡尼克派你来的，是吗?我可是整天盼着他的消息呢。我在艾萨拉发现了很多有趣的事情……我知道夜精灵的寿命很长，长得几乎令人难以置信，但是我们忘了他们生命中那些更为不幸的事情。这不是批判，而是观察。$B$B很久以前，精灵建造了许多城市，城市中保存着许多关于魔法的知识。我以学者的身份开始调查，而结果却令我毛骨悚然。', '什么?什么?我能帮你什么忙吗，$C?心灵传送?神秘的知识?对贫瘠之地的部落发动突袭?我可是个多才多艺的强者，而且经验丰富。告诉我要怎么帮你吧。$B$B等一下，你在我的房间里干什么?!我可没邀请你进来!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3450, '简单的接收任务', '我想把这些拓片送到我的塔里去，但是你不必亲自跑一趟，我会把它们空运到艾萨拉。$B$B希格斯·熔火欠我的人情，而且他马上就会到那个地方去——因为他被派遣到海岸边去巡逻。在你离开之前，别忘了去跟他谈谈。他会给你一支闪光弹发射器用于发送信号。当你拿到拓片之后就到他指定的地点去给他发信号，这样他就能把拓片安全地送到我的塔里了。现在他应该在军事区的棚厂里。', '与铁炉堡的希格斯·熔火谈一谈。', '我能为你做什么吗，$N?我正忙着准备远行啊。我是来找我的那些坦克驾驶员的—我需要一些雪怪的鬃毛来装饰座舱，驾驶员们通常都有一些多余的存货。$B$B如果你不会太久，我可以给你一分钟的时间……有个驾驶员刚刚起飞前往钢架补给站去帮我找雪怪鬃毛了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3451, '信号发射器', '啊，泰摩尔派你来的，是吗？对，我可欠他的情呢。怎么？哦，那个小恶魔，我当然可以帮助他。你需要一枚闪光弹和一块合适的地方……就行了。$B$B在艾萨拉南部的半岛附近有一座小岛，我们可以在那儿着陆。你发射闪光弹，我就能看见信号，然后过去接收那个……他想要的随便什么东西了。', '与铁炉堡的希格斯·熔火谈一谈，从他那儿获得一支标准型闪光信号枪。', '这是我的标准型信号枪，你发射之后要耐心等待一会儿─这把枪用不了太多次，我可能要花点时间才能到你那里。发射信号之后，你只需要盯着海面就可以了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3454, '惩戒火炬', '现在，火炬必须与它的拥有者建立联结。拿起火炬，$N。', '拿起惩戒火炬。', '你用双手抓住火炬，一阵阵的憎恶和愤怒瞬间流过了你的身体。', '火炬在空中悬浮着。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3462, '侍卫玛特拉克', '跟我的特使——侍卫玛特拉克谈谈吧,他会进一步指导你使用惩戒火炬。', '与侍卫玛特拉克谈一谈。', '你做好战斗的准备了吗?', '你得原谅我的主人，他最近……有些异常。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3481, '打开箱子…', '箱子似乎上锁了。', '打开箱子。', '你打开了箱子。里面究竟放着多少东西?只有一种办法可以知道。', '打开箱子。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3483, '信号发射器', '', '', '啊，还要一枚闪光弹?没问题。$B$B别忘了，是艾萨拉的南部地区。那里有一座小岛被改造成了停机坪。只要仔细观察一下，你是绝对不会错过的。', '你还需要什么吗，$C?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3503, '见到主人', '', '', '这就足够了，我会好好利用它们的。你准备好了之后就到塔里去见我的主人吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3508, '破坏结界', '你是个有勇无谋的$r，$N。你这样的$r具有令人敬佩的品质——在希望渺茫的情况下盲目地进行战斗。我会协助你，即使你只能杀掉拉瑟莱克的一个小小的爪牙，我也会协助你。$B$B要破坏拉瑟莱克的结界要花些时间，还需要稀有的神器。$B$B你先别急，我必须首先进行一次启迪仪式，我收集的信息将有助于我们铸造威力强大的武器。', '等待洛拉姆斯完成启迪法术。', '我们……要找到他的名字。', '不要打扰我。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3509, '恶魔之名', '要除掉恶魔之王和他的爪牙，只有一个方法：铸造一件刻有他真名的强大武器。$B$B这件武器铸造完成之时，就是恶魔之王的死期。$B$B有一个名叫亚考罗克的低阶神祗居住在艾萨拉，你必须找到他，但是如果他发现了你，那么他的爪牙就会不顾一切地想要杀死你。$B$B毫无疑问，你不费点力是没法成功的。', '与艾萨拉的亚考罗克谈一谈。你应该在海边搜索亚考兰神殿。', '恶魔领主?$B$B<亚考罗克领主大笑了起来。>$B$B也许我可以告诉你，但是首先你得帮助我。', '我可不愿意被你这种小虫打扰，走开。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3512, '帮助伊兰尼库斯', '$N，第一步，我们将设法通过宝石与伊兰尼库斯交谈。现在他正处于半睡半死的不稳定状态，并受到噩梦的困扰。尽管你给我的精华已经被严重污染，但我们还是有机会跟他沟通的。$B$B到冬泉谷东部的冰川地带去寻找我们的盟友，灵语者阿姆布兰希。他可以与死者进行交谈——尽管伊兰尼库斯并没有真正死去，但阿姆布兰希依然会对我们有所帮助。', '到冬泉谷的东部地区去，与灵语者阿姆布兰希谈一谈。', '伊萨里奥斯派你来找我，这真是个明智的决定。伊兰尼库斯的状态并非你所理解的死亡，他将很快以他自己的语言给我们提供建议。但是，我不能直接帮助你……至少现在还不能。$B$B我可以教你与死者通话的方法，但是首先我需要一个人的帮助，这个人不会受到年老体衰的影响。我最有效的占卜装备早已被夺走，除非拿回它，否则我们就没法帮助伊兰尼库斯。', '我的拜访者可不多，这儿可算是世界之颠呢。你为什么来到这里，$C?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3519, '需要帮助的朋友', '啊啊啊……我在探索旁边那个蜘蛛洞的时候被一只名叫基塞伊斯的蜘蛛咬成了重伤。我知道自己中了剧毒，你必须帮帮我。$B$B请把我中毒的消息告诉迪兰妮亚·月光，她知道该怎么办。$B$B快一点……我的头很晕……', '与幽影谷的迪兰妮亚·月光谈一谈。', '天啊，我正在想为什么今天还没看到埃沃隆呢。我一直警告他得当心那些蜘蛛……', '你好，$N。你找到埃沃隆了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3525, '封印神像', '在入口附近有一尊令人毛骨悚然的石像，野猪人用它来烤熟食物。这些野兽……它们整日食用那些从贫瘠之地绑架来的生物。我可以封印这尊神像，使野猪人无法再次使用它，但是我需要你的帮助。我的计划是这样的，你保护我接近神像，之后我便开始进行仪式。在一段时间里，我几乎无法跟你沟通，更不用说保护自己了。当我在封印神像时，你必须保护我。如果野猪人击倒了我，那我们就都完了。$B$B你明白了吗？', '保护奔尼斯特拉兹来到剃刀高地的野猪人神像处。$B$B当他在进行仪式封印神像时保护他。', '贝尼斯塔兹匆忙离开，只留下一只燃烧的火盆。当你盯着火苗看时，你的脑海中浮现出了一只有着超大翅膀的红色巨龙。耳畔响起贝尼斯塔兹沙哑的声音。$B$B「你成为我所希望的英雄了。你摧毁了这些野兽的屠杀场。我对人类的信任度又重新建立起来了。收下这个吧，这是你作为英雄应得的奖赏。」', '', '在奔尼斯特拉兹进行封印神像的仪式时保护他', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3567, '登高', '', '', '你想要站在双塔山的最高处俯瞰世界吗?我可以送你到那儿去，$C。$B$B但是，你得自己想办法下来。我这是单程服务。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3570, '堕落之水', '', '', '我从没有想过这瓶药剂可以如此快的发挥效果。谢谢你，$N。我会马上开始研究这些剩下的样品。我敢说它们不久之后就可供希瓦娜斯女士王和被遗忘者使用了。', '啊，你看到她的脸了吗?你看到了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3626, '返回诅咒之地', '救赎的时刻就要来临了，$N。你必须拿着你的新武器回到诅咒之地，然后从部落英雄的灵魂那里接受你最后的任务。', '回到悲伤沼泽中断矛路口的部落英雄的灵魂那里。', '看来你经历了不少激烈的战斗，$N。你做好面对拉瑟莱克的准备了吗?', '你终于回来了!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3631, '召唤地狱战马', '嗯，我觉得你还没有准备好，但这件事情的决定权不在我手里。斯坦哈德和我持不同意见，这次是他作的决定。$B$B他要你去见他，越快越好。到贫瘠之地的棘齿城去，他就和他的那些侍僧一起待在塔里。$B$B不要再闲逛了，快点去。', '与贫瘠之地棘齿城的斯坦哈德·法尔杉谈一谈。', '那么说来，你又决定要回应我的召唤，很好。$B$B我的侍僧还在怀疑你会不会出现呢。我告诉他们这一点是毫无疑问的:当你想要获得更强大的力量时，你就会像飞蛾扑火一般急切地来我这里。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3681, '圣洁之书', '抱歉打扰你的旅途，$c，但是我认为你应该知道，最近从暴风城传来消息说，要召集世界各地的圣骑士回那里去进行训练。$B$B重要的时刻即将来临，你可以开始学习圣骑士的圣典了。$B$B去暴风城寻找达索瑞恩·拉尔。他通常在光明大教堂训练骑士。', '与暴风城的达索瑞恩·拉尔谈一谈。', '你好，我们又见面了，$N。你对圣洁之书的研究进展如何?$B$B那么你应该准备好接受考验了。我们的城市和国家到处都有等着我们去完成的任务，给予他人同情和理解;\n援助需要帮助的人;\n击杀凶恶的生物。$B$B只要证明你可以秉持耐心去帮助别人─特别是那些不幸的人，你就能证明自己是圣光的侍从，正直心灵的表率。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3721, '你自己的OOX', '', '', '你帮我找回了三个OOX导航机器人!这简直帮了我的大忙，所以我要送你一件特殊的礼物以表谢意。这是一个迷你版的OOX导航机器人，你一定已经很熟悉而且很喜欢它们了!$B$B我一般不会把这种高精度的装置送给别人，但是你确实帮了我不少忙。另外，这个机器人的战斗模组和导航逻辑模组都已经被遮罩掉了。$B$B除此之外，这是一个绝不缩水的OOX机器人!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3762, '协助大德鲁伊', '打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B雷霆崖的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是哈缪尔·符文图腾亲自负责这项研究。$B$B要是你感兴趣的话，请直接去雷霆崖的长者高地找他谈谈。', '与雷霆崖的大德鲁伊哈缪尔·符文图腾谈一谈。', '你好，$C。很高兴你愿意帮助我们进行研究。你要做的事情很多，如果是我告诉你这工作并不危险，也许会伤害到你的感情。希望你不会因此受惊……但是，从你的表情看来，你已经经历过不少危险了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3763, '协助大德鲁伊', '打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B达纳苏斯的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是伊范达尔·鹿盔亲自负责这项研究。$B$B要是你感兴趣的话，请直接去达纳苏斯的塞纳里奥区找他谈谈。', '与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。', '好吧，$C……你被告知是我独自负责这项研究，所以显然你尽快赶来了。$B$B现在既然你已经到了这儿，那么当我告诉你详细情况时，你可要集中精神听仔细了，我可没耐心再说一次。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3765, '遥远的旅途', '暴风城——一个繁忙的中枢城市！$b$b我从遥远的地方赶来寻求帮助。据说这座城市里满是勇敢的冒险者。$b$b我在达纳苏斯的兄弟戈沙拉需要帮助，他居住在海边的小镇奥伯丁。$b$b我们面前是一次漫长而壮丽的旅途，因此，我请求像你这样的经验丰富的$c给予帮助。', '到奥伯丁的戈沙拉·夜语那儿去。', '啊，是我的兄弟阿古斯让你来的?旅途劳顿，你一定很疲倦了。但是我有很重要的事情要跟你商量。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3784, '协助大德鲁伊', '打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B雷霆崖的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是哈缪尔·符文图腾亲自负责这项研究。$B$B要是你感兴趣的话，请直接去雷霆崖的长者高地找他谈谈。', '与雷霆崖的大德鲁伊哈缪尔·符文图腾谈一谈。', '你好，$C。很高兴你愿意帮助我们进行研究。你要做的事情很多，如果是我告诉你这工作并不危险，也许会伤害到你的感情。希望你不会因此受惊……但是，从你的表情看来，你已经经历过不少危险了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3787, '奎恩提斯的请求', '朋友，打扰一下……$B$B我的同伴想与你谈谈有关你同塞纳里奥议会联合进行的研究。他是一名德鲁伊，名叫奎恩提斯，居住在菲拉斯的羽月要塞。他想就晨光麦与你交换一些意见……而且他希望我们的谈话不为大德鲁伊所知。$B$B如果你感兴趣的话，就去跟他谈谈，当然，一旦你这么做了，所有的一切便不是秘密了。', '与羽月要塞的奎恩提斯谈一谈。', '疲惫的旅者，感谢你来到此地!请允许我自我介绍─我是奎恩提斯，一名德鲁伊，同时也是玛法里恩和塞纳里奥议会的身份低微的仆人。我和我的同伴(珊蒂斯.羽月将军和护国者─或许你听说过我们)想与你谈谈你为达纳苏斯的范达尔.鹿盔所做的事情。$B$B在进一步交谈之前，我想声明我们的谈话仅限于你我之间。如果你对此无异议的话，我们就可以开始了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3788, '奎恩提斯的请求', '朋友，打扰一下……$B$B我的同伴想与你谈谈有关你同塞纳里奥议会联合进行的研究。他是一名德鲁伊，名叫奎恩提斯，居住在菲拉斯的羽月要塞。他想就晨光麦与你交换一些意见……而且他希望我们的谈话不为大德鲁伊所知。$B$B如果你感兴趣的话，就去跟他谈谈，当然，一旦你这么做了，所有的一切便不是秘密了。', '与羽月要塞的奎恩提斯谈一谈。', '疲惫的旅者，感谢你来到此地!请允许我自我介绍─我是奎恩提斯，一名德鲁伊，同时也是玛法里恩和塞纳里奥议会的身份低微的仆人。我和我的同伴(珊蒂斯.羽月将军和护国者─或许你听说过我们)想与你谈谈你为达纳苏斯的范达尔.鹿盔所做的事情。$B$B在进一步交谈之前，我想声明我们的谈话仅限于你我之间。如果你对此无异议的话，我们就可以开始了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3789, '协助大德鲁伊', '打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B达纳苏斯的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是伊范达尔·鹿盔亲自负责这项研究。$B$B要是你感兴趣的话，请直接去达纳苏斯的塞纳里奥区找他谈谈。', '与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。', '好吧，$C……你被告知是我独自负责这项研究，所以显然你尽快赶来了。$B$B现在既然你已经到了这儿，那么当我告诉你详细情况时，你可要集中精神听仔细了，我可没耐心再说一次。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3790, '协助大德鲁伊', '打扰一下，$c，如果可能的话，我想占用你一点时间。$B$B达纳苏斯的塞纳里奥议会希望能找到像你这样经验丰富的冒险家来帮助他们进行一项重要的研究项目。虽然我不知道详细的情况，但是我可以告诉你，正是伊范达尔·鹿盔亲自负责这项研究。$B$B要是你感兴趣的话，请直接去达纳苏斯的塞纳里奥区找他谈谈。', '与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。', '好吧，$C……你被告知是我独自负责这项研究，所以显然你尽快赶来了。$B$B现在既然你已经到了这儿，那么当我告诉你详细情况时，你可要集中精神听仔细了，我可没耐心再说一次。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3801, '黑铁的遗产', '你好，$N。我是弗兰克罗恩·铸铁。没错，正是我创造了以石头为基础的建筑方法。在探索这个饱受战争创伤的世界的旅途中，你一定见过了不少由我设计建造的建筑物。$B$B你也许想要知道我为什么在这里，以及我想要你帮我做些什么——这些问题都很合理。$B$B我当然需要你的帮助。作为请求你帮助我的交换条件，我会给你一把钥匙，让你得以进入这座由我建造的……被诅咒的城市。', '如果你想要得到进入这座城市主城区的钥匙，就去和黑石山铸铁之墓的弗兰克罗恩·铸铁谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3821, '巨槌石', '沙妮被派去调查过去三个星期以来燃烧平原上的那些火腹食人魔所进行的一些奇怪仪式。$B$B高图斯告诉我说没有听到过任何关于那支部队的消息，所以他建议我最好不要再管这件事情，继续自己手头上的工作。你相信他居然这么说了吗？要知道沙妮是我的妻子啊！$B$B我不能离开我的哨所，$N，但是我必须要知道沙妮现在怎么样了。到燃烧平原去，找到她。', '到燃烧平原去找到沙妮·长齿。', '我可怜的萨特拉克。$B$B我们原本计画在这段旅程结束之后和我们的父母搬到辛特兰居住的，但是这一计画现在显然已经不可能实现了!', '离开这里，陌生的$r。不然你就会像我一样死去……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3844, '无人知晓的秘密', '一艘被毁坏的小艇搁浅在岸边。这里是个小池塘，为什么会有一艘小艇搁浅在这里就不得而知了，不过从树上的痕迹来看，这里的水位并不是一直不变的。$B$B也许在附近继续搜查一下的话有可能发现更多的线索……', '在池塘附近查找与搁浅的小艇有关的线索。', '在池底有一只被池水浸湿的袋子。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3903, '米莉·奥斯沃斯', '你是个值得信赖的$c，$N。可靠，而且不畏惧战斗，对吗？$B$B我有个朋友名叫米莉·奥斯沃斯，她遇到麻烦了。她就在修道院另一边的马厩旁，我想她可能需要你的帮助。', '与米莉·奥斯沃斯谈一谈。', '啊，维里副队长让你来找我?他是个勇敢而热心的人，但是职责所在，他不能离开北郡修道院，所以也没法帮我的忙……$B$B你能帮帮我吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3912, '墓地相见', '这瓶药剂可以让你和那些普通状态下无法看见的生物对话……$B$B把这瓶视灵药剂和林克的剑带到塔纳利斯去，在加基森镇外的墓地中喝下这瓶药剂。你也许会对它所产生的效果感到奇怪，但是不要为此担心。$B$B在你处于“另外”一种形态的时候，一直往北走到山的旁边，你要找的人就在那里的石壁缝里，他的名字叫加里杨。$B$B记住，只有你在那种形态下的时候，他才会和你对话。', '在加基森镇外的墓地中使用视灵药剂，然后按照多诺瓦的指示找到加里杨。', '已经很久没有人来找我说话了……', '你为什么而来?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3941, '侏儒的援助', '让我想想……让我想想……我来这里肯定是为了某个很重要的事情……$B$B我有个办法，$N。那边的那个洞穴里有个叫科琳的侏儒，我记得我刚到这里的时候她给我留下了很好的印象。也许在我思维混乱的时候曾向她提过一些关于我的东西。$B$B为什么你不去问问她呢？哦，不过你要小心——她对这个地区的那些水晶表现得特别疯狂，我不知道她究竟想干什么！', '到马绍尔营地那里的山洞中去找科琳。', '就站在那里别动……我正在实验一种新的水晶组合……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3942, '林克的记忆', '哦……林克？当然，他是个有趣的家伙，他刚到这里的时候总是对所有奇怪的事情喃喃自语。也许他的脑袋被什么东西敲过了。$B$B他说的一些话给我留下了较深的影响——他好像要做什么图腾，还说要去找一个叫什么艾瑞丹·蓝风的暗夜精灵……如果我没记错的话，她好像在费伍德森林。$B$B我不知道她是否能告诉你更多的东西，如果你想要知道什么的话，为什么你不去问问艾瑞丹自己呢？', '到费伍德森林去找艾瑞丹·蓝风。', '你好，$C。我能帮你什么忙吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (3981, '指挥官哥沙克', '可怜的加加尔……他甚至没有看到那支箭射过来。咔的一声！它就射中了他的眉心。他并不机灵，但是现在……$B$B<贾拉玛弗露出了痛苦的表情。>$B$B当我们拔出那支箭之后，我们注意到在箭杆上包着一张便笺。那上面草草地画着一个铁栏后面的兽人，下面还有指挥官哥沙克的签名。$B$B如果他还活着的话，你就要到黑石深渊去找到他。$B$B你说这是个陷阱？废话，你这蠢货！不然我要你去干什么！', '在黑石深渊里找到指挥官哥沙克。$B$B在那幅草图上画着的是一个铁栏后面的兽人，也许你应该到某个类似监狱的地方去找找看。', '我们没有多少时间。仔细听好了，$R。我要告诉你的事情可是高度机密，千万不要告诉别人!', '<他惊奇地睁大了双眼>$B$B你……你是谁??', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4002, '东部王国', '你带来了非常有价值的情报，$N。$B$B作为酋长，我的职责就是做一切对部落有益的事情，以确保我们的后代有一个光明的未来。$B$B一个结交新盟友的机会已经落在了我们的肩上。帮助矮人的举动可以极大地改善我们与东部王国的关系。这就是你绝对不能失败的原因！$B$B你准备好了吗？', '如果你准备好要接受萨尔所安排的任务，就去找他谈一谈。', '踏出这一步，你就再也无法回头了，$N。', '你接受任务吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4004, '拯救公主？', '你杀了我的丈夫！我的孩子诞生之后将会没有父亲。$B$B<茉艾拉公主直指着你。>$B$B我向你保证，这个孩子会成为铁炉堡的下一任统治者。你和你的同类将会因为今天的所做所为而付出代价。$B$B<你认为茉艾拉公主也许是受到了索瑞森的法术影响才变成这样。>$B$B让我独自留在这里，$r。你的酋长一定正在急切地想要知道他管闲事的结果。', '返回奥格瑞玛，向格罗玛什堡垒中的萨尔报告！', '<索尔对你带给他的讯息感到非常吃惊。>$B$B一个新的威胁正在酝酿当中。麦格尼日渐老迈，看来那个未出生的黑铁矮人真的要成为铁炉堡的统治者了。$B$B你完成了我给你的任务，你应该得到奖励。$B$B你现在可以走了，$N!我必须跟希瓦娜斯和凯恩交换一下意见。', '<索尔向你敬礼。>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4122, '格拉克·洛克鲁布', '我追踪他穿过灼热峡谷，穿过群山，进入燃烧平原。在那里，我亲眼看见那个叛徒——我说的是格拉克·洛克鲁布——把我们的详细行动计划交给了黑石兽人。$B$B他现在仍然在燃烧平原，在黑石兽人的保护之下高枕无忧——至少他自己是这么以为的。$B$B拿着这些镣铐，$N。找到格拉克，给他戴上镣铐，然后把他带出黑石山。成功之后，我必定会重赏你。', '到燃烧平原去找到格拉克·洛克鲁布。你回忆起雷克斯洛特曾经提起过，格拉克应该是在一座大型的黑石要塞中。$B$B当你找到格拉克·洛克鲁布之后，用瑟银镣铐把他铐起来，然后将其带回灼热峡谷。雷克斯洛特会让他的部下等在那里接应你。', '你难道看不出我们在加入黑石军团之后获得了多么强大的力量吗?', '你只是暂时获得了胜利，$r。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4124, '失踪的信使', '我的同事基恩诺·火花正在寻找信使的下落，以及他身上携带的包裹。那个信使已经失踪一个星期了，我们所有的搜寻行动都徒劳而返，因此现在我不得不宣布：信使已经失踪了。$B$B如果你有时间的话，请去跟基恩诺谈谈。他应该在要塞里——也许在他自己的房间里。', '和羽月要塞的基恩诺·火花谈一谈。', '我想应该是拉托尼库斯派你来的。当我们的搜寻行动毫无进展的时候，我愿意接受任何人提供的帮助。我必须承认……如果我能平息这件事情的话，我会很高兴的。每天我都会到菲拉斯的丛林里去寻找拉斯卡尔，但每次我都会带着遗憾和豺狼人的齿痕无功而返。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4125, '失踪的信使', '拉斯卡尔这个信使出发去萨兰纳尔已经快一个星期了。他对菲拉斯了如指掌，自从羽月将军率领远征军踏上这片土地的时候，他就和我们在一起了。我知道他这次是想要划船沿着海岸前进，然后横穿菲拉斯的南部区域以避开部落的营地。$B$B我找不到他的船，但是也许你可以。也许那艘船被藏起来了，也许它已经沉没了。不管怎么样，只要找到船，就有可能找到他的线索。如果你找到什么东西的话，请赶快告诉我。', '找到信使的小船，你应该在菲拉斯的南部海岸线上展开搜索。', '你找到了一只搁浅的小船。透过有些浑浊的水，你看到左船舷有很多洞，整只船被破坏得几乎只剩下龙骨了，似乎是有什么力量想要把这只船撕为两半。在右舷上有一个小小的羽月要塞标志。$B$B在船底下的泥土里，似乎有什么金属物品在闪光……', '|n', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4128, '拉格纳·雷酒', '你好，$N。我听说拉格纳·雷酒正因为有人偷了他的酒而大发雷霆呢。他在找合适的冒险者来帮忙，而且报酬丰富。$B$B如果你感兴趣的话就去找拉格纳谈谈吧，他在丹莫罗，卡拉诺斯的雷酒酿制厂里。', '和拉格纳·雷酒谈一谈。', '你说的很多，我确实疯了!我被人抢劫了!那些强盗抢了我祖传的配方!他们怎么敢这样做!在此之前我还不怎么恨那些黑铁矮人了!现在，哦……他们就是罪魁祸首!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4130, '心灵占卜术', '我仍然有些晕，不好意思。嗯，我看到了一些有用的图像。$B$B拉斯卡尔从小船里拿了两只皮袋子，然后上了岸；然而，他又回到了小船那里。我看到了豺狼人……他遇到了豺狼人——那些被称作木爪豺狼人的家伙。他看起来很着急——看上去有些恐惧——似乎是在躲避什么。他甚至没有注意到身后的水元素……就是这些了。$B$B我得休息一下，对不起，$N。把我看到的东西告诉基恩诺，他需要知道这些。', '和羽月要塞的基恩诺·火花谈一谈。', '感谢你把奎恩提斯看到的东西告诉我，$N。我下一次和他打牌的时候看来要小心一些了。$B$B拉斯卡尔应该可以应付那些豺狼人，他的实力还不至于弱到被豺狼人打得落花流水。也许在获得这些新的情报之后，你可以帮我们再去找找新的线索。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4131, '木爪豺狼人', '拉斯卡尔也许是被我们的那些豺狼人“朋友”抓去了，虽然直觉告诉我事情并不是这样的。但是你最好还是从它们那里开始搜索。$B$B我希望我知道该干什么，现在我现在能说的只有“去搜索木爪豺狼人的营地，现在就出发。”我知道豺狼人会把他们抢到的东西藏起来，而且为何这些东西互相争斗。也许是它们抢了奎恩提斯所说的包裹。我在搜索过程中没有去跟豺狼人作战，不过既然奎恩提斯有这种预感，我们就必须采取行动了。', '在菲拉斯南部地区的木爪豺狼人营地里寻找信使的下落或者信使的物品。', '两个皮制的大背包靠在附近的树旁，每个包上都有羽月要塞的标志……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4133, '薇薇安·拉格雷', '暗法师薇薇安·拉格雷需要你的帮助。她在荒芜之地，就在兽人的卡加斯前哨基地里，她在那里对有关黑铁矮人的事情进行调查。$B$B去和薇薇安谈谈吧，她正在等着你。', '与卡加斯的暗法师薇薇安·拉格雷谈一谈。', '谢谢你到这里来，$N。这里不缺少荒漠地区的独特魅力，但是似乎医疗条件差了点。$B$B不开玩笑了。你是来这里谈生意的，对不对?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4135, '痛苦深渊', '在背包中有两样东西：第一件是要送到萨兰纳尔去的包裹，第二件是匆忙书写的便笺。$B$B便笺上面写着在豺狼人营地南边有一处被称作痛苦深渊的地方，那里有许多邪恶的虫类生物。作者认为他应该亲自去调查一番，因为他觉得那是对整个菲拉斯的威胁。便笺的末尾署了名，“羽月要塞的拉斯卡尔”。$B$B看来你最终找到了拉斯卡尔的下落。', '现在你已经知道了拉斯卡尔的去向，那么你最好到痛苦深渊去寻找他，或者至少是他的尸体。根据便笺上的信息，那个地方应该在木爪豺狼人营地的南边。', '你找到了一个很大的脓包状物体。看起来这东西粘糊糊的，有些地方还有硬质的瘤。这个脓包的高度和宽度足够装下一个人型生物……通过里面隐约可见的人形轮廓，你大概猜出了里面裹着的究竟是什么。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4147, '玛尔冯的车间', '我查了查穆尔金到底在干什么，结果发现他居然在种植那些该死的东西！$B$B我想现在唯一的解决方法是……不，不是去和他谈判……你在想什么？唯一的解决方法就是以牙还牙！$B$B我需要我的朋友玛尔冯的帮助，他在棘齿城有个车间。我敢说他一定能造点对我们有用的东西出来。', '到棘齿城去，在玛尔冯·瑞文斯克的车间里找到他。', '玛尔冯很久之前就离开这里了，$N。他去塔纳利斯研究那里的古代食人妖遗迹去了。$B$B那么你刚才说你需要什么来着?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4223, '真正的主人', '<所罗门镇长叹着气。>$B$B你必须回到燃烧平原去，$N。作为暴风城的代表，你现在应该去向麦克斯韦尔元帅报告。祝你好运。', '和燃烧平原的麦克斯韦尔元帅谈一谈。', '<麦斯威尔元帅大笑着。>', '啊，你就是我们要求的「增援」?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4241, '温德索尔元帅', '这么说来，那个没用的废物说温德索尔还活着，是吗？$B$B做好准备，士兵，你必须去找到他。如果温德索尔还活着的话，你就把他带回来。如果他死了，那我就要你拿出他已经死亡的证据。$B$B<麦克斯韦尔大笑着。>$B$B我打赌你已经厌倦听到这样的命令了，是不是？', '到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。$B$B狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。', '他在哪里?我要杀了他!', '<温德索尔元帅朝你发出低吼。>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4242, '被遗弃的希望', '伯瓦尔是个笨蛋。我一直以来都在收集有关他的“证据”，要将他彻底打败。$B$B他是个没脑子的小丑，证据在他面前堆了足有两英尺高而他却视而不见。$B$B如果我能找到铁仇之锤并且走出这个该死的迷宫，那我要做的第一件事就是去暴风城，把那个卑鄙的家伙一劈为二。$B$B离我远点，$N。', '前往燃烧平原，摩根的岗哨。把这个坏消息传达给麦克斯韦尔元帅。', '显然，他疯了。$B$B<麦斯威尔难过地垂下了头。>$B$B一个曾经是那么光荣和高贵的战士现在却成了唠唠叨叨的家伙。我猜想我们进了一个死胡同……$B$B不管怎么样，我必须为你所做的努力而奖励你，$N。', '你回来啦!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4243, '找回A-Me 01', '非常不幸，我的一项最伟大的发明出了点问题。你以前见过机械松鼠，对吗？嗯，为了接近安戈洛环形山的猿猴，我制造了一只机械猿猴混入它们的群落——我把她称为A-Me 01。$B$B她的水晶眼珠上附有特殊的魔法，因此我能看见她所看见的一切。不过，在她到了北边的蘑菇石——也就是那群猿猴的巢穴里面之后，我便与她失去了联系。我最后看到她的时候，猿群中有一只雄猿正在冲上前去想和她套近乎！$B$B你能帮我找到她吗？', '在安戈洛环形山找到A-Me 01。', '在你检查 艾米 01时，你发现她身上有两处非常明显的咬痕，一处在肩膀上，另一处在头上。$B$B你对她做了进一步的检查，发现似乎没有任何动力驱动这台复杂的机械。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4261, '远古之灵', '费伍德森林曾经是个和平安详的地方……直到燃烧军团占据了这里。恶魔、毁灭和混乱接踵而来……$B$B古尔丹之颅让这里的所有生物无一幸免地全都堕落了。$B$B直到现在，我还是身陷其中，不得不忍受这片土地所遭受的痛苦。请帮我找到回家的路吧，$N，告诉我你愿意带领一个古树之灵离开这里，让我得到最终的安息。$B$B在我获得自由之后，就请去找住在林歌神殿的德鲁伊凯尼斯·静风。', '护送艾雷脱离危险，然后和灰谷东部的林歌神殿中的凯尼斯·静风谈一谈。', '', '', '帮助艾雷脱离危险', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4266, '羽月将军的欢迎', '$N，珊蒂斯·羽月将军想与你私下谈一谈。毫无疑问，她是想要感谢你对要塞做出的贡献，但我知道她还想和你讨论一下你和拉斯卡尔在菲拉斯南部遇到的那种昆虫。毫不夸张地说，那些祖卡什的昆虫……非常可怕。$B$B羽月将军正在主厅里等你。', '与羽月要塞的珊蒂斯·羽月谈一谈。', '$N，对你给予我们的帮助，我向你致以最衷心的感谢。你在面对巨大的困难表现出了过人的勇气，因此我希望你接受这一奖励。$B$B现在，如果可以的话……我想再次请求你的帮助。这个任务涉及到了在菲拉斯这里发现的祖卡什虫穴，我想你是最佳的人选。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4298, '为人父母', '哇，他们比我想象中的要成熟得多……', '与辛特兰的阿格纳谈一谈。', '过来，拿着这颗蛋……你最好随身带着它，让它以为你是它的$g爸爸:妈妈;\n。$B$B恭喜，$N。你是一个家长了……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4321, '分析水晶塔', '你带给我的有关这些水晶塔的信息很有趣……$B$B给我点时间，我要计算一下，$N。过会再和我说话，我应该可以给你一些答复。', '过一会再和科琳说话。', '好吧，$N。这太令人着迷了……我希望我的这些图表是正确的!$B$B我相信自己已经可以回答你所有的关于水晶的问题了，$N。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4324, '尤卡·斯库比格特', '尽管我的弟弟雷布里一生都无所作为，但是我认为，最终他的生命还是有些价值的！然而……我们可能需要你的帮助来让雷布里发挥他最后的价值。$B$B我姐姐尤卡这段日子以来都在寻找他，而且跟踪他到了燃烧平原。她曾带话给我，要我雇些人给她帮忙。$B$B那么，你有兴趣吗？如果你想要试试的话，就去跟我姐姐说吧。她就住在巨槌石西北的称作烈焰洞里。', '与燃烧平原的尤卡·斯库比格特谈一谈。', '对，我正在寻找我的弟弟。我们必须找到他，愿神保佑他。$B$B但是如果我们无法将他活着带走……至少也要带走他的首级。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4341, '卡兰·巨锤', '你去过索瑞森废墟那个破地方没有？碰到过一个名叫卡兰·巨锤的可怜家伙没有？那个应该是正在看守我女儿的矮人！$B$B<国王抽泣着。>$B$B我已经派人把燃烧平原翻了个底朝天，现在唯一关于我女儿的线索就是她应该在黑石深渊里。有消息说她有可能已经死了！$B$B卡兰在黑石深渊中负责看守囚犯……找到他！我要知道我女儿的下落！', '去黑石深渊找到卡兰·巨锤。$B$B国王提到卡兰在那里负责看守囚犯——也许你应该在监狱附近寻找他。', '求求你，请听我解释。', '又来了一个?$B$B<卡兰抱怨着。>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4361, '糟糕的消息', '你必须把这个消息带给麦格尼陛下，$N。他会知道接下来该怎么做的！', '回到铁炉堡，把这个坏消息带给国王麦格尼·铜须。', '<麦格尼愤怒地用他的拳头砸向王座的扶手。>', '你找到他了?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4362, '王国的命运', '看起来我的老对手——达格兰·索瑞森——已经把我和铁炉堡都置于他的控制之下了。$B$B你可能是我的最后希望了，$N。你必须拯救我亲爱的女儿，茉艾拉！$B$B只有一种方法可以破除索瑞森施放在茉艾拉身上的咒语，那就是杀死他。$B$B还有，$N，不要伤害茉艾拉！记住，她正在被索瑞森控制着！她所做所说的一切都只是索瑞森邪恶咒语的结果！', '回到黑石深渊，从达格兰·索瑞森大帝的魔掌中救出铁炉堡公主茉艾拉·铜须。', '铜须公主为达格兰.索瑞森大帝的死而放声痛哭。>$B$B为什么?', '我……我在哪儿?你是谁?$B$B<铜须公主看着达格兰.索瑞森大帝的尸体。>$B$B你对我亲爱的达格兰做了什么?!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4363, '语出惊人的公主', '索瑞森是个伟大的、值得尊重的矮人。你毁了我的一生，还有我肚子里的孩子的一生！$B$B<你认为茉艾拉公主也许是受到了索瑞森的法术影响才变成这样的。>$B$B回铁炉堡去告诉我父亲，铁炉堡的下一任统治者将会是个黑铁矮人。$B$B不管他同不同意，事情都会是这样。', '回到铁炉堡去，与国王麦格尼·铜须谈一谈。', '<国王麦格尼.铜须显然非常失望。>$B$B看来即使索瑞森死了，他也获得了胜利。$B$B你可以走了，$N。在你离开之前，别忘了从皇家宝库里选择你应得的奖励。$B$B<麦格尼.铜须瘫倒在王座上，陷入了沉思。>', '欢迎回来，$N!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4442, '净化！', '我要用月神之水来净化这根笛子。我们必须结束这场劫难……$B$B愿艾露恩指引我的双手和我的心。$B$B过一会再和我说话。', '过一会儿再与艾瑞丹对话。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4485, '高贵之书', '你好，$N。我看到你仍然有着奉献的热情，仍然有着坚定的信念。$B$B我觉得你应该去跟暴风城的达索瑞恩·拉尔谈一谈了。你还有更多的东西要到那里去学习，我觉得你已经准备好了。$B$B到光明大教堂去找他吧，$n，你一定要认真学习这些知识。你因为谦卑和勤恳赢得了我们的尊敬，不要因为傲慢而让我们失望。$B$B祝你好运。', '与暴风城的达索瑞恩·拉尔谈一谈。', '恭喜你，愿圣光保护你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4486, '高贵之书', '嘿，看看我们这位圣骑士不可一世的样子。$B$B对不起，$N，我不是想要冒犯你……我只是有时候会对你能做那么多的事情而感到嫉妒。蒂萨说过这是我的弱点，我向她发誓我正在努力改正它……不过说起来容易做起来就难了。$B$B但是我要告诉你的是，暴风城的达索瑞恩·拉尔派人捎信过来说，让你近期回一趟光明大教堂，听上去他是有什么重要的事情要找你。', '与暴风城的达索瑞恩·拉尔谈一谈。', '恭喜你，愿圣光保护你。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4487, '召唤地狱战马', '啊，很好，你来了。我派了一个$g魅魔:地狱火;\n跟着你，以便引起你的注意，但看起来你在它找到你之前就来到这里了。没关系。$B$B最近大家都知道你的力量在日渐增长，而且大家对此议论纷纷——这对你来说很好，但有可能对其他人来说就不是什么好消息了。这些都是鸡毛蒜皮的事情。重要的是，我觉得你已经证明了自己有资格得到……呵呵……某种祝福。$B$B在贫瘠之地的棘齿城中有一个名叫斯坦哈德的人，我相信你以前见过他的。', '与棘齿城的斯坦哈德·法尔杉谈一谈。', '那么说来，你又决定要回应我的召唤，很好。$B$BB我的侍僧还在怀疑你会不会出现呢。我告诉他们这一点是毫无疑问的:当你想要获得更强大的力量时，你就会急切地来我这里。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4488, '召唤地狱战马', '啊，$N,你的出现使我们倍感荣幸！$B$B不过你也没指望我们会对你俯首贴耳吧？你的力量也许正在迅速增长，但说到真正的知识和理解力，你还是一个新手呢。如果你不当心的话，堕落的力量就会侵蚀你的意志。$B$B说正事吧，斯坦哈德想要跟你见一面。他仍然住在贫瘠之地，就在那座可以俯瞰棘齿城的塔中。我建议你不要耽搁太久。', '与棘齿城的斯坦哈德·法尔杉谈一谈。', '那么说来，你又决定要回应我的召唤，很好。$B$BB我的侍僧还在怀疑你会不会出现呢。我告诉他们这一点是毫无疑问的:当你想要获得更强大的力量时，你就会急切地来我这里。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4489, '召唤地狱战马', '你，说你哪！过来！$B$B你就是他们所说的那个叫做$N的$r，对吗？$B$B我也这么想。我长话短说：你的力量在不断增长，这点众所周知。现在，你的努力终于可以为你带来回报了。$B$B到贫瘠之地去，在那里的棘齿城中找到斯坦哈德·法尔杉——你还记得他吧？他会跟你详谈的，赶快去吧。', '与棘齿城的斯坦哈德·法尔杉谈一谈。', '那么说来，你又决定要回应我的召唤，很好。$B$BB我的侍僧还在怀疑你会不会出现呢。我告诉他们这一点是毫无疑问的:当你想要获得更强大的力量时，你就会急切地来我这里。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4490, '召唤地狱战马', '我会为你的忍耐和辛勤工作而奖励你的。但你要知道，召唤一匹地狱战马的能力在将来会变得困难许多。你必须努力争取它……而且这不很容易。$B$B现在，你可以在自己需要的时候召唤地狱战马了。', '与棘齿城的斯坦哈德·法尔杉谈一谈，学习召唤地狱战马的能力。', '祝你好运，$N。我期盼着能与你再次见面。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4493, '异种蝎的远征', '看起来异种蝎的意图，不——它们存在的原因，就是毁灭它们遇到的所有其它生物。它们的目标非常明确，也正是由于这个原因，它们成了对艾泽拉斯所有生物的巨大威胁。$B$B我们现在见到的仅仅是个开始，我怀疑它们的力量来自卡利姆多的腹地：安戈洛环形山。到塔纳利斯沙漠里的加基森镇去，跟炼金师匹斯特苏格谈一谈。把我的想法告诉他，他肯定会帮我们对抗异种蝎的。', '与加基森的炼金师匹斯特苏格谈一谈。', '嗯，我知道是格拉希娜派你来的。你与这些小动物的作战经验是非常宝贵的，据我所知没几个人曾经对付过这类生物。至于格拉希娜所持的安戈洛环形山是异种蝎发源地的观点……可能确实如此。安戈洛环形山是西边的一个神秘而危险的丛林。也许我们可以在那里搞清楚异种蝎的来龙去脉。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4494, '异种蝎的远征', '看起来异种蝎的意图，不——它们存在的原因，就是毁灭它们遇到的所有其它生物。它们的目标非常明确，也正是由于这个原因，它们成了对艾泽拉斯所有生物的巨大威胁。$B$B我们现在见到的仅仅是个开始，我怀疑它们的力量来自卡利姆多的腹地：安戈洛环形山。到塔纳利斯沙漠里的加基森镇去，跟炼金师匹斯特苏格谈一谈。把我的想法告诉他，他肯定会帮我们对抗异种蝎的。', '与加基森的炼金师匹斯特苏格谈一谈。', '嗯，我知道是格拉希娜派你来的。你与这些小动物的作战经验是非常宝贵的，据我所知没几个人曾经对付过这类生物。至于格拉希娜所持的安戈洛环形山是异种蝎发源地的观点……可能确实如此。安戈洛环形山是西边的一个神秘而危险的丛林。也许我们可以在那里搞清楚异种蝎的来龙去脉。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4495, '好朋友', '我有一位名叫埃沃隆的朋友，他通常都会在每天的固定时间段里来拜访我。奇怪的是，今天他根本没来，实际上现在他已经晚了好几个小时了。$B$B我承认我有些担心，$N。埃沃隆常常在北面的一个洞穴里待很长时间，你知道那里有多危险——那里到处都是蜘蛛！$B$B如果你恰巧要过去那边的话，能帮我找一下他吗？', '在北边的洞穴附近找到埃沃隆。', '真高兴你能找到我，$N。你是怎么知道我在这里的?', '啊啊啊……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4605, '超级清洁器5200型！', '', '', '超级清洁器5200型突然停止了运行，「叮」的一声响，机器的盖子打开了，里面放着一只扎着蝴蝶结的小盒子。似乎这机器在清除物体表面的污垢以后会把物体包装起来。即使机器没有清理过什么，至少这东西被装在了一个漂亮的盒子里。$B$B好吧，让我们来看看它有没有清洁你放进去的东西……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4606, '超级清洁器5200型！', '', '', '超级清洁器5200型突然停止了运行，「叮」的一声响，机器的盖子打开了，里面放着一只扎着蝴蝶结的小盒子。似乎这机器在清除物体表面的污垢以后会把物体包装起来。即使机器没有清理过什么，至少这东西被装在了一个漂亮的盒子里。$B$B好吧，让我们来看看它有没有清洁你放进去的东西……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4736, '寻找梅纳拉·沃伦德', '啊，你好，$N。你的训练进行得很顺利，所以我想你应该因自己的辛勤努力——以及你至今仍未被魔法的力量腐蚀——而获得奖励。$B$B如果你感兴趣的话，就到棘齿城去找梅纳拉·沃伦德。她在斯坦哈德的塔里俯瞰着整个小镇。$B$B她并不是很友好，$N，所以你可别想从她那里得到什么赞许。但是如果你努力的话，那她一定会好好照顾你的。', '与贫瘠之地的梅纳拉·沃伦德谈一谈。', '啊，泽弗洛斯特让你来的。很好。看来我的话传到了如此之远的地方，为我找到了新的学生，这让我感到非常高兴。$B$B我们这些$C必须联合在一起，$N，无论自己属于哪个种族。这一点很重要，因为跟我们打交道的家伙都十分疯狂─如果我们没能安抚它们或者正确地控制它们的话。$B$B我觉得你已经学会了很多东西，如果你愿意的话，我会帮你继续提高你的能力。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4737, '寻找梅纳拉·沃伦德', '嗯，你还在努力变得更强。要我说，你迟早会堕落和沉溺于魔法，迟早会被你所追寻的力量所奴役。$B$B哎！你真是笨蛋！时间会证明我是正确的——没有别的……只需要时间。$B$B看来并不是所有人都同意泽弗洛斯特的意见。梅纳拉会创造一些可以让你变得更加强大的东西，如果你感兴趣的话，就去贫瘠之地的棘齿城吧。她在城外的一座塔中。', '与贫瘠之地的梅纳拉·沃伦德谈一谈。', '啊，泽弗洛斯特让你来的。很好。看来我的话传到了如此之远的地方，为我找到了新的学生，这让我感到非常高兴。$B$B我们这些$C必须联合在一起，$N，无论自己属于哪个种族。这一点很重要，因为跟我们打交道的家伙都十分疯狂─如果我们没能安抚它们或者正确地控制它们的话。$B$B我觉得你已经学会了很多东西，如果你愿意的话，我会帮你继续提高你的能力。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4738, '寻找梅纳拉·沃伦德', '让我们来澄清一件事情，$N：我觉得你并没有准备好肩负这样的责任。我认为一个新手在创造某件具有强大力量的物品的过程中起不到什么作用，特别是一个没有经过试炼的新手。$B$B但是这不是我能决定的，因为掌握着这种力量的人决定要赋予你强大的力量。$B$B如果你想要对此有更多了解的话，我建议你到棘齿城去找梅纳拉·沃伦德，她就住在港口上面的塔里。', '与贫瘠之地的梅纳拉·沃伦德谈一谈。', '啊，泽弗洛斯特让你来的。很好。看来我的话传到了如此之远的地方，为我找到了新的学生，这让我感到非常高兴。$B$B我们这些$C必须联合在一起，$N，无论自己属于哪个种族。这一点很重要，因为跟我们打交道的家伙都十分疯狂─如果我们没能安抚它们或者正确地控制它们的话。$B$B我觉得你已经学会了很多东西，如果你愿意的话，我会帮你继续提高你的能力。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4739, '寻找梅纳拉·沃伦德', '$c！没错，叫的就是你！$B$B你没有准备好所有必须的装备，但你已经准备就绪了，你看起来自信十足。嗯，现在我看到你的自信了。$B$B如果你准备好了，那么梅纳拉·沃伦德会教你一些东西。她主要负责向年轻的学生传授魔法的知识，也会给那些通过测试的学生赠送特殊的礼物。$B$B如果你感兴趣的话，就到贫瘠之地的棘齿城去。她就在斯坦哈德的塔里俯瞰全城。', '与贫瘠之地的梅纳拉·沃伦德谈一谈。', '啊，泽弗洛斯特让你来的。很好。看来我的话传到了如此之远的地方，为我找到了新的学生，这让我感到非常高兴。$B$B我们这些$C必须联合在一起，$N，无论自己属于哪个种族。这一点很重要，因为跟我们打交道的家伙都十分疯狂─如果我们没能安抚它们或者正确地控制它们的话。$B$B我觉得你已经学会了很多东西，如果你愿意的话，我会帮你继续提高你的能力。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4761, '桑迪斯·织风', '桑迪斯·织风应该已经对你在熊怪的营地那里所进行的侦察行动有所了结了。他是奥伯丁的长者，在那里负责处理村中的日常事务。请把你对熊怪的侦察结果汇报给他。$B$B我相信，他对熊怪堕落的原因有自己的解释。或许你能与他一起制定出恢复自然平衡的计划！', '与奥伯丁的桑迪斯·织风谈一谈。', '很高兴见到你，$C。你对熊怪进行的侦察活动对奥伯丁而言是件大好事。这段时间以来，我们不仅要对付那些公开与我们为敌的生物，还要面对整个森林不断堕落的现状。希望你能在这样艰难的时期对奥伯丁有所帮助。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4766, '玛亚拉·布莱特文', '我的一个手下——玛亚拉·布莱特文被派到燃烧平原去调查索瑞森废墟。在那座被摧毁的城市里，黑铁矮人也许隐藏了什么有价值的东西……能放在我的家族博物馆里的东西。$B$B玛亚拉说她发现了一些东西，不过一时半会还拿不到它，那东西不在索瑞森，而是在黑石塔里。$B$B我不清楚具体的细节，不过如果你感兴趣的话，那就去燃烧平原跟玛亚拉谈谈吧。', '与燃烧平原中摩根的岗哨的玛亚拉·布莱特文谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4769, '薇薇安·拉格雷和黑暗石板', '薇薇安·拉格雷从荒芜之地的卡加斯派人捎了信过来。她认为黑石塔中的一份远古文稿可以对我们的研究有所帮助。为了证实这一点，她需要找人帮她从塔中取出这份文稿——这任务可不容易。$B$B如果你感兴趣的话，就去跟卡加斯的薇薇安谈一谈吧。', '与卡加斯的暗法师薇薇安·拉格雷谈一谈。', '没错，我相信黑石塔中有一块刻有古老的鍊金配方的石板。我需要那块石板，很高兴你能来帮我。$B$B放松一下，我会进一步向你解释的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4770, '回家', '请帮帮我，$c！我藏在这里已经很久了，好多天都没有看到过一张友好的面孔。我来这里是准备研究双足飞龙的，但是也许我靠得太近了。我在研究一只双足飞龙的时候遭到了攻击，一直被追到这里，而且迷了路。$B$B我要回白沙岗哨去！莫特加不知道我失踪了，如果他知道我独自进入风巢的话，一定会暴跳如雷的。$B$B白沙岗哨就在这里的东面……请把我带到那里去！', '护送波卡·雨山走出风巢，然后和白沙岗哨的莫特加·火鬃谈一谈。', '什么!?如果我知道波卡.捷山要独自进入风巢的话，我会把他拴在图腾上面!他的父亲勉强才允许他和我一起来千针石林，我们来这里是为了研究这片美丽的土地上的各种生物。$B$B非常感谢你给予波卡的帮助，希望这个能够替你阻挡各种的不幸之事。', '', '保护波卡离开风巢', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4782, '魔化金线血袍', '回到梅纳拉那儿去吧，告诉她我需要一些时间来完成这活儿，但是我向她……和你保证，我肯定会完成它。等你弄到你所需的其它物品之后，我应该已经纺好金线了。到那时你就可以到我这儿来取走金线。$B$B祝你好运，$N。哦，对了，请帮我向斯坦哈德问好。那个老疯子……他居然在棘齿城旁边盖了座塔……真是疯了。', '回到贫瘠之地的梅纳拉·沃伦德那里。', '好极了，你回来了，$N。金线在哪儿?$B$B啊，我明白了，我能接受。那个哥布林跟他的兄弟还没让我们失望过呢─所以我估计他是在慢吞吞地纺织金线。就这样吧……在这期间我们还有其他事情要做呢。$B$B你准备好接受下一项任务了吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4785, '优质金线', '', '', '拿着吧，$N。请代我们向梅纳拉问好。$B$B我们希望你将来能有所作为。也许有一天，当燃烧军团被击败时，人们将呼喊着你的名字，赞颂着你的力量。我已经等不及要看到那场面了!', '你回来了，$N。我和我的兄弟都很高兴。$B$B毫无疑问，你是来取金线的。当然，我们都准备好了。完工的速度比我们的预期速度要快得多。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4813, '水晶中的碎骨', '月亮井的水让嵌在水晶里的东西显现了出来，那是一些细小的骨头碎片，还有半块下颌骨。这块下颌骨似乎是人类的，但是你没办法打开水晶，所以还不能确定这一点——即使是最强大的魔法也几乎不可能打碎这块水晶。$B$B现在看来，你只能去向奥伯丁的哨兵哨兵戈琳达·纳希恩汇报这个发现了。', '向奥伯丁的哨兵哨兵戈琳达·纳希恩报告你的发现。', '那么，看起来即使我们对这块水晶有了进一步的了解，其结果也不过是发现了更多有待回答的问题!$B$B我要把你汇报的这些情报交给奥伯丁的议会，他们可能会制定后续的计画，嗯，我是说假设他们能制定出计画来的话……现在，东边的威胁一时半会还不会对我们造成什么伤害。$B$B至于你，请拿着这个。这是给你的奖赏，$N。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4861, '被激怒的枭兽', '小$G伙子:姑娘;\n，过来一下！我被一群嗜血如命的枭兽追赶，从我那个在冬泉谷南部的营帐里逃到了这儿！我觉得这可能是我离枭兽要保护的某种东西太近的缘故。$B$B我刚刚设法安全脱身，但是跟我一起的那个同伴可就没这么幸运了……你愿意到我的营地里去一趟吗？我真的需要那些补给物资，另外我还想取回昨天在挖掘场发现的护符。', '在冬泉谷的南部寻找加隆·石矛的被破坏的营帐，以及他的补给物资。', '在这个一片狼藉的营帐中有一只严重毁损的木箱……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4863, '被激怒的枭兽', '你朝四周看了看，没找到加隆想要的东西。但是，你注意到先前找到的箱子已被打碎，似乎是被枭兽洗劫过……$B$B你向东看去，勉强辨认出那里有一辆支离破碎的马车。或许你能在那里找到加隆的东西，最好去看一看。', '找到加隆·石矛的马车。', '在马车附近似乎没有加隆想要的东西。但是，你在地面上发现了一些半埋在雪地里的未被损坏的木箱。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4865, '狂热之蛇', '若不是亲眼所见，我绝不会相信这是真的。复仇之灵已经来到了千针石林！$B$B<哈加尔擦了擦额头上的汗。>$B$B$N，你必须尽快采取行动！现在就去找到莫特加·火鬃，他住在乱风岗西北部的白沙岗哨，他知道该怎么做！', '向千针石林白沙岗哨的莫特加·火鬃汇报你的发现。', '复仇?!那么，阿利卡拉的传说是真的了。这确实是一个必须尽快解决的问题。', '你把自己的发现汇报给莫特加.火鬃了吗?你应该立即告诉他这个消息。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4881, '暗杀计划', '牛头人卡纳提·灰云胆敢在千针石林建立营地，简直是胆大妄为。我们必须杀了他，铲除他的营地，消灭他的所有同伴。我们将在升降梯西南方的小岗哨中会合，然后出发。', '将暗杀计划通知给白沙岗哨的卡纳提·灰云。', '他们要来杀我?我会让他们看到牛头人是怎样战斗的!', '什么?他们想要杀死我!让他们来吧，我会让他们知道厉害的!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4901, '祭坛守护者', '在山脊的顶部有一座艾露恩的祭坛。根据我所了解到的情况，我们必须点燃那一带每座洞穴里的火炬，然后我们就可以直接到祭坛那边去了。$B$B我在凯斯利尔废墟的石头上发现了一些用符文书写的咒语，我想这可以打开通往祭坛的路。我需要你来帮忙点燃那些火炬，与此同时，我将诵读咒语。$B$B如果我们成功了，你就可以把我们的发现汇报给艾瑞拉斯了！', '在兰莎尔拉尝试激活艾露恩祭坛的过程中保护她。然后将你的发现报告给鲁瑟兰村的艾瑞拉斯·琥珀。', '你找到兰莎尔拉了没有?', '', '揭开艾露恩祭坛的秘密', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4902, '艾露恩的枭兽', '这可真叫人着迷！$B$B我一直在思考事情的真相……呃，你也应该跟我们分享这些知识！立即到大德鲁伊范达尔·鹿盔那儿去，你可以在达纳苏斯的塞纳里奥区里找到他。把这里所发生的一切都告诉他，就像你刚才跟我说的那样。我敢说他肯定会对此很感兴趣！$B$B这可是个重要的情报，$N！', '与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。', '别犹豫，告诉我你为什么来这儿。$B$B哦，是吗?嗯，好吧。$B$B谢谢你直接了当地告诉我这个，开门见山总是最好的……但是……没错。塞纳里奥议会的德鲁伊对枭兽已有所了解。它们是伊露恩的宠物，被指派去守护那些最神圣的地方。$B$B虽然这不是什么新闻，但我还是对你的努力表示敬意。拿着这个─这是给你的奖赏。', '你好!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4907, '丁奇·斯迪波尔', '嗨，$N。你还记得丁奇·斯迪波尔吗？嗯，她还记得你！她让我留意你的行踪，因为……她需要你的帮助。我认为这可能跟她对龙类的研究工作有关。$B$B你应该到燃烧平原的烈焰峰去找她谈谈。', '与燃烧平原烈焰峰的丁奇·斯迪波尔谈一谈。', '菲诺克说得对!我确实需要你的帮助，这次的任务……非常危险。$B$B你准备好了吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4964, '达奥拉赫宝珠', '我马上就开始为你制作宝珠，并将新的恶魔禁锢在里面。等宝珠完成之后，你可以选择是把它制成法杖还是保留这颗宝珠。我始终认为术士应该选择自己最喜欢的武器……所以这次我也没理由不按老规矩办。', '等待梅纳拉·沃伦德完成达奥拉赫宝珠，然后再与她谈一谈。', '完成了，$N。告诉我你喜欢哪一种就行了:法杖是要用两只手拿的，而宝珠只需一只手拿着，因此你就可以腾出手来使用匕首或是长剑。$B$B战胜恶魔犬是件很了不起的事情，这件东西作为给你的回报是再合适不过了。希望你以后能掌握更强大的力量，$N。', '再等一等，$N……', '等待梅纳拉·沃伦德完工', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4965, '奥拉赫宝珠', '啧啧，很高兴看到你的力量在逐渐增长，$N。我敢打赌，你是准备去贫瘠之地找梅纳拉·沃伦德谈话吧。如果你以前没有跟她说过话，那么让我来告诉你吧，到现在为止，我还没有遇到过比她更熟练的制造师呢——尤其是是制造宝珠。那宝珠甚至可以禁锢恶魔，不费吹灰之力就能让恶魔按我们的意愿行事。$B$B如果你感兴趣的话，就到贫瘠之地棘齿城旁边的塔里去找她吧。', '与贫瘠之地的梅纳拉·沃伦德谈一谈。', '啊，你的确是在寻找更为……实际的东西。如果你已经准备就绪了，那么我可以帮你。$B$B我很高兴看到我们的同行寻求更多的力量，而不仅仅是知识，这很好。$B$B那么，你准备好了吗，$N?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4966, '保护卡纳提·灰云', '但是，半人马的数量可能比我想象中的要多，我请求你，$n，与我一起反击这些可耻的暗杀者吧。', '保护卡纳提·灰云免受半人马的袭击。', '谢谢你的帮助，$N。没有你，我可对付不了他们。', '', '保护卡纳提·灰云', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4967, '奥拉赫宝珠', '你这个蠢货，仍然被那些世俗的东西捆着手脚。没错，我蔑视你，看见你在我前面，我就不禁要大笑。你真可悲！$B$B但是我怎么想并不重要，关键是那些愿意与你打交道的人怎么想！虽然我并不看重你，但那些掌握着力量的人认为你应得到更多。$B$B如果这就是你想要的，那么你就到棘齿城边的塔里去找梅纳拉·沃伦德谈谈吧。我想你以前应该见过她。', '与贫瘠之地的梅纳拉·沃伦德谈一谈。', '啊，你的确是在寻找更为……实际的东西。如果你已经准备就绪了，那么我可以帮你。$B$B我很高兴看到我们的同行寻求更多的力量，而不仅仅是知识，这很好。$B$B那么，你准备好了吗，$N?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4968, '奥拉赫宝珠', '嗯，你居然大有长进……这真令人吃惊。我曾认为你肯定已经魔法的力量拉入了堕落的深渊，那么，让我们来继续增强你的力量，如何？$B$B如果你想要看看自己到底有多大的本事，就到棘齿城外的那座塔里去找梅纳拉·沃伦德，她会给你指引的。', '与贫瘠之地的梅纳拉·沃伦德谈一谈。', '啊，你的确是在寻找更为……实际的东西。如果你已经准备就绪了，那么我可以帮你。$B$B我很高兴看到我们的同行寻求更多的力量，而不仅仅是知识，这很好。$B$B那么，你准备好了吗，$N?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4969, '奥拉赫宝珠', '哈哈！年轻的$r$c，你做得很好。$B$B再过一段日子，即使是地狱火和恐惧魔王都会在你面前低头的！$B$B但是在那之前，你还得依赖凡人铸造的武器。$B$B看起来你已经准备好了。如果你愿意的话，梅纳拉·沃伦德想跟你谈谈！她住在斯坦哈德的塔里，就在棘齿城的边上。去吧。', '与贫瘠之地的梅纳拉·沃伦德谈一谈。', '啊，你的确是在寻找更为……实际的东西。如果你已经准备就绪了，那么我可以帮你。$B$B我很高兴看到我们的同行寻求更多的力量，而不仅仅是知识，这很好。$B$B那么，你准备好了吗，$N?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4975, '诺奥拉赫宝珠', '我马上就开始为你制作宝珠，并将新的恶魔禁锢在里面。等宝珠完成之后，你可以选择是把它制成法杖还是保留这颗宝珠。我始终认为术士应该选择自己最喜欢的武器……所以这次我也没理由不按老规矩办。', '等待梅纳拉·沃伦德完成诺奥拉赫宝珠，然后再与她谈一谈。', '完成了，$N。告诉我你喜欢哪一种就行了:法杖是要用两只手拿的，而宝珠只需一只手拿着，因此你就可以腾出手来使用匕首或是长剑。$B$B战胜炼狱火是件很了不起的事情，这件东西作为给你的回报是再合适不过了。希望你以后能掌握更强大的力量，$N。', '再等一等，$N……', '等待梅纳拉·沃伦德完工', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (4981, '狡猾的比修', '决不要相信地精。这是我多年来总结的经验，$N。$B$B她的名字是比修——我们最机敏的侦察员之一。我发现她在为燃烧平原外面的一个名叫基布雷尔的可疑的宠物商工作，而且非常卖力。更糟糕的是，她在使用部落的资金来做这些事情。$B$B把她给我带回来，要活的。$B$B她已经钻到黑石塔里面去了。去找到她，并把她带回来。$B$B还有，$N，不要让她的甜言蜜语欺骗了你。', '到黑石塔去查明比修的下落。', '我不会对你撒谎的，$C。我需要钱!基布雷尔的报酬非常，非常丰厚─比卡加斯远征军给的多得多。$B$B但是不要怀疑我的忠诚!你以为我为什么会在这里?给那个疯狂的哥布林倒腾一些奇异的蛋或者诸如此类的蠢东西吗?不，只有那些真正有毛病的人才会来黑石塔收集宠物。嗯，我不认为这世上有很多那样的笨蛋。$B$B<比修笑了。>$B$B我们最不需要的就是那种家伙了。', '很高兴见到你!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5021, '迟到总比不到好', '“在我被困在这里之前，这个包裹一定得送……送出去！”$B$B一个惊恐的女人的哭声在这所房子里穿梭回荡。你看到一个女人的灵魂瑟缩在楼上的角落里，看上去她并不完全熟悉周围的环境，她只是隐约地感觉到了你的存在。$B$B“你是来帮我送包裹的吗？趁事情还没有变得更加糟糕……求你了，帮帮我！我本来是要骑马离开这里的，包裹应该还在我的马旁边……是不是已经太迟了？”', '这个女人的幽灵告诉你她要送出一只包裹。她说那只包裹就在她的马旁边。至于马在哪里或者包裹要送到哪里去，她却根本没有说。', '一个你原本没有注意到的包裹从破败的废墟中显现出来。可能这就是詹妮丝.费尔斯通的鬼魂在不断念叨的那个包裹……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5057, '以往的努力', '$N，我已经听说过许多有关你的传言了……据说你有着坚强不屈的信念，作为一个$c，你具备杰出的能力。现在看到你，我终于相信这些都是事实了。$B$B像你这样优秀的$r值得嘉奖。把这个交给我在雷霆崖的一个名叫梅洛·石蹄的朋友。我肯定他会记得你，还有你以往做出的努力。将你近期所取得的胜利告诉他，还有永远不要忘记你今天所取得的成就。', '把斯托姆·影蹄的徽记交给雷霆崖的梅洛·石蹄。', '我们从生活经历中学习，$N。从这个标记所说的，我肯定你由于自身的原因已经变得越来越强大，越来越聪明。自从我们上次谈话以来你已经成长了许多。$B$B拿着这个作为你以$r$C的身份完成的艰难任务的纪念，而且记住你永远都会得到我的尊敬和钦佩。', '自从上次见到你后已经很久了，$N。有需要我帮忙的事吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5066, '战斗的号角：瘟疫之地！', '大家都听着！大家都听着！所有的英雄都应该聆听这号召的声音！$B$B暴风城已经发出了备战的号召！所有勇士都应该拿起武器，一同面对来自东部王国北部地区亡灵天灾的威胁！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，联盟的安全岌岌可危！$B$B联盟的英雄们——去向指挥官阿什拉姆·瓦罗菲斯特报到吧，他的大本营就在奥特兰克山脉北边的冰风岗！', '找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。', '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天谴军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5084, '堕落熊怪', '这种绿色液体……它让我想起了费伍德森林中的那些淤泥。我还看见一些冬泉谷的信使进入了木喉要塞……也许这与你正在寻找的瓶子有关，$N。$B$B有一大群熊怪刚刚经过费伍德森林的木喉要塞，它们被称为死木部族，恶魔的气息让它们堕落了。你为什么不去周围看看，找到冬泉谷熊怪和死木熊怪之间的关系？', '搜寻费伍德森林北部的死木熊怪的营帐，继续寻找线索。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5090, '战斗的号角：瘟疫之地！', '大家都听着！大家都听着！所有的英雄都应该聆听这号召的声音！$B$B暴风城已经发出了备战的号召！所有勇士都应该拿起武器，一同面对来自东部王国北部地区亡灵天灾的威胁！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，联盟的安全岌岌可危！$B$B联盟的英雄们——去向指挥官阿什拉姆·瓦罗菲斯特报到吧，他的大本营就在奥特兰克山脉北边的冰风岗！', '找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。', '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天谴军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5091, '战斗的号角：瘟疫之地！', '大家都听着！大家都听着！所有的英雄都应该聆听这号召的声音！$B$B暴风城已经发出了备战的号召！所有勇士都应该拿起武器，一同面对来自东部王国北部地区亡灵天灾的威胁！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，联盟的安全岌岌可危！$B$B联盟的英雄们——去向指挥官阿什拉姆·瓦罗菲斯特报到吧，他的大本营就在奥特兰克山脉北边的冰风岗！', '找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。', '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天谴军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5093, '战斗的号角：瘟疫之地！', '部落的英雄们，请聆听这召唤的声音——部落召唤你们迅速行动起来！$B$B战斗的号角已经吹响，所有勇士都应拿起武器，准备与天灾军团殊死作战！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，部落的安全岌岌可危！$B$B部落的英雄们——去向高级执行官德灵顿报到吧，他的大本营就在提瑞斯法林地东部的亡灵壁垒！', '找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。', '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边的广袤土地上，到处都潜伏着天谴军团的势力。面对部落的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5094, '战斗的号角：瘟疫之地！', '部落的英雄们，请聆听这召唤的声音——部落召唤你们迅速行动起来！$B$B战斗的号角已经吹响，所有勇士都应拿起武器，准备与天灾军团殊死作战！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，部落的安全岌岌可危！$B$B部落的英雄们——去向高级执行官德灵顿报到吧，他的大本营就在提瑞斯法林地东部的亡灵壁垒！', '找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。', '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边的广袤土地上，到处都潜伏着天谴军团的势力。面对部落的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5095, '战斗的号角：瘟疫之地！', '部落的英雄们，请聆听这召唤的声音——部落召唤你们迅速行动起来！$B$B战斗的号角已经吹响，所有勇士都应拿起武器，准备与天灾军团殊死作战！城中传言四起，东部王国的废墟中滋生出了新的威胁！它们已经在幽暗城东面的瘟疫之地大量集结，部落的安全岌岌可危！$B$B部落的英雄们——去向高级执行官德灵顿报到吧，他的大本营就在提瑞斯法林地东部的亡灵壁垒！', '找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。', '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边的广袤土地上，到处都潜伏着天谴军团的势力。面对部落的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!$B$B如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5096, '误导血色十字军', '在进军安多哈尔之前，我们必须解决来自壁炉谷的血色十字军的威胁。他们已经在费尔斯通农场和达尔松之泪中间建立了营地，这使得我们在对亡灵天灾和十字军的作战中处于劣势，风险激增。$B$B我的计划是挑起他们之间的战争，你要做的就是去摧毁十字军的指挥帐篷，使用这只箱子里的燃烧瓶就行了。在点燃了帐篷之后，把亡灵天灾的战旗插在他们的营地中。如果我们运气够好的话，十字军就会对亡灵天灾进行报复。', '到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。$B$B将亡灵天灾的战旗插在营地中，然后回到西瘟疫之地亡灵壁垒的高级执行官德灵顿那儿。', '干得很好，$N。你对血色十字军的攻击为我们赢得了时间。我已经派出了最好的斥候去监视营地，确保那些十字军钻进圈套。$B$B随着我们承受的压力开始减弱，我们就能发起对安多哈尔的攻击，虽然有些风险，但这场战役非常重要。由于你已经顺利地完成了多次任务，我非常希望你也能参与这次行动。', '对血色十字军薄弱的防线进行突袭，这为我们赢取了向安多哈尔进军的时间。我相信你是来此汇报胜利的消息的!$B$B一旦你成功地完成了任务，我们很快就要开战了。如果天谴军团和血色十字军识破我们的计谋，以我们的实力是不可能同时与这两方抗衡的。', '摧毁指挥帐篷，在营地中插上天灾战旗', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5103, '火热的死亡', '这个人留下的只有一把烧焦了的骨头。他似乎是死于他找到的东西——一副未淬火的板甲护手。$B$B也许你应该拿起那副手套，然后离开这里？', '世界上一定有人知道关于这副手套的事情，祝你好运！', '你要干什……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5125, '奥里克斯的清算', '', '', '$N，我快死了……但我的灵魂得到了拯救。我欠你的情是无法用言语来表达的。请拿着这个……继续战斗下去吧，勇敢的$C!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5126, '罗拉克斯的故事', '那个萨特正在四处踱步并且自言自语。你想跟他搭话吗？', '与罗拉克斯谈一谈，听听他要说什么。', '<罗拉克斯大笑了起来。>', '……', '聆听罗拉克斯的故事', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5142, '小帕米拉', '在达隆郡战役中，我们牺牲了很多人。很多人死了……很多人死后又站了起来……$B$B战争一开始，我就把我的侄女帕米拉藏了起来，我不知道她现在到底怎么样了。我只是一个游魂，但是我一直很想知道帕米拉的情况。$B$B求求你，好心的$c，你能去达隆郡帮我找找她吗？往东边走，过了盖罗恩农场就到达隆郡了。', '在达隆郡找到帕米拉·雷德帕斯。', '你好。我叫帕米拉，你叫什么名字?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5152, '玛莱恩姑妈', '啊，我感到好孤独！我的家人在哪里？玛莱恩姑妈要我等在这里，但是她就这样一去不复返了！还有我的父亲……你看到过他没有？$B$B也许玛莱恩姑妈知道他在哪里。她住在安多哈尔附近，在靠南边的一座房子里。我想那房子是在一座小山上……她说过房子在山上。$B$B请你帮帮忙，$N。你是我的新朋友！你可以帮我去找我的姑妈吗？', '与安多哈尔废墟南边的玛莱恩谈一谈。', '你看到帕米拉了?她怎么样了?她还活着吗?不!可怜的帕米拉!她那么小，她是个多么快乐的小孩子啊……$B$B她不知道她爸爸发生了什么事情，是不是?我的兄弟约瑟夫?$B$B不……她无法理解约瑟夫究竟是怎么了。即使她可以理解，我想我也不能把这件事情告诉她……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5161, '蓝龙之怒', '我们了解那些被诅咒的死亡之翼的后代想要做什么，我们不能让它们得逞。$B$B由于黑石山脉对奈法利安有着天然的保护作用，我们根本无法与它们进行沟通。$B$B但是，我们可以授权给你，$r——你必须这么做。$B$B你眼前的道路充满了危险，你必须决定是否接受我们的帮助。考虑一下，决定之后再找我谈谈吧。', '要是你想继续的话，就与哈尔琳谈一谈。', '那么，好吧……', '做出明智的抉择吧，$N。如果你要决定离开这里，从此不再回来，我也不会怪罪你。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5162, '蓝龙之怒', '我所驾驭的是魔法的力量，而这魔法的力量将把你送到下一个目的地。$B$B当你准备好之后，你的旅程就将开始。你将前往瘟疫之地，与耶兹巴见面。$B$B他是个睿智的精灵，他像亘古不变的大地那样富有耐心。到安多哈尔去找他。', '与瘟疫之地的耶兹巴交谈。他居住在安多哈尔。', '我是耶兹巴，许多人称我为雕刻家。我所雕刻和塑造的却不是雕像，而是英雄。', '欢迎你，$r。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5164, '游荡者目录', '这是一个更好的选择，但是哈尔琳肯定不会选择它。阅读游荡者目录，得到它的启示。$B$B如果你坚持……如果你完成它交给你的任务……如果你能活下来……那么你将成为一名英雄。', '阅读游荡者目录。', '数百页充斥着混乱的文字和符号的书页组成了这本书。', '你打开了书。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5215, '瘟疫之锅', '在洛丹伦的土地上有八口瘟疫之锅，其中四口在西瘟疫之地，另外四口在东瘟疫之地。这些瘟疫之锅不断向空中喷出毒气，将天灾军团的瘟疫传播到整个大地。$B$B克尔苏加德的力量太强大了，我们无法关掉这些瘟疫之锅，但是我想我们可能有办法利用它们。我的助手，高阶牧师玛多妮尔负责此项任务的执行，你去找她谈谈吧。', '与西瘟疫之地冰风岗的高阶牧师玛多妮尔谈一谈。', '愿圣光的力量在这黑暗的日子里能够照耀着你，$C。我很高兴能与你共同执行这个破坏瘟疫之锅的计画。$B$B我们的目标是把瘟疫之锅中产生的瘟疫成分变成某种对天谴军团有负面影响的东西，为了能做到这一点，你就必须打开西瘟疫之地的四口瘟疫之锅。$B$B准备出发吧，英雄，一场与邪恶的天谴军团对抗的战争正在等着你!!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5228, '瘟疫之锅', '在洛丹伦的土地上有八口瘟疫之锅，其中四口在西瘟疫之地，另外四口在东瘟疫之地。这些瘟疫之锅不断向空中喷出毒气，将天灾军团的瘟疫传播到整个大地。$B$B克尔苏加德的力量太强大了，我们无法关掉这些瘟疫之锅，但是我想我们可能有办法利用它们。我的助手，暗影牧师范蒂丝负责此项任务的执行，你去找她谈谈吧。', '与西瘟疫之地亡灵壁垒的暗影牧师范蒂丝谈一谈。', '我以暗影之名问候你，$C。我将和你一起进行破坏天谴军团的瘟疫之锅的计画。$B$B我们的目标是把瘟疫之锅中产生的瘟疫成分变成某种对天谴军团有负面影响的东西，为了能做到这一点，你就必须打开西瘟疫之地的四口瘟疫之锅。$B$B英雄，进攻天谴军团的时机已经到了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5237, '任务完成！', '', '', '啊，$N!能为像你这样伟大的英雄提供奖励真让我感到荣幸。请允许我继续。$B$B<高阶执行官清了清喉咙，又开始大声咆哮。>$B$B请所有在场者见证:由于对被遗忘者和部落作出了杰出的贡献，而且是在面对极端强大的敌人和令人难以置信的危险的情况下做出这样的贡献，我将这个给予$N，并对这位部落的英雄表示最崇高的敬意!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5238, '任务完成！', '', '', '啊，$N!能为像你这样伟大的英雄提供奖励真让我感到荣幸。请允许我继续。$B$B<高阶执行官清了清喉咙，又开始大声咆哮。>$B$B请所有在场者见证:由于对被遗忘者和部落作出了杰出的贡献，而且是在面对极端强大的敌人和令人难以置信的危险的情况下做出这样的贡献，我将这个给予$N，并对这位部落的英雄表示最崇高的敬意!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5241, '卡林叔叔', '有时，在夜里，我可以听到我的叔叔卡林在哭，但那哭声听起来好像是从很遥远的东边传过来的。$B$B我希望他不是在为我哭泣！$N，你能找到我的叔叔并告诉他我过得很好吗？$B$B如果你找到他，跟他说我在等他，还有我想听他过去常讲的故事……那个关于兔子和果酱的故事！那个故事可真有趣！', '找到卡林·雷德帕斯。', '你见过帕米拉了?她还活着吗?$B$B她死了?不!哦，帕米拉!为什么你的灵魂还留在这世上受苦。为什么你死了，而命运却让我活着?我宁愿与你交换命运，在达隆郡这片死寂的土地上当一个孤魂野鬼!$B$B啊，但这个消息并不能改变命运。谢谢你，$N。现在，我的责任，我复仇的责任，像从前一样猛烈地燃烧起来了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5244, '凯斯利尔废墟', '凯斯利尔背后的故事是关于一个被诅咒的种族的,这个种族被困在在他们试图进行一场典礼的地方……$B$B你会在那里找到的上层精灵从前偷了一个圣物，它们相信可以把它的力量吸出供自己使用，以使自己变得更加强大。在他们试图吸取其力量时，这个遗物在一场大爆炸中粉碎了，碎片被埋在了湖面的冰下……$B$B如果你想知道更多的话去找加隆·石矛谈话；他最近刚去过这一地区可以告诉你更多事情。', '与坠星村的加隆·石矛谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5249, '前往冬泉谷！', '在冬泉谷，也就是这里北面的极寒之地，有许多远古的精灵遗迹。那是一块荒凉的土地，但它藏着许多秘密和有待探索的地方。$B$B因为我在费伍德森林这里还有事情要做，因此我没有机会到冬泉谷去。但你如果不去可就没有理由了！$B$B你到了冬泉谷之后，就去坠星村找到维恩德·夜风，他非常了解那片土地。', '找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5250, '坠星村', '在冬泉谷，也就是这里北面的极寒之地，有许多远古的精灵遗迹。那是一块荒凉的土地，但它藏着许多秘密和有待探索的地方。$B$B因为我在费伍德森林这里还有事情要做，因此我没有机会到冬泉谷去。但你如果不去可就没有理由了！$B$B你到了冬泉谷之后，就去坠星村找到维恩德·夜风，他非常了解那片土地。$B$B告诉他你是我的学生……', '找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。', '达蕾恩.轻风的学生?很高兴见到你，$N。', '有事吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5261, '伊根·派特斯金纳', '伊根·派特斯金纳正在找人帮他猎捕生病的狼。这是个好消息，因为现在在北郡山谷里生病的狼实在是太多了。$B$B如果你感兴趣的话，那就去和伊根谈谈吧。他就在修道院的左边。', '与伊根·派特斯金纳谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5264, '玛克斯韦尔·泰罗索斯男爵', '你即将获得最崇高的荣誉，$N。$B$B玛克斯韦尔男爵会因你对银色黎明所做的贡献而嘉奖你！$B$B玛克斯韦尔已经有很多年没有嘉奖过外人了。', '和玛克斯韦尔·泰罗索斯男爵谈一谈。他就在教堂里面。', '你是个非常重要的盟友，$N。你应该因你所做出的贡献而获得嘉奖。', '啊，伟大的英雄!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5265, '银色黎明宝箱', '许多年来，银色黎明宝箱都一直锁着，没有人能得到打开它的殊荣——直到今天。$B$B银色黎明宝箱现在为你敞开，$N。', '打开银色黎明宝箱，拿取你应得的奖励。', '哇……', '箱子悄无声息地打开了。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5281, '永不安息的灵魂', '在斯坦索姆沦陷的时候，许多人都悲惨地死去了。其中许多人是自杀的，他们宁愿选择葬身火海，也不愿成为亡灵天灾的一员。$B$B现在他们成了永远也不得安息的幽灵，在斯坦索姆的街道上到处游荡。$B$B我们必须拯救他们，$N！$B$B我有一个名叫埃根的同伴，他多年来对鬼魂和幽灵进行了大量的研究，你可以去找他帮忙。埃根正在斯坦索姆附近的东瘟疫之地对他的新发明进行测试。', '找到埃根。你只知道他在斯坦索姆附近。', '奥林总算是找到了一个足够勇敢的$r!', '我可没料到会有人来找我。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5401, '银色黎明委任徽章', '', '', '所有以银色黎明之名与邪恶战斗的勇士都必须佩戴我们的委任徽记，这样你们就可以向我们的军需官领取奖赏。$B$B在受到委任之后，你就可以从天谴军团士兵的尸体上收集天谴石，那是他们身份和职位的证明。将你收集到的天谴石交给我，每套天谴石都可用来换取一枚勇气和荣耀的象征─银色黎明勇气徽记。$B$B实现你的价值，$C，今天就加入与天谴军团作战的行列!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5405, '银色黎明委任徽章', '', '', '所有以银色黎明之名与邪恶战斗的勇士都必须佩戴我们的委任徽记，这样你们就可以向我们的军需官领取奖赏。$B$B在受到委任之后，你就可以从天谴军团士兵的尸体上收集天谴石，那是他们身份和职位的证明。将你收集到的天谴石交给我，每套天谴石都可用来换取一枚勇气和荣耀的象征─银色黎明勇气徽记。$B$B实现你的价值，$C，今天就加入与天谴军团作战的行列!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5503, '银色黎明委任徽章', '', '', '所有以银色黎明之名与邪恶战斗的勇士都必须佩戴我们的委任徽记，这样你们就可以向我们的军需官领取奖赏。$B$B在受到委任之后，你就可以从天谴军团士兵的尸体上收集天谴石，那是他们身份和职位的证明。将你收集到的天谴石交给我，每套天谴石都可用来换取一枚勇气和荣耀的象征─银色黎明勇气徽记。$B$B实现你的价值，$C，今天就加入与天谴军团作战的行列!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5528, '戈多克好酒', '', '', '你是头儿，可以喝我的酒!让你精神焕发!都是好酒，头儿……你尝尝，告诉克雷格!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5533, '通灵学院', '通灵学院坐落在凯尔达隆岛上，这所学校是亡灵天灾的一座堡垒。我们的敌人就聚居在那里，安全地进行研究并不断增强他们的力量。有一扇坚固的大门封住了唯一的入口，如果没有一把合适的钥匙，我们无论如何都无法通过它。$B$B化学家阿尔比顿一直以来都负责与通灵学院有关的事务，他应该知道如何才能获得那把钥匙。你应该向我证明你确实有存在的价值，现在我把这个任务交给你，去跟阿尔比顿谈谈关于这件事的详细情况吧。', '和西瘟疫之地冰风岗的化学家阿尔比顿谈一谈。', '你好啊，$C。我最近把大部分的精力都花在研究通灵学院上，我相信我已经找到了让你获得那把钥匙的方法。$B$B我简直不敢去想像那座学院里隐藏着怎样的邪恶和危险，$N。不知道你们这些英雄是否够胆深入其中……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5601, '小妹妹帕米拉', '我在大战中逃离了洛丹伦，在亡灵天灾席卷我的家园，将那儿变成一片可怕的废墟之前，我幸运地逃脱了！我太幸运了，但是我的家族却非常悲惨。我担心他们都已经在达隆郡战役中死去了。$B$B达隆郡就在东瘟疫之地南部山区里，你能帮我去那儿找找我的家族成员吗？我非常想念他们，特别是我的妹妹帕米拉。$B$B请帮我找到她！', '在达隆郡里找到帕米拉·雷德帕斯。', '我的姐姐杰希卡在哪儿?在我还是很小很小的小女孩的时候，她就离开了。她走的时候哭得很伤心，我不知道她为什么要哭!也许是她跌伤了脚趾吧。$B$B杰希卡还在这儿的时候，我们经常一起玩游戏，一起跳舞，一起在屋子周围采花。有时看到爸爸回来的时候我们就藏起来，然后突然跳出来吓他!$B$B回来吧，杰希卡!要是你回来了，爸爸也会回来，我们就能像以前一样在一起玩了……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5622, '月神的恩赐', '$N，你在幽影谷的事务都已经告一段落了，现在你必须去多兰纳尔。你可以在那里找到劳尔娜·晨光，她会进一步指导你沿着艾露恩之路走下去，从她那里，你可以获得你的第一件艾露尼牧师专用的长袍。$B$B小心一点，愿你一路顺风。艾露恩牧师专用的长袍。$B$B小心一点，愿你一路顺风。', '与泰达希尔的劳尔娜·晨光谈一谈。', '我很高兴珊达派你来找我，$N。教导年轻的牧师总是让我感到无比的愉悦和满足。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5623, '圣光的恩赐', '你好，年轻的牧师。是时候让你对我们的信仰有更多了解了。在你完成北郡这里的事务之后，请去闪金镇找洁塞塔牧师谈一谈。她会继续教导你，让你在圣光之道上继续成长。', '与艾尔文森林的女牧师洁塞塔谈一谈。', '我很高兴你来了，$N。关于你的未来和你在圣光之道上的修行，我们有很多要谈的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5626, '圣光的恩赐', '嘿！$N！你有时间吗？！$B$B你已经在圣光之道上修行了很长时间，应该去卡拉诺斯找马克萨恩·安沃尔谈谈了。他会向你传授更多你应掌握的知识，如果你能够证明自己的价值，他还会给你第一件代表牧师身份的长袍。$B$B现在就去吧！当你完成这里的事情以后，穿过隧道去卡拉诺斯吧——他会在那里等你的。', '与丹莫罗的马克萨恩·安沃尔谈一谈。', '哦，布兰斯托克派你来的，是吗?很好，很好!他说得没错，你应该在圣光之道上更进一步了。我要好好地培养你，让你变得更加强大……这也是你所需要的，更强大的身体，以及更强大的意志。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5627, '艾露恩之星', '', '', '你已经证明了自己的价值并引起了伊露恩的注意，$N。如果你感觉自己已经准备好了，那么我就将传授你一项艾露尼赐予我们夜精灵的独特法术。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5628, '回家', '啊，你好，是$N吗？我很高兴你能停下来和我谈谈。你如此年轻就离开了家园——我真羡慕你。我真希望我年轻的时候也有这样的勇气去周游世界。$B$B有一个你们那边的牧师不久之前在到处找你，她说要你尽快赶回达纳苏斯，跟女祭司阿兰希雅谈谈——似乎你的修行有关。我不能耽搁你太久，你尽快去吧。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '太好了，你终于回家了，$N。每当泰兰妲和我看到自己亲手训练的那些牧师走向未知的世界并最终安全返回的时候，我们总是非常高兴。你过得怎么样?伊露恩有没有在旅途中护佑你?也许在我们完成了手边的事情之后，你可以告诉我更多你在旅途中的所见所闻。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5629, '回家', '你好，$N。我知道你正忙着帮助我们的人民，但是你必须为自己花点时间了。女祭司阿兰希雅派人来这里找你，你已经得到了长者们的关注，她们觉得你必须为更重要的事情作准备了。到达纳苏斯的月神殿去找阿兰希雅，她会在那里等你。祝你好运，愿艾露恩与你同在。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '太好了，你终于回家了，$N。每当泰兰妲和我看到自己亲手训练的那些牧师走向未知的世界并最终安全返回的时候，我们总是非常高兴。你过得怎么样?伊露恩有没有在旅途中护佑你?也许在我们完成了手边的事情之后，你可以告诉我更多你在旅途中的所见所闻。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5630, '回家', '你好，$g小伙子:小姑娘;\n。很高兴看到你长途跋涉来到如此遥远的地方。我并不是想要冒犯你，但是你们的许多族人对这里的严寒都不太习惯，很高兴你可以适应这里。$B$B不久之前，你们的一个女祭司来找过你——她说要你去达纳苏斯的月神殿找女祭司阿兰希雅，还说事情很紧急，所以你最好马上回去。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '太好了，你终于回家了，$N。每当泰兰妲和我看到自己亲手训练的那些牧师走向未知的世界并最终安全返回的时候，我们总是非常高兴。你过得怎么样?伊露恩有没有在旅途中护佑你?也许在我们完成了手边的事情之后，你可以告诉我更多你在旅途中的所见所闻。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5631, '回家', '最近有一个女祭司到我们这里来找过你，年轻的$r。她说你应该尽快回到达纳苏斯的月神殿去。女祭司阿兰希雅在那里等着你，她会告诉你更多的信息。$B$B愿圣光与你同在，$N。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '太好了，你终于回家了，$N。每当泰兰妲和我看到自己亲手训练的那些牧师走向未知的世界并最终安全返回的时候，我们总是非常高兴。你过得怎么样?伊露恩有没有在旅途中护佑你?也许在我们完成了手边的事情之后，你可以告诉我更多你在旅途中的所见所闻。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5632, '回家', '哦，当然，你好，$N。我们的一位信使说她正在找你。她说在达纳苏斯那里有一些重要的事情，你应该尽快回到月神殿去找女祭司阿兰希雅。我相信她会帮助你在我们的道路上更进一步。$B$B希望你尽快地回到达纳苏斯去。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '太好了，你终于回家了，$N。每当泰兰妲和我看到自己亲手训练的那些牧师走向未知的世界并最终安全返回的时候，我们总是非常高兴。你过得怎么样?伊露恩有没有在旅途中护佑你?也许在我们完成了手边的事情之后，你可以告诉我更多你在旅途中的所见所闻。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5633, '回家', '你好，$g小伙子:小姑娘;\n。很高兴在这里见到你。愿你和你的族人一切安好。$B$B当你在我们的土地上旅行的时候，你们那边的一位祭司来找过你。她说你必须尽快回到月神殿去，很遗憾，我无法告诉你更多的内容，但是听起来挺重要的。当你回到神殿里之后，就赶快去找女祭司阿兰希雅。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '太好了，你终于回家了，$N。每当泰兰妲和我看到自己亲手训练的那些牧师走向未知的世界并最终安全返回的时候，我们总是非常高兴。你过得怎么样?伊露恩有没有在旅途中护佑你?也许在我们完成了手边的事情之后，你可以告诉我更多你在旅途中的所见所闻。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5634, '绝望祷言', '', '', '你以圣光之名做出的贡献已经成为了冒险者们的榜样。请你接受这个，作为我们对你的感谢。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5635, '绝望祷言', '你已经引起了我们高层的注意，$N。他们要你尽快到暴风城的光明大教堂去一趟。显然，他们认为你已经证明了自己的实力，也已经准备好接受下一步的训练了。当你到了那里之后，就去找高阶牧师劳瑞娜，她会进一步地指导你。祝你好运，愿圣光与你同在。', '与暴风城的高阶牧师劳瑞娜谈一谈。', '很高兴你来了，$N。我们有很多要谈的，但是最重要的是你在圣光之道上的修行情况。$B$B有些课程是所有圣光的追随者都需要学习的，如果你准备好了，我们现在就来讨论一些相关的内容吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5636, '绝望祷言', '艾露恩祝福你，好心的$r。我愿圣光与你同在，愿它一直保护着你。$B$B你们的一位牧师不久之前来找过你，他说要你到光明大教堂去找高阶牧师劳瑞娜，希望你可以尽快动身。我不会在这里浪费你宝贵的时间——你的人民需要你。', '与暴风城的高阶牧师劳瑞娜谈一谈。', '很高兴你来了，$N。我们有很多要谈的，但是最重要的是你在圣光之道上的修行情况。$B$B有些课程是所有圣光的追随者都需要学习的，如果你准备好了，我们现在就来讨论一些相关的内容吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5637, '绝望祷言', '是时候到暴风城去了，$N。光明大教堂的高阶牧师劳瑞娜要你去找她，看来她有什么事要与你商议，但是在我看来，你迄今为止表现得一直很出色，看来她要和你谈的是件好事情。$B$B不要在这里浪费太多的时间。如果我是你，我会尽快去那里的。', '与暴风城的高阶牧师劳瑞娜谈一谈。', '很高兴你来了，$N。我们有很多要谈的，但是最重要的是你在圣光之道上的修行情况。$B$B有些课程是所有圣光的追随者都需要学习的，如果你准备好了，我们现在就来讨论一些相关的内容吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5638, '绝望祷言', '刚才你们的一位牧师来这里找你，$r。他说如果我看到你，就让我告诉你赶快回光明大教堂去。他说这件事很重要，但是换了我是你的话，我不会过于担心。他似乎并不是很焦急的样子……看来是好事情。赶快动身吧，愿艾露恩与你同在，好心的$r。', '与暴风城的高阶牧师劳瑞娜谈一谈。', '很高兴你来了，$N。我们有很多要谈的，但是最重要的是你在圣光之道上的修行情况。$B$B有些课程是所有圣光的追随者都需要学习的，如果你准备好了，我们现在就来讨论一些相关的内容吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5639, '绝望祷言', '暴风城需要你，$N。高阶牧师劳瑞娜在那里等着你，她说是时候让你要证明自己的价值并进行下一阶段的训练了。不要在这里继续浪费时间，赶快动身吧，你可以在光明大教堂找到她。代我向她问好，然后向她证明自己的价值。愿圣光与你同在，$N。', '与暴风城的高阶牧师劳瑞娜谈一谈。', '很高兴你来了，$N。我们有很多要谈的，但是最重要的是你在圣光之道上的修行情况。$B$B有些课程是所有圣光的追随者都需要学习的，如果你准备好了，我们现在就来讨论一些相关的内容吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5641, '毫无畏惧', '', '', '你已经具备了成为一个伟大牧师的条件，$N。继续加油!$B$B既然你已经做好了作战的准备，那么也许我们应该再教你一些东西了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5642, '暗影守卫', '奥格瑞玛有些重要的事情在等着你去完成，$N。$B$B到这里来寻找巨魔牧师的信使并不少见，但是这次他们却显得非常着急。不要在雷霆崖耽搁太久，尽快回到精神谷去吧。', '与奥格瑞玛的乌尔库谈一谈。', '你将要进行的祭仪对于我们种族的牧师来说是非常重要的，$N。我会慢慢解释给你听的，因为你已经准备好了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5643, '暗影守卫', '和我们的牧师一样，你的种族也会让你参加种种仪式，通过这些仪式来让你掌握许多特殊的能力。我想现在就是时候了，你必须回到奥格瑞玛的精神谷去，与那里的乌尔库谈一谈。他传授给你的东西也许会对你的未来大有好处。', '与奥格瑞玛的乌尔库谈一谈。', '你将要进行的祭仪对于我们种族的牧师来说是非常重要的，$N。我会慢慢解释给你听的，因为你已经准备好了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5644, '噬灵瘟疫', '啊，今天对你来说是个美妙的日子，$N。通过你所接受的课程，我可以看出你该回去找艾萨莱斯特了。有些东西只有她能教给你，当然，那是在你证明了自己有足够的价值之后。$B$B我不想扫你的兴致，但是我记得当我还是个年轻的牧师的时候，那第一次掌握了真正的力量的感觉……强大的力量。啊，那些日子真是令人怀念啊。$B$B到幽暗城的军事区去找艾萨莱斯特吧，$N。', '与幽暗城的艾萨莱斯特谈一谈。', '很好，你准时地回来了。我们有些重要的事情要讨论，$N。你变得越来越强大，我们必须确保你已经准备好迎接更大的挑战了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5645, '毫无畏惧', '$N，高阶牧师洛汉希望能在铁炉堡与你会面。快点去吧，我强大的朋友，你的下一次试炼即将到来。虽然我希望能亲眼看着你通过你们种族的特殊仪式，但是我的职责让我必须留在这里。愿圣光照耀你前行的道路。洛汉应该是在秘法区里等你。', '与铁炉堡的高阶牧师洛汉谈一谈。', '你终于来了，很好，$N。我们的种族是光荣而又强大的，关于这一点，你不仅要自己清晰地认识到这一点，还应该让别人也有这样的感觉。你准备好了吗，$g小伙子:小姑娘;\n?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5646, '噬灵瘟疫', '艾萨莱斯特让我的同胞回到我这里来接受训练，这是她对我们的尊重，现在我也会做同样的事情。$B$B回到幽暗城去吧，$N。在军事区那里找到她，让她给你传授更多的技艺。马上回去，不要耽搁。', '与幽暗城的艾萨莱斯特谈一谈。', '很好，你准时地回来了。我们有些重要的事情要讨论，$N。你变得越来越强大，我们必须确保你已经准备好迎接更大的挑战了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5647, '毫无畏惧', '你的种族非常强大，$N。我们很高兴能称你们为盟友。你和你们的种族每一天都向发现自己起源的目标迈进一步，而且在正确的道路上更加坚定地前行。这种成功的感觉一定非常不错。$B$B最近从铁炉堡传来消息说，秘法区的高阶牧师洛汉要你回到那里去找他。如果我是你的话，我可是不会让他久等的。愿艾露恩指引你的旅程。', '与铁炉堡的高阶牧师洛汉谈一谈。', '你终于来了，很好，$N。我们的种族是光荣而又强大的，关于这一点，你不仅要自己清晰地认识到这一点，还应该让别人也有这样的感觉。你准备好了吗，$g小伙子:小姑娘;\n?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5649, '部族的传统', '啊，朋友。我们之所以加入部落，是因为他们对我们很好。他们彼此忠诚，他们教会我们很多东西——比如荣耀。但是我们的一些传统正在逐渐失去。也许兽人不认同我们所有的传统，但是这并不妨碍我们秘密地延续它们。$B$B你知道这些，所以我派你去找剃刀岭的泰金。她会向你教授更多关于我们历史的东西，她会向你教授更多关于我们部族的东西。当你准备好了之后，就去找她。', '与杜隆塔尔的泰金谈一谈。', '啊……你终于来找泰金了。很好。$B$B你应该已经知道我们已经不同于加入部落的那个时候了，我们变得更加强大。我们之所以强大，是因为我们能够适应变化─部落教会了我们许多东西。我们不再先击败我们的敌人再获取他们的力量，现在我们先获得力量，然后击败我们的敌人。$B$B虽然这其中的差别很小，但是你会明白的。我们的部族需要你去了解这些。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5651, '黑暗的恩赐', '被遗忘者通过实战学到了很多东西——而某些种族才刚刚开始领会这些东西。尽管我们的道路笼罩在黑暗之中，但是你会发现很多事物既依赖于光明，也依赖于黑暗。你学得的知识将引导你正确地利用光明与黑暗的力量，但是你要记住我的话：永远别忘记我们是在黑暗和腐化中生存的被遗忘者，黑暗是我们的家园。$B$B当你准备好学习更多的东西时，就去布瑞尔找黑暗牧师贝里尔谈谈吧。', '与提瑞斯法林地的黑暗牧师贝里尔谈一谈。', '你终于来了。年轻的$C，单靠信念是无法通过你即将面临的试炼的，紧迫感和雄心壮志也是不可或缺的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5652, '虚弱妖术', '', '', '认真上这堂课会对你很有帮助，年轻人。在战斗中，虚弱妖术可以为你在战斗中提供极大的帮助。稍后我会对你进行测试让你提升自己的能力并证明你对部族的价值。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5654, '虚弱妖术', '是时候让你跟乌尔库会面了，$N。他居住在兽人城市的精神谷中，到那儿去跟他谈谈吧。现在，该让你学习我们那些古老的法术了。你将进入我们的行列，成为一名真正的祭司。', '与奥格瑞玛的乌尔库谈一谈。', '啊，好极了，你终于来了。我们现在可以用传统的方法开始对你进行训练了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5655, '虚弱妖术', '我来此是为了确定你没有在离家过远的地方游荡，$N。他们派我来叫你返回家园，因为我们最伟大的祭司乌尔库想要跟你谈谈。到兽人城市的精神谷里去跟他谈谈，他正在等你呢。', '与奥格瑞玛的乌尔库谈一谈。', '啊，好极了，你终于来了。我们现在可以用传统的方法开始对你进行训练了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5656, '虚弱妖术', '看到各个种族的牧师们在世界各地周游，总是能让我感到温暖。我知道，世上的力量尽在我们掌控之中。因此指引你回归家园是我的荣幸，$N。$B$B奥格瑞玛城中的伟大的祭司乌尔库要你回去见他，就在精神谷里。', '与奥格瑞玛的乌尔库谈一谈。', '啊，好极了，你终于来了。我们现在可以用传统的方法开始对你进行训练了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5657, '虚弱妖术', '家，回家去，年轻的$r。$B$B你的精神领袖乌尔库要你回到他那儿，他要与你谈一谈。$B$B到奥格瑞玛城中的精神谷去找他。', '与奥格瑞玛的乌尔库谈一谈。', '啊，好极了，你终于来了。我们现在可以用传统的方法开始对你进行训练了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5658, '虚弱之触', '', '', '啊，年轻的$g牧师:女牧师;\n，我很高兴你回来这里。我会帮你上一堂令你永生难忘的课。你准备好了吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5660, '虚弱之触', '你已离家很远了，$c。你的那座地下的城市需要你。你的女主人，那位召唤你回家的艾萨莱斯特需要你回到她身边。有些东西你只能从她那儿学到，就像我的部落一样。别在这儿呆得太久了，你该迅速赶往幽暗城的军事区。', '与幽暗城的艾萨莱斯特谈一谈。', '啊，好极了，又来了一个。时间对我来说不成问题，但是对你而言就至关重要了。你要学习的东西还很多，而我想传授给你的也很多。你必须证明自己的价值，以此来赢得丰厚的回报。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5661, '虚弱之触', '血蹄村离你的家园很远，$N。我来此是为了寻找自己部落的祭司，将他们带回去同我们的领袖谈谈，但是这并不意味着我就没法帮你了。$B$B我听说你们的牧师领袖想要召集所有的被遗忘者——让他们去跟她学点什么。$B$B回到你的城市去，在军事区跟艾萨莱斯特见一面吧。', '与幽暗城的艾萨莱斯特谈一谈。', '啊，好极了，又来了一个。时间对我来说不成问题，但是对你而言就至关重要了。你要学习的东西还很多，而我想传授给你的也很多。你必须证明自己的价值，以此来赢得丰厚的回报。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5662, '虚弱之触', '我对你和你的族人表示尊重，$N。我一般只向我自己的同胞传授技艺，你的课程开始于那座曾经被称作洛丹伦的城市中。$B$B如果你要学习那些只有你们才能掌握的技能，就回到幽暗城的军事区里去找艾萨莱斯特吧。', '与幽暗城的艾萨莱斯特谈一谈。', '啊，好极了，又来了一个。时间对我来说不成问题，但是对你而言就至关重要了。你要学习的东西还很多，而我想传授给你的也很多。你必须证明自己的价值，以此来赢得丰厚的回报。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5663, '虚弱之触', '艾萨莱斯特正在召集她管辖的所有牧师，我们要指引那些较为年轻的成员到幽暗城去进行更多的训练。如果你真的认为自己是我们中的一员，那么你也应该回到那儿去。$B$B你可以在幽暗城深处的军事区里找到艾萨莱斯特。', '与幽暗城的艾萨莱斯特谈一谈。', '啊，好极了，又来了一个。时间对我来说不成问题，但是对你而言就至关重要了。你要学习的东西还很多，而我想传授给你的也很多。你必须证明自己的价值，以此来赢得丰厚的回报。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5672, '艾露恩的赐福', '', '', '通过向伊露恩和我们的同胞作出奉献，你已经达到了一种并非所有人都能达到的境界。按照传统，我将传授给你更为强大的技能作为对你的回报，你接受吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5673, '艾露恩的赐福', '你知道自己可以任何时候拜访我们的训练师，$N，但是有一些东西是无法从我们这里学到的——那些由艾露恩赐予你的东西。她将特殊的能力赋予她的信徒，如果我没有弄错的话，现在是你返回月神殿接受试炼的时候了。$B$B回到那儿去，与女祭司阿兰希雅谈谈吧。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '伊露恩护佑着你，让你如此迅速地回到我们身边。现在是你修行之旅中的一个重要时刻，我们对此都非常重视。当你从旅途的劳顿中恢复过来之后就告诉我一声，然后我们就可以讨论一下诸如你的试炼和未来之类的事情了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5674, '艾露恩的赐福', '今天是个好日子，$N。你已经到了学习那些只有暗夜精灵牧师才能掌握的特有技能的年纪了，不过负责训练你的并不是我。你应该尽快了结你在此地的事务，然后返回月神殿去跟女祭司阿兰希雅谈谈。她将对你进行试炼以确保你已准备就绪，只有通过了她的试炼，你才能学到艾露恩的恩赐。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '伊露恩护佑着你，让你如此迅速地回到我们身边。现在是你修行之旅中的一个重要时刻，我们对此都非常重视。当你从旅途的劳顿中恢复过来之后就告诉我一声，然后我们就可以讨论一下诸如你的试炼和未来之类的事情了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5675, '艾露恩的赐福', '$g小伙子:小姑娘;\n，不要虚度光阴，你该回一趟达纳苏斯了。女祭司阿兰希雅派人捎信来通知你返回家园进行试炼。他们似乎认为你已准备好接受新的试炼了，就像那些信仰圣光的人也要接受试炼一样。阿兰希雅说她正在月神殿等你，祝你好运。', '与达纳苏斯的女祭司阿兰希雅谈一谈。', '伊露恩护佑着你，让你如此迅速地回到我们身边。现在是你修行之旅中的一个重要时刻，我们对此都非常重视。当你从旅途的劳顿中恢复过来之后就告诉我一声，然后我们就可以讨论一下诸如你的试炼和未来之类的事情了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5676, '奥术回馈', '', '', '秘法魔法是我们最强大的敌人，我们不得不学习一些魔法来保护自己免受它的伤害。$B$B我将传授给你一种法术，它可使你和你的同伴能够应付那些拥有这种力量的敌人。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5677, '奥术回馈', '我很想向你传授使用圣光的技能，但是这不是该由我们来做的事情。现在，你应该回到暴风城里，去找你的同伴，$N……相信我，我没有冒犯你的意思。当你回到光明大教堂的高阶牧师劳瑞娜那儿时，你就会了解我在说什么了——现在是你的种族为了未来而训练你，使你在同类人中出类拔萃的时候了。', '与暴风城的高阶牧师劳瑞娜谈一谈。', '啊，你真是很准时，$N。我先前还在怀疑是不是所有的信差都成功地完成了他们的使命呢。幸运的是他们都做到了，否则我敢打赌你现在仍在到处旅行，在世界各地了解我们的人民所面对的威胁。$B$B你准备好了吗?我是说准备接受更多的试炼。你的能力提高得很快，我想你已经做好对我们的信仰加深了解的准备了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5679, '噬灵瘟疫', '', '', '如果你准备好了，我将传授噬灵瘟疫法术给你，$N。这可不是一个无关痛痒的小把戏，它会在战斗中派上大用场的。好好练习吧─你很快就要接受试炼了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5680, '暗影守卫', '', '', '你的祭仪很快就准备好了。我要传授给你的法术会在战斗中派上大用场的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5722, '寻找背包', '穴居人并不是怒焰裂谷中唯一令玛加萨感兴趣的东西。她已经得到消息说她的仆从——玛尔·恐怖图腾在怒焰裂谷找到了某种奇特的东西，但是他没能活着把它拿出来。她希望能找到玛尔的遗体——如果他还有遗体的话——以及他在试图与穴居人交谈的过程中发现的东西。$B$B如果你能将玛加萨感兴趣的东西交给她，我敢肯定她会慷慨地奖赏你。$B那么，到奥格瑞玛最黑暗的区域去找寻怒焰裂谷吧。', '在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。', '尸体似乎曾被棍棒或拳头猛烈地击打过，伤痕累累，但是大部分衣物和装备看起来还是很新的，似乎穴居人并没有过分注重这些东西。$B$B你开始搜查尸体，寻找一切有可能帮助玛加萨的东西。', '尸体', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5729, '隐藏的敌人', '我想下一步应该让你接近尼尔鲁。如果他像报告中所说的那样焦虑不安，那么我们也许能做成两件事。第一，你可以获得关于议会或者至少是 火刃氏族的更多情报；第二，你也许能取得他的信任，他会让你协助他。鉴于当前领导层的混乱状况，他可能会将你当作填补空缺的人选。$B$B回到他那里去，再跟他谈谈，但是别露出马脚来。', '与奥格瑞玛的尼尔鲁·火刃谈一谈。', '什么?!哦，$C……我向你道歉。我的愤怒快可以与一头狂暴的科多兽相提并论了……但这也许是我的错。在派遣他们前往怒焰裂谷之前，我就应该了解他们惹祸上身的可能性。似乎巴札兰和耶戈什都是在毫无防备的情况下被索尔的手下杀死的。他们死得真不是时候，但是如今已经于事无补了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5730, '隐藏的敌人', '你是我的得力助手！做好准备，$c。不久之后我就会召唤你。$B$B我花在灼刃氏族上的时间看来是白费了，但是这不意味着暗影议会的其它计划也会受到影响。我要尽可能地消除在怒焰裂谷的损失。同时，我会让我在贫瘠之地和灰谷的部下继续执行新的计划。尽快回到我这里来。', '与奥格瑞玛的萨尔谈一谈，告诉他你了解到的东西。', '梣谷?嗯，我没有听说过梣谷有议会或者燃刃氏族的势力存在。我的探子会去调查的，$N。你干得很出色。$B$B至于现在，去好好休息吧，然后继续执行其他的任务。不久之后我会再次召唤你。$B$B为了部落的荣耀!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5846, '爱与家庭', '当泰兰还是孩子的时候，我们全家经常去凯尔达隆度假。我们最后一次去那里时，一位名叫瑞弗蕾的艺术家为我们画了一张在湖边漫步的画。这是最能让我回想起与泰兰和卡兰德拉在一起时的美好时光的东西。那个时候我牵着我的妻子和儿子，心中充满了无限的爱意。$B$B如果那幅画还存在的话，你必须找到它。$B$B去凯尔达隆那座废弃的岛上看看那副画或者那个画家是不是还在吧。', '到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。', '我怎么能忘记?这座岛上的许多生灵在遭遇劫难之前都中了诅咒，从而丧失了他们最美好的记忆。$B$B我也中了诅咒，但是和他们不一样─我记得所有的东西……$B$B也许你询问我的东西就是我在这些遗迹中游荡的原因。也许我所告诉你的东西能让我得到彻底的解脱。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5902, '瘟疫与你', '现在我们有足够的白蚁了，把这只铁桶拿到壁炉谷南边的北山伐木场去——就在那条通往镇子的小路的西边。$b$b当你到了那里之后，就在伐木场的中间找个高一点的地方，比如一只箱子或者别的什么东西，把桶放在上面，然后打开桶盖。接下来的事情就交给那些白蚁吧。完事之后回到我这里来，我会奖励你的。', '到西瘟疫之地的北山伐木场去找个合适的地方，在那里放下一桶瘟疫白蚁。', '当你把木桶放在木箱上之后，白蚁就开始不停地忙碌了。', '你把木桶放在了木箱上，然后在旁边找了一根撬棍打开了它。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5904, '瘟疫与你', '现在我们有足够的白蚁了，把这只铁桶拿到壁炉谷南边的北山伐木场去——就在那条通往镇子的小路的西边。$b$b当你到了那里之后，就在伐木场的中间找个高一点的地方，比如一只箱子或者别的什么东西，把桶放在上面，然后打开桶盖。这样，白蚁就会开始它们的工作，然后让那个伐木场彻底完蛋。', '到西瘟疫之地的北山伐木场去找个合适的地方，在那里放下一桶瘟疫白蚁。', '当你把木桶放在木箱上之后，白蚁就开始不停地忙碌了。', '你把木桶放在了木箱上，然后在旁边找了一根撬棍打开了它。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5923, '响应召唤', '朋友，打扰一下……$B$B我注意到玛斯雷·驭熊者已经放出话来，说想要和你谈谈。看样子你即将开始崭新的生活——去接受德鲁伊的训练，他将亲自训练你。玛斯雷是大德鲁伊的助手，也是泰达希尔中最为睿智、最为威严的德鲁伊之一。$B$B他居住在达纳苏斯的塞纳里奥区，就在范达尔·鹿盔所在的那棵树的第二层。', '与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。', '年轻的德鲁伊，很高兴今天可以在这里看到你。现在是你大步迈向一个更广阔世界的时候了。$B$B我们都向往着为自然效力。动物和植物是我们的朋友，也是我们力量的泉源。我们选择为它们，也是为守护自然的平衡而奉献自己的一生。作为进入这个世界的第一步，你首先要学习的是熊之道，以及肉体和心灵所蕴含的力量。$B$B做好准备吧!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5924, '响应召唤', '朋友，打扰一下……$B$B我注意到玛斯雷·驭熊者已经放出话来，说想要和你谈谈。看样子你即将开始崭新的生活——去接受德鲁伊的训练，他将亲自训练你。玛斯雷是大德鲁伊的助手，也是泰达希尔中最为睿智、最为威严的德鲁伊之一。$B$B他居住在达纳苏斯的塞纳里奥区，就在范达尔·鹿盔所在的那棵树的第二层。', '与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。', '年轻的德鲁伊，很高兴今天可以在这里看到你。现在是你大步迈向一个更广阔世界的时候了。$B$B我们都向往着为自然效力。动物和植物是我们的朋友，也是我们力量的泉源。我们选择为它们，也是为守护自然的平衡而奉献自己的一生。作为进入这个世界的第一步，你首先要学习的是熊之道，以及肉体和心灵所蕴含的力量。$B$B做好准备吧!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
