INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5926, '响应召唤', '朋友，打扰一下……$B$B我注意到图拉克·符文图腾已经放出话来，说想要和你谈谈。看样子你即将开始崭新的生活——去接受德鲁伊的训练，他将亲自训练你。图拉克是大德鲁伊的助手，也是最为睿智、最为威严的德鲁伊之一。$B$B他居住在雷霆崖，就在长者高地上的塞纳里奥议会大帐里。', '与雷霆崖长者高地上的图拉克·符文图腾谈一谈。', '年轻的德鲁伊，很高兴你在此踏入正途。现在是你大步迈向一个更广阔的世界的时候了。$B$B我们都向往着为自然效力。动物和植物是我们的朋友，也是我们力量的源泉。我们选择为它们，也是为守护自然的平衡而奉献自己的一生。作为进入这个世界的第一步，你首先要学习的是的熊之道，以及肉体和心灵所蕴含的力量。$B$B准备好了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
