INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5928, '响应召唤', '朋友，打扰一下……$B$B我注意到图拉克·符文图腾已经放出话来，说想要和你谈谈。看样子你即将开始崭新的生活——去接受德鲁伊的训练，他将亲自训练你。图拉克是大德鲁伊的助手，也是最为睿智、最为威严的德鲁伊之一。$B$B他居住在雷霆崖，就在长者高地上的塞纳里奥议会大帐里。', '与雷霆崖长者高地上的图拉克·符文图腾谈一谈。', '年轻的德鲁伊，很高兴你在此踏入正途。现在是你大步迈向一个更广阔的世界的时候了。$B$B我们都向往着为自然效力。动物和植物是我们的朋友，也是我们力量的源泉。我们选择为它们，也是为守护自然的平衡而奉献自己的一生。作为进入这个世界的第一步，你首先要学习的是的熊之道，以及肉体和心灵所蕴含的力量。$B$B准备好了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5929, '巨熊之灵', '在月光林地的西北部住着一个充满智慧而又高贵的生物，我们称它为巨熊之灵。对所有德鲁伊来说，它能够教授他们关于熊的第一课——关于熊的最本质的东西。所有的德鲁伊都要去寻找巨熊之灵，寻求它的智慧，你也不例外。$B$B现在就到巨熊之灵那里去，学习它教给你的东西吧。当它对你的学习感到满意之后，你就可以回到永夜港来找我了。我们会检验你是否真的学会了它教给你的东西。', '到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。', '在你回到德迪利特面前的时候，他在自己面前的空气中画了一个无形的符记。一股力量光环笼罩着这位微笑着的德鲁伊。$B$B「我感受到了你的智慧，年轻的$r，在我们第一次见面的时候它并没有体现出来。你的眼神体现出了你的力量和求知欲─虽然这种意愿还没有集中起来。现在你要学会如何集中你的力量，并适应熊的天性，让它为你所用。」', '只有当巨熊之灵让你回来的时候，你才可以回来。除非获得了它的祝福，否则你的训练是无法继续的。', '到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5930, '巨熊之灵', '在月光林地的西北部住着一个充满智慧而又高贵的生物，我们称它为巨熊之灵。对所有德鲁伊来说，它能够教授他们关于熊的第一课——关于熊的最本质的东西。所有的德鲁伊都要去寻找巨熊之灵，寻求它的智慧，你也不例外。$B$B现在就到巨熊之灵那里去，学习它教给你的东西吧。当它对你的学习感到满意之后，你就可以回到永夜港来找我了。我们会检验你是否真的学会了它教给你的东西。', '到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。', '在你回到德迪利特面前的时候，他在自己面前的空气中画了一个无形的符记。一股力量光环笼罩着这位微笑着的德鲁伊。$B$B「我感受到了你的智慧，年轻的$r，在我们第一次见面的时候它并没有体现出来。你的眼神体现出了你的力量和求知欲─虽然这种意愿还没有集中起来。现在你要学会如何集中你的力量，并适应熊的天性，让它为你所用。」', '只有当巨熊之灵让你回来的时候，你才可以回来。除非获得了它的祝福，否则你的训练是无法继续的。', '到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5931, '返回达纳苏斯', '我们该分道扬镳了，年轻的$r，现在你必须回到派你来这里的导师那里。玛斯雷·驭熊者和自然相处得很好——即使他正居住在自然平衡陷入混乱的地方。听从他的指导，你很快就可以完成你作为自然保护者的第一课了。$B$B现在就去吧，年轻的$r。我们会再次相见的。', '回到达纳苏斯，与塞纳里奥区的玛斯雷·驭熊者谈一谈。', '欢迎回来，$N。我感觉到你在第一次与巨熊之灵会面时，跟别的追寻熊的力量的德鲁伊一样……感觉有些困惑，但是意愿很强烈。我以前也是这样的。$B$B从艾泽拉斯世界存在以来，巨熊之灵就是它的一部分。我们要依赖它的智慧和力量来完成我们的任务。现在，你应该接受第一个试炼了。仔细听好……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5932, '返回雷霆崖', '我们该分道扬镳了，年轻的$r，现在你必须回到派你来这里的导师那里。虽然牛头人在领悟塞纳留斯的教义这方面还是新手，但是图拉克·符文图腾和大自然的关系非常融洽。听从他的指导，你很快就可以完成你作为自然保护者的第一课了。$B$B现在就去吧，年轻的$r。我们会再次相见的。', '回到雷霆崖，与长者高地的图拉克·符文图腾谈一谈。', '欢迎回来，$N。我感觉到你在第一次与巨熊之灵会面时，跟别的追寻熊的力量的德鲁伊一样……感觉有些困惑，但是意愿很强烈。我以前也是这样的。$B$B只要艾泽拉斯世界存在，巨熊之灵就是它的一部分。我们牛头人聆听熊灵所说的话，遵从他的指示，我们逐渐茁壮。现在，你应该接受第一个试炼了。仔细听好……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (5961, '女妖之王的勇士', '我很高兴地看到强大的勇士不断加入我们的行列。随着时间的推移，我们的军队数量和战斗力在不断提升。也许现在已经到了考验你的勇气的时候了，$c。$B$B我手下最勇猛的大将是纳萨诺斯·凋零者。我们之中很少有谁能比他更具有奉献精神和活力了。$B$B到东瘟疫之地去找他。他就住在玛瑞斯农场，偶尔也会在附近徘徊，杀死沿途所遇到的一切亡灵天灾和联盟成员。', '与东瘟疫之地的纳萨诺斯·凋零者谈一谈。据说他居住在玛瑞斯农场。', '黑暗女王当然认为你没有资格会见她的勇士。你是来这里让我的狗饱餐一顿的吗?看起来你没有别的理由来打扰我们。', '<纳萨诺斯咆哮着。>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6001, '身心之力', '在奥伯丁的正东方有很多月夜枭兽的洞穴，离奥伯丁最近的洞穴内有一块月夜枭兽之石。月爪枭兽是这块石头的守护者，只有当塞纳里奥月尘洒在石头上的时候它才会出现。月爪枭兽的体内有一种力量，你必须得到这种力量，才能成为真正的利爪德鲁伊。$B$B你已经获得了使用塞纳里奥月尘的权力，$N……现在向我证明你已经赢得了拥有身心之力的权力！', '使用奥伯丁的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。$B$B任务完成之后，与达纳苏斯的玛斯雷·驭熊者谈一谈。', '你终于大步迈进了一个更加广阔的世界，$N。我感觉到你已经掌握了巨熊之灵所传授的知识，还有月爪枭兽曾经拥有的力量。$B$B在你的面前没有其他的障碍了……现在，让我告诉你成为一个利爪德鲁伊意味着什么吧!', '当你面对挑战的时候，你对身心之力的理解就会更加充分。在你领会那种力量的精髓之前，我无法帮你做什么。', '击败月爪枭兽并吸取它所拥有的身心之力。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6065, '猎人之道', '你好，年轻的猎人。看起来你已经准备好要驯服一头野兽，并将其训练成自己的同伴了。$B$B你必须去见一见血蹄村的雅文·刺鬃，他可以帮助你驯服自己的第一头宠物。', '与莫高雷的血蹄村的雅文·刺鬃谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
