INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6076, '猎人之道', '你好，年轻的猎人。看起来你已经准备好要驯服一头野兽，并将其训练成自己的同伴了。$B$B你必须去见一见卡拉诺斯的格瑞夫，他可以帮助你驯服自己的第一头宠物。', '与丹莫罗的卡拉诺斯的格瑞夫谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6081, '训练野兽', '你现在已拥有了驯服宠物的力量，但是你还必须掌握训练宠物的技能。$B$B去奥格瑞玛吧。你得去跟奥玛克——我们最敬重的猎人谈一谈，他会传授你训练新宠物的技能。奥玛克就在荣誉谷内。$B$B祝你好运，$N。', '与奥格瑞玛的奥玛克谈一谈。', '嗯，一个年轻的猎人。我将向你传授训练和操纵宠物的方法。你不仅可以让宠物学习新的技能，还可以喂养它们，如果它们在战斗中阵亡的话，你还可以让它们复活。$B$B现在你可以走了，年轻的猎人。我们以后会再见面的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6086, '训练野兽', '$N，现在你已具备了驯服宠物的能力，但是你还必须掌握训练它的方法。$B$B到铁炉堡的军事大厅去跟我们最尊敬的驯兽师贝莉亚·雷岩谈谈吧，她将向你传授训练新宠物的方法，那么赶快出发吧，$G小子:小姑娘;\n！$B$B贝莉亚是个友好的驯兽师，你应该能和她相处得很融洽。祝你好运，$N。', '与铁炉堡的贝莉亚·雷岩谈一谈。', '新来的?我明白了，你正在向成为一名优秀猎人的目标而努力。$B$B没错，我将向你传授训练和操纵宠物的技巧。你不仅可以给你的宠物传授新的技能，还可以喂养它们，如果它们在战斗中阵亡的话，你还可以使它们复活。$B$B记住，如果你想要最大限度地从新宠物那儿获益，那么你就要尊重它，好好对待它。作为回报，你的宠物将成为你最忠实的朋友。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6089, '训练野兽', '现在你已经拥有了驯服宠物的能力，但是你还必须学会训练它的方法。$B$B到雷霆崖去吧，在那里同最受尊敬的猎人浩特·雷角谈谈。如果他认可你的能力，便会将训练新宠物的方法传授给你。$B$B浩特曾经驯服过世界上最强大、最可怕的野兽，他与大地母亲的联结很紧密，你可以从他那儿学到许多东西。祝你好运，$N。', '与雷霆崖猎人高地的浩特·雷角谈一谈。', '我明白了，年轻的猎人。我可以向你传授训练和操纵宠物的技巧。你不仅可以给你的宠物传授新的技能，还可以喂养它们，如果它们在战斗中阵亡的话，你还可以使它们复活。$B$B现在，继续踏上你的旅程吧，愿大地之母保佑你。我们以后一定会再见面的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6103, '训练野兽', '现在你已经拥有驯服宠物的能力了，但是你还必须学会如何训练它。$B$B到达纳苏斯去跟我们最尊敬的猎人——祖卡斯特谈一谈吧。她将传授你训练新宠物的技能，赶快出发吧。$B$B虽然祖卡斯特看起来很严厉，但她总是乐于看见新的猎人诞生。对她保持尊敬，她也会对你态度和蔼。祝你好运，$N。', '与达纳苏斯塞纳里奥区的祖卡斯特谈一谈。', '嗯，一个刚刚出道的猎手。我可以把驯服和引导宠物的技能传授给你，你不仅可以教你的宠物学习新的技能，还可以喂养它，如果它在战斗中死亡的话，你还可以复活它。$B$B记住，$N，永远对自然的平衡保持敬畏的态度，对大自然永远抱有崇敬之情。出发吧，我们以后会再见面的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6121, '新的课程', '你应该好学习有关德鲁伊的解毒能力的知识了，$N。塞纳留斯赐予了我们特殊的能力，让我们只需施展一个简单的法术就能净化世间最邪恶的剧毒。但是这份礼物可不是随便就可以送给你的……为了保证你能深刻地理解这门新的课程，你要像个刚刚入行的新手那样，逐一了解各种毒药的特点。$B$B到月光林地去跟德迪利特·星焰谈谈吧，他会在那里向你传授这些知识的。', '到月光林地去，与永夜港的德迪利特·星焰谈一谈。', '你好，年轻的德鲁伊，很高兴见到你来学习解毒知识。$B$B大多数的德鲁伊都是通过事先准备好的试炼来完成学习的，而你则会有些不同。在贫瘠之地的十字路口出现了许多起动物中毒事件，那里的居民已经没法控制局面了。最终，他们派了一个代表来我这里，要求月光林地为他们提供帮助，我们准备派你去。这不是练习─你要做的是拯救许多生命的严肃工作。你要牢记这一点。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6125, '解毒之术', '你已经知道在没有精神支柱的情况下清除毒素有多么困难了。你很快就会拥有可以轻松解除毒性的能力了，所以请牢记其他的生灵在抵抗毒素侵袭时所承受的痛苦。$B$B现在，你应该返回达纳苏斯去找玛斯雷·驭熊者了，$N。既然你已经领悟了这一课的内容，那么他就应该会把这个非常重要的法术教给你。$B$B再见，年轻的德鲁伊。', '回到达纳苏斯塞纳里奥区的玛斯雷·驭熊者那里。', '欢迎回来，自从你离开之后，我就一直在关注你的进展。我必须承认，奥伯丁的状况让我感到很惊讶。这确实需要进一步的调查，这类毒物一旦扩散开来，对自然平衡所造成的影响就会非常可怕。$B$B你可以从容地面对压力，为此，我将奖励给你清除毒素的力量。好好使用它，$N……好好使用它。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6126, '新的课程', '你应该好学习有关德鲁伊的解毒能力的知识了，$N。塞纳留斯赐予了我们特殊的能力，让我们只需施展一个简单的法术就能净化世间最邪恶的剧毒。但是这份礼物可不是随便就可以送给你的……为了保证你能深刻地理解这门新的课程，你要像个刚刚入行的新手那样，逐一了解各种毒药的特点。$B$B到月光林地去跟德迪利特·星焰谈谈吧，他会在那里向你传授这些知识的。', '到月光林地去，与永夜港的德迪利特·星焰谈一谈。', '你好，年轻的德鲁伊，很高兴见到你来学习解毒知识。$B$B大多数的德鲁伊都是通过事先准备好的试炼来完成学习的，而你则会有些不同。在贫瘠之地的十字路口出现了许多起动物中毒事件，那里的居民已经没法控制局面了。最终，他们派了一个代表来我这里，要求月光林地为他们提供帮助，我们准备派你去。这不是练习─你要做的是拯救许多生命的严肃工作。你要牢记这一点。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6130, '解毒之术', '你已经知道在没有精神支柱的情况下清除毒素有多么困难了。你很快就会拥有可以轻松解除毒性的能力了，所以请牢记其他的生灵在抵抗毒素侵袭时所承受的痛苦。$B$B现在，你应该返回雷霆崖去找图拉克·符文图腾了，$N。既然你已经领悟了这一课的内容，那么他就应该会把这个非常重要的法术教给你。$B$B再见，年轻的德鲁伊。', '回到雷霆崖长者高地的图拉克·符文图腾那里。', '欢迎回来，自从你离开之后，我就一直在关注你的进展。我必须承认，十字路口的状况让我感到很惊讶。这确实需要进一步的调查，这类毒物一旦扩散开来，对自然平衡所造成的影响就会非常可怕。$B$B你可以从容地面对压力，为此，我将奖励给你清除毒素的力量。好好使用它，$N……好好使用它。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6141, '安东修士', '我的好兄弟安东修士听说在卡利姆多大陆的某处有亡灵出没的传闻——那个地方叫做凄凉之地。安东立即就决定要到那里去消灭亡灵！$B$B他正在寻找有勇气和决心帮助他的冒险者。如果你愿意的话，就去找安东谈谈吧。他在凄凉之地的尼耶尔前哨站里。', '与凄凉之地尼耶尔前哨站的安东修士谈一谈。', '我听说了有援军要来的消息，你就是来帮助我们的那个$r吗?你是来帮助血色十字军征讨亡灵的吗?$B$B如果是这样，那么请靠近些听我说……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6144, '上级的命令', '命令已经传达下来了，$c。瓦里玛萨斯要求我把手下最能干的特工派回幽暗城去，完成一项高度机密的任务。$B$B不幸的是，我最能干的特工三年多以前就基本上死绝了，代替他们的是一大群不长脑子的蠢货。$B$B<纳萨诺斯冷冷地注视着你。>$B$B立即到幽暗城去向布拉贡·血拳报告。不要给我添麻烦，$c！', '到幽暗城去与布拉贡·血拳谈一谈。', '大十字军稳坐在血色十字军堡垒中，与此同时，他的军队涌入你们的土地，亵渎你们的纪念碑，屠杀你们的人民。$B$B黑暗女王已经命令我亲自对付这条害虫了，你会成为被遗忘者的先遣力量。', '你就是纳萨诺斯最能干的特工?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6147, '向纳萨诺斯复命', '大十字军有一个不寻常的要求。嗯，不管怎么说……他的命令必须执行。返回血色堡垒去，告诉他圣贤很快就要上路了。$B$B我们将尽全力防范，确保她毫发无伤地抵达斯坦索姆。', '带着新情报返回纳萨诺斯·凋零者那里。', '这些傻瓜!我的计谋成功了!等着吧，$C。我们就要发动无情的攻击了!', '什么?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6182, '第一个和最后一个', '纳萨诺斯·玛瑞斯是历史上第一个也是最后一个人类游侠领主，他是希尔瓦娜斯·风行者的学生。$B$B我们一直以为纳萨诺斯在五年前的洛丹伦保卫战中牺牲了。尽管他的尸体从未被发现，但人们都认为他不大可能从东瘟疫之地逃出来。$B$B马迪亚斯·肖尔一直在调查这起失踪案，而且可能有了一些新的消息。立即去向他汇报。马迪亚斯就住在旧城区的兵营里。', '与暴风城的马迪亚斯·肖尔谈一谈，他住在旧城区的兵营里。', '在收到几起关于东瘟疫之地有被遗忘者异常活动的报告后，军情七处派出了一些密探前去调查。调查的结果令人感到不安。', '你是乌瑞恩派来的?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6183, '逝者的荣耀', '我手下最强的五个人被派去调查玛瑞斯的那件事情。只有一个人回来了，三天之后，他在睡梦中死掉了。$B$B我们从他混乱而含糊的喃喃自语中没有得到什么有用情报，只听出来两个词：“纳萨诺斯”和“凋零者”。$B$B我没有足够的人手来继续调查，而拉文霍德也不愿意协助我们。我们必须对这件事情调查到底，即便只是为了表示对逝者的哀悼。你愿意帮忙吗？', '如果你愿意接这个任务，就再和马迪亚斯·肖尔谈一谈。', '<马迪亚斯点了点头。>$B$B我就知道乌瑞恩会派出值得尊敬的人 - 联盟可靠的勇士。', '你做出决定了吗，$N?你愿意在此时此刻再次挺身而出，为联盟效力吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6184, '弗林特·沙多摩尔', '到目前为止，我们掌握的唯一信息就是纳萨诺斯·玛瑞斯也许已经被这个凋零者给杀死了。而且我们认为凋零者就是杀死那些军情七处密探的恶魔。$B$B另一个军情七处的间谍弗林特·沙多摩尔正驻守在西瘟疫之地冰风岗的联盟营地中。去找到他，他会告诉你瘟疫之地的现状，并派给你下一步的任务。$B$B祝你好运，$N。', '到西瘟疫之地的冰风岗去跟弗林特·沙多摩尔会面。', '第一个任务很简单，$N。进去，然后出来。侦察……', '你来得正好。很高兴见到你，$N。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6186, '凋零者', '<弗林特面无血色。>$B$B这是纳……纳萨诺斯干的？纳萨诺斯是就是凋零者？$B$B为什么？他……他那么高贵——他是个受人尊敬的游侠领主，是唯一接受过高等精灵训练的人类。他居然是亡灵的一员？$B$B我……我很抱歉要再请你做一件事，$N，但是你必须立刻将这件事情告诉瓦里安·乌瑞恩国王。赶快去暴风城吧。', '回到暴风城，将纳萨诺斯·玛瑞斯的下落报告给瓦里安·乌瑞恩国王。', '被遗忘者的尖兵?女妖之王的勇士?$B$B<瓦里安.乌瑞恩国王显得相当沮丧。>$B$B太荒谬了……', '你这么快就回来了，$N。你从瘟疫之地带来了什么消息?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6344, '尼莎·影歌', '我的朋友尼莎·影歌是鲁瑟兰村的一个渔业商人，她要把一只包裹送到黑海岸去，所以她正在找人帮忙。$B$B如果你感兴趣的话，那就去找尼莎吧。从达纳苏斯到鲁瑟兰村去的传送门就在神殿花园的西边。', '与尼莎·影歌谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6382, '灰谷狩猎', '你的力量给我留下了深刻的印象，$c。你对狩猎兴趣昂然，这让我相信你有能力参与更大规模的狩猎行动……面临更大的挑战。$B$B灰谷森林是一大片未开化的土地，部落正在为控制这片土地而努力。如果你想要在那里证明自己的能力，就到碎木哨岗去寻求塞娜尼·雷心的指点吧。那个前哨站就在贫瘠之地的正北方。', '与灰谷碎木哨岗的塞娜尼·雷心谈一谈。', '欢迎来到这块新的疆土，$N。梣谷是一片充满机遇的土地，像你这样年轻的$C肯定可以在这里找到无数证明自己实力的机会。在这里的前哨站到处转转，然后到佐拉姆海岸去，部落在那儿设有另一个岗哨。$B$B我看得出你是到这儿来学习狩猎的。用心学习吧，我将很乐意与你分享我所掌握的知识。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6383, '灰谷狩猎', '', '', '梣谷中生活着三头强大的生物，你可以寻找它们，与它们进行较量。在这一过程中，你会对自身的能力有更多了解。你要找的生物是:熊怪乌萨苟斯、夜刃豹萨杜布拉和角鹰兽沙普塔隆。$B$B它们都是强而有力的生物，或许你需要借助同伴的力量才能制服它们。如果你能击败它们，就拿些证物回来给我看看吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6401, '卡雅还活着', '把这个好消息告诉卡雅的姑母，烈日石居的塔姆拉·荒原！告诉她卡雅还活着！我们以为在村子经历了那场劫难之后她就失踪了。沿着西面的路去烈日石居吧。', '把这个好消息告诉烈日石居的塔姆拉·荒原。', '天啊，我的侄女卡雅还活着!这真是个好消息。谢谢你，$N。', '你把这个好消息告诉塔姆拉.荒原了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6402, '集合在暴风城', '你必须到暴风城的城门去，在那里跟温德索尔元帅碰面。$B$B温德索尔即将披露的事情将震撼整个暴风王国！$B$B别想逞英雄，$N。你必须集合一支强大的军队！召集你的同胞，准备战斗吧！', '前往暴风城的城门。与侍卫洛文交谈，他会通知温德索尔元帅你已经到达了。', '在开始之前，我要你首先集合一支军队。毕竟我们要面对的是一条龙!', '我就知道你会来的，$N!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6523, '保护卡雅', '谢谢你救了我！我们必须赶快离开，不然很快就会被发现的。请护送我回到阿帕拉耶营地去。到了那里，我就知道回去的路了。$B$B我的父亲玛卡巴·扁蹄得知我安全回家之后一定会很高兴的。', '护送卡雅·扁蹄回到阿帕拉耶营地，然后到石爪山东南边界附近的玛卡巴·扁蹄那里去复命。', '卡雅还活着!$N，我要感谢你救了她的命。', '', '护送卡雅·扁蹄回到阿帕拉耶营地', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6541, '向卡德拉克报到', '你去过北面的灰谷没有？部落最近在那里的佐拉姆海岸旁设立了哨所，我们经常派一些刚刚招募的新兵来协助防守前线。$B$B如果你愿意的话，就到贫瘠之地北部的哨塔里找卡德拉克。他正要去灰谷进行战斗，应该可以给你进一步的指示。', '到贫瘠之地北部的卡德拉克那里报到。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6542, '向卡德拉克报到', '你去过北面的灰谷没有？部落最近在那里的佐拉姆海岸旁设立了哨所，我们经常派一些刚刚招募的新兵来协助防守前线。$B$B如果你愿意的话，就到贫瘠之地北部的哨塔里找卡德拉克。他正要去灰谷进行战斗，应该可以给你进一步的指示。', '到贫瘠之地北部的卡德拉克那里报到。', '梣谷是一块战事频频的土地，但是我们最近采取的一系列行动都非常成功。我们不仅在佐拉姆海岸建立了哨所，还在更北边的碎木林建立了另一座。', '又一个精神抖擞的新兵，不错!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6562, '帮助耶努萨克雷', '耶努萨克雷需要帮助。他在灰谷的佐拉姆加前哨站那里，就在石爪山的北面。穿过风剪峭壁，或者从贫瘠之地直接往北走，都可以到达那里。佐拉姆海岸在森林的最西面，小心一些，$N。那里是非常危险的。', '与灰谷的耶努萨克雷谈一谈。', '苏纳曼派你来的?太好了。我们有很多事情要办。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6567, '部落的勇士', '我的一位忠诚的勇士雷克萨说他发现了进入龙穴的方法，不过他已经离开艾泽拉斯，加入了外域远征军。$B$B幸好，雷克萨的同伴罗卡鲁目前住在葬影村，他可以帮助你。去找他吧。', '按照酋长的指示找到罗卡鲁。他在凄凉之地的葬影村。', '只有一条路可以进入龙的巢穴。当然，除非你刚好是黑龙军团的荣誉成员之一。$B$B即便如此，你还是必须通过许多试炼才能拿到被达基萨斯将军亲自附魔的钥匙。$B$B你是不是很幸运呢?那是我进来的地方。', '幸会，$r。我是罗卡洛。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6570, '埃博斯塔夫', '我已经对这块奖章施加了魔法，它可以在埃博斯塔夫的巢穴里制造并维持幻影。$B$B埃博斯塔夫是一条古老的龙，它是奈法利安的卫士，专门负责考察那些即将成为奥妮克希亚精英守卫的龙人。$B$B到尘泥沼泽中的巨龙沼泽吧，埃博斯塔夫的巢穴就在那里。进入巢穴之后戴上护符，让命运指引你前进吧！', '到尘泥沼泽中的巨龙沼泽去，找到埃博斯塔夫的洞穴。进入洞穴之后戴上龙形护符，然后跟埃博斯塔夫交谈。', '是不是我对士兵的考察标准太低了，奈法利安连这种小家伙也送到我这儿来?小子，你是没办法通过我的考核。', '你是来接受考验的吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6603, '冬泉谷的麻烦！', '冬泉谷有麻烦了！$B$B当然，我在野外度过了如此长的时间，所以我对这些事情是了如指掌……我总是对能这么说感到很光荣。我感到我在那些山岭里度过的时光是很宝贵的，那段时光培养了我快捷的反应，冷静的头脑，还有锐利的目光……$B$B只有具备足够的判断力和丰富的知识才能像我一样评价大自然。$B$B嗯，我都说了些什么？$B$B啊，对，麻烦。到温泉那边去找多诺瓦·雪山，她会告诉你更多的细节。', '到冬泉谷的温泉附近去找到多诺瓦·雪山。', '你好!麦吉已经把我在这儿碰到的麻烦事情跟你说了?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6604, '被激怒的枭兽', '你有没有注意到南边那个废弃的营地？看来那里是被疯狂的枭兽洗劫过了！$B$B我听说从那次攻击中侥幸逃脱的一个幸存者正在坠星村里休养，就在这里的西边。我对这事情很感兴趣……你呢？', '与坠星村的加隆·石矛谈一谈。', '啊，我能为你做些什么吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6605, '奇怪的家伙', '我刚从费伍德森林回来，$N。我在血毒岗哨停留了一下，在那里我遇见了一个奇怪的家伙……她似乎有重要的事情要做，我可以告诉你她要干什么，但是我想最好还是让她自己解释给你听吧。$B$B如果你感兴趣的话，就到费伍德森林西部的血毒岗哨去找温娜·哈萨德。$B$B谁知道呢，也许她需要你的帮助……', '与费伍德森林的温娜·哈萨德谈一谈。', '啊，一个$C。看来现在有希望了，你是来帮助我的吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6606, '一点运气', '我们总是需要一些运气，不是吗？一些小优势就可以让你把事情转向有利你的方向……$B$B我让一个熟人，嗯，一个奇怪的巫医帮我做了个幸运符……当然是有代价的。但是相信我，那绝对值得！$B$B也许你自己也想要有这样一个幸运符？那么到冬泉谷去找巫医玛艾里吧，我可不会把自己的这个给你！', '与冬泉谷永望镇的巫医玛艾里谈一谈。', '啊，是哈鲁让你来的?好吧，那么，你是谁呢?你是来找我帮忙的吧?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6608, '你真棒！', '鲁玛克已经没有什么可教给$n的了。你太棒了！去找鲁玛克的朋友纳特·帕格吧，他是一个人类，但我不吃他！他是鲁玛克的朋友！纳特教你钓鱼。$B$B你也许可以在塞拉摩岛的那个人类镇子南面，嗯，尘泥沼泽里，在那里找到他，纳特·帕格可能正在那里钓鱼。现在就出发吧！', '你认为鲁玛克想要告诉你，他已经不能帮你提高钓鱼的技能了。也许你应该去找到他的朋友纳特·帕格，他居住在塞拉摩以南的某个岛屿上，他是一名人类渔夫（至少你认为鲁玛克是这么说的）。', '你一定是鲁玛克的朋友吧。$B$B钓鱼?我可以告诉你所有跟钓鱼有关的事情。', '我不太常有访客……让我算算上次有人来找我是那一年的事情了……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6609, '青出于蓝！', '我是个大嗓门的矮人，我亲爱的$g小伙子:小姑娘;\n！我可不是为了钓鱼而生出来的！我的意思是，看看我！我是用石头刻出来的。$B$B我没有什么可保留的了——你已经把我知道的全都学会啦！$B$B你还不明白吗？啊，好吧。我在卡利姆多大陆有一个朋友，他也许可以帮你。他的名字叫纳特·帕格，是一个很友善的人。你可以在塞拉摩南边的岛上找到他。快出发吧！', '到卡利姆多大陆的塞拉摩去。从那里向南方出发，找到一座岛屿。纳特·帕格就在岛上等待着你的到来！', '我欢迎所有的来访者……我猜…', '我猜你是老矮人的朋友，……是不是?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6611, '加基森之旅！', '你还想让扎姆沙教你什么呢？你已经学到了扎姆沙的所有烹饪秘诀,所以扎姆沙已经无能为力了！肥胖的$r应该去加基森，你可以在那里找到一个名叫迪尔格的小地精——他会帮助你的。$B$B当你成为炙手可热的大厨时，再回来教教扎姆沙吧，好吗？出发吧！', '到塔纳利斯沙漠的加基森去，与迪尔格·奎克里弗谈谈你的厨师生涯。', '<戴格吐出一些皮鞋的碎皮。>$B$B呸呸……$B$B<戴格剧烈地咳了起来。>$B$B什么?难道你不知道吗，皮革的蛋白质含量极高，而糖份含量极低!', '<戴格正在尝试吃下一只皮鞋。>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6612, '我认识一个家伙…', '我可以从你手里的炒菜勺子看出你是干什么的。不幸的是，我什么也不能教你。$B$B不过我认识一个家伙，他是个地精，也许是卡利姆多大陆上最好的厨师。$B$B啊，也许这是个坏消息，$g小伙子:小姑娘;\n——你要跑一趟卡利姆多。到加基森去找迪尔格·奎克里弗，他会告诉你接下来该怎么做的。', '到塔纳利斯沙漠的加基森去，与迪尔格·奎克里弗谈谈你的厨师生涯。', '<戴格吐出一些皮鞋的碎皮。>$B$B呸呸……$B$B<戴格剧烈地咳了起来。>$B$B什么?难道你不知道吗，皮革的蛋白质含量极高，而糖份含量极低!', '<戴格正在尝试吃下一只皮鞋。>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6623, '部落医疗队', '$N医生，我想我应该这么称呼你。很高兴再见到你。$B$B我有些好消息要告诉你！格里高利·维克托医生，也就是部落外科医疗队的首席医师，要求你到落锤镇去加入他的队伍。这可是毕生难求的机会啊！我真希望能付出一切来换取跟随格里高利·维克托医生学习的机会！你可不要浪费了这个机会！', '到阿拉希高地的落锤镇去，与格里高利·维克托医生谈一谈关于加入部落外科医疗队的事宜。', '很好。拿上你的医疗器械，我们现在就开始!', '你一定是新来的吧。很高兴你来到这里，医生。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6625, '联盟医疗队', '$N医生，我想我应该这么称呼你。很高兴再见到你。$B$B我有些好消息要告诉你！古斯塔夫·范沃森医生，也就是联盟外科医疗队的首席医师，要求你到塞拉摩去加入他的队伍。这可是毕生难求的机会啊！我真希望能付出一切来换取跟随古斯塔夫·范沃森医生医生学习的机会！你可不要浪费了这个机会！', '到尘泥沼泽的塞拉摩去，与古斯塔夫·范沃森医生谈一谈关于加入联盟外科医疗队的事宜。', '很好。拿上你的医疗器械，我们现在就开始!', '你一定是新来的吧。很高兴你来到这里，医生。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6641, '鞭笞者沃尔沙', '鞭笞者沃尔沙……在海中出没的残忍的多头蛇怪……$B$B她频繁地、无缘无故地袭击我们的岗哨，到处制造混乱。$B$B但是我已经准备就绪了，$N。我要去击败那个怪物，让她不再对佐拉姆构成威胁。$B$B纳迦在海岸边的小岛上放置着一个长明的火盆，以此来表示他们对这野兽的尊崇。我想，如果我们熄灭火盆，沃尔沙一定会非常愤怒的。$B$B我们需要帮助，因此你最好邀上一些强大的朋友同去。', '在穆格拉什寻找火盆的过程中保证他的安全。帮助他扑灭火盆，然后在与纳迦作战时保护他。$B$B如果你成功了，就回到佐拉姆加前哨站去，把鞭笞者沃尔沙的死讯通知给战歌信使。', '自从我到了这儿后，纳迦进攻我们的事情就时常发生。听到沃尔沙再也不能猖狂的消息，让我如释重负!$B$B我们欠你一份人情，$N。', '', '击败鞭笞者沃尔沙', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6721, '猎人之道', '你好，年轻的猎人。看起来你已经准备好要驯服一头野兽，并将其训练成自己的同伴了。$B$B你必须去见一见多兰纳尔的达扎拉，他可以帮助你驯服自己的第一头宠物。', '与泰达希尔的多兰纳尔的达扎拉谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6722, '猎人之道', '你好，年轻的猎人。看起来你已经准备好要驯服一头野兽，并将其训练成自己的同伴了。$B$B你必须去见一见多兰纳尔的达扎拉，他可以帮助你驯服自己的第一头宠物。', '与泰达希尔的多兰纳尔的达扎拉谈一谈。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6761, '新的边疆', '我已经让我的助手玛斯雷·驭熊者来处理月光林地求援的事宜了。去跟他谈谈吧——不要找我。$B$B不过我要给你一些……友好的建议。是我领导着大家走出了黑暗，不是月光林地的塞纳里奥议会。我们曾经陷入了一无所有的困境，但是泰达希尔给了我们新的生命！他们会努力让你相信他们那套鬼扯，如果你真的相信了他们，那你无疑是个蠢货。$B$B你自己来决定是不是要当一个傻瓜吧。', '与达纳苏斯的塞纳里奥区的玛斯雷·驭熊者谈一谈。', '嗯，$C，感谢你来到这里……大德鲁伊和月光林地的守护者雷姆洛斯之间似乎有着太多的隔阂。双方都在强调自己是正确的，而泰达希尔那边奇怪的堕落气息还是在不断扩散。即使这样，双方的误解也丝毫没有化解的迹象……$B$B不管怎么样，我们对于塞纳里奥议会的职责还在……尽管那些领导着它的长者们可能各执己见。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6762, '拉比恩·萨图纳', '这个任务的内容是这样的，守护者雷姆洛斯在月光林地的总管——拉比恩·萨图纳——正在征集愿意去探索塔纳利斯沙漠以及安戈洛尔环形山地区的冒险者，他就住在月光林地的永夜港里。$B$B虽然你的工作会对我们都有好处，但是我建议你仍然要小心行事，达纳苏斯和月光林地之间的关系最近有些紧张……而且可能会越来越紧张。', '与月光林地永夜港的拉比恩·萨图纳谈一谈。月光林地在费伍德森林和冬泉谷之间，可以从木喉要塞中的一条通道抵达那里。', '我是拉比恩.萨图纳，我代表守护者雷姆洛斯以及这块圣地的所有居民欢迎你。$B$B我感谢你有兴趣并且急切地想要帮助塞纳里奥议会，我也知道达纳苏斯的大德鲁伊对你向我们提供帮助表示了不满。你必须了解，你所做的事情是为了实现崇高的目标，而不是某个心怀叵测的阴暗目的。$B$B欢迎你来到这里，$N。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6823, '海达克西斯的使者', '如果你真的想要与我们结盟，那我邀请你对我们的敌人——空气元素、土元素和火元素——发动战争。每杀死他们的一个成员，都会削弱他们在这个世界上的势力，并进一步证明你对我们事业的忠诚。$B$B这场战役肯定会持续很长时间，但是如果你坚持下去，那么你就将得到至高的荣誉。', '在海达希亚水元素中达到被尊敬的声望，然后与艾萨拉的海达克西斯公爵谈一谈。', '你抗击敌人的功绩响彻水元素的世界，$N。有些水元素认为你不可能赢得这样的战斗，但你却取得了伟大的成就。你也赢得了我们的尊敬，以及无比丰厚的奖励。', '你的战役还没有结束，$N。去打败我们的敌人，空气、大地和火焰的奴仆，这样也许你会在将来的某一天赢得水元素的尊敬。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6845, '发现过去的秘密', '无论如何，如果你想要了解这儿的情况的话……就应该尽快找我核实。一旦我查明了真相，而且这确实是一本书的话，那么我会很高兴与你分享这里面的知识。$B$B同时，我也会通知月光林地的拉比恩，他肯定想要知道你做出了多么疯狂的事情。别让他等太久，$N……除非你想被扔到蜂蜜中。$B$B相信我，这样的事儿不是没发生过。', '与月光林地永夜港的拉比恩·萨图纳谈一谈。', '啊，$N─我正在等你来呢，很高兴看到你一切安好。$B$B我接到消息说你要回来了，我想亲自表达塞纳里奥议会对你的感激之情。毫无疑问，希利苏斯还有许多秘密有待揭示，你交给阿姆伯尔的东西一定有着非常重要的价值。请收下这个作为我们给你的回报。$B$B谢谢你，慷慨的$C。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6847, '雷尔松的全视之眼', '你们在奥特莱克山脉大举交战对辛迪加来说没什么意义，$c。我们会按照惯例来做，等待时机，直到看见你们分出胜负，然后趁势发起攻击。$B$B但是，那并不是我们现在留在这里的原因。我的全视之眼不见了，它被这里的冰斧巨魔给拿走了。$B$B找到全视之眼，然后我们就会为你效力——直到分出胜负。$B$B当你拿到全视之眼后就回到我这里来，然后我就可以好好看看你了。$B$B<指挥官雷尔松咧嘴笑着。>', '从冰斧巨魔洞穴中找到雷尔松的全视之眼，然后回到指挥官雷尔松那里。$B$B要当心，据说雷尔松的全视之眼带有可怕的诅咒！', '<指挥官雷松检查着全视之眼。>$B$B现在你就可以见证全视之眼的恐怖力量了!', '全视之眼，你这个蠢货。你拿到全视之眼了吗?', '找回雷尔松的全视之眼', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6848, '雷尔松的全视之眼', '你们在奥特莱克山脉大举交战对辛迪加来说没什么意义，$c。我们会按照惯例来做，等待时机，直到看见你们分出胜负，然后趁势发起攻击。$B$B但是，那并不是我们现在留在这里的原因。我的全视之眼不见了，它被这里的冰斧巨魔给拿走了。$B$B找到全视之眼，然后我们就会为你效力——直到分出胜负。$B$B当你拿到全视之眼后就回到我这里来，然后我就可以好好看看你了。$B$B<指挥官雷尔松咧嘴笑着。>', '从冰斧巨魔洞穴中找到雷尔松的全视之眼，然后回到指挥官雷尔松那里。$B$B要当心，据说雷尔松的全视之眼带有可怕的诅咒！', '<指挥官雷松检查着全视之眼。>$B$B现在你就可以见证全视之眼的恐怖力量了!', '全视之眼，你这个蠢货。你拿到全视之眼了吗?', '找回雷尔松的全视之眼', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6861, '斯菲莱克斯的便携式伐木机', '我和你一样焦急地想要试一下我的便携式伐木机，$c，但是我必须要弄到一些材料——我是说很多材料——才能制作出配套的工具！$B$B实际上，我需要像山那么大的一堆瑟银、秘银和铁，另外每一台伐木机还需要有一个蒸汽锯才能完工，你最好到伐木场去找找看。$B$B我在这里游荡的时候（在我被抓住之前），曾在雷矛伐木场里看到很多的蒸汽锯。', '首席技师斯菲莱克斯要你给他拿去下列物品：$B$B30块瑟银锭。$B$B50块秘银锭。$B$B75块铁锭。$B$B1个蒸汽锯。', '太棒了，$N。由于，嗯，伐木机中的自动计量等化器和链齿同步协调仪的天然的不稳定性，所以我只能保证它可以正常工作三天。三天之后么……$B$B<斯菲莱克斯耸了耸肩膀。>', '「像山那么大的一堆」是个哥布林工程学的术语……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6862, '斯菲莱克斯的便携式伐木机', '我和你一样焦急地想要试一下我的便携式伐木机，$c，但是我必须要弄到一些材料——我是说很多材料——才能制作出配套的工具！$B$B实际上，我需要像山那么大的一堆瑟银、秘银和铁，另外每一台伐木机还需要有一个蒸汽锯才能完工，你最好到伐木场去找找看。$B$B我在这里游荡的时候（在我被抓住之前），曾在雷矛伐木场里看到很多的蒸汽锯。', '首席技师斯菲莱克斯要你给他拿去下列物品：$B$B30块瑟银锭。$B$B50块秘银锭。$B$B75块铁锭。$B$B1个蒸汽锯。', '太棒了，$N。由于，嗯，伐木机中的自动计量等化器和链齿同步协调仪的天然的不稳定性，所以我只能保证它可以正常工作三天。三天之后么……$B$B<斯菲莱克斯耸了耸肩膀。>', '「像山那么大的一堆」是个哥布林工程学的术语……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6901, '开始攻击！', '', '', '一切准备就绪!现在我会让那些联盟的蠢货知道闯入奥特兰克山谷是个多么严重的错误!', '我的战士渴望战斗!我所需要的就是进攻命令……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6961, '冬天爷爷来了！', '冬幕节快乐，我的朋友！你一定要去冬天爷爷打个招呼！如果你今年表现的不错的话，你会在冬幕节那天收到一份很棒的礼物。你一定要告诉冬天爷爷你今年想要什么！$B$B另外，记得多买些好东西来给那些今年表现得好的人。我们这里货物齐全。各种货物一应俱全——这是烟林牧场精心为您准备的货物！', '和冬天爷爷谈谈；他在奥格瑞玛烟林牧场的商人区旁边。', '呴呴，你好啊。我是冬天爷爷，作为燻木牧场的良好成员……我这里有「一应俱全的东西，包括所有燻木牧场精心为您准备的货物」，希望你度过一个愉快的冬幕节。$B$B如果你在这一年表现得很好的话，你将在冬幕节这一天收到来自于燻木牧场的礼物。哈哈。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6963, '被偷走的冬幕节礼物', '听着……我不想破坏了节日的美好气氛，但是烟林牧场需要帮助——需要你这样的冒险家。$B$B我们弄丢了节日所需的重要礼品，现在连我们派去寻找礼品的烟林牧场密探也不见了！请帮帮忙——礼品是在奥特兰克山脉附近丢失的，我们派出的密探也在那儿。$B$B看看礼品和密探是否都安然无恙吧！', '前往奥特兰克山脉雪域寻找失踪的烟林牧场密探。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6964, '冬幕节的意义', '礼物，礼物，礼物……啊，呸！$B$B这些地精玷污了冬幕节的真正含义。这是个新旧更替的时节；大地在冬天爷爷降下的皑皑白雪下沉睡，冬天爷爷可不是那个身着红衣装模作样的傻子！$B$B如果你想亲自了解冬幕节，就去询问探险者协会的史学家卡尼克吧。有人关心历史胜过关心礼物，我想他一定会很惊讶的。', '与奥格瑞玛智慧谷中的萨格尼谈谈关于冬幕节的情况。', '你说冬幕节?啊，在过去的岁月中，这个节日对我们牛头人代表着重大的意义。然而，现在这个在万物复甦的季节中具有深远历史意义的节日却变成了帮忙促销糖果和礼物的节日。$B$B难怪法穆德对此耿耿于怀。他和别的牛头人把我们的过去视为战争的标志。虽然我认为适当的庆祝也是需要的，但是记住这个节日的源起应该也是很重要的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (6984, '烟林牧场的感谢', '我们这些烟林牧场的人感谢你找回了被偷窃的物品，$N。为此，我们要给你一件特殊的礼物……冬天爷爷将会亲自把它给你！$B$B请你去找冬天爷爷，他会给你冬幕节的礼物，来自于我们烟林牧场的礼物！我们这里应有尽有，烟林牧场能满足你一切需求……当然，我们还要谢谢你！', '和奥格瑞玛的冬天爷爷谈一谈。', '呴呴，你好，冒险者!$B$B哥布林已经告诉我你理应获得这个节日的一份特殊礼物，我很高兴把它给你。就是这个─祝你冬幕节快乐，以后一直快乐。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7021, '冬天爷爷来了！', '朋友，祝你在冬幕节玩得开心！记得跟奥格瑞玛的冬天爷爷问好！如果你今年表现得好的话，就能在冬幕节那天收到很多礼物。记得告诉他你希望收到礼物！$B$B另外，别忘了准备一些礼品，送给那些今年表现良好的朋友！我们有很多东西可供选择，都是从农场精心挑选的新鲜食物——来自烟林牧场的馈赠！', '跟冬天爷爷谈一谈，他就在奥格瑞玛的烟林牧场零售店附近。', '呴呴，你好啊。我是冬天爷爷，作为燻木牧场的良好成员……我这里有「一应俱全的东西，包括所有燻木牧场精心为您准备的货物」，希望你度过一个愉快的冬幕节。$B$B如果你在这一年表现得很好的话，你将在冬幕节这一天收到来自于燻木牧场的礼物。哈哈。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
