INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7042, '被偷走的冬幕节礼物', '听着……我不想破坏了节日的美好气氛，但是烟林牧场需要帮助——需要你这样的冒险家。$B$B我们弄丢了节日所需的重要礼品，现在连我们派去寻找礼品的烟林牧场密探也不见了！请帮帮忙——礼品是在奥特兰克山脉附近丢失的，我们派出的密探也在那儿。$B$B看看礼品和密探是否都安然无恙吧！', '前往奥特兰克山脉雪域寻找失踪的烟林牧场密探。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7045, '烟林牧场的感谢', '我们这些烟林牧场的人感谢你找回了被偷窃的物品，$N。为此，我们要给你一件特殊的礼物……冬天爷爷将会亲自把它给你！$B$B请你去找冬天爷爷，他会给你冬幕节的礼物，来自于我们烟林牧场的礼物！我们这里应有尽有，烟林牧场能满足你一切需求……当然，我们还要谢谢你！', '和铁炉堡的冬天爷爷谈一谈。', '呴呴，你好，冒险者!$B$B那些哥布林告诉我你已经为自己在这个节日季节赢得了一份特殊的礼物，我很高兴能把它给你。给你这个─祝你冬幕节快乐，并且在未来的每个季节都快乐。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7062, '冬幕节的意义', '礼物，礼物，礼物……啊，呸！$B$B这些地精玷污了冬幕节的真正含义。这是个新旧更替的时节；大地在冬天爷爷降下的皑皑白雪下沉睡，冬天爷爷可不是那个身着红衣装模作样的傻子！$B$B如果你想亲自了解冬幕节，就去询问探险者协会的史学家卡尼克吧。有人关心历史胜过关心礼物，我想他一定会很惊讶的。', '与铁炉堡探险者协会的史学家卡尼克谈谈关于冬幕节的情况。', '你是说冬幕节吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7121, '军需官', '$N，我们的军需官让我派新兵去他那里报到。他需要奥特兰克矿洞中的矿藏作为军需之用，也许他会派你去采集它们。$B$B沿着这条路走，你可以在西边找到军需官。', '与雷矛军需官谈一谈。', '很高兴看到有新的力量加入我们，$N，但是看来你马上就要开始忙碌了!$B$B听好了，我有些任务要交给你去做……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7123, '霜狼军需官', '$N，霜狼军需官正在招募新兵，他需要派一些士兵深入奥特兰克山谷的矿洞。去和他谈谈吧，他会告诉你更多的信息。$B$B沿着西边的路进入碉堡，然后从西边的出口出去，你就可以找到军需官了。', '与霜狼军需官谈一谈。', '嘿，$N!很高兴看到像你这样的$C愿意为部落做出自己的贡献。现在听好了，我有一个重要的任务要交给你……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7142, '为奥特兰克而战', '雷矛部族的矮人和他们的盟友正在入侵奥特兰克山谷，我们必须和他们决一死战！要想赢得这场战斗的胜利，我们就必须干掉他们的统帅，范达尔·雷矛！$B$B你可以在北面的丹巴达尔要塞里找到他，$B$B干掉他，然后回来向我报告。', '进入奥特兰克山谷，击败矮人将军范达尔·雷矛。然后回到沃加·死爪那里。', '你找到它们了!干得好，$N!这些计画可以告诉我们，那些雷矛部族的家伙究竟想要从这次愚蠢的入侵中获得什么好处。$B$B哈哈!迄今为止，他们所得到的只是他们将军的葬礼!', '你拿到计画了吗，$N?我们必须知道那些矮人为什么如此急于把他们的鲜血洒在战场上。', '击败范达尔·雷矛。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7181, '科尔拉克的传说', '雷矛部族并不是我们在这个地区唯一的威胁，士兵。我们在这座山谷中面对的是两股敌人的攻击——野蛮而原始的冰斧巨魔也在和我们进行争斗。$B$B它们的领袖是血怒者科尔拉克，一个残酷而又狡猾的混蛋。$B$B如果能干掉他，那对于整个冰斧巨魔族来说都会是一次致命的打击。杀了科尔拉克，你就将获得奖励！', '血怒者科尔拉克躲在冰斧洞穴的深处。据说只有在第1001个冰斧巨魔被干掉的时候，这个强大的冰斧巨魔领袖才会出现。$B$B到冰斧洞穴中去，杀掉所有挡在你面前的巨魔，直到科尔拉克出现为止。杀掉科尔拉克，然后向拉格隆德复命。', '现在我们的敌人只剩下雷矛部族了。干得好!', '小心一点，士兵。雷矛部族也在猎捕科尔拉克。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7202, '血怒者科尔拉克', '这个地区的冰斧巨魔是个野蛮而原始的种族，他们只想把我们做成炖肉吃了。$B$B我们必须让他们尝尝苦头！$B$B从他们的洞穴找到的古书中详细记述了他们的部族领袖权的传承方式。那本古书中还写到，它们现在的领袖——血怒者科尔拉克只有在需要显身的时候才会出现。$B$B干掉科尔拉克就能使冰斧部族灭亡！杀了他，然后回到我这里来。', '血怒者科尔拉克躲在冰斧洞穴的深处。据说只有在第1001个冰斧巨魔被干掉的时候，这个强大的冰斧巨魔领袖才会出现。$B$B到冰斧洞穴中去，杀掉所有挡在你面前的巨魔，直到科尔拉克出现为止。杀掉科尔拉克，然后向哈格丁中尉复命。', '干得好!科尔拉克死了，我们终于可以集中精力来对付霜狼氏族的那群渣滓了。', '小心一点，士兵。霜狼氏族也在猎捕科尔拉克。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7221, '勘查员塔雷·石镐', '啊，$N，你是来向我报到的？太好了，雷矛部族需要各方面的支援！$B$B和丹巴达尔的勘查员塔雷·石镐谈谈吧，你可以在丹巴达尔兵营的最下层找到他。$B$B当你穿越丹巴达尔的时候多四处看看。对于一个勤劳的$c来说，根本不用担心找不到事情做。', '与丹巴达尔兵营的勘查员塔雷·石镐谈一谈。', '来了个新兵?太好了。欢迎来到丹巴达尔!你准备为联盟挥洒热血了吗?不，不是你的血!战争不是让你为国捐躯，而是让那些部落的渣滓们为国捐躯!我们需要的不是烈士，而是英雄!$B$B听好了，我有一个重要的任务要交给你，英雄。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7222, '沃加·死爪', '一个$c？太好了！我们很高兴在奥特兰克看到你，$N。无耻的矮人和他们的盟军入侵了我们的山谷，我们欢迎所有部落的成员加入这场正义的战斗！$B$B去和沃加·死爪谈谈吧。他正在寻找足够的人手来完成一项重要的任务，目标就是联盟设立在奥特兰克的城堡！$B$B你可以在霜狼要塞里找到沃加。', '与霜狼要塞里的沃加谈一谈。', '你好，$N。很高兴能看到一个想要通过对抗联盟来进行试炼的$C。听好了，我有一个任务要让你去做，它可以检验你的意志、力量和精神。$B$B想要继续听下去吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7241, '保卫霜狼氏族', '战鼓的轰鸣再次回响在遥远的土地上，$c。与酋长血脉相连的氏族正在被穷凶极恶的铁炉堡雷矛部族围攻。$B$B我可以看出你很渴望战斗，并且愿意帮助霜狼氏族。$B$B你必须马上证明你的决心。$B$B你可以在希尔斯布莱德丘陵找到奥特兰克山谷的入口。进入其中，找到拉格隆德。快点出发吧，$c，我们马上要展开战斗了！', '到希尔斯布莱德丘陵地区的奥特兰克山谷去。找到拉格隆德并和他谈谈，然后成为霜狼氏族的士兵。', '你要成为霜狼氏族的一名士兵，就得先经过我们的考验……', '嗯?又来一个新兵?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7261, '国王的命令', '我们正在奥特兰克山谷进行一场血腥的战斗，蒙昧的冰斧巨魔和野蛮的霜狼氏族从两边夹击我们。以麦格尼·铜须陛下的名义，我们一定要把他们全都消灭掉！占领那片土地，将敌人赶出去，这对于王国的稳定是非常重要的。$B$B啊，士兵可不是从树上长出来的！向奥特兰克的哈格丁中尉报告，在那里加入雷矛部族的军队，开始履行你光荣的职责吧。', '到希尔斯布莱德丘陵地区的奥特兰克山谷去。到那里之后，和哈格丁中尉谈谈。$B$B为了铜须的荣耀！', '开工吧!', '<哈格丁中尉向你敬礼!>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7364, '诺莫瑞根大通缉！', '大工匠亲自派我来这片战场上保卫我的侏儒兄弟和姐妹。我们听说牛头人正在磨刀霍霍地准备屠杀侏儒，最糟糕的是，他们居然拔掉死去侏儒的头发！这种残暴的行为必须被阻止，我们必须以牙还牙！$B$B我要砍下他们的蹄子，$c。把他们的蹄子交给我，向我证明你是侏儒的盟友！', '你被指派去杀死奥特兰克山谷中的牛头人玩家。$B$B杀死一个牛头人，然后把牛头人的蹄子交给丹巴达尔的德尔克。', '<德尔克将牛头人的蹄子丢到他身后的一堆蹄子中。>$B$B继续保持，$C。', '我倒要看看没有蹄子的牛头人还能耍什么花样。该死的东西……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7365, '鹿盔的挽歌', '范达尔·鹿盔已经给我下达了指令：战场上的所有巨魔都必须被消灭。他们那关于暗夜精灵是他们后代的荒谬理论一定是他们嫉妒的结果，所以我们要用武力来回应他们。$B$B杀了他们，把他们的魔精给我拿来。', '你被指派去杀死奥特兰克山谷中的巨魔玩家。$B$$杀死一个巨魔，将暗矛巨魔魔精交给丹巴达尔的亚斯拉玛尼斯。', '达纳苏斯的夜精灵会感谢你，但是还有更多的工作需要完成。你准备继续战斗吗?', '这是一个众所周知的事实:所有食人妖都带着魔精。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7367, '爆破专家', '霜狼部族在他们的前线和基地中都布置了陷阱，$C。所以当你进入敌人领地的时候，必须多加小心。$B$B如果你想要放心大胆地攻击他们的话，就得先摧毁这种针对单兵的防御武器——我要你做的就是干掉他们的爆破专家。如果你杀了他，就可以安全地拆除那些地雷。因为只要他被干掉了，那些地雷也就变成了一堆废物。$B$B你可以在冰血要塞附近的哨塔里找到他。祝你好运！', '找到霜狼爆破专家并干掉他。完成任务之后向雷矛爆破专家复命。', '干得漂亮，$N。希望你从这里学到的东西可以在将来的战斗中帮助你。', '你闻到了吗，$C?那是胜利的味道!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7368, '爆破专家', '我对关于地雷的技术细节了如指掌，我负责将所有的地雷埋设在前线。$B$B如果你想要解除雷矛部族的地雷阵，你要做的就是干掉对方的爆破专家。那个矮人懦夫无疑藏在征战平原的第一座哨塔中。把他干掉，联盟就没法再埋设地雷了。$B$B在你干掉他之后，别忘了回到我这里来通报一声，你会得到奖励的。', '找到雷矛爆破专家并干掉他。完成任务之后向霜狼爆破专家复命。', '现在他已经死了，你接下来所要做的就是把那些地雷给拆掉。这样，我们就可以安全地通过那个区域，直到联盟找到一个新的爆破专家。问题是，他们来得及吗?', '你没看见我正在尽力避免把自己炸上天么?你有什么事?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7381, '科尔拉克归来', '虽然科尔拉克确实被干掉了，但是还有一个问题：他是不是会一直保持死了的状态？巨魔一向以来都以擅长妖术魔法而声名狼藉，如果他们复活一个死去的领袖，并让他重新执掌部族，那我绝对不会感到惊奇。$B$B你应该知道如果这种事情真的发生了的话，你该怎么做。$B$B<拉格隆德用手指在自己的脖子上做了一个切割的动作。>$B$B这一次，我要他的徽记。打起精神，士兵。$B$B解散！', '如果科尔拉克重新出现在奥特兰克山谷的冰斧山洞中，就找到并干掉他。$B$B将科尔拉克的徽记交给霜狼要塞的拉格隆德。', '我倒要看看他们怎么复活一具无头的尸体!那些该死的蠢货居然认为他们比拉格隆德聪明。$B$B<拉格隆德大笑着。>$B$B现在解散!哦，不要忘了拿你的符文。', '他回来了吗?那个嗜血的野兽又复活了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7382, '永生的科尔拉克', '现在有一件紧急的事情……有没有人想过要净化科尔拉克的尸体？那些巨魔一定会想法设法复活他们的领袖，你知道，那些蓝皮肤的怪物经常会那么做。$B$B你要小心了，$N。如果科尔拉克重新出现在你的面前，千万不要惊慌失措。如果他真的复活了，那么我要你把他干掉，然后净化他的尸体。$B$B为了以防万一，在焚烧尸体之前拿走他的徽记，然后把他的徽记交给我。', '如果科尔拉克重新出现在奥特兰克山谷的冰斧山洞中，就找到并干掉他。$B$B将科尔拉克的徽记交给丹巴达尔的哈格丁中尉。', '这样就没问题了!显然，那些野兽不可能复活一具无头的尸体，是不是?$B$B你可以退下了。哦，不要忘了拿着你的符文。', '他复活了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7402, '通缉：兽人！', '根据诺雷格·雷矛中尉的命令，所有雷矛部族的士兵都要杀掉$g他:她;\n在战场上看到的每一个兽人。$B$B带回兽人的獠牙来作为完成任务的证明。$B$B另外别忘了戴手套。', '你被指派去杀死奥特兰克山谷中的兽人玩家。$B$B杀掉一个兽人，然后把兽人的獠牙交给丹巴达尔的诺雷格·雷矛中尉。', '不要把这个告诉任何人，我们要把这些牙齿磨成上好的粉末，然后用这些粉末制作神奇的生发剂。这种东西在地精中非常流行!$B$B<诺雷格.雷矛下士向你眨了眨眼。>', '放松一点，士兵。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7421, '暗矛的防御', '', '', '夜精灵终将学会尊重食人妖。通过诉诸武力，他们将会接受夜精灵是食人妖后裔的事实。$B$B继续向他们展示我们的力量，$N。', '继续保卫暗矛部族，$N。杀了那些夜精灵，把他们的头颅交给纳亚克。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7422, '踏平侏儒', '', '', '<拉瓦克将一束地精的头发放到他的鼻子旁边，然后深吸了一口。>$B$B犹如可爱的花朵。地精，男性，青年，走起来有些跛。我说的对不对?', '看来高等技工已经听说了我们参加奥特兰克山谷之战的事情。他已经下达了命令，要求其子民拿回牛头人的蹄子作为报复。这些地精比我想像得更难对付!我们必须进行更多的研究，我们需要更多地精的头发。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7423, '更多的骨头', '', '', '你是我们的勇士，$N。继续好好干!', '你为那些人类做了一件好事，$N。继续拯救那些没有像我们这样幸运的种族吧。$B$B每块人类的骨头碎片都是一个可以被拯救的灵魂，我们可以让他们从冰冷无情、污秽而又压抑的躯体和生命中解脱出来。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7424, '牛头人的蹄子', '', '', '<德尔克把蹄子丢到他身后的一堆蹄子里面去。>$B$B继续好好做，$N。', '让他们个个都变成瘸子，$N。让他们知道地精可不是好欺负的!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7425, '鹿盔的魔精悬赏', '', '', '你受到了达纳苏斯夜精灵的青睐，但是你仍然任重而道远。', '除非所有食人妖都永远沉默……否则鹿盔是不会满意的。继续从他们病态的躯体上收集魔精油吧。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7426, '光明的关爱', '', '', '感谢本尼迪塔斯!又一个失落的灵魂将要被圣光的火焰救赎!$B$B继续好好干!我们还要拯救更多的被遗忘者!', '<指挥官菲力浦好像在哭泣。>$B$B这样的仁慈足以让任何人都潸然泪下。本尼迪塔斯是一个活生生的奇迹!$B$B继续传播他的仁慈吧，$N。还有许多被遗忘者的心脏等着你去焚烧净化!不要让他(或者我)失望。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7427, '通缉：更多矮人！', '', '', '我知道我说过你不会忘记第一次拿到脊骨的过程，但是我忘了告诉你，也别忘了接下来还要继续弄到500条脊骨。快去工作吧!', '只要我有了足够的脊骨，就可以将它们都装载在我们的投石车上，然后射向丹巴达尔。$B$B雷矛部族将感受到分离和死亡的恐怖。我简直等不及了!$B$B我们还需要更多的脊骨。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7428, '通缉：更多兽人！', '', '', '干得不错，士兵。继续努力!', '那些蛮子永远也不懂得吸取教训，$N。继续攻击那些兽人。霜狼氏族将会知道「痛苦」这两个字的含义，地精们的头发也得以保全。$B$B这就是我们所说的「双赢」战略。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7462, '辛德拉的宝藏', '你可以在图书馆的楼梯下方找到一只古老的箱子，从中拿取你所需的东西吧。', '返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！', '你打开了箱子，发现了……', '这是一只大箱子。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7491, '万众敬仰', '伦萨克在力量谷等你。$B$B<萨尔向你致敬。>$B$B不要让你的民众等得太久，英雄。', '在力量谷找到伦萨克。', '请选择你的奖励，然后我们就将开始庆祝你光辉的胜利。', '这是一种光荣，也是一种特权，英雄。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7492, '莫沙彻营地', '菲拉斯的牛头人长者塔罗·刺蹄派人送信请求帮助。他并没有详细述说详情，但是他说他需要一个有着足够的勇气而且做事细致的冒险者来帮助他。$B$B为了部落而战，$N。到菲拉斯的莫沙彻营地去找塔罗谈谈吧。', '和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。', '啊，很高兴看到一个$C响应了我的召唤。我需要你的帮助，$N，你必须踏上一条危险的道路……$B$B一条通往厄运之槌的道路。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7493, '一切才刚刚开始', '', '', '一个屠龙者，同时还是一个老练的制皮师?你让我感到十分吃惊，英雄。$B$B请接受我将要教给你的东西。这种知识对于准备去摧毁所有黑龙军团的你来说是十分有用的。$B$B我要教你如何使用黑龙公主奥妮克希亚的皮来制作一件披风，当你和你的队友与黑石之王奈法利安作战的时候，这件披风可以让你们不至于被他那炽热的火焰气息烧成灰烬。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7494, '羽月要塞', '$N！菲拉斯需要你的帮助！$B$B一个名叫蕾瑟塔蒂丝的流亡法师逃进了古代暗夜精灵的遗迹——埃雷萨拉斯，现在那里被称为厄运之槌。她手中有一件非常危险的魔法物品，我们一定要拿回它。$B$B拉托尼库斯·月矛要求派遣强大的冒险者进入厄运之槌，从蕾瑟塔蒂丝手里拿回那件东西。$B$B为了联盟而战！你可以在菲拉斯的羽月要塞中找到拉托尼库斯。', '和菲拉斯羽月要塞的拉托尼库斯·月矛谈一谈。', '你好，$N。很高兴见到你，只是如果我们的会面发生在更让人愉悦的环境之下就好了。$B$B听好了，我有个重要的任务要交给你……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7496, '英雄庆典', '到英雄谷去找到玛丁雷少校，$N。他会在那里等着你……', '在英雄谷找到玛丁雷少校。', '除了庆典之外，你还可以选择一些东西作为奖励，$N。请选择你想要的奖励，然后我们就可以开始隆重的庆典了。', '你让暴风城重获了荣耀，年轻的勇者。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7497, '一切才刚刚开始', '', '', 'A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.$B$BPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.$B$BCrea', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7541, '为部落效力', '', '', '我们的学者要花一些时间来研究你带来的这个坠饰，但是为了感谢你对部落做出的贡献，请你收下这个。$B$B谢谢你，$N。你为你自己─也为我们─赢得了荣誉。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7562, '莫苏尔·召血者', '$N，你对于黑暗艺术的钻研已经颇具成效。你对于其它世界的知识已经非常完备了……也许你已经做好了驯服著名的恐惧战马的准备。$B$B从这种野兽的家园召唤它们的仪式需要大量的能源，但是如果你想要得到这匹史诗级的坐骑，就去和莫苏尔·召血者谈谈吧。他就在燃烧平原的风暴祭坛旁边。$B$B去吧，$N。这个任务将会十分危险，但是你这样的术士应该会知难而进的！', '与燃烧平原风暴祭坛的莫苏尔·召血者谈一谈。', '你好，$N，欢迎你的到来。你是否也与我一样要在暴风祭坛旁进行学习?或者你是为了某些未知的目标而汲取这里的能量?$B$B或者……你是来这里找我的?嗯，我相信是这样的。$B$B你想要驾驭一匹恐惧战马?这可不是一件容易的事情。它将会让你费尽周折……还要花费大量的金币。但是克索诺斯恐惧战马将会是对你最好的奖励，如果你感兴趣的话，请继续听下去……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7601, '尼比的助手', '如果要我向你传授召唤地狱火仆从的秘密，那么你就必须干掉克罗苏斯，然后把它那灼热的尸体中的恶魔之核交给我。这个任务其实并不是像它听上去的那么简单，因为克罗苏斯已经完全燃尽了。你必须将它的尸体重新点燃，让他在烈焰中重生。因此你就得从其它恶魔身上采集材料来完成这个任务。$B$B我的小鬼伊普斯会告诉你该怎么做的。', '与费伍德森林的伊普斯谈一谈。', '哦，孩子，我们这就开始。', '你的能力绝不比我的主人差。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7621, '警示', '', '', '牧师，你将要经历一严格的试炼，它将检验你学过的所有技能。$B$B我建议你听听我要说的故事。$B$B你要注意，你必须独自完成这个任务，所以我建议你与你的盟友保持一定的距离。任何来自外界的帮助都将导致严重的惩罚。$B$B命运引领你来到了这里。倚仗圣光的力量，为荣耀而战吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7622, '光与影的平衡', '你必须完成我没有能够做到的事情：拯救那些未能逃出斯坦索姆的农夫。$B$B他们将向着光明前进，你的职责就是保证他们的存活。如果过多的农夫倒下，那我们仍将继续被诅咒，而你则会可耻地失败。$B$B你所学到的每项技能、每句祷言和每个法术都会经受考验。愿圣光护佑你，$N。', '在总计有15个农夫被杀死之前拯救50个农夫。完成任务之后与艾瑞斯·哈文法谈谈。$B$B你可以通过浏览死亡布告来了解自己拯救了多少农夫。', '你的坚毅和勇气让人惊叹，牧师。你现在可以拿起诺达希尔碎片了。现在只剩下一个任务等着你去完成了:找到暗影之眼。净化整个世界吧。', '完成你的使命，$N。', '光与影的平衡', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7623, '魔王贝恩霍勒', '莫苏尔说你需要一扇通往克索诺斯的传送门。如果是这样的话，你就得用到克索诺斯星尘。在艾泽拉斯大陆上找到这种星尘可不容易！$B$B但是我知道谁手中有星尘——加德纳尔的魔王贝恩霍勒，他就在暗影议会那里！和他谈谈，也许他会给你一些星尘。$B$B但是在你去加德纳尔之前，你必须用暗影议会的邪恶气息来伪装自己。也就是说，你需要一些暗影药水，我这里就有暗影药水，不过这可不是免费的……', '从燃烧平原风暴祭坛的戈瑟奇那里购买暗影药水。$B$B使用这种药剂进入费伍德森林的加德纳尔，然后与暗影堡中的魔王贝恩霍勒谈一谈。', '我的耐心是无限的，$C。但是不要认为你有资格浪费我的时间……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7631, '克索诺斯恐惧战马', '所有东西都准备好了。现在，你必须施展仪式制造出强力召唤法阵，然后再使用卷轴和克索诺斯星尘来打开通向克索诺斯的传送门。$B$B我已经把施展仪式的具体步骤写在了一张卷轴上。仔细读一读卷轴，然后严格按照上面所述的步骤来做，否则你就无法成功施展仪式。$B$B祝你好运，$N。愿你的背包中装满了敌人的灵魂碎片。', '阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。', '克索诺斯恐惧战马的灵魂被击败了。虽然它显得十分愤怒，但是你知道这头野兽的灵魂已经是属于你的了……$B$B它吟唱着黑暗的魔法，充满强大能量的咒语深深印入你的脑海，你已经学会了召唤恐惧战马的方法。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7633, '介绍', '', '', '你的勤奋和正直已经引起了我们的注意，$C。$B$B我们是远古保卫者，保护这片伟大森林的古树。我们的身躯早在一万年前阿克蒙德和他的燃烧军团入侵海加尔的时候就被摧毁了。然而，我们的灵魂被完整地保存了下来。$B$B我们有一些任务可以交由你去完成，如果你能获得成功，古老的秘密就将被你洞悉。$B$B只要你完成任务并回到这里来，我们就会响应你的召唤。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7638, '格雷森·沙东布瑞克公爵', '这个伟大的时刻终于到来了，$N，接下来你就将获得你渴望已久的东西——你的战马。$B$B去和暴风城教堂区的格雷森·沙东布瑞克公爵谈谈吧。他将指引你完成必需的任务，令你获得一匹圣骑士最可信任的坐骑。$B$B我祝你在这次试炼中好运，为了圣光而战，我的$g兄弟:姐妹;\n！', '与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。', '很高兴见到你，$N。我知道你急切地想要知道如何才能获得你的战骑，现在这个时刻终于来临了。$B$B你需要经过许多试炼，但是最重要的是，你的信念将通过克服这些困难得到最大程度的提升。这些并不是教课书式的试炼─你必须全身心地投入，才能克服即将到来的挑战。在拯救你未来的伙伴之前，你必须与无数邪恶的力量抗衡。$B$B现在，我们开始吧!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7641, '格瑞曼德·艾尔默', '圣骑士的坐骑如果没有合适的马饰，那它就和运货的畜牲没有什么区别。你所使用的马饰不仅需要使用最好的材料来制作，而且还需要与灵魂世界进行密切的沟通。$B$B首先，$N——让我们来搞定马饰的问题。在暴风城的矮人区里面有一位顶级铁匠，格瑞曼德·艾尔默。他的开价不会低，但是他的质量正是我们所追求的。去和他谈谈吧。', '与暴风城矮人区的格瑞曼德·艾尔默谈一谈。', '你好，$g小伙子:小姑娘;\n─格雷森.破影者领主已经派人通知我说你会来找我了。我很乐意帮你制作马饰，但是这并不简单，也不便宜。我们闲话少说吧，我会告诉你要怎么做，以及最重要的是什么。$B$B我这么说吧，格雷森也会百分之百的赞同我的话……在艾泽拉斯世界上，你找不到能比我做出更好马饰的铁匠了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7652, '君王板甲的设计图', '', '', '好吧，$g先生:小姐;\n，我有个很好的提议。$B$B我这里有一些帝国铠甲的配方，我想要把它们卖掉，换些我用得到的东西。我所需要的只是一些瑟银锭，你觉得怎么样?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7660, '更换冰狼', '', '', '好好照顾你的新坐骑，不然小心它把你的喉咙给撕出来!', '如果你把原本供你骑乘的高速座狼给我带来，我就可以让你从新的狼中选择一头。新的狼将和你原来的狼拥有同样的速度，但是其外观将会有所不同，看看周围的这些迅捷座狼就可以知道它们大概是什么样子了。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
