INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7673, '更换霜山羊', '', '', '为了铁炉堡，前进!', '如果你把你的冰霜山羊带来交给我，那么我可以换给你一头新的山羊，它和你的冰霜山羊速度一样快，但是拥有不同的外观。你可以看看这里的迅捷山羊，然后再决定要选哪一头。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7674, '更换黑山羊', '', '', '为了铁炉堡，前进!', '如果你把你的黑山羊带来交给我，那么我可以换给你一头新的山羊，它和你的旧山羊速度一样快，但是拥有不同的外观。你可以看看这里的迅捷山羊，然后再决定要选哪一头。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7675, '更换冰蓝色机械陆行鸟', '', '', '为了诺姆瑞根而战!', '如果你还骑着旧的冰蓝色机械陆行鸟A型，那么你一定想要用它来换一台新型号的坐骑。你的新型机械陆行鸟的速度会和旧的型号一样，但是它拥有崭新的外表。你可以看看这里的迅捷机械陆行鸟，然后决定要选哪一个型号。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7676, '更换白色机械陆行鸟', '', '', '为了诺姆瑞根而战!', '如果你还骑着旧的白色机械陆行鸟A型，那么你一定想要用它来换一台新型号的坐骑。你的新型机械陆行鸟的速度会和旧的型号一样，但是它拥有崭新的外表。你可以看看这里的迅捷机械陆行鸟，然后决定要选哪一个型号。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7677, '更换白马', '', '', '请好好照顾她!', '如果你把你的白马给我带来，那么我可以让你从新的马中选择一匹。它们和你原来的马拥有同样的速度，但是其外观将会有所不同。看看这里的马就知道它们大概是什么样子了。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7678, '更换褐色马', '', '', '请好好照顾你的新坐骑!', '如果你把你的褐色马给我带来，那么我可以让你从新的马中选择一匹。它们和你原来的马拥有同样的速度，但是其外观将会有所不同。看看这里的马就知道它们大概是什么样子了。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7704, '看看它的个头！', '啧啧……这难道不是个惊喜吗？这实在就是个惊喜啊。比拉凯琳的巨大而精美的枕头现在是你的囊中之物啦。艾沃奈斯肯定很想将她那脏兮兮的小手放在枕头上。把枕头交给她，看看她是否会奖励你点什么。', '将比拉凯琳的枕头交给灼热峡谷的艾沃奈斯。', '这东西比我想像中得还要棒!比拉凯琳的魔法枕头属于我啦!你会得到丰厚的奖励，$N!', '这真是个巨大的枕头!你从哪儿弄来的?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7761, '黑手的命令', '愚蠢的家伙，$B$B对于你的能力我向来不抱什么希望，我不相信你可以阻止外来者进入主人的巢穴。如果你死亡了，那么这颗宝珠内建的安全机制可以防止外来者直接传送到黑翼巢穴中。$B$B只有那些手上烙有达基萨斯徽记的人才能使用这颗宝珠。值得庆幸的是，达基萨斯不像你那么没用，军需官。它会守卫着那枚烙印！$B$B- 大酋长雷德·黑手$B$B备注 ：别忘了毁掉这封信，笨蛋。', '真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。$B$B你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。', '当灼热的烙印烫在你的躯体上时，你丝毫没有畏缩。你真是非常坚强!$B$B现在你拥有了达基萨斯的徽记。', '<整个房间中充满了烧焦的尸体的味道。>', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7782, '黑石之王', '到英雄谷去，与艾法希比元帅谈一谈。', '回到暴风城的英雄谷，与艾法希比元帅谈一谈。', '<艾法希比元帅向你鞠躬。>$B$B选择你的奖赏吧，让我们开始狂欢庆祝!', '欢迎你，勇士。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7784, '黑石之王', '到力量谷去找伦萨克大王。', '和奥格瑞玛的伦萨克大王谈谈。他在力量谷等你。', '选择你的奖励吧，我会把这个野兽的头颅挂起来，让所有人都看见。', '你的成就让我感到备受鼓舞。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7788, '击败入侵者！', '在这个通道的另一端，你会看到一片战火纷飞的土地，年轻的$c。部落不断侵入我们神圣的森林，锯断这里的苍天古树来建造他们的战争机器。$B$B进入战歌峡谷，帮助银翼要塞击败入侵的部落势力吧。', '进入战歌峡谷抵御部落小队的攻击，获得一枚银翼功勋奖章，然后向银翼树林中的哨兵艾蒂亚·轻歌回复。', '银翼哨兵部队感谢你的贡献，$C。我们和战歌先遣骑的战斗远未结束，但是你的胜利一定可以减缓他们建造战争机器的速度─即使只是减缓一小会儿。', '银翼要塞那边有什么消息吗?你有没有击败战歌氏族的部队，拿到你的功勋奖章?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7810, '竞技场高手', '要成为竞技场高手肯定需要付出更多的代价！也许管理古拉巴什竞技场的海盗知道到底要多少！', '与荆棘竞技场的小个子约翰·米斯瑞尔谈一谈。', '啊，我的朋友!仅有一件饰品是不能成为竞技场高手的!现在是证明你实力的时候啦!', '|n|n|n', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7845, '被绑架的断齿长者！', '我的爱人在邪枝巨魔发动的一次夜间突袭中被掳走。我们的探子回报说他还活着，并且被关在辛萨罗的顶部。据说邪恶祭司海克斯正准备把他当作祭品献给邪神哈卡。$B$B你必须救救他，$N！我们的村庄不能失去他。', '辛特兰恶齿村的断齿族长要求你到辛萨罗去拯救她的爱人，断齿长者。$B$B你听说他被关在辛萨罗顶部，辛萨罗位于辛特兰的南部地区，那里是邪枝巨魔的主城。', '你必须快点行动，$N。守卫一定注意到你的出现了。', '你必须帮帮我……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7847, '向断齿族长复命', '回到我的爱人——恶齿村的断齿族长那里。告诉她我马上就回去！她一定会奖励你的。', '辛萨罗的断齿长者要求你将他已经被营救的消息带给恶齿村的断齿族长。', '你为恶齿村做出了巨大的贡献，$N!我们欠你一个人情。', '太好了!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7863, '哨兵基础护理包', '', '', '你向我们证明了你的实力，$N。作为奖励，请收下这只背包!你可以在里面发现一些补给品和绷带，这些东西只有在战歌峡谷中才能使用。$B$B当你在战歌峡谷的战场上不断证明自己的价值之后，就能找到更多可以购买的东西。当你在我们这里的声望达到友好的程度之后，你就能购买这些补给品，而当你的声望达到尊敬的程度之后，就可以购买绷带。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
