INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (7925, '荣誉奖章', '', '', '夜精灵和他们的盟友听到你的名字就会吓得发抖!为部落而战!', '你已经证明了自己在战歌峡谷中的价值!继续攻打银翼要塞的哨兵部队，给我带来更多的功勋奖章!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8041, '穆贾巴之力', '', '', '我们会再见面的，$C。', '见到你身体健康真好，$N。这场显赫的战斗影响着这个星球上的所有生物。绝不能让哈卡离开祖尔格拉布，否则世界将会毁在他无尽的欲望中。$B$B把坠饰给我吧，我会强化它的力量。运用穆贾巴之力惩罚我们的敌人吧!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8045, '异教徒的烙印', '', '', '去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>', '我的判断看来有些草率，$C。似乎你对圣光的盲目信仰还有些用处。$B$B把烙印给我吧，我会强化它的力量。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8049, '祖达萨之眼', '', '', '$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。', '牧师，你与古拉巴什一族作战的英勇事迹早已家喻户晓，就连皇室成员也开始谈论你的故事。据说拉斯塔哈甚至提到了你的名字。$B$B现在是为祖达萨之眼注入魔法的时候了。把坠饰交给我吧。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8101, '卡亚罗之石', '', '', '$C，这块坠饰上镶嵌的卡亚罗之石来自南海的卡亚罗山脉。卡亚罗山脉地带分布着许多活火山，那里的地质地形不断发生剧烈的变动。$B$B随着你与赞达拉食人妖的关系日益密切，卡亚罗之石的力量也会增强。利用这块石头的力量打败我们的敌人吧。就像卡亚罗山脉那样:迅速、致命、富有爆炸力……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8103, '卡亚罗之石', '', '', '$C，这块坠饰上镶嵌的卡亚罗之石来自南海的卡亚罗山脉。卡亚罗山脉地带分布着许多活火山，那里的地质地形不断发生剧烈的变动。$B$B随着你与赞达拉食人妖的关系日益密切，卡亚罗之石的力量也会增强。利用这块石头的力量打败我们的敌人吧。就像卡亚罗山脉那样:迅速、致命、富有爆炸力……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8105, '阿拉希盆地之战！', '$N，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。', '进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。', '我收到了你在阿拉希盆地大显神威的报告，$N。做得好!如果有越来越多的像你这样勇敢的$C加入我们，我坚信我们总有一天能夺回我们的家园。', '$N，你还没有完成对这4个战略要点的攻击。任务完成之后再回到我这里来。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8106, '科赞的玷污', '', '', '请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布林的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布林主城幽坑城的属地;\n但是在科赞被玷污之前，它曾是一片伟大的土地。即使在今天，我们仍将科赞看作神圣的地方。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8110, '南海魔化海藻', '', '', '看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8114, '控制四座基地', '$N，你赢得了在阿拉希盆地的战争，并在战场上证明了自己有资格得到荣耀和尊重。你是一个有价值的$c，你让我们的敌人知道我们绝对不会向他们的暴行屈服！$B$B现在我有一项艰巨的任务要交给你。我需要你进入阿拉希盆地，占领至少四座基地。如果你可以完成这个任务的话，那么我们不仅保证了重要资源的供给，而且还向部落展示了我们的力量！$B$B出发吧，$N，祝你好运。', '进入阿拉希盆地，同时占据并控制四座基地，当任务完成之后向避难谷地的奥斯莱特元帅报告。', '做得好，$N!一个激动的斥候已经带来了你成功的消息。我们阿拉索联军上下都为你感到欢欣鼓舞!$B$B你已经渐渐变成这个军团的英雄，今天你的事迹又再一次证明了你的价值。', '你还没有占据四座基地，$N。回到阿拉希盆地，完成你的任务吧!', '控制四座基地。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8115, '控制五座基地', '$N，阿拉希盆地的资源之战是一场血腥的战斗。阿拉索联军需要你的帮助。$B$B我们还有一个任务需要交给你。$B$B联军想要对污染者进行一次大规模攻击。我们要把他们从这个战场中的每个重要战略点里赶出去！$B$B这个任务不简单，但是如果说有人可以完成它的话，那个人就是你。', '同时控制阿拉希盆地中的五座基地，然后向避难谷地的奥斯莱特元帅复命。', '你成功了!你占据了所有基地!做得好，$N!$B$B以前有人曾怀疑你能否顺利完成，但是我就知道你会成功。感谢你，整个阿拉索联军向你表示致敬，而被遗忘者的污染者每次提到你的名字，必定感到胆战心惊!', '你还没有完成你的任务，$N。这很困难，但是我深信你的实力。', '夺取五座基地。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8116, '巫毒幻象', '', '', '看看吧，$N。巫毒的力量更加强大了，不是吗?让原始的力量流遍你吧。', '啊哈!梅维基闹了一个笑话!$B$B<梅维基大笑。>$B$B这么说，你一直利用灵魂和元素的力量对抗那些藏在祖尔格拉布的敌人，是吗?这值得奖励!$B$B梅维基会磨亮你的宝珠的。把宝珠放在这儿，$N。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8120, '阿拉希盆地之战！', '无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉希盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！$B$B去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。$B$B出发吧，$N。当任务完成之后向我复命。', '进攻阿拉希盆地的矿洞、伐木场、铁匠铺和兽栏，然后向落锤镇的屠杀者杜维尔复命。', '污染者斥候已经向我报告你成功了，$N。做得好。$B$B你慢慢就会知道，想要赢得阿拉希盆地的胜利，我们必须保持警惕，并击败联盟任何想扩张的企图。唯有如此，我们才能确保赢得最后的胜利。', '你还没有完成你的任务，$N。攻击我提到的所有四处基地，你完成任务之后再回到我这里来!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8121, '夺取四座基地', '$N，随着阿拉希盆地的战事进展，你的事迹已经传遍了战场。你的所做所为让我确信你一定可以完成现在我要给你的任务。$B$B现在是给阿拉索联军一个信号的时候了。我们将会向他们展示，他们在阿拉希盆地的防守是多么脆弱。我们要通过同时占领阿拉希盆地的四个战略点来让他们明白这一点。$B$B如果你可以完成这个任务，$N，你将赢得污染者的尊敬。', '同时占据阿拉希盆地中的四座基地，然后向落锤镇的屠杀者杜维尔复命。', '做得好，$N!你最近在阿拉希盆地所完成的任务都十分困难，它们的成功值得表扬。阿拉索联军在最近的遭遇战中必定被打得抱头鼠窜，希望他们可以重新考虑一下继续在这里战斗的必要性。', '回到阿拉希盆地，$N，完成你所肩负的任务!占据四座基地!', '控制四座基地。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8122, '夺取五座基地', '我们其实已经深深陷入战争之中，只是我们还没有意识到。幸好，我们的探子回报说发现了阿拉索联军的弱点。我们必须利用这一机会对他们造成致命一击！回到阿拉希盆地，和我们的敌人交战吧。诅咒他们，干掉他们，控制所有的五个战略点！让他们的士兵尖叫，流血，从前线仓皇撤退，让他们用抽泣的嘴唇述说你的事迹。$B$B完成这一目标，为污染者带来光辉的胜利。', '同时占据阿拉希盆地中的五座基地，然后向落锤镇的屠杀者杜维尔复命。', '联盟的哭喊声和你的冲锋号角响彻战场，即使在这里也可以清晰听到，$N。对于他们所遭受的苦痛和你带去的恐惧，我感到遗憾。不过只是一点点而已。$B$B你对于污染者的贡献是毋庸置疑的。你在阿拉希盆地的事迹让人感到震撼，它已经传到了瓦里玛萨斯大人……甚至是黑暗女王的耳中。', '你必须迅速出击，$N!不要犹豫!占据阿拉希盆地的五座基地，然后回来向我报告!', '控制五座基地。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8123, '切断阿拉索补给线', '阿拉索联军正在不惜一切代价进攻阿拉希，并妄图夺回这个区域。联盟的各个种族正在全力进军这块遥远的土地，想要将他们的势力从避难谷地扩张到这里。我们必须阻止他们，而最好的方式就是夺取他们的资源。$B$B你可以帮助我们，$N。进入阿拉希盆地，那里遍地都是丰富的矿藏、肥沃的土地和技艺精湛的能工巧匠。占据并控制你找到的所有基地，赢得战斗，然后把你获得的资源给我拿回来。', '进入阿拉希盆地，获得一箱阿拉希资源箱，然后将它交给落锤镇的亡灵哨兵莫提斯。', '非常感谢，$N。我们会确保这些资源不落入联盟的手中。$B$B你的战斗能力值得表彰，$N，去面对阿拉索联军，赢得更辉煌的胜利吧。', '你赢得阿拉希盆地的战斗了吗，$N?你拿到资源木箱了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8141, '赞达拉暗影坠饰', '', '', '年轻人$C，你进步神速。或许是该让你加入塞拉利卡─赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了食人妖同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8145, '漩涡之藤', '', '', '在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要前往漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8151, '猎人的护符', '艾萨拉的奥汀克正在召集象你这样经验丰富的猎人。他是一名熊怪猎人，他离开了自己的部族，前来帮助塞纳里奥议会。奥汀克与他人分享自己的智慧，也告诉他们要如何维护平衡。你最好去跟他谈谈。$B$B奥汀克居住在艾萨拉埃达拉斯废墟东北部的悬崖顶部。', '跟艾萨拉的奥汀克谈一谈。', '打猎再也不是我的目的，教导猎人才是。而那是命运赋予我的。$B$B和我一起制作一个猎人的符咒—那是从倒下的猎物收集的战利品，会提醒你记得过去的试炼和胜利。我会好好保存这个符咒，并提供你另外的奖励。', '很少人来看望老熊怪了。你也是来看我的吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8160, '切断阿拉索补给线', '阿拉索联军正在不惜一切代价进攻阿拉希，并妄图夺回这个区域。联盟的各个种族正在全力进军这块遥远的土地，想要将他们的势力从避难谷地扩张到这里。我们必须阻止他们，而最好的方式就是夺取他们的资源。$B$B你可以帮助我们，$N。进入阿拉希盆地，那里遍地都是丰富的矿藏、肥沃的土地和技艺精湛的能工巧匠。占据并控制你找到的所有基地，赢得战斗，然后把你获得的资源给我拿回来。', '进入阿拉希盆地，获得一箱阿拉希资源箱，然后将它交给落锤镇的亡灵哨兵莫提斯。', '非常感谢，$N。我们会确保这些资源不落入联盟的手中。$B$B你的战斗能力值得表彰，$N，去面对阿拉索联军，赢得更辉煌的胜利吧。', '你赢了阿拉希盆地的战斗吗，$N?你拿到资源木箱了没?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
