INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8168, '阿拉希盆地之战！', '$N，在阿拉希盆地的战斗是为了资源和领土而进行的战斗。这个地区作战的关键是保证我们军队稀有物资和补给的顺畅运作。我命令你去攻击距离我们在阿拉希盆地中的基地最远的战略设施。$B$B当农场、矿洞、伐木场或铁匠铺被敌人占据时，攻击这些设施，找到敌人的旗帜，然后把它拔掉！$B$B当你完成了夺回这四个点的任务之后，就回到我这里来。', '进攻矿洞、伐木场、铁匠铺和农场，然后向避难谷地的奥斯莱特元帅复命。', '我收到了你在阿拉希盆地大显神威的报告，$N。干得好!如果有越来越多的像你这样勇敢的$C加入我们，我相信我们终有一天能夺回我们的家园。', '$N，你还没有完成对这4个战略要点的攻击。任务完成之后再回到我这里来。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8169, '阿拉希盆地之战！', '无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉希盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！$B$B去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。$B$B出发吧，$N。当任务完成之后向我复命。', '进攻阿拉希盆地的矿洞、伐木场、铁匠铺和兽栏，然后向落锤镇的屠杀者杜维尔复命。', '污染者斥候已向我回报你成功了，$N。做得好。$B$B你慢慢就会知道，想要赢得阿拉希盆地的胜利，我们必须保持警惕，并击败联盟任何想扩张的企图。唯有这样，我们才能确保赢得最后的胜利。', '你还没有完成你的任务，$N。攻击我提到所有的4处基地，完成任务之后再回到我这里来!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8170, '阿拉希盆地之战！', '无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉希盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！$B$B去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。$B$B出发吧，$N。当任务完成之后向我复命。', '进攻阿拉希盆地的矿洞、伐木场、铁匠铺和兽栏，然后向落锤镇的屠杀者杜维尔复命。', '污染者斥候已向我回报你成功了，$N。做得好。$B$B你慢慢就会知道，想要赢得阿拉希盆地的胜利，我们必须保持警惕，并击败联盟任何想扩张的企图。唯有这样，我们才能确保赢得最后的胜利。', '你还没有完成你的任务，$N。攻击我提到所有的4处基地，完成任务之后再回到我这里来!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8171, '阿拉希盆地之战！', '无疑你已经听说了，阿拉索联军正派大量的军队进驻阿拉希盆地。联盟那帮蠢货想要食物和补给，因此妄图占据这块富饶的土地。我们必须让他们知道阿拉希永远不再会是人类的家园了！$B$B去阿拉希盆地然后进攻那里矿井，伐木场，铁匠铺和马厩。夺下敌人在那里的旗帜，把那里变成部落的领土。$B$B出发吧，$N。当任务完成之后向我复命。', '进攻阿拉希盆地的矿洞、伐木场、铁匠铺和兽栏，然后向落锤镇的屠杀者杜维尔复命。', '污染者斥候已向我回报你成功了，$N。做得好。$B$B你慢慢就会知道，想要赢得阿拉希盆地的胜利，我们必须保持警惕，并击败联盟任何想扩张的企图。唯有这样，我们才能确保赢得最后的胜利。', '你还没有完成你的任务，$N。攻击我提到所有的4处基地，完成任务之后再回到我这里来!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8181, '面对叶基亚', '通过对摩沙鲁石板的研究，我得出了一个可怕的消息，$N。你用一枚蛋收复了哈卡，然而血神哈卡的真身可以通过那枚蛋获得新生！叶基亚告诉你说那枚蛋是用来禁锢哈卡的邪恶力量的，但实际上，它的作用是让哈卡重生！那个巨魔将你引入了歧途！$B$B去找到叶基亚，摧毁那枚蛋。希望我们还有足够的时间阻止哈卡死灰复燃！', '跟叶基亚谈一谈。', '这么说，你已经跟那个老矮人詹斯.铁靴谈过话，知道丢失的摩沙鲁石板的秘密了?那个爱管闲事的勘察员……$B$B没关系。要挽救世界，现在已经太晚了。哈卡已经重获新生，他的力量还在继续增长中……他就在古老的食人妖王国祖尔格拉布!他来了!他将再次使世界笼罩在血腥和恐怖之中!$B$B谢谢你，$N。在你的帮助下，夺魂者又回来了!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8182, '拉斯塔哈之手', '$N，我们最担心的事情终于发生了。相传拥有无上力量的夺灵者哈卡正在统治着巨魔的古代帝国，那里充斥着邪恶和恐怖。如果我们不做点什么的话，他的统治范围很可能会蔓延到整个艾泽拉斯！$B$B也许赞达拉巨魔能帮助我们阻止悲剧的发生。他们驻扎在荆棘谷的祖昆达废墟以西，也就是那个名叫尤亚姆巴的小岛上。跟他们的首领莫托尔谈谈，但愿他知道如何打败哈卡。', '跟荆棘谷的莫托尔谈一谈。', '是勘察员铁靴派你来的吧?他很聪明，派你来找我更是明智之举─因为我和赞达拉食人妖知道如何打败夺魂者。$B$B跟岛上的食人妖谈谈，留意他们的话。准备作战吧，$N，你要踏上的将是洒满鲜血的道路。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8228, '能给我一张宣传单吗？', '', '', '本周日在藏宝海湾有一场钓鱼比赛!这是给你的比赛规则!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8229, '能给我一张宣传单吗？', '', '', '本周日在藏宝海湾有一场钓鱼比赛!这是给你的比赛规则!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8233, '简单的要求', '乔拉齐·拉文霍德公爵邀请你到他那儿去。这事儿得保密，我不能再透露更多消息了。$B$B拉文霍德庄园位于希尔斯布莱德丘陵，敦霍尔德城堡的西北方有一条道路通往那儿。', '前往拉文霍德庄园，和乔拉齐·拉文霍德公爵谈一谈。', '欢迎!欢迎!坐吧，$N，我们简单谈谈。$B$B你知道，$N，我最近弄丢了一件心爱之物;\n坦率地说，我愿意不惜一切代价都要将它找回来。别担心，我有东西送你的!是的，很不错的东西。$B$B嗯，$N……你准备好冒险了吗?', '$C，做个自我介绍吧。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8250, '法师的会见', '最近经常有人打听大法师克希雷姆……他们都跟你差不多。$B$B如果你想要找他的话，就去艾萨拉吧。克希雷姆居住在高高的悬崖顶端，只有他那傲慢的仆人萨纳斯能利用传送术到达那儿。$B$B萨纳斯就在崖下扎营。你可以在埃达拉斯废墟入口处找到通往艾萨拉的大道，在交叉路口往北直走就是了。', '找到萨纳斯，让他将你传送到大法师克希雷姆那儿。', '<萨纳斯轻蔑的看着你。>$B$B大法师克希雷姆等待着你的到来。', '你是?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8254, '塞纳里奥议会的求助', '神的道路是帮助那些需要帮助的人。如何去帮助他们，这并不重要；重要的是你为什么要去帮助他们。$B$B塞纳里奥议会需要你的帮助，去和艾萨拉的奥汀克谈一谈吧，他就住在埃达拉斯废墟东北部悬崖的顶部。', '找到艾萨拉的奥汀克。', '你的到来减轻了我肩头上的重担。我们有好多事情得做。', '欢迎，$C。你是来帮助我们的吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8260, '阿拉索基本医疗包', '', '', '你向我们证明了自己的实力，$N。作为奖励，请收下这个包裹!里面装满了仅可在阿拉希盆地使用的补给物品和绷带。$B$B随着你在阿拉希盆地取得的进展，你会发现你可以购买这些物品。当你在我们当中的声望达到尊敬时，你即可购买补给物品;\n达到崇敬时即可购买绷带。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
