INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8383, '铭记奥特兰克！', '', '', '你为联盟不断带来荣耀，$N。如果我们继续努力的话，部落迟早会被我们击垮的。', '奥特兰克山谷的战斗正在激烈地进行中，$N!你有没有完成你应尽的职责，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
