INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8408, '自然屏障', '', '', '干得好，$N。感谢你，我们在梣谷的自然屏障又能安稳地度过一天了。', '不要忘记，在战歌峡谷中进行战斗不止是为了保护森林，更重要的是我们在保护梣谷和贫瘠之地之间的自然屏障。你有没有从战场带回什么消息，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8409, '恶臭的鸡蛋', '腐烂的蛋已经被放进了桶里。以后南海镇旅馆出产的酒肯定都是次品了！$B$B你现在应该回提瑞斯法林地向黑暗召唤者雅恩卡报告你的成功。', '向提瑞斯法林地的黑暗召唤者雅恩卡复命。', '啊，你成功了!我要说的是，你展现了万鬼节的精神─被遗忘者的精神!$B$B<黑暗召唤者雅恩卡搓着手大笑着。>$B$B现在南海镇没有美味的麦芽酒喝了，我为此要庆祝一番!至于你，收下这些礼物。你会发现其中必定有有用的东西!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8415, '冰风岗', '指挥官阿什拉姆·瓦罗菲斯特需要你这样纯洁和勇敢的圣骑士，$N。你可以在西瘟疫之地南部的冰风岗找到他。以圣光的名义，去帮助他吧！', '与冰风岗的指挥官阿什拉姆·瓦罗菲斯特谈一谈。', '很好，$C!让我们看看你的力量。', '只有圣骑士能承担我给予的任务。你就是我要找的人吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8436, '资源竞赛', '我们和联盟的冲突已经上升为一场真正的战争，不久之后战争就将全面打响。$B$B对于阿拉希盆地的争夺就是一个很好的开战理由。要么就是联盟占据它，并用其对付我们；或者就是我们占据它，然后用来对付联盟。帮助污染者保持这场资源竞赛上的优势吧，$N！', '将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。', '保护我们在阿拉希盆地的资源是一件非常重要的任务!你干得很好，$N。', '你带来阿拉希盆地的消息了吗，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8437, '资源竞赛', '我们与联盟的冲突已经升级为真正的战争。在这个节骨眼上，双方都不愿意轻易开战。$B$B阿拉希盆地的战争就是资源争夺战。不是联盟夺得资源战胜我们，就是我们夺得资源保持军需供给。帮助污染者保护我们所需的战争资源，$N！', '将3枚阿拉希盆地荣誉奖章交给战场外的部落战争使者。', '保护我们在阿拉希盆地的资源是一件非常重要的任务!你干得很好，$N。', '你带来阿拉希盆地的消息了吗，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
