INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8442, '资源竞赛', '', '', '干得好，$N!只要阿拉希盆地在我们的控制之下，那么我们就可以源源不断地获得补给。', '我们要对付那些想要抢夺我们资源的联盟废渣，$N!我们不允许战争中有物资短缺的情形。继续努力，确保阿拉希盆地掌握在我们手中!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8443, '资源竞赛', '', '', '干得好，$N!只要阿拉希盆地在我们的控制之下，那么我们就可以源源不断地获得补给。', '我们要对付那些想要抢夺我们资源的联盟废渣，$N!我们不允许战争中有物资短缺的情形。继续努力，确保阿拉希盆地掌握在我们手中!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8447, '唤醒传说', '月神湖的湖水可以融解这东西里面的梦魇。给我点时间来净化它吧，$N。', '等待月光林地的守护者雷姆洛斯净化梦魇包裹的物品。', '戴上他的戒指，$N。它为玛法里恩效劳的日子结束了。现在它该为你效劳了……', '你已经看到你必须看到的事情了。', '唤醒传说。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8462, '与纳菲恩交谈', '也许你可以帮助我们木喉部族应付我们正在遭受着的更大的威胁。你一定可以在这里展示自己的能力……$B$B在木喉要塞另一头站着一个我的同类，就沿着这条路去背面。他的名字叫纳菲恩；虽然他看上去是很凶猛和令人讨厌的野兽，但是你不要害怕。他只是在寻求帮助来对抗那些威胁我们家园的力量。', '沿着费伍德森林的路向北走，与一个名叫纳菲恩的熊怪谈谈。他站在木喉要塞的入口处。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8465, '与萨尔法交谈', '除了来自南面的死木熊怪的堕落威胁之外，东面的冬泉熊怪同样也同样是我们的心头大患。如果你愿意继续帮助我们的话，就去和要塞另外一头的萨尔法谈谈吧。沿着左边的这条路一直走下去。$B$B你要小心，如果我里面的兄弟对你表示敌意，他们也许会攻击你。尽快通过那里，避免纠纷。你每杀死一个木喉熊怪——即便是出于自卫——都会极大地降低你在木喉熊怪中的声望。', '穿过木喉要塞去冬泉谷。和萨尔法谈谈，他就在木喉要塞另一头的出口处。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8504, '联盟需要更多荆棘藻！', '你好……这是谁来着？啊，当然，$N！你是来看看我是否还需要荆棘藻的？好吧，今天是你的幸运日，对于你的疑问，答案是肯定的，嗯！你可以再收集20份荆棘藻吗？', '把20棵荆棘藻交给丹莫罗飞机场的列兵德拉里格。', '喔，天啊!你带来的荆棘藻还真多。快，把它装进箱子里保持新鲜。你把这批货带来真是帮了我…我们…联盟一个大忙。我会让大家都知道是你，伟大的$N，为安其拉之战做出荆棘藻贡献!', '又见面了…有什么事?啊，对了，$N!来看看我是否需要更多的荆棘藻吗?嗯，今天真是你的幸运日，因为这个重要问题的答案是肯定的「是」!你可以再收集20个来吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8506, '联盟需要更多紫莲花！', '欢迎回来，$c。我们的储备量正在增加，但是我们仍然需要更多的紫莲花。如果你可以收集这种草药的话，那么我希望你继续努力，把它们交给我。', '把20朵紫莲花交给丹莫罗飞机场的艾文·夜歌。', '我代表联盟接受你的贡献，$N。你的努力让我们可以做出一些药剂和油料供战场上的人们使用。谢谢你。', '欢迎回来$C。我们的收集仍在成长，但即使现在我们仍需要更多的紫莲花。如果你还能收集更多草药，我恳求你继续做并将它们带来给我。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8510, '联盟需要更多阿尔萨斯之泪！', '嗯，看来我需要更多的阿尔萨斯之泪，我想你可以在上次收集到它们的地方再次找到它们。我们越快收集资源，就可以越快地组织对安其拉的进攻。$B$B你会再次帮助我们的吧，$c？', '把20棵阿尔萨斯之泪交给丹莫罗飞机场的士官长戈麦恩。', '做的好，$N!你的确对联盟做出了贡献。我会找人确保这些草药会在战争中派上用场。随时欢迎你回来，尤其是当你有更多的阿萨斯之泪可以带给我的时候。', '嗯，看来我仍需要更多的阿萨斯之泪。我想你应该可以再到上次收集它们的地方帮我找到更多吧。我们越快弄到这些东西，就能越快开始防守安其拉的军队。$B$B你会再次帮助我们吗$C?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8519, '往日的回忆', '当你恢复镇静并重新汇集目光的时候，你发现有些东西从水晶之内往外瞪着。通过进一步的观察，你所看到的是过去……一段记忆……很久之前就遗忘的记忆。', '了解所以可以的过去的事情，然后和塔纳利斯时光之穴的阿纳克洛斯谈谈。', '在鹿盔的背叛之后，我收集了流沙之地权杖碎片并回到这里。我尽了所有力气来保护权杖，不让想用它来伤害世界的人使用它－因此才有龙族军团的攻击。$B$B在四只巨龙之间分裂的权杖实在不太可能重整那些蓄意制造的混乱……至少我是这样想的。我真是个笨蛋。到现在我还是被那受诅咒的思想困扰着。', '<安纳克罗斯点点头。>', '流沙之战', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8527, '联盟需要更多烤迅猛龙肉！', '你好，$c。我看得出，你对这些感到十分兴奋。我想你愿意再带给我20份烤迅猛龙肉。太好了。快去吧，我会在这里等你回来的。', '把20块烤迅猛龙肉交给丹莫罗飞机场的萨拉·塞维斯。', '哇，你真是个干劲十足的人。光是看着你我都累了。总而言之，联盟感谢你做的一切。我会把你的名字和所做的贡献写在单子上让大家喜欢你。我想你可以等会儿再回来看我们是否需要更多肉，虽然这边的肉已经多的发臭了。', '又见面了，$C。我看的出来你对一切感到相当兴奋。所以我想你应该可以再另外帮我带20份烤迅猛龙肉来。很好。你会帮忙吧。回头见囉。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8550, '部落需要更多宁神花！', '', '', '谢谢你不断的努力，$N。你无私的奉献带给你自己和你的祖先无上的荣耀，而且大家都会知道!我要先把这些草药收好让它们在使用前保持新鲜。你再一次的展现了最真实的部落精神，可以战胜困难并允诺我们一起努力的精神。', '又见面了，$N。我很高兴你又回来关心我们从未停止需要的宁神花。战事不停，我们就不断需要制作药水和药剂。$B$B你会再次协助我们吗，$C?我需要和以前相同数量的宁神花，所以如果你可以收集到再拿来这里给我，我会很感激。当然，如果你现在就有的话，我会非常乐意收下它们。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8553, '船长的弯刀', '我的第一条船被那些海巨人们搞沉了之后，我只好买了第二艘，而且给它起名为“斯莫特的复仇”。我为它配备了新的装备和船员，并出发去寻找那些该死的巨人。我找到了他们，但……他们又一次击败了我们。他们把“斯莫特的复仇”号给打成了碎片，船员也几乎被他们杀光了，但那帮混蛋却把我丢在了一条救生艇上，让我一个人漂了回来。$B$B这次，那些海巨人中的另外一个偷了我的弯刀。$B$B到奈古拉什那里去把我的佩刀给抢回来！$B$B去和斯普罗格谈谈吧。他本来是“斯莫特的复仇”号上的厨子，沉船的时候他也幸存了下来，我想他能帮你们找到那些', '与斯普罗格谈一谈。', '你好你好，$N。船长大人跟我说你要去找奈古拉什的晦气，呵呵，是真的吗?', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8555, '守护之龙', '', '', '伊兰尼库斯、瓦拉斯塔兹、和艾索雷葛斯……你的确知道这些龙，凡人。这不是巧合，他们看守我们的世界，扮演着如此有影响力的角色。$B$B不幸的是(有部份也要怪我涉世未深)不论是上古诸神的密探或者称他们为朋友的背叛者，每个守卫都沦陷了。其程度只加深了我对你的种族的不信任。$B$B找到他们……$r，做好最坏的准备吧。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8565, '往日的胜利：阿拉希盆地', '', '', '这是你该得到的，$N!', '啊，对!我们当然不会忘记你过去在阿拉希盆地的成就，$N。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8566, '往日的胜利：阿拉希盆地', '', '', '这是你该得到的，$N!', '啊，对!我们当然不会忘记你过去在阿拉希盆地的成就，$N。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8567, '往日的胜利：战歌峡谷', '', '', '这是你该得到的，$N!让联盟毁灭!', '啊，对!我们当然不会忘记你过去在战歌峡谷的成就，$N。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8568, '往日的胜利：战歌峡谷', '', '', '这是你该得到的，$N!让联盟毁灭!', '啊，对!我们当然不会忘记你过去在战歌峡谷的成就，$N。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8569, '往日的贡献：战歌峡谷', '', '', '这是你该得到的，$N!', '当然胜利不是唯一重要的事情，英雄的努力是一切的精神所在!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8570, '往日的贡献：战歌峡谷', '', '', '这是你该得到的，$N!', '当然胜利不是唯一重要的事情，英雄的努力是一切的精神所在!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8576, '翻译龙语', '', '', '先处理当务之急，$N!我们必须搞清楚艾索雷葛斯到底在石板上写了什么。$B$B你说他叫你做一个奥金浮标而这只是个概要图吗?可是他会用龙语写还真奇怪。那个讨厌的老家伙知道我看不懂这乱七八糟的文字。$B$B如果有用的话，我需要我的水晶球护目镜，一只500磅的鸡和〝龙语傻瓜教程〞第二卷。不需要按照顺序。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8577, '斯图沃尔，前任死党', '如果我要翻译东西的话，就得戴上我的占卜眼镜。不幸的，很久以前，我的眼镜就被我的前任死党给偷走了，他就是斯图沃尔。他把我打翻在地，然后拿走了眼镜，把我留在了这里。$B$B在我忠实的水晶球的帮助下，我现在找到他了！他要么就在银松森林的格雷迈恩之墙，要么就在遍地传送门的外域，那里现在到处都是燃烧军团的家伙。你要追踪到他，然后把我的眼镜拿回来，$N！', '纳瑞安要你找到他的前任死党斯图沃尔，从他那里拿回从纳瑞安那里偷走的占卜眼镜。', '真不敢相信他竟找到了我。我还以为我在外域时就与他走失了。我不会回去那里的，$r!不会，绝对不会!我受够了当他兼职的好朋友和全职的佣人。', '<箱子里一个高声调的声音回应了你的呼唤>$B$B是谁啊?打扫房间的吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8579, '凡人中的勇士', '', '', '你继续好好的效忠我们吧，$N。我们的协定依然存在。', '杀死其拉主使者对人类而言是个显着的成就，$N。无论如何，他们拥有强大的能量与数量。继续对抗他们以证明自己成为我们勇士的价值。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8581, '部落需要更多火焰花！', '', '', '这不是开玩笑吧，$C?你这么快就帮比雷凯基带火焰花来了吗?比雷凯基现在就要算算它们的数量!你让比雷凯基感到很开心，他会告诉大家$N是有史以来最棒的火焰花收集者。比雷凯基等不及开战了。现在我们真的把希利苏斯的天空点亮了，对吧$g兄弟:姐妹;\n?!', '比雷凯基知道你来帮忙。带很多火焰花来让他高兴。比雷凯基可能会用火焰花制作大炸弹。战争来临时把它们丢到安其拉的昆虫身上。但是比雷凯基需要更多火焰花，$C!$B$B你要帮比雷凯基带火焰花来，动作要快。至少要带和上次一样多的火焰花来他才会开心。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8584, '少管闲事', '如果说我有一些原则是你应该了解的，那就是：永远不要管我的闲事！我所做的事情都是你无法理解的。比如说：你知道精神电能整流器是什么吗？显然你不知道！这就是为什么我来负责我们的项目规划，而你负责满世界跑腿。$B$B我之前说过，如果你想继续下去的话，那么我们需要一只500磅重的鸡。$B$B到加基森去跟迪尔格·奎克里弗谈谈——他知道如何让你找到合适的品种。', '塔纳利斯的纳瑞安让你和加基森的迪尔格·奎克里弗谈一谈。', '<戴格抓了抓他的头。>$B$B一只500磅的鸡?哪有这种东西!至少，现在没有了。我知道有这种鸡……死亡的黑鸡…$B$B<戴格的声音变小了。>$B$B但是，没有人可以见过那只鸡还活着讲这个故事。我有个主意能让我们双方获利，孩子。', '一只什么?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8597, '龙语傻瓜教程', '我就知道总有一天这本书会有用的！幸运的是，我已经学聪明了！我把它藏了起来。$B$B不要担心，它被放在谁都找不到的地方！嗯，我需要搭乘一架直升飞机才可以到那里去。不幸的是，在我回来的路上，飞机坠毁了。就是因为这次事故，我才获得了超级侏儒精神力量！$B$B到天涯海滩那边去寻找坠毁的直升飞机，然后往南边游！你到了那里就会看到的！', '寻找纳瑞安埋在南海的某座小岛上的书。', '书不见了!在土石堆上的是一张纸条。', '那个地方有一个X标记……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8601, '部落需要更多硬甲皮！', '', '', '练习，练习，练习。一把磨锐的好刀和使用它的技能会让你所向披靡，$N。看来这次的皮革边缘比上次切割的好。你买了新的小刀吗?$B$B我们感谢你的努力。你的捐献会被记录下来，而你的名声会远播至关心这类事情的人那里。如果你又获得了更多硬甲皮，请务必回来与我交谈，因为我可能会需要它。', '为安其拉之战做的准备继续进行，$C。但是，要确定我们没有落后，或至少不要成为造成落后的人，我要你再带回另一批硬甲皮给我。这一次，尽量切割的干净一点，知道吗?我还要浪费时间清理你上次给我的那批货。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8605, '部落需要更多绒线绷带！', '', '', '你是个高尚的$C，$N!我会代表部落确实记录你的贡献并让负责的人都知道你的努力。平静的走吧，如果你又找到多余的绒线绷带再回来找我。', '能再见到你真好，$C。我们仍在为战事做准备，所以我仍然需要你协助我收集绒线绷带。我们非常感谢你能提供的任何协助。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8606, '螳螂捕蝉！', '我终于想到了！我们应该这样做。我要给袋子里装满石头，然后你来负责送货。我知道他们说应该由我亲自送去之类的。$B$B<纳瑞安上下打量着你。>$B$B嗯，你也可以完成这个任务。戴上这条头巾，穿上这件长袍，拿着这袋石头，去冬泉谷的交货地点吧。$B$B我在这个工具包中帮你准备了所有必需的东西。当他们冒出来拿货的时候，就干掉他们！让他们知道惹毛了纳瑞安的下场！', '塔纳利斯的纳瑞安要你去冬泉谷，把一袋金子放在绑匪的勒索信上所写的位置。他还要求你教训一下那些家伙！', '我想我低估了这些绑架书的人。', '快，$N!不知道他们对我的书有什么病态疯狂的计画!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8608, '部落需要更多魔纹布绷带！', '', '', '真是太惊讶了，$C，你真的又完成了。嗯，他们都说我很会选人做事。很好，我会将你的名字记录在你的贡献旁边，这样你就能获得这项努力应得的社会利益。如果你真的想证明自己的价值，我建议你再出去收集另一堆魔纹布绷带。', '你回来了?真有趣。你看我还在收集安其拉战役要用的东西。这表示我需要你再次为我收集一堆魔纹布绷带。如果你能再做一次会相当令人惊讶的$C。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8610, '部落需要更多符文布绷带！', '', '', '你的付出相当地无私，$N。你解救了安其拉战士。非常感谢你对部落的慷慨解囊。如果你能制作、或是遇到更多的符文布绷带，请考虑带回来这里给我。', '时间越来越接近我们一头栽进安其拉战火的时候了，$C。但是首先我们必须聚集我们的力量并准备好一切，这样我们才能在那些昆虫和他们的首领猛攻下生存。$B$B如果你可以的话，就再贡献另一批符文布绷带吧。请尽快完成并再次回到我这里。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8612, '部落需要更多瘦狼排！', '', '', '你真是个好厨师，$N。那些瘦狼排让我口水直流;\n我想如果少了几个应该不会被发现吧。总之，做的好。我会确定有人记录下你的贡献。如果你又有更多瘦狼排，你知道在哪里可以找到我。', '如你所见，$C，我们仍需要打包更多的食物给士兵。我不知道你打过仗没有，但是一旦你经过战场上第一个杀戮，你就会变的很飢饿。你上次做的很好，所以我希望这次也可以，如果不是有点赶，请为我带回另一批瘦狼排。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8614, '部落需要更多斑点黄尾鱼！', '', '', '这是最好的捕获量，$N!很好，很认真的工作。而且也没有骨头。谢谢你为这些斑点黄尾鱼到外面去。如果你又煮了更多的黄尾鱼请快点回到我这里!', '如你所见，我们仍然需要很多的鱼。安其拉的战士们需要很多食物，所以我要尽所能的弄到所有斑点黄尾鱼。你抓到、煮好它们并带来给我，我会表达我的谢意，还有部落的谢意。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8616, '部落需要更多烤鲑鱼！', '', '', '你为战争奉献的时间和心血难以言喻，$N。我保证你的努力不会白费。致上我的谢意，还有部落的感谢。如果你又烤了另一批鱼，请再次回到我这里。', '你捐赠的最后一批烤鲑鱼看起来非常好吃，$C。我承认我真的很想偷留几条。你也看到了，我们尚未达到需要的配额。我希望你快点回来，因为你还要收集另一批烤鲑鱼。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8619, '黎明长者', '', '', '很庆幸这片大地的居民仍然会对古老的种族表达敬意。我祝你平安，$N，并且送你这个硬币……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8621, '风暴召唤者的足甲', '其拉虫人的魔法古老而又强大，它们最强大的武器甚至可以与龙抗衡。$B$B把其拉统御腕轮和其它辅助材料交给我，我将为你制作一双威力无比的靴子。$B$B你会在与敌人作战的时候发现它所蕴含的力量。', '把其拉统御腕轮、2个先知塑像、5个青铜甲虫和5个陶土甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到中立声望才可以完成这个任务。', '你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。', '你拿到我所需要的东西了吗，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8622, '风暴召唤者的护甲', '最令人恐怖的上古之神正在从安其拉的休眠之中慢慢醒来。艾泽拉斯世界不久之后即将面对这股恐怖的力量，时间对于如此强大的存在来说毫无意义。$B$B当星辰的位置合适的时候，他将让恐怖的力量席卷所有的一切。你必须在此之前找到他，消灭他。$B$B完成这个任务，把他的外壳交给我。我会奖励你一件凡人从未见到过的护甲……一件只有弑神者才有资格获得的护甲！', '把上古之神的外鞘、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的温瑟拉。你必须在诺兹多姆的子嗣中达到尊敬声望才能完成这个任务。', '我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸部铠甲做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弒神者!', '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8623, '风暴召唤者的王冠', '双子皇帝……他们正向我轻声密语，这折磨着我的神志。他们嘲笑我，他们知道我无法进入神殿的深处去拯救我的兄弟亚雷戈斯。$B$B我可以看见他们狰狞的脸庞，他们头上戴着具有无穷力量的皇冠。但是我必须要报仇……我会把这种代表其拉虫人力量的饰品转化成对我们有利的东西。$B$B把我需要的材料交给我，$N。我会为你制作一顶具有超凡力量的头盔。', '把维克洛尔的王冠、2个重生塑像、5个岩石甲虫和5个水晶甲虫交给安其拉的安多葛斯。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。', '你把我所要求的材料都带回来了吗， $N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8624, '风暴召唤者的护腿', '你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。', '把巨型沙虫的皮、2个征战塑像、5个青铜甲虫和5个象牙甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。', '你把我需要的材料带来了吗，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8631, '神秘护腿', '你想要向我们证明你的价值吗，凡人？很好，也许我们可以互相帮助。$B$B在传说中，古老的沙虫奥罗是一个非常强大的存在。据说是上古把它创造出来的原因是为了嘲笑生命的软弱。$B$B它的皮肤非常特殊……异常结实，甚至是无法击破的，而它本身的移动速度却不会因此而受到任何妨碍，它和那些小型生物一样动作灵敏。$B$B把它的皮肤样品和其它一些原材料都交给我，我会给你制作一条具有强大力量的护腿。', '把奥罗的外皮、2个先知塑像、5个银质甲虫和5个白骨甲虫交给安其拉的坎多斯特拉兹。你必须首先在诺兹多姆的子嗣中达到友善声望才可以完成这个任务。', '太好了……虫的皮肤会是很棒的保护层。和我们在路上摧毁的其拉材料结合，这会是个令人畏惧的护甲。愿它协助你面对里面难以言喻的恐怖。', '你把我需要的材料带来了吗，$N?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8635, '碎石长者', '', '', '战争的历史是传奇茁壮的种子。你正处于英雄的时代，年轻人。愿你的英勇传奇深植人心、源远流长。$B$B祝你平安， $N，这是你应有的奖赏……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8636, '巨石长者', '', '', '万物皆难逃一死，但精神却永垂不朽。祝你平安， $N，这是给你的奖赏……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
