INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8854, '二十枚荣誉徽章换取物资', '', '', '很好，这里是你要的补给品，$C。如果你还想要更多的话，请随时来找我，别客气。$B$B继续努力吧，$N。我们必须不惜一切代价地赢得这场战争。如果每个人都尽忠职守，那么胜利必将是我们的!', '啊，又来给自己领取补给品了吗?好吧，我当然理解你需要更多物资的想法……不信你可以看看周围。$B$B我可以给你一些补给品，但是你必须给我几枚荣誉徽章作为交换。你不会因此获得任何声望的提升，但当战斗来临时，这些物资也许可以保住你的性命。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8855, '三十枚荣誉徽章换取物资', '', '', '很好，这里是你要的补给品，$C。如果你还想要更多的话，请随时来找我，别客气。$B$B继续努力吧，$N。我们必须不惜一切代价地赢得这场战争。如果每个人都尽忠职守，那么胜利必将是我们的!', '啊，又来给自己领取补给品了吗?好吧，我当然理解你需要更多物资的想法……不信你可以看看周围。$B$B我可以给你一些补给品，但是你必须给我几枚荣誉徽章作为交换。你不会因此获得任何声望的提升，但当战斗来临时，这些物资也许可以保住你的性命。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8856, '沙漠生存包', '目前塞纳里奥要塞涌入了大量的新兵，我们的首要问题就成了如何保证他们在沙漠中生存下来。缺水的环境和遍布希利苏斯的剧毒生物都威胁着这些缺乏经验的志愿者。去收集一些必需的物资，把他们交给要塞里的卡兰德拉斯吧。', '把4份纯水之球、4份特效抗毒药剂和4份烤鲑鱼交给希利苏斯塞纳里奥要塞的卡兰德拉斯。', '太好了!我们正需要这些，$N。谢谢你。', '你有东西要给我吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8863, '美味佳肴', '', '', '太棒了－', '如果你很饿，那你就来对地方了，我的朋友!$B$B饺子是新年中的传统食品;\n从第一个新年开始就有这样的传统了，我很乐意给你一份让你尝尝看。只要你用一枚先祖硬币跟我交换，就能得到一份美味佳肴，这肯定是你从来没有享用过的美食!', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8866, '铜须长者', '', '', '很庆幸这片大地的居民仍然会对古老的种族表达敬意。我祝你平安，$N，并且送你这个硬币……', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8868, '艾露恩的祝福', '年兽曾经是这个世界的英雄，一头充满着力量、能给人带来幸运的巨狼。在上古之战时，它和其他的英雄一起对抗燃烧军团，但最终却被恶魔腐蚀，成为了邪恶的野兽，在艾泽拉斯传播恐惧与死亡。$B$B最终，它在月光林地这里被打败了，并长眠在月神湖底。但是每年的这个时候，在春节期间，它都会苏醒……$B$B集结你的军团吧，$n，召唤并打败年兽，艾露恩将赐予你祝福！', '召唤年兽，击败它，并获得艾露恩的祝福。完成任务之后回到永夜港的瓦拉达尔·星歌那里。', '做得好，$N。年兽的灵魂已经回到了月神湖底。这头野兽受过伊露恩的祝福，因此不会死去，但它的愤怒可以因此平息一整年。$B$B你的胜利就是一场庆典，为了纪念强大的年兽，纪念这位悲剧性的英雄，以及你和你的盟友带给它的宁静。', '年兽仍然在月神湖底咆哮，$N……', '获得艾露恩的祝福。', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8869, '甜美的平静', '平静之剑位于血色堡垒内，红衣铸锤师以生命守护着它。打败他，并将他的围裙交给我。作为报答，我将训练你成为锻造战锤的铁匠。$B$B不过你要知道，一旦你选择成为铸锤师，就不能再学习打造刀剑和战斧的技艺了。', '到斯坦索姆去杀死红衣铸锤师。将红衣铸锤师的围裙交给莉莉丝。', '希望你的战锤可以打爆许多脑浆，$N!', '他的围裙!在哪儿?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8870, '春节将至！', '春节将至，$n！塞纳里奥议会邀请所有艾泽拉斯的居民参加我们的新年庆典活动。你可以在这座城市中寻找一个有神圣的月光之环标记的地方，我们的春节预告者就在那里！她可以告诉你更多关于这个节日的细节信息。', '与铁炉堡秘法区的春节预告者交谈。当然，你也可以到其他主城中去寻找当地的新年预报者。', '欢迎，$N。你是来这儿参加我们的庆祝吗?', '找我有事吗，$C?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
