INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8874, '春节将至！', '春节将至，$n！塞纳里奥议会邀请所有艾泽拉斯的居民参加我们的新年庆典活动。你可以在这座城市中寻找一个有神圣的月光之环标记的地方，我们的春节预告者就在那里！她可以告诉你更多关于这个节日的细节信息。', '与幽暗城入口处的春节预告者交谈。当然，你也可以到其他主城中去寻找当地的新年预报者。', '欢迎，$N。你是来这儿参加我们的节庆吗?', '找我有事吗，$C?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8875, '春节将至！', '春节将至，$n！塞纳里奥议会邀请所有艾泽拉斯的居民参加我们的新年庆典活动。你可以在这座城市中寻找一个有神圣的月光之环标记的地方，我们的春节预告者就在那里！她可以告诉你更多关于这个节日的细节信息。', '与雷霆崖长者高地的春节预告者交谈。当然，你也可以到其他主城中去寻找当地的新年预报者。', '欢迎，$N。你是来这儿参加我们的节庆吗?', '找我有事吗，$C?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8876, '小型烟花', '', '', '啊，很好。这是给你的设计图，$N，愿伊露恩祝福你。', '我知道制作新年烟花的秘诀，而且我很乐意将我的知识分享给有荣誉感的人。$B$B拿一点先祖硬币来交换，我就会给你制作小型烟花的设计图……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8877, '烟花发射器', '', '', '给你，$N。这是烟火发射器的结构图。你可以把发射器放在任何地方，然后和你的朋友一起庆祝!', '烟花是节庆不可或缺的好东西，但是要看到这样美丽绚烂的花朵在空中绽放……你就得使用烟火发射器。$B$B给我先祖硬币，我就教你学会制作月光林地里随处可见的那种烟火发射器。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8878, '节日的设计图', '', '', '给你图样，$N。我相信你会发现这些衣服非常漂亮的。', '你看到的这些服饰都是很久很久以前的传统了。我们穿着这些衣服来纪念逝去的岁月和亲人。$B$B如果你能拿来一些先祖硬币来给我，$N，那么我就送你一张图样，它可以教你学会制作传统的红色长裙或服装。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8879, '大型烟花', '', '', '很好，我接受这些先祖硬币。这是给你的设计图，$N。愿你用它来散播伊露恩的荣耀!', '大型的烟花可以把夜空照耀得有如白昼一般，只有集束的烟花可以与它们的华丽媲美!$B$B给我一些先祖硬币，我就教你制作大型烟花的办法。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8880, '烟花束', '', '', '给你，$N。拿着这些设计图，好好学习吧。祝你好运，我期待看到你的大作!', '把一束烟花聚集在一起，它们就会绽放令人赞叹的美丽烟火!给我一些先祖硬币，我就告诉你如何制作烟花束……', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8883, '瓦拉达尔·星歌', '现在你已经拿到了春节邀请函，就赶快到月光林地去吧！你可以在那里看到狂欢的人群，瓦拉达尔·星歌和他的妹妹法蕾尔·星歌在永夜港负责接待前来参加庆典的人。$B$B走上这道月光就可以被传送到月光林地去，到那里之后就找瓦拉达尔·星歌谈谈吧，看看你能在节日期间拿到什么奖品！', '在月光中使用你的春节邀请函前往月光林地，抵达之后与永夜港的瓦拉达尔·星歌谈一谈。', '$N，欢迎来到永夜港，这里是举办新年庆典的地方!虽然我们的村子离艾泽拉斯的人们有点遥远隐蔽，但在这欢庆的时刻我们诚心欢迎所有的人。$B$B好好玩吧，$N，等你准备好了再和我或我的姐姐谈谈。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8929, '寻找安泰恩', '好吧，看来我们除了试试地精的发明外别无他法。据说安泰恩在试图进入斯坦索姆时被天灾军团砍翻了。$B$B试试使用这个设备，看看你能从安泰恩的灵魂那里得到什么消息。', '在斯坦索姆的入口处使用超维度幽灵显形器，然后与安泰恩·哈尔蒙的灵魂交谈。', '是德莉娜叫你来找我的?我会尽力帮你，但首先我必须请你帮我一个大忙。', '你是谁?你怎么可以和我交谈?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8930, '寻找安泰恩', '非常好，$N。后面唯一要做的事就是把这个地精的发明拿去测试一下了。据说安泰恩在尝试进入斯坦索姆的时候被亡灵军团干掉了。$B$B到那里去用一下这个装置吧，看看你是否真的能跟死人说话！', '在斯坦索姆的入口处使用超维度幽灵显形器，然后与安泰恩·哈尔蒙的灵魂交谈。', '是德莉娜叫你来找我的?我会尽力帮你，但首先我必须请你帮我一个大忙。', '你是谁?你怎么可以和我交谈?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8960, '伯德雷的不幸', '那么也就是说我们需要找回勋章的其他部分？要找伯德雷可有点麻烦。他去了黑石山，想尝试重新进入黑石塔，结果就再也没有回来了。$B$B我建议你带上地精的那台设备吧，万一最坏的结果发生了，你也有办法应对。', '到黑石山去，使用超维度幽灵显形器找到伯德雷。', '我好高兴你能看到我，终于有人能跟我说说话!$B$B你能帮帮我们吗，$N?帮帮我们将以前所犯的错导入正轨?如果你真的有瓦萨拉克领主护符上半块，我就能指引你拿到另外那2块，然后拼凑好就行了。$B$B喔，对了，你好，我叫布德利。很高兴认识你!', '你看的到我?什么?喔，谢天谢地!你叫什么名字?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8980, '金格的评估', '这真让人感到意外。看来芬斯塔还真是个很警觉的家伙。我在香水中发现了某些可以用来控制精神的物质。$b$b在香水中应用这些物质虽然并非是前所未有的事情，但我从其中提炼出的一些原料……这是严肃的炼金术问题，以皇家药剂师协会成员的能力一定可以查出结果。', '回到幽暗城银行附近的芬斯塔·艾吉勒那里。', '所以，我是对的。我们千万别浪费时间。一定要找出这些受污染的香水来源。$B$B来，这是酬谢你购买古龙水和香水的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8981, '赠送礼品', '', '', '太好了!太好了!我会把这个跟其他礼物堆放在一起。$B$B我没想到会有这么多!你一定很爱你的领导者。$B$B现在，让我在清单上再加一笔……', '你是来送仰慕之情礼物给你最喜爱的领导者吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8982, '追查货源', '我们一定得找出香水的供货商！我注意药剂师卡崔娜那里似乎有一瓶香水的样子。她告诉我说是从旅店老板诺曼那里买来的。', '与幽暗城中的旅店老板诺曼谈一谈。', '啊是的。我最近刚收到一批香水和古龙水。我不知道它们还能在柜子上放多久 - 看来还没有人闻腻了。$B$B如果你问我，其实我觉得它也没什么大不了的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8983, '追查货源', '我的货有问题？好吧好吧，我从来没见过别人对我的货物这么热衷痴迷。$b$b我是从一个叫玛拉·雷尼克的商人那里进到这批货的。她是新来的。$b$b她提到过说要有些货物得送到法师区的裁缝店那边去。', '与幽暗城法师区裁缝店里的玛拉·雷尼克谈一谈。', '很抱歉我已经将所有的香水和古龙水存货卖给旅店老板诺曼了。如果你想要，就得去和他谈谈 - 假设他还有剩下的话。$B$B不过，你得快点。我想你会发现那$g古龙水:香水;\n是无法抗拒的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8984, '水落石出', '你看，一个游手好闲外加无所事事的药剂师要干什么我根本不关心。要是他想给我找麻烦的话，那我就必须告诉你什么是正确的事。$b$b如果他是无辜的，那他根本没什么好担心的，对吗？$b$b我这批货是从药剂师斯塔弗隆·雷伦特那里进的。他就在希尔斯布莱德丘陵的拉文霍德庄园那边工作。坦率地讲，我认为他确实有点古怪。', '到希尔斯布莱德丘陵去，在拉文霍德庄园后面找到药剂师斯塔弗隆·雷伦特。', '是的，是我做了那些香水。很香啊，不是吗?另人无法抗拒。$B$B当联盟和部落的战士们都为这些爱的感觉所倾倒，他们就无法抵抗暗影议会的崛起了。$B$B他们会变的衰弱，手足无措。当他们担心着内心所挚爱的人，就会失去他们的优势。$B$B解决的方法很简单。为什么我要花那么久的时间去想呢?弱点就是心啊。会发生的事就是会发生，你无法避免的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8993, '赠送礼品', '', '', 'Wonderful! Wonderful! I will add this to the pile of other gifts.$b$bI didn''t expect so many! You must truly love your leaders.$b$bNow, let me just add one more to the count...', '你是来送仰慕之情礼物给你最喜爱的领导者吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8997, '回到起点', '我想该说再见了，我的朋友。要是你想回来跟我谈谈，我随时在此恭候，哪怕你在等待朋友一起前往黑石塔的闲暇时间来找我也行。$B$B走吧，别惹我哭出来。去铁炉堡找德莉亚娜，跟她说说发生了什么事儿。', '跟铁炉堡王座大厅内的德莉亚娜谈一谈。', '我很高兴看到你能平安归来，$N。你看起来很好，只是衣着有点糟。$B$B来吧，告诉我都发生了什么事。', '好久没看到你了，$N。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (8998, '回到起点', '我想该说再见了，我的朋友。要是你想回来跟我谈谈，我随时在此恭候，哪怕你在等待朋友一起前往黑石塔的闲暇时间来找我也行。$B$B走吧，别惹我哭出来。去奥格瑞玛找莫克瓦尔，跟他说说发生了什么事儿。', '跟位于奥格瑞玛智慧谷里的莫克瓦尔谈一谈。', '很高兴看到你还活着，$N。你看起来很好，只是有点历经风霜。$B$B来吧，告诉我都发生了什么事。', '好久没看到你了，$N。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9025, '摩根的发现', '好吧，有问题。看来阿瑞斯坦还真是个很警觉的人。我在香水中发现了一些应用在爱情药水中的物质，以及一些可以影响情绪的危险成分。$b$b在香水中应用这些物质虽然并非是前所未有的，但我从中分析出的一些原料……闻起来很有趣。', '回到暴风城银行附近的阿瑞斯坦·莫塔那里。', '虽然我认为这应该就是事实，但仍未证实我的怀疑是对的。我们要三思而后行。$B$B拿着，酬谢你购买古龙水跟香水。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9026, '追查货源', '我们一定得找到源头才行。我看到许多人，包括卫兵，都在镶金玫瑰那里进进出出。跟奥里森谈谈，要是她在卖这些东西，就问问她是从哪里弄来的货。', '与暴风城贸易区中的镶金玫瑰旅店的老板奥里森谈一谈。', '是的，我最近刚进了香水和古龙水。相当地热卖，我不知道它们还能放在柜子上多久。$B$B如果你问我，其实我觉得有点无聊。每个人身上的味道都一样?不过是真的很好闻啦。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9027, '追查货源', '我的香水有点古怪？有可能。我从来没见过人们对某种产品这样痴迷。$b$b你看，要是有什么古怪的话，我也很想知道。我是从一个叫埃文特·索里萨姆的商人那里进到这批货的。他是新来的。$b$b他提到过说有些货物得送到“最好的线团”那边去。', '与暴风城运河旁的裁缝店“最好的线团”里面的埃文特·索里萨姆谈一谈。', '是，当然。那些香水是这个季节最热卖的商品。你是这个小时之内第五或第六个询问它们的人了。$B$B我想我的存货已经卖完了。如果你想买，你要去和镶金玫瑰的旅店老板奥里森谈谈。$B$B你不该浪费任何时间。我想你会找到$g古龙水:香水;\n那是令人无法抗拒的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9028, '水落石出', '什么？叛国罪？不，不，我向你保证，我绝对没有任何的恶意。$b$b难道说帮助那些想轻松度过痛苦的求爱期的年轻人也有错吗？拜托，这绝对不是犯罪。$b$b为了证明我确实没有恶意，我可以告诉你货源。$b$b据说这些香水都是一个叫斯塔弗隆·雷伦特的药剂师制作的，不过我从未与他见过面，也没有说过话。$b$b我们的地精中间人说，他就在希尔斯布莱德地区工作，似乎就是那个神秘的拉文霍德庄园一带。祝你好运！', '到希尔斯布莱德丘陵去，在拉文霍德庄园后面找到药剂师斯塔弗隆·雷伦特。', '是的，是我做了那些香水。很香啊，不是吗?另人无法抗拒。$B$B当联盟和部落的战士们都为这些爱的感觉所倾倒，他们就无法抵抗暗影议会的崛起了。$B$B他们会变的衰弱，手足无措。当他们担心着内心所挚爱的人，就会失去他们的优势。$B$B解决的方法很简单。为什么我要花那么久的时间去想呢?弱点就是心啊。会发生的事就是会发生，你无法避免的。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9029, '薰炉', '', '', '一阵香味从大锅里飘送出来。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9032, '伯德雷的不幸', '包含着瓦塔拉克灵魂的奖章？怪不得这个物品上被施加了那么强烈的诅咒。$B$B找到伯德雷恐怕有点困难。上次我听说他正在筹备前往黑石塔的冒险，可在那以后就再也没有他的消息了。$B$B在黑石山外找一找他吧，不过，我想……他恐怕已经死了。我建议你拿上那个地精造的装置，朋友。', '到黑石山去，使用超维度幽灵显形器找到伯德雷。', '我好高兴你能看到我，终于有人能跟我说说话!$B$B你能帮帮我们吗，$N?帮帮我们将以前所犯的错导入正轨?如果你真的有瓦萨拉克领主护符上半块，我就能指引你拿到另外那2块，然后拼凑好就行了。$B$B喔，对了，你好，我叫布德利。很高兴认识你!', '你看的到我?什么?喔，谢天谢地!你叫什么名字?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9063, '托尔瓦·寻路者', '有位名叫托尔瓦·寻路者的猎人最近请求德鲁伊的帮助。他说只有我们才具备必要的技巧与对大自然的尊重。$b$b托尔瓦并不难找，他就在由塔纳利斯通往安戈洛环形山的路上，准确的说，是环形山的入口位置。', '与安戈洛环形山的托尔瓦·寻路者谈一谈。', '你千里迢迢来找我，$C，而且还真花了很多时间。', '你千里迢迢来找我，$C，而且还真花了很多时间。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9094, '银色黎明手套', '', '', '你做的很好，$N。收下你的护手装备感谢你的努力。', '如果你给我带来30个亡域符文，我就会给你一套护手做为回礼。这些东西在我们对抗不死族天谴军团时很有用。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9120, '克尔苏加德的末日', '克尔苏加德的护符匣是这位纳克萨玛斯首脑的唯一遗物。理性告诉你应该摧毁护符，令这个巫妖再也无法复活。好在你从来不会听从理智的心声。$B$B圣光之愿礼拜堂的某人会出大价钱换取这件护符的。克尔苏加德就算恢复力量又如何，管他的呢！', '将克尔苏加德的护符匣带往东瘟疫之地圣光之愿礼拜堂。', '我一生中从不期望见到这个东西……$B$B<蒙托神父好像开始流口水。>$B$B喔太好了，你会得到奖励的，亲爱的$g小男孩:小女孩;\n。你会得到丰厚的奖励。拿去。快!', '祝福圣光!你拿着什么邪恶的东西，$g小男孩:小女孩;\n?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9142, '工匠文书', '', '', '这是你的奖励，蠢蛋。现在，不要跟我抱怨你的任务。完成它们 - 或者 - 摧毁它们。', '你知道规矩，孩子。一枚勇气勋章才能让你获得一份工匠的令状。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9154, '圣光之愿礼拜堂', '天灾军团纠集了浩浩荡荡的部队向我们发动了全面进攻，这一定是巫妖王进犯的信号！银色黎明现在招募所有有战斗能力的有志之士，无论男女，共同保卫我们的家园。$B$B如果我们站在同一阵线，请将这份文件交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '将征兵公告交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '银色黎明发出求援的召集，而你起身响应。现在已经没有时间让我们给予你训练。但我们对你的能力有信心，你的加入让我们得以抵御天谴军团的威胁。', '你是来加入保卫家园的行列吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9238, '冰川护腕', '感谢你和奥玛里恩（愿奥玛里恩就此安息），现在我可以开始制作冰川护腕了。你要做的只是为我提供材料，并支付一笔小小的加工费。', '将4个冰冻符文、2个符文布卷、2个水之精华、2个铁网蛛丝和200金币交给东瘟疫之地圣光之愿礼拜堂的工匠威尔海姆。', '这是你要求的东西，$N。依约抵达!', '你有带材料来吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9247, '圣光的召唤', '$N，$B$B在过去的日子里，你尽心尽力地为银色黎明做出了杰出的贡献。现在，在这紧要关头，我们再次发出号召。$B$B$N，如果你愿意伸出援手，就去东瘟疫之地圣光之愿礼拜堂向名单登记员报道吧。', '将名单登记员的信交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '为了只是向你回覆征召，我们这可惨了，$N。你们无疑是银色黎明光明的典范，其他人则是更明白、洞察该如何有效抵御天谴军团的入侵!', '啊，$N。很高兴见到你。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9257, '埃提耶什，守护者的传说之杖', '艰巨的任务总在最后，$N。你已经击败了一位上古之神和一位巫妖王的大将，现在是面对萨格拉斯的时候了。$B$B带上这根杖子前往斯坦索姆。你会在那儿发现一处神圣之地：洛丹伦最伟大的骑士们的埋骨之处。将这柄被玷污的传说之杖放在神圣之地中，准备好挑战被驱赶出法杖的可怕生物……击败控制着法杖的恶魔，然后再回来找我。', '塔纳利斯时光之穴的阿纳克洛斯要你前往斯坦索姆，在神圣之地上使用埃提耶什，守护者的传说之杖。击败被驱赶出法杖的生物，然后回到阿纳克洛斯那里去。', '这伟大的成就绝对不能就这样让它轻描淡写过去，$N。你完成了不可能的任务。哎，这是命中注定啊。法杖已经作出了自己的选择……', '遵命，$r。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9260, '调查暴风城的天灾入侵', '巫妖王的部队已经在我们鼻子底下扎了营，我们可不能坐以待毙！你会拿起武器跟这些可憎的入侵者作战，保卫暴风城的吧？$B$B城外出现了奇怪的符文法阵，它散发着神秘的能量，亡灵和悬浮在半空的浮空城也被同样的能量环绕着。我想这个符文法阵对天灾士兵们必然有着重要的意义，因此想让你调查此事。去和城外的亡灵作战吧，带回你杀死他们的证据，以及你的调查结果，我会奖励你的。去吧！', '从暴风城外面的天灾士兵身上收集3块暗淡的死灵石，并调查天灾营地附近的发光符文法阵。', '嗯。从你告诉我的事情，法阵里的声音……它们一定是被用来做为某种沟通的工具。我一想到那些邪恶的脑袋会透过这样的魔法联系就不寒而栗。无论如何，你看起来还是很健全很清醒。银色黎明感谢你的努力。', '你调查过入侵行动了吗?没有时间可以浪费了!', '调查法阵', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
