INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9272, '海盗的制服', '', '', '呀……如果你真的那么想加入我们老练水手的行列，你最好穿的像个水手一点!来，在我严责你之前快穿上适当的服饰。$B$B它们穿在你身上比穿在红眼阿班那个老家伙身上适合多了。他死在海上的一场暴风雨里。$B$B骄傲的穿着它吧，朋友!', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9295, '被撕碎的信', '你在某个天灾士兵的尸体上找到了这封信。破旧发黄的信纸散发着霉臭，看来它在亡灵手里已经有些日子了。或许圣光之愿礼拜堂的家伙会对此感兴趣的……', '将被撕碎的信交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;\n我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。', '什么事吗?你手里拿着的是什么?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9300, '破旧的信', '你在某个天灾士兵的尸体上找到了这封信。破旧发黄的信纸散发着霉臭，看来它在亡灵手里已经有些日子了。或许圣光之愿礼拜堂的家伙会对此感兴趣的……', '将破旧的信交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;\n我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。', '什么事吗?你手里拿着的是什么?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9302, '被弄皱的信', '你在某个天灾士兵的尸体上找到了这封信。破旧发黄的信纸散发着霉臭，看来它在亡灵手里已经有些日子了。或许圣光之愿礼拜堂的家伙会对此感兴趣的……', '将被弄皱的信交给东瘟疫之地圣光之愿礼拜堂的名单登记员。', '多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;\n我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。', '什么事吗?你手里拿着的是什么?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9310, '暗淡的死灵水晶', '你在怪物的尸体上找到一块散发着微弱的腐坏能量的水晶。', '将暗淡的死灵水晶交给幽暗城庭院处的卢卡中尉。', '你说这是从攻击城市的活尸身上找到的?$B$B我们已听说天谴军团召唤亡域基础营地的事。我猜他们想在幽暗城里也造一个。我们以后要严加提防。', '有什么事吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9317, '神圣磨刀石', '', '', '谢谢你，$N。这是你的圣化磨刀石。谨慎地使用它们。', '如果你帮我带来八个天谴军团入侵者的亡域符文，我就能给你一个圣化磨刀石。它们在你对付巫妖王的爪牙时会很有帮助。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9318, '神圣巫师之油', '', '', '我希望你在将来的战役中会发现这些物品很有用。', '如果你拿天谴军团入侵者的亡域符文来交换，银色黎明就会给你一瓶受祝福的巫师之油。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9320, '超级法力药水', '', '', '拿去吧，$N。在那里要小心。我们的数量没有那么大，不能容许太多人阵亡。', '除了我们其他的补给外，我们还有很多很有用的极效法力药水。你拿十五个亡域符文来我就会给你一瓶。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9321, '超级治疗药水', '', '', '拿去吧，$N。在那里要小心。我们的数量没有那么大，不能容许太多人阵亡。', '除了我们其他的补给外，我们还有很多很有用的极效治疗药水。你拿十五个亡域符文来我就会给你一瓶。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9333, '银色黎明手套', '', '', '你做的很好，$N。收下你的护手装备感谢你的努力。', '如果你给我带来30个亡域符文，我就会给你一套护手做为回礼。这些东西在我们对抗不死族天谴军团时很有用。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
