INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9337, '超级法力药水', '', '', '拿去吧，$N。在那里要小心。我们的数量没有那么大，不能容许太多人阵亡。', '除了我们其他的补给外，我们还有很多很有用的极效法力药水。你拿十五个亡域符文来我就会给你一瓶。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9339, '盗贼的奖励', '从暴风城中心偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是(NAME)或许知道些什么……', '将暴风城烈焰交给(NAME)。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9341, '银色黎明战袍', '', '', '收下这件外袍并骄傲地穿上它。或许你的行为能激励其他人也加入我们对抗天谴军团的行列。', '你对我们的目标提供了非常大的帮助，$N。如果你想的话，我可以给你一件银色黎明外袍。有你这样的盟友我们深感荣幸。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9343, '银色黎明战袍', '', '', '收下这件外袍并骄傲地穿上它。或许你的行为能激励其他人也加入我们对抗天谴军团的行列。', '你对我们的目标提供了非常大的帮助，$N。如果你想的话，我可以给你一件银色黎明外袍。有你这样的盟友我们深感荣幸。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9365, '盗贼的奖励', '从暴风城中心偷来的烈焰令你感到异常的温暖。你对这种罕见的力量一无所知，但是(NAME)或许知道些什么……', '将暴风城烈焰交给(NAME)。', '', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9378, '恐怖之城，纳克萨玛斯', '病木林深处就是纳克萨玛斯的宫殿入口。那儿的符文传送门被魔法结界笼罩，一般人是根本进不去的，不过现在不一样了。$B$B我们已经想出了破除结界的方法——奥术遮罩。我对肯瑞托古老的咒语进行了一些修改，使它具备了破除纳克萨玛斯结界的能力。我说过，这种咒语价格不菲，但是你对银色黎明的贡献是不可估量的！我们不会向你收取任何费用。', '东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯会免费为你施放奥术遮罩的咒语。你在银色黎明中的声望必须达到崇拜。', '你会感到一点刺痛，$N。那种感觉就表示它发挥作用了。完成之后，你就能踏上病木林里的符文传送门进入纳克萨玛斯。', '从没有人能进入纳克萨玛斯还活着讲他的故事。', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9386, '黑暗中的光明', '你真是个渴望冒险的家伙，不是吗？如果你愿意再一次进入地下城深处的话，那我会给你奖励的。$b$b去看看通灵学院、斯坦索姆、黑石塔和厄运之槌厅堂内的篝火，我会在这里等你回来的。', '找到并碰触在黑石塔、厄运之槌、通灵学院和斯坦索姆内的火盆，并回到节日护火者处。', '你的本质和你所找到的火焰能量共鸣着，$N。你找到的火焰相当强大，只需要正确地处理，就能增强它的力量……$B$B<老者对着空气中低语，然后拿出一个发光的瓶子。>$B$B啊!好了。不管你往何处去，愿它照亮你的道路。', '你找到你在黑暗中的路了吗?', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9415, '向布鲁沃尔元帅报告', '你就是布鲁沃尔元帅招募来的新兵吗？显然。$b$b那你还在等什么呢？我们最优秀的士兵们正在战场上流血牺牲。要加入他们是否让你感觉到很兴奋呢？$b$b现在，去吧，不要耽搁。', '与佐拉虫巢附近联盟营地的布鲁沃尔元帅谈一谈。', '联盟需要所有有能力的人。部落一直从北方大陆获得稳定的援军物资，我们要撑下去实在很艰难。$B$B让我把情况解释给你听。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
INSERT INTO `locales_quest` (`entry`, `Title_loc4`, `Details_loc4`, `Objectives_loc4`, `OfferRewardText_loc4`, `RequestItemsText_loc4`, `EndText_loc4`, `CompletedText_loc4`, `ObjectiveText1_loc4`, `ObjectiveText2_loc4`, `ObjectiveText3_loc4`, `ObjectiveText4_loc4`) VALUES (9416, '向吉里卡将军报到', '你一定就是吉里卡将军招募来的新兵了？来的正是时候，沙漠里激战正酣呢！$b$b现在矮人几乎每天都能得到增援，我们要想争夺希利苏斯的资源的话，可不能失去任何据点。$b$b立刻到将军那里去接受命令，我的任务可不是训练你，只是找到你而已。', '与雷戈虫巢附近部落营地的吉里卡将军谈一谈。', '有你在这真是太好了，不过没有时间闲聊了。你需要任务的指示，接着得要去外面干活。$B$B听仔细了。', '', '', '', '', '', '', '') ON DUPLICATE KEY UPDATE `Title_loc4`=VALUES(`Title_loc4`), `Details_loc4`=VALUES(`Details_loc4`), `Objectives_loc4`=VALUES(`Objectives_loc4`), `OfferRewardText_loc4`=VALUES(`OfferRewardText_loc4`), `RequestItemsText_loc4`=VALUES(`RequestItemsText_loc4`), `EndText_loc4`=VALUES(`EndText_loc4`);
